  const [hoveredArea, setHoveredArea] = useState<MapMarkerData | null>(null);
  const [pinnedArea, setPinnedArea] = useState<MapMarkerData | null>(null);
  const [tableSort, setTableSort] = useState<TableSortState>({ key: 'revenue', direction: 'desc' });

  // Sync with external config (e.g. jumping from Returns tab)
  useEffect(() => {
    if (externalConfig) {
        if (externalConfig.carrier) setSelectedCarrier(externalConfig.carrier);
        if (externalConfig.metric) {
            setColorMetric(externalConfig.metric);
            if (externalConfig.metric === 'RETURN_RATE') {
                setTableSort({ key: 'returnRate', direction: 'desc' });
            }
        }
    }
  }, [externalConfig]);

  const getAreaDisplayName = (code: string) => {
    const name = UK_POSTCODE_AREA_NAME[code];
    return name ? `${name} (${code})` : `${code} (Unknown Area)`;
  };

  const handleAreaDeepDive = (areaCode: string) => {
      if (onSearch) {
          const areaName = UK_POSTCODE_AREA_NAME[areaCode] || areaCode;
          const platformText = selectedPlatform !== 'All' ? ` on ${selectedPlatform}` : '';
          const timeText = timePeriodLabel || 'Last 30 Days';
          
          // Construct explicit natural language query that the parser will understand
          // Changed "Transactions" to "Sales" to be safer with existing keywords
          const query = `Sales in Postcode: ${areaCode} ${timeText}${platformText}`;
          onSearch(query);
      }
  };

  // 1. Extract Unique Categories for Filter
  const categories = useMemo(() => {
    const cats = new Set<string>();
    products.forEach(p => {
        if (p.category) cats.add(p.category);
    });
    return Array.from(cats).sort();
  }, [products]);

  const subcategories = useMemo(() => {
    const subs = new Set<string>();
    products.forEach(p => {
        if (selectedCategory === 'All' || p.category === selectedCategory) {
            if (p.subcategory) subs.add(p.subcategory);
        }
    });
    return Array.from(subs).sort();
  }, [products, selectedCategory]);

  const carriers = useMemo(() => {
    const carrierSet = new Set<string>();
    priceHistoryMap.forEach((logs) => {
        logs.forEach(log => {
            if (log.logisticPartner) carrierSet.add(log.logisticPartner);
        });
    });
    return Array.from(carrierSet).sort();
  }, [priceHistoryMap]);

  // 2. Aggregate Data by Postcode Area
  const mapData: AreaData[] = useMemo(() => {
    const base = aggregateUkMapData(
        products,
        priceHistoryMap,
        { startDate: dateRange.start, endDate: dateRange.end, selectedPlatform, selectedCategory, selectedSubcategory, selectedCarrier }
    );
    if (refundHistory.length === 0) return base;

    const validSkus = new Set(
        products
            .filter(p => {
                if (selectedCategory !== 'All' && p.category !== selectedCategory) return false;
                if (selectedSubcategory !== 'All' && p.subcategory !== selectedSubcategory) return false;
                return true;
            })
            .map(p => p.sku)
    );

    const orderContextMap = new Map<string, { postcode?: string; platform?: string; carrier?: string; sku?: string }>();
    priceHistoryMap.forEach((logs, sku) => {
        logs.forEach(log => {
            if (log.orderId) {
                orderContextMap.set(log.orderId, {
                    postcode: log.postcode,
                    platform: log.platform,
                    carrier: log.logisticPartner,
                    sku
                });
            }
        });
    });

    const startKey = asDateKey(dateRange.start);
    const endKey = asDateKey(dateRange.end);
    if (!startKey || !endKey) return base;

    const refundQtyByArea: Record<string, number> = {};
    const refundLossByArea: Record<string, number> = {};
    refundHistory.forEach((r: RefundLog) => {
        const refundKey = asDateKey(r.date);
        if (!refundKey || !isDateKeyBetween(refundKey, startKey, endKey)) return;

        const baseOrderId = r.resendBaseOrderId || r.orderId;
        const orderCtx = baseOrderId ? orderContextMap.get(baseOrderId) : undefined;

        const sku = r.sku || orderCtx?.sku;
        if (!sku || !validSkus.has(sku)) return;

        const platform = r.platform || orderCtx?.platform;
        if (selectedPlatform !== 'All' && platform !== selectedPlatform) return;

        const carrier = r.logisticPartner || orderCtx?.carrier || 'Unknown';
        if (selectedCarrier !== 'All' && carrier !== selectedCarrier) return;

        const postcode = orderCtx?.postcode;
        if (!postcode) return;

        const areaMatch = postcode.match(/^([A-Z]{1,2})/i);
        if (!areaMatch) return;
        const area = areaMatch[1].toUpperCase();

        refundQtyByArea[area] = (refundQtyByArea[area] || 0) + Number(r.quantity || 0);
        refundLossByArea[area] = (refundLossByArea[area] || 0) + (Number(r.amount) + Number(r.freightAmount || 0));
    });

    return base.map(d => {
        const refundQty = refundQtyByArea[d.code] || 0;
        const refundLoss = refundLossByArea[d.code] || 0;
        const nextReturnRate = d.volume > 0 ? (refundQty / d.volume) * 100 : 0;

        if (!deductRefunds || refundLoss === 0) {
            return { ...d, returnRate: nextReturnRate };
        }

        const newProfit = d.profit - refundLoss;
        const newMargin = d.revenue > 0 ? (newProfit / d.revenue) * 100 : 0;
        return { ...d, returnRate: nextReturnRate, profit: newProfit, margin: newMargin };
    });
  }, [products, priceHistoryMap, dateRange.start, dateRange.end, selectedPlatform, selectedCategory, selectedSubcategory, selectedCarrier, deductRefunds, refundHistory]);

  // 3. Rank data and calculate shares
  const rankedMapData: MapMarkerData[] = useMemo(() => {
      const dataWithValues = mapData.map(d => ({
          ...d,
          value: mode === 'ABSOLUTE' 
              ? (metric === 'REVENUE' ? d.revenue : d.volume)
              : (metric === 'REVENUE' ? d.revenueDelta : d.volumeDelta),
          sizeValue: mode === 'ABSOLUTE'
              ? (metric === 'REVENUE' ? d.revenue : d.volume)
              : (metric === 'REVENUE' ? Math.abs(d.revenueDelta) : Math.abs(d.volumeDelta)),
      }));
  
      const totalValue = dataWithValues.reduce((sum, d) => sum + d.value, 0);
  
      return dataWithValues
          .map(d => ({
              ...d,
              share: totalValue > 0 ? (d.value / totalValue) * 100 : 0
          }))
          .sort((a, b) => b.sizeValue - a.sizeValue)
          .map((d, index) => ({
              ...d,
              rank: index + 1
          }));
  }, [mapData, metric, mode]);
  
  // 4. Scales
  const maxValue = useMemo(() => {
      return Math.max(...rankedMapData.map(d => d.sizeValue), 0);
  }, [rankedMapData]);

  const sizeScale = scaleLinear()
    .domain([0, maxValue])
    .range([4, 20]); // Min bubble size 4, Max 20

  const revenueDomain = useMemo(() => {
    const revenues = rankedMapData.map(d => d.revenue).filter(r => isFinite(r));
    if (revenues.length === 0) return [0, 1000];
    return [0, Math.max(...revenues)];
  }, [rankedMapData]);

  const profitDomain = useMemo(() => {
      const profits = rankedMapData.map(d => d.profit).filter(p => isFinite(p));
      if (profits.length === 0) return [-100, 0, 100];
      const min = Math.min(...profits);
      const max = Math.max(...profits);
      if (min < 0 && max > 0) return [min, 0, max];
      if (max <= 0) return [min, min / 2, 0];
      return [0, max / 2, max];
  }, [rankedMapData]);

  const marginDomain = useMemo(() => {
    const margins = rankedMapData.map(d => d.margin).filter(m => isFinite(m));
    if (margins.length === 0) return [-10, 0, 30]; // Default domain
    
    const min = Math.min(...margins);
    const max = Math.max(...margins);
    
    if (min < 0 && max > 0) return [min, 0, max];
    if (max <= 0) return [min, min / 2, 0];
    return [0, max / 2, max];
  }, [rankedMapData]);

  const tacosDomain = useMemo(() => {
    const tacosValues = rankedMapData.map(d => d.tacos).filter(t => isFinite(t));
    if (tacosValues.length === 0) return [0, 15, 30];
    const max = Math.max(...tacosValues);
    return [0, Math.min(max, 15), Math.max(max, 30)]; // Green -> Yellow -> Red
  }, [rankedMapData]);

  const colorScale = useMemo(() => {
      switch (colorMetric) {
        case 'REVENUE':
          return scaleLinear<string>()
            .domain(revenueDomain)
            .range(["#e0f2fe", "#7dd3fc", "#0ea5e9"]); // Light to dark blue
        case 'PROFIT':
          return scaleLinear<string>()
            .domain(profitDomain)
            .range(["#ef4444", "#facc15", "#22c55e"]); // Red -> Yellow -> Green
        case 'MARGIN':
          return scaleLinear<string>()
            .domain(marginDomain)
            .range(["#ef4444", "#facc15", "#22c55e"]); // Red -> Yellow -> Green
        case 'TACOS':
          return scaleLinear<string>()
            .domain(tacosDomain)
            .range(["#22c55e", "#facc15", "#ef4444"]); // Green -> Yellow -> Red (high TACoS is bad)
        case 'RETURN_RATE':
          return scaleLinear<string>()
            .domain([0, 5, 10])
            .range(["#22c55e", "#facc15", "#ef4444"])
            .clamp(true); // Green -> Yellow -> Red
        default:
          return scaleLinear<string>()
            .domain(revenueDomain)
            .range(["#e0f2fe", "#7dd3fc", "#0ea5e9"]);
      }
  }, [colorMetric, revenueDomain, profitDomain, marginDomain, tacosDomain]);
  
  const deltaColor = (value: number) => {
      if (value > 0) return "#22c55e"; // green
      if (value < 0) return "#ef4444"; // red
      return "#9ca3af"; // gray for no change
  };

  const sortedAreas = rankedMapData.slice(0, 5);

  const areaToShow = useMemo(() => {
    // Tooltip should only show on hover, not pin
    if (!hoveredArea) return null;
    return rankedMapData.find(d => d.code === hoveredArea.code);
  }, [hoveredArea, rankedMapData]);
  
  const sortedTableData = useMemo(() => {
    const data = [...rankedMapData];
    // Sort by selected column
    data.sort((a, b) => {
        const valA = (a as any)[tableSort.key] ?? 0;
        const valB = (b as any)[tableSort.key] ?? 0;
        const result = valA < valB ? -1 : valA > valB ? 1 : 0;
        return tableSort.direction === 'asc' ? result : -result;
    });
    return data;
  }, [rankedMapData, tableSort]);

  const SortableHeader = ({ label, sortKey, align = 'left' }: { label: string, sortKey: keyof AreaData, align?: 'left' | 'right' }) => {
    const isActive = tableSort.key === sortKey;
    return (
        <th 
            className={`cursor-pointer ${align === 'right' ? 'r' : ''}`}
            onClick={() => setTableSort(prev => ({ key: sortKey, direction: prev.key === sortKey && prev.direction === 'desc' ? 'asc' : 'desc' }))}
            style={isActive ? { backgroundColor: `${themeColor}12` } : {}}
        >
            <div className={`flex items-center gap-1 ${align === 'right' ? 'justify-end' : ''}`}>
                <span>{label}</span>
                {isActive ? (
                    tableSort.direction === 'asc' ? <ChevronUp className="w-3 h-3 text-theme" /> : <ChevronDown className="w-3 h-3 text-theme" />
                ) : (
                    <ArrowUpDown className="w-3 h-3 text-gray-300" />
                )}
            </div>
        </th>
    );
  };

  return (
    <div className="flex flex-col h-auto pb-10">
        {/* Controls Header */}
        <div className="flex flex-row justify-between items-center mb-4 gap-4 p-4 bg-white/50 rounded-xl border border-gray-200">
            <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                    <div className="p-2 bg-theme-10 text-theme rounded-lg">
                        <MapIcon className="w-5 h-5" />
                    </div>
                    <div>
                        <h3 className="font-bold text-gray-900">UK Sales Distribution</h3>
                        <p className="text-xs text-gray-500">Geographic performance by Postcode Area</p>
                    </div>
                </div>
            </div>

            <div className="flex items-center gap-4">
                {/* Filters */}
                <div className="flex flex-wrap items-center gap-2 p-2 bg-gray-100/50 rounded-lg border border-gray-200/80">
                    {/* Mode Toggle */}
                    <div className="flex bg-gray-200 p-1 rounded-lg">
                        <button 
                            onClick={() => setMode('ABSOLUTE')}
                            className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all flex items-center gap-1 ${mode === 'ABSOLUTE' ? 'bg-white shadow text-theme' : 'text-gray-500'}`}
                        >
                            <BarChart2 className="w-3 h-3" /> Absolute
                        </button>
                        <button 
                            onClick={() => setMode('CHANGE')}
                            className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all flex items-center gap-1 ${mode === 'CHANGE' ? 'bg-white shadow text-theme' : 'text-gray-500'}`}
                        >
                            <TrendingUp className="w-3 h-3" /> Change (PoP)
                        </button>
                    </div>

                    {/* Metric Toggle */}
                    <div className="flex bg-gray-200 p-1 rounded-lg">
                        <button 
                            onClick={() => setMetric('REVENUE')}
                            className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all flex items-center gap-1 ${metric === 'REVENUE' ? 'bg-white shadow text-theme' : 'text-gray-500'}`}
                        >
                            <DollarSign className="w-3 h-3" /> Revenue
                        </button>
                        <button 
                            onClick={() => setMetric('VOLUME')}
                            className={`px-3 py-1.5 text-xs font-medium rounded-md transition-all flex items-center gap-1 ${metric === 'VOLUME' ? 'bg-white shadow text-theme' : 'text-gray-500'}`}
                        >
                            <Package className="w-3 h-3" /> Volume
                        </button>
                    </div>

                    <div className="h-6 w-px bg-gray-300"></div>
                    
                    {/* Color Metric Toggle */}
                    <div className="flex items-center gap-1 text-[10px] font-medium text-gray-500">
                        COLOR:
                        <div className="flex bg-gray-200 p-1 rounded-lg">
                            <button onClick={() => setColorMetric('REVENUE')} className={`px-2 py-1 text-xs font-medium rounded-md transition-all ${colorMetric === 'REVENUE' ? 'bg-white shadow text-theme' : 'text-gray-500'}`}>Revenue</button>
                            <button onClick={() => setColorMetric('PROFIT')} className={`px-2 py-1 text-xs font-medium rounded-md transition-all ${colorMetric === 'PROFIT' ? 'bg-white shadow text-theme' : 'text-gray-500'}`}>Profit</button>
                            <button onClick={() => setColorMetric('MARGIN')} className={`px-2 py-1 text-xs font-medium rounded-md transition-all ${colorMetric === 'MARGIN' ? 'bg-white shadow text-theme' : 'text-gray-500'}`}>Margin %</button>
                            <button onClick={() => setColorMetric('TACOS')} className={`px-2 py-1 text-xs font-medium rounded-md transition-all ${colorMetric === 'TACOS' ? 'bg-white shadow text-theme' : 'text-gray-500'}`}>TACoS %</button>
                            <button onClick={() => setColorMetric('RETURN_RATE')} className={`px-2 py-1 text-xs font-medium rounded-md transition-all ${colorMetric === 'RETURN_RATE' ? 'bg-white shadow text-theme' : 'text-gray-500'}`} title="Return Rate %">
                                <RotateCcw className="w-3 h-3 inline" />
                            </button>
                        </div>
                    </div>

                    <div className="h-6 w-px bg-gray-300"></div>

                    {/* Category Filters */}
                    <div className="relative">
                        <select 
                            value={selectedCategory}
                            onChange={e => { setSelectedCategory(e.target.value); setSelectedSubcategory('All'); }}
                            className="pl-8 pr-8 py-1.5 bg-white border border-gray-300 rounded-lg text-xs font-medium appearance-none focus:ring-2 focus:ring-theme"
                        >
                            <option value="All">All Categories</option>
                            {categories.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                        <Filter className="absolute left-2.5 top-2 w-3 h-3 text-gray-400 pointer-events-none" />
                    </div>

                    <div className="relative">
                        <select 
                            value={selectedSubcategory}
                            onChange={e => setSelectedSubcategory(e.target.value)}
                            className="pl-3 pr-8 py-1.5 bg-white border border-gray-300 rounded-lg text-xs font-medium appearance-none focus:ring-2 focus:ring-theme"
                            disabled={selectedCategory === 'All'}
                        >
                            <option value="All">All Subcategories</option>
                            {subcategories.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>

                    {/* Carrier Filter */}
                    <div className="relative">
                        <select 
                            value={selectedCarrier}
                            onChange={e => setSelectedCarrier(e.target.value)}
                            className="pl-8 pr-8 py-1.5 bg-white border border-gray-300 rounded-lg text-xs font-medium appearance-none focus:ring-2 focus:ring-theme"
                        >
                            <option value="All">All Carriers</option>
                            {carriers.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                        <Truck className="absolute left-2.5 top-2 w-3 h-3 text-gray-400 pointer-events-none" />
                    </div>
                </div>
            </div>
        </div>

        <div className="flex flex-col lg:flex-row gap-6">
            {/* Map Visualization */}
            <div className="flex-1 h-[450px] bg-white rounded-xl border border-gray-200 shadow-sm relative overflow-hidden" onClick={() => setPinnedArea(null)}>
                <ComposableMap 
                    projection="geoAzimuthalEqualArea"
                    projectionConfig={{
                        rotate: [2.5, -54.0, 0], // Center on UK roughly
                        scale: 3000
                    }}
                    className="w-full h-full"
                >
                    <ZoomableGroup>
                        <Geographies geography={UK_TOPO_JSON}>
                            {({ geographies }) =>
                                geographies
                                    .filter(geo => {
                                        const id = String(geo.id);
                                        return id === "826" || id === "372";
                                    })
                                    .map((geo) => (
                                    <Geography
                                        key={geo.rsmKey}
                                        geography={geo}
                                        fill="#e5e7eb"
                                        stroke="#d1d5db"
                                        strokeWidth={0.5}
                                        style={{
                                            default: { outline: "none" },
                                            hover: { fill: "#d1d5db", outline: "none" },
                                            pressed: { outline: "none" },
                                        }}
                                    />
                                ))
                            }
                        </Geographies>
                        {regions.map(({ name, coordinates }) => (
                            <Marker key={name} coordinates={coordinates}>
                                <text
                                textAnchor="middle"
                                style={{
                                    fontFamily: 'system-ui, sans-serif',
                                    fontSize: '18px',
                                    fontWeight: 'bold',
                                    fill: '#cbd5e1', // A light grey color
                                    pointerEvents: 'none',
                                    opacity: 0.5,
                                }}
                                >
                                {name}
                                </text>
                            </Marker>
                        ))}
                        {rankedMapData.map((d) => {
                            if (d.sizeValue <= 0) return null;
                            const isPinned = pinnedArea && pinnedArea.code === d.code;
                            const isLowMargin = d.margin < LOW_MARGIN_PCT;
                            const isHighTacos = d.tacos > HIGH_TACOS_PCT;
                            
                            return (
                                <Marker key={d.code} coordinates={d.coordinates}>
                                    {isLowMargin && (
                                        <circle
                                            r={sizeScale(d.sizeValue) + 3}
                                            fill="none"
                                            stroke="#f59e0b"
                                            strokeWidth={1.5}
                                            strokeOpacity={0.8}
                                        />
                                    )}
                                    {isHighTacos && (
                                        <circle
                                            r={sizeScale(d.sizeValue) + 5}
                                            fill="none"
                                            stroke="#8b5cf6"
                                            strokeWidth={1}
                                            strokeDasharray="2 2"
                                            strokeOpacity={0.9}
                                        />
                                    )}
                                    <circle
                                        r={sizeScale(d.sizeValue)}
                                        fill={mode === 'ABSOLUTE' ? colorScale(
                                          colorMetric === 'REVENUE' ? d.revenue :
                                          colorMetric === 'PROFIT' ? d.profit :
                                          colorMetric === 'MARGIN' ? d.margin :
                                          colorMetric === 'TACOS' ? d.tacos :
                                          d.returnRate
                                        ) : deltaColor(d.value)}
                                        fillOpacity={0.7}
                                        stroke={isPinned ? themeColor : '#fff'}
                                        strokeWidth={isPinned ? 2.5 : 1}
                                        className="cursor-pointer hover:opacity-100 transition-all"
                                        onMouseEnter={() => setHoveredArea(d)}
                                        onMouseLeave={() => setHoveredArea(null)}
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setPinnedArea(prev => (prev && prev.code === d.code) ? null : d);
                                        }}
                                    />
                                </Marker>
                            );
                        })}
                    </ZoomableGroup>
                </ComposableMap>

                {/* Floating Tooltip */}
                {areaToShow && (
                    <div className="absolute top-4 right-4 bg-white/95 backdrop-blur shadow-lg rounded-lg p-3 border border-gray-100 w-60 pointer-events-none z-10">
                        <div className="flex justify-between items-center mb-2 pb-2 border-b border-gray-100">
                            <span className="font-bold text-gray-900 text-lg">{getAreaDisplayName(areaToShow.code)}</span>
                            <span className="text-xs font-medium text-gray-500">#{areaToShow.rank}</span>
                        </div>
                        <div className="space-y-1.5 text-sm">
                            {mode === 'ABSOLUTE' ? (
                                <>
                                    <div className="flex justify-between">
                                        <span className="text-gray-500">Revenue</span>
                                        <span className="font-bold text-theme">£{areaToShow.revenue.toLocaleString(undefined, { maximumFractionDigits: 0 })}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-gray-500">Volume</span>
                                        <span className="font-bold text-gray-800">{areaToShow.volume} units</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-gray-500">Orders</span>
                                        <span className="font-bold text-gray-800">{areaToShow.orders}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-gray-500">Profit</span>
                                        <span className={`font-bold ${areaToShow.profit >= 0 ? 'text-green-600' : 'text-red-600'}`}>£{areaToShow.profit.toLocaleString(undefined, { maximumFractionDigits: 0 })}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-gray-500">Margin</span>
                                        <span className={`font-bold ${areaToShow.margin >= 15 ? 'text-green-600' : areaToShow.margin > 0 ? 'text-amber-600' : 'text-red-600'}`}>{areaToShow.margin.toFixed(1)}%</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-gray-500">Return Rate</span>
                                        <span className={`font-bold ${areaToShow.returnRate > 5 ? 'text-red-600' : 'text-gray-800'}`}>{areaToShow.returnRate.toFixed(1)}%</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-gray-500">Ad Spend</span>
                                        <span className="font-bold text-orange-600">£{areaToShow.adSpend.toLocaleString(undefined, { maximumFractionDigits: 0 })}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="text-gray-500">TACoS</span>
                                        <span className={`font-bold ${areaToShow.tacos > 15 ? 'text-red-600' : 'text-gray-800'}`}>{areaToShow.tacos.toFixed(1)}%</span>
                                    </div>
                                    {areaToShow.platformBreakdown.length > 0 &&
                                      <div className="flex justify-between text-xs pt-1 border-t border-gray-100 mt-1">
                                          <span className="text-gray-500">Top Platform</span>
                                          <span className="font-medium text-gray-800">
                                              {areaToShow.platformBreakdown[0].platform} ({((areaToShow.platformBreakdown[0].revenue / areaToShow.revenue) * 100).toFixed(0)}%)
                                          </span>
                                      </div>
                                    }
                                </>
                            ) : (
                                <>
                                    <div className="flex justify-between">
                                        <span className="text-gray-500">Current</span>
                                        <span className="font-bold text-theme">{metric === 'REVENUE' ? `£${areaToShow.revenue.toLocaleString(undefined, { maximumFractionDigits: 0 })}` : `${areaToShow.volume} u`}</span>
                                    </div>
                                     <div className="flex justify-between">
                                        <span className="text-gray-500">Previous</span>
                                        <span className="font-bold text-gray-600">{metric === 'REVENUE' ? `£${areaToShow.prevRevenue.toLocaleString(undefined, { maximumFractionDigits: 0 })}` : `${areaToShow.prevVolume} u`}</span>
                                    </div>
