                                </th>
                                <th className="p-4 text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredAndSortedGroups.length > 0 ? filteredAndSortedGroups.map(group => {
                                const isSelected = selectedIds.has(group.id);
