                                            const isSelected = modalData.memberSkus?.includes(product.sku);
                                            return (
                                                <div
                                                    key={product.sku}
                                                    onClick={() => {
                                                        const current = modalData.memberSkus || [];
                                                        setModalData({
                                                            ...modalData,
                                                            memberSkus: isSelected ? current.filter(s => s !== product.sku) : [...current, product.sku]
