import React, { useState } from 'react';
import { X } from 'lucide-react';
import { Product, PricingRules } from '../../../types';

interface AliasDrawerProps {
    product: Product;
    pricingRules: PricingRules;
    onClose: () => void;
    onSave: (p: Product) => void;
    themeColor: string;
}

export const AliasDrawer: React.FC<AliasDrawerProps> = ({ product, pricingRules, onClose, onSave, themeColor }) => {
    const [platformTags, setPlatformTags] = useState<{ platform: string; tags: string[] }[]>(() => {
        const existing = product.channels.map((c:any) => ({ platform: c.platform, tags: c.skuAlias ? c.skuAlias.split(',').map((s:string) => s.trim()).filter(Boolean) : [] }));
        Object.keys(pricingRules).forEach(pKey => { if (!existing.find((e:any) => e.platform === pKey)) existing.push({ platform: pKey, tags: [] }); });
        return existing;
    });
    const [inputValues, setInputValues] = useState<Record<string, string>>({});

    const addTags = (platform: string, newTags: string[]) => {
        setPlatformTags(prev => prev.map(p => p.platform === platform ? { ...p, tags: [...new Set([...p.tags, ...newTags])] } : p));
    };

    const handleSave = () => {
        const updatedChannels = [...product.channels];
        platformTags.forEach(pt => {
            const aliasString = pt.tags.join(', ');
            const idx = updatedChannels.findIndex(c => c.platform === pt.platform);
            if (idx >= 0) updatedChannels[idx] = { ...updatedChannels[idx], skuAlias: aliasString };
            else if (aliasString) updatedChannels.push({ platform: pt.platform, manager: 'Unassigned', velocity: 0, skuAlias: aliasString });
        });
        onSave({ ...product, channels: updatedChannels });
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 flex justify-end">
            <div className="fixed inset-0 bg-black/20 backdrop-blur-sm" onClick={onClose}></div>
            <div className="bg-white w-full max-w-md h-full shadow-2xl relative flex flex-col animate-in slide-in-from-right">
                <div className="p-6 border-b flex justify-between items-center bg-gray-50">
                    <h3 className="font-bold text-lg">Manage Aliases</h3>
                    <button onClick={onClose}><X className="w-5 h-5 text-gray-500" /></button>
                </div>
                <div className="p-6 flex-1 overflow-y-auto space-y-6">
                    {platformTags.map(item => (
                        <div key={item.platform}>
                            <label className="text-[10px] font-medium text-gray-500 uppercase tracking-wide">{item.platform}</label>
                            <div className="flex flex-wrap gap-2 p-2 border rounded-lg mt-1 focus-within:ring-2 focus-within:ring-theme">
                                {item.tags.map((tag:string, i:number) => (
                                    <span key={i} className="px-2 py-1 bg-theme-10 text-theme rounded text-xs flex items-center gap-1">
                                        {tag} <button onClick={() => setPlatformTags(prev => prev.map(p => p.platform === item.platform ? { ...p, tags: p.tags.filter((_, idx) => idx !== i) } : p))}><X className="w-3 h-3" /></button>
                                    </span>
                                ))}
                                <input 
                                    type="text" 
                                    className="flex-1 min-w-[80px] outline-none text-sm" 
                                    placeholder="Add alias..." 
                                    value={inputValues[item.platform] || ''}
                                    onChange={e => setInputValues({...inputValues, [item.platform]: e.target.value})}
                                    onKeyDown={e => {
                                        if (e.key === 'Enter' && inputValues[item.platform]) {
                                            addTags(item.platform, [inputValues[item.platform]]);
                                            setInputValues({...inputValues, [item.platform]: ''});
                                        }
                                    }}
                                />
                            </div>
                        </div>
                    ))}
                </div>
                <div className="p-4 border-t flex justify-end gap-2">
                    <button onClick={onClose} className="px-4 py-2 border rounded hover:bg-gray-50">Cancel</button>
                    <button onClick={handleSave} className="px-4 py-2 bg-theme text-white rounded hover:bg-theme">Save</button>
                </div>
            </div>
        </div>
    );
};

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { ResponsiveContainer, ScatterChart, Scatter, XAxis, YAxis, ZAxis, CartesianGrid, Tooltip, ReferenceLine, ReferenceArea, Cell, LabelList } from 'recharts';
import { ProductTrendData } from '../../../services/productTrendAgg';
import { formatMoney, formatSmartMoney, formatNumber, formatPct } from '../../../utils/format';
import { Search, Info, Filter, MousePointerClick, Scale, DollarSign, Percent, Plus, Minus, RotateCcw } from 'lucide-react';

interface BcgMatrixProps {
    data: ProductTrendData[];
    onDeepDive: (sku: string) => void;
}

type LimitPercent = 10 | 25 | 50 | 100;
type FilterMode = 'REVENUE' | 'BALANCED';
type XAxisMetric = 'REVENUE' | 'MARGIN';

export const BcgMatrix: React.FC<BcgMatrixProps> = ({ data, onDeepDive }) => {
    const [limitPct, setLimitPct] = useState<LimitPercent>(25); 
    const [filterMode, setFilterMode] = useState<FilterMode>('BALANCED');
    const [xAxisMetric, setXAxisMetric] = useState<XAxisMetric>('REVENUE');

    // Zoom & Pan State
    const [xDomain, setXDomain] = useState<[number, number] | null>(null);
    const [yDomain, setYDomain] = useState<[number, number] | null>(null);
    const [isDragging, setIsDragging] = useState(false);

    // References for interaction
    const containerRef = useRef<HTMLDivElement>(null);
    const dragRef = useRef<{ startX: number, startY: number, startXDom: [number, number], startYDom: [number, number] } | null>(null);
    const boundsRef = useRef<{ x: [number, number], y: [number, number] } | null>(null);

    // 1. Prepare Data & Calculate Thresholds
    const { displayData, xMedian, showingCount, totalCount } = useMemo(() => {
        // Filter out zero-revenue items to keep chart relevant
        const validItems = data
            .filter(p => (p.current.revenue || 0) > 0)
            .map(p => {
                // Parse and sanitize growth
                const rawGrowth = p.deltas.unitsDeltaPct;

                let effectiveGrowth = 0;
                let isNew = false;

                if (rawGrowth === null) {
                    effectiveGrowth = 200; // New products go to top
                    isNew = true;
                } else if (!isFinite(rawGrowth)) {
                    effectiveGrowth = 0;
                } else {
                    effectiveGrowth = rawGrowth;
                }

                // Strict Visual Clamping for Y-Axis
                const vizGrowth = Math.max(-100, Math.min(effectiveGrowth, 200));

                return {
                    ...p,
                    vizGrowth,
                    isNew,
                    rawGrowth,
                    xValue: xAxisMetric === 'REVENUE' ? p.current.revenue : p.current.marginPct
                };
            });

        // Calculate Median for X-Axis using ALL valid data (Global Context)
        const xValues = validItems.map(p => p.xValue).sort((a, b) => a - b);

        const getMedian = (arr: number[]) => {
            if (arr.length === 0) return 0;
            const mid = Math.floor(arr.length / 2);
            return arr.length % 2 !== 0 ? arr[mid] : (arr[mid - 1] + arr[mid]) / 2;
        };

        const xMed = getMedian(xValues);
        const yMed = 0; // Standard BCG growth split

        // Logic Selection
        const totalItems = validItems.length;
        const targetCount = limitPct === 100 ? totalItems : Math.ceil(totalItems * (limitPct / 100));

        let finalData = [];

        if (filterMode === 'REVENUE' || limitPct === 100) {
            // Dynamic Top N based on current X Axis Metric (Revenue or Margin)
            finalData = [...validItems]
                .sort((a, b) => b.xValue - a.xValue)
                .slice(0, targetCount);
        } else {
            // BALANCED: Try to get equal representation from all quadrants based on CURRENT AXIS
            // Sort by Revenue (Importance) within quadrants to keep the most relevant items visible
            const stars = validItems.filter(i => i.xValue >= xMed && i.vizGrowth >= yMed).sort((a,b) => b.current.revenue - a.current.revenue);
            const cows = validItems.filter(i => i.xValue >= xMed && i.vizGrowth < yMed).sort((a,b) => b.current.revenue - a.current.revenue);
            const questions = validItems.filter(i => i.xValue < xMed && i.vizGrowth >= yMed).sort((a,b) => b.current.revenue - a.current.revenue); 
            const dogs = validItems.filter(i => i.xValue < xMed && i.vizGrowth < yMed).sort((a,b) => b.current.revenue - a.current.revenue);

            const quotaPerQuad = Math.ceil(targetCount / 4);

            const take = (arr: any[], limit: number) => {
                const taken = arr.slice(0, limit);
                return { taken, remainder: Math.max(0, limit - arr.length) };
            };

            const r1 = take(stars, quotaPerQuad);
            const r2 = take(cows, quotaPerQuad);
            const r3 = take(questions, quotaPerQuad);
            const r4 = take(dogs, quotaPerQuad);

            let pooled = [...r1.taken, ...r2.taken, ...r3.taken, ...r4.taken];

            // If we haven't met the total target count, fill with top revenue from remaining
            if (pooled.length < targetCount) {
                const usedIds = new Set(pooled.map(x => x.sku));
                const remainingItems = validItems
                    .filter(x => !usedIds.has(x.sku))
                    .sort((a, b) => b.current.revenue - a.current.revenue);

                const needed = targetCount - pooled.length;
                pooled = [...pooled, ...remainingItems.slice(0, needed)];
            }

            finalData = pooled;
        }

        return {
            displayData: finalData, // Actual rendered dots
            xMedian: xMed,
            showingCount: finalData.length,
            totalCount: totalItems
        };
    }, [data, limitPct, filterMode, xAxisMetric]);

    // Update domains when data view changes
    useEffect(() => {
        if (displayData.length > 0) {
            const xValues = displayData.map(d => d.xValue);
            const minX = Math.min(...xValues);
            const maxX = Math.max(...xValues);
            const paddingX = (maxX - minX) * 0.05 || (maxX * 0.05) || 10;

            const newXDom: [number, number] = [Math.max(0, minX - paddingX), maxX + paddingX];
            // Base Y Domain matching visual design [-100, 220]
            const newYDom: [number, number] = [-100, 220]; 

            setXDomain(newXDom);
            setYDomain(newYDom);

            // Store bounds for clamping
            boundsRef.current = { x: newXDom, y: newYDom };
        }
    }, [displayData, xAxisMetric]);

    const handleZoom = (direction: 'in' | 'out') => {
        if (!xDomain || !yDomain) return;
        const factor = direction === 'in' ? 0.8 : 1.25;

        const xRange = xDomain[1] - xDomain[0];
        const yRange = yDomain[1] - yDomain[0];
        const newXRange = xRange * factor;
        const newYRange = yRange * factor;

        const xCenter = (xDomain[0] + xDomain[1]) / 2;
        const yCenter = (yDomain[0] + yDomain[1]) / 2;

        const nextX: [number, number] = [xCenter - newXRange / 2, xCenter + newXRange / 2];
        const nextY: [number, number] = [yCenter - newYRange / 2, yCenter + newYRange / 2];

        // Clamp Zoom Out to max bounds
        if (direction === 'out' && boundsRef.current) {
            const bx = boundsRef.current.x;
            const by = boundsRef.current.y;
            if (nextX[0] < bx[0]) nextX[0] = bx[0];
            if (nextX[1] > bx[1]) nextX[1] = bx[1];
            if (nextY[0] < by[0]) nextY[0] = by[0];
            if (nextY[1] > by[1]) nextY[1] = by[1];
        }

        setXDomain(nextX);
        setYDomain(nextY);
    };

    const handleReset = () => {
        if (boundsRef.current) {
            setXDomain(boundsRef.current.x);
            setYDomain(boundsRef.current.y);
        }
    };

    const handleMouseDown = (e: React.MouseEvent) => {
        // Prevent pan start if clicking on a point
        if ((e.target as Element).closest('.recharts-scatter-symbol')) return;

        if (xDomain && yDomain) {
            setIsDragging(true);
            dragRef.current = {
                startX: e.clientX,
                startY: e.clientY,
                startXDom: xDomain,
                startYDom: yDomain
            };
        }
    };

    const handleMouseMove = (e: React.MouseEvent) => {
        if (!isDragging || !dragRef.current || !containerRef.current) return;
        e.preventDefault();

        const { startX, startY, startXDom, startYDom } = dragRef.current;
        const dx = e.clientX - startX;
        const dy = e.clientY - startY;

        // Chart plotting area approx dimensions (container size - margins)
        const { width, height } = containerRef.current.getBoundingClientRect();
        const plotW = width - 80; // left 60 + right 20
        const plotH = height - 60; // top 20 + bottom 40

        const xRange = startXDom[1] - startXDom[0];
        const yRange = startYDom[1] - startYDom[0];

        const xShift = -(dx / plotW) * xRange;
        const yShift = (dy / plotH) * yRange; 

        let nextX: [number, number] = [startXDom[0] + xShift, startXDom[1] + xShift];
        let nextY: [number, number] = [startYDom[0] + yShift, startYDom[1] + yShift];

        // Clamp to bounds
        if (boundsRef.current) {
            const bx = boundsRef.current.x;
            const by = boundsRef.current.y;

            if (nextX[0] < bx[0]) nextX = [bx[0], bx[0] + (nextX[1] - nextX[0])];
            if (nextX[1] > bx[1]) nextX = [bx[1] - (nextX[1] - nextX[0]), bx[1]];

            if (nextY[0] < by[0]) nextY = [by[0], by[0] + (nextY[1] - nextY[0])];
            if (nextY[1] > by[1]) nextY = [by[1] - (nextY[1] - nextY[0]), by[1]];
        }

        setXDomain(nextX);
        setYDomain(nextY);
    };

    const handleMouseUp = () => setIsDragging(false);

    // 2. Define Custom Tooltip
    const CustomTooltip = ({ active, payload }: any) => {
        if (active && payload && payload.length) {
            const d = payload[0].payload;
            return (
                <div className="bg-white/95 backdrop-blur-md border border-gray-200 p-3 rounded-xl shadow-xl text-xs z-50">
                    <div className="font-bold text-gray-900 mb-1 border-b border-gray-100 pb-1 flex justify-between gap-4">
                        <span className="font-mono">{d.sku}</span>
                        {d.isNew && <span className="text-[9px] bg-green-100 text-green-700 px-1.5 rounded-full">NEW</span>}
                    </div>
                    <div className="text-[10px] text-gray-500 mb-2 max-w-[200px] truncate">{d.name}</div>
                    <div className="space-y-1">
                        <div className="flex justify-between gap-4">
                            <span className="text-gray-500">Revenue:</span>
                            <span className="font-mono font-bold text-theme">{formatSmartMoney(d.current.revenue)}</span>
                        </div>
                        <div className="flex justify-between gap-4">
                            <span className="text-gray-500">Margin:</span>
                            <span className={`font-mono font-bold ${d.current.marginPct >= 10 ? 'text-green-600' : 'text-red-500'}`}>{formatPct(d.current.marginPct)}</span>
                        </div>
                        <div className="flex justify-between gap-4">
                            <span className="text-gray-500">Volume Growth:</span>
                            <span className={`font-mono font-bold ${d.vizGrowth > 0 ? 'text-green-600' : d.vizGrowth < 0 ? 'text-red-600' : 'text-gray-600'}`}>
                                {d.isNew ? 'New (∞)' : `${d.rawGrowth > 0 ? '+' : ''}${d.rawGrowth.toFixed(1)}%`}
                            </span>
                        </div>
                         <div className="flex justify-between gap-4">
                            <span className="text-gray-500">Net Profit:</span>
                            <span className={`font-mono font-bold ${d.current.netProfit > 0 ? 'text-green-600' : 'text-red-600'}`}>
                                {formatSmartMoney(d.current.netProfit)}
                            </span>
                        </div>
                    </div>
                    <div className="mt-2 pt-1 border-t border-gray-100 text-[9px] text-theme font-medium flex items-center justify-center gap-1">
                        <Search className="w-3 h-3" /> Click to Deep Dive
                    </div>
                </div>
            );
        }
        return null;
    };

    if (totalCount === 0) {
        return (
            <div className="h-[500px] flex items-center justify-center text-gray-400 bg-gray-50 rounded-xl border border-dashed border-gray-200">
                Not enough data to generate matrix.
            </div>
        )
    }

    const xLabel = xAxisMetric === 'REVENUE' ? 'Rev' : 'Margin';

    return (
        <div className="space-y-4">
            {/* Explanation / Legend */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <div className="p-2.5 bg-white rounded-lg border border-gray-200 shadow-sm flex items-center gap-3">
                    <div className="w-8 h-8 rounded-md bg-green-100 flex items-center justify-center text-lg">🌟</div>
                    <div>
                        <div className="text-[10px] font-bold text-green-700 uppercase">Stars</div>
                        <div className="text-[9px] text-gray-500">High {xLabel} / Growing</div>
                    </div>
                </div>
                <div className="p-2.5 bg-white rounded-lg border border-gray-200 shadow-sm flex items-center gap-3">
                    <div className="w-8 h-8 rounded-md bg-yellow-100 flex items-center justify-center text-lg">🐄</div>
                    <div>
                        <div className="text-[10px] font-bold text-yellow-700 uppercase">Cash Cows</div>
                        <div className="text-[9px] text-gray-500">High {xLabel} / Stable</div>
                    </div>
                </div>
                <div className="p-2.5 bg-white rounded-lg border border-gray-200 shadow-sm flex items-center gap-3">
                    <div className="w-8 h-8 rounded-md bg-theme-10 flex items-center justify-center text-lg">❓</div>
                    <div>
                        <div className="text-[10px] font-bold text-theme uppercase">Questions</div>
                        <div className="text-[9px] text-gray-500">Low {xLabel} / Growing</div>
                    </div>
                </div>
                <div className="p-2.5 bg-white rounded-lg border border-gray-200 shadow-sm flex items-center gap-3">
                    <div className="w-8 h-8 rounded-md bg-red-100 flex items-center justify-center text-lg">🐕</div>
                    <div>
                        <div className="text-[10px] font-bold text-red-700 uppercase">Dogs</div>
                        <div className="text-[9px] text-gray-500">Low {xLabel} / Declining</div>
                    </div>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-lg border border-gray-200 p-4 h-[600px] relative flex flex-col">
                <div className="flex flex-wrap justify-between items-center mb-2 gap-3 relative z-0">
                    <div className="flex items-center gap-1.5 text-[9px] text-gray-400 bg-gray-50 px-2 py-1 rounded border border-gray-100">
                        <Info className="w-3 h-3" />
                        <span>Showing <strong>{limitPct}%</strong> ({showingCount} products)</span>
                    </div>

                    <div className="flex flex-wrap items-center gap-2">
                         {/* X-Axis Toggle */}
                         <div className="flex bg-gray-100 p-0.5 rounded-lg">
                            <button
                                onClick={() => setXAxisMetric('REVENUE')}
                                className={`px-2 py-1 text-[10px] font-bold rounded-md transition-all flex items-center gap-1 ${
                                    xAxisMetric === 'REVENUE' 
                                    ? 'bg-white text-green-700 shadow-sm' 
                                    : 'text-gray-500 hover:text-gray-700'
                                }`}
                                title="X-Axis: Revenue"
                            >
                                <DollarSign className="w-3 h-3" /> Revenue
                            </button>
                            <button
                                onClick={() => setXAxisMetric('MARGIN')}
                                className={`px-2 py-1 text-[10px] font-bold rounded-md transition-all flex items-center gap-1 ${
                                    xAxisMetric === 'MARGIN' 
                                    ? 'bg-white text-theme shadow-sm' 
                                    : 'text-gray-500 hover:text-gray-700'
                                }`}
                                title="X-Axis: Margin %"
                            >
                                <Percent className="w-3 h-3" /> Margin
                            </button>
                        </div>

                        <div className="h-4 w-px bg-gray-200"></div>

                        {/* Sampling Mode Toggle */}
                        <div className="flex bg-gray-100 p-0.5 rounded-lg">
                            <button
                                onClick={() => setFilterMode('REVENUE')}
                                className={`px-2 py-1 text-[10px] font-bold rounded-md transition-all flex items-center gap-1 ${
                                    filterMode === 'REVENUE' 
                                    ? 'bg-white text-theme shadow-sm' 
                                    : 'text-gray-500 hover:text-gray-700'
                                }`}
                                title={xAxisMetric === 'REVENUE' ? "Always show top products by Revenue" : "Always show top products by Margin"}
                            >
                                {xAxisMetric === 'REVENUE' ? <DollarSign className="w-3 h-3" /> : <Percent className="w-3 h-3" />}
                                {xAxisMetric === 'REVENUE' ? 'Top Rev' : 'Top Margin'}
                            </button>
                            <button
                                onClick={() => setFilterMode('BALANCED')}
                                className={`px-2 py-1 text-[10px] font-bold rounded-md transition-all flex items-center gap-1 ${
                                    filterMode === 'BALANCED' 
                                    ? 'bg-white text-theme shadow-sm' 
                                    : 'text-gray-500 hover:text-gray-700'
                                }`}
                                title="Equal representation from Stars, Cows, Questions, Dogs"
                            >
                                <Scale className="w-3 h-3" /> Balanced
                            </button>
                        </div>

                        <div className="h-4 w-px bg-gray-200"></div>

                        {/* Limit Toggle */}
                        <div className="flex bg-gray-100 p-0.5 rounded-lg">
                            {([10, 25, 50, 100] as const).map((opt) => (
                                <button
                                    key={opt}
                                    onClick={() => setLimitPct(opt)}
                                    className={`px-3 py-1 text-[10px] font-bold rounded-md transition-all ${
                                        limitPct === opt 
                                        ? 'bg-white text-theme shadow-sm' 
                                        : 'text-gray-500 hover:text-gray-700'
                                    }`}
                                >
                                    {opt === 100 ? 'All' : `Top ${opt}%`}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                <div 
                    className={`flex-1 min-h-0 w-full relative ${isDragging ? 'cursor-grabbing' : 'cursor-grab'}`}
                    ref={containerRef}
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                >
                    {/* Map Controls */}
                    <div className="absolute top-2 right-2 z-20 flex flex-col gap-1.5 bg-white/90 p-1.5 rounded-lg border border-gray-200 shadow-sm backdrop-blur-sm">
                         <button onClick={() => handleZoom('in')} className="p-1 text-gray-500 hover:text-theme hover:bg-gray-100 rounded transition-colors" title="Zoom In"><Plus className="w-4 h-4" /></button>
                         <button onClick={() => handleZoom('out')} className="p-1 text-gray-500 hover:text-theme hover:bg-gray-100 rounded transition-colors" title="Zoom Out"><Minus className="w-4 h-4" /></button>
                         <div className="w-full h-px bg-gray-200 my-0.5"></div>
                         <button onClick={handleReset} className="p-1 text-gray-500 hover:text-red-600 hover:bg-gray-100 rounded transition-colors" title="Reset View"><RotateCcw className="w-4 h-4" /></button>
                    </div>

                    {limitPct === 100 && totalCount > 2000 && (
                        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-20 pointer-events-none bg-red-50 text-red-600 px-4 py-2 rounded-lg border border-red-100 shadow-lg text-xs font-bold ">
                            Warning: Rendering {totalCount} items may cause lag.
                        </div>
                    )}

                    <ResponsiveContainer width="100%" height="100%">
                        <ScatterChart margin={{ top: 20, right: 20, bottom: 40, left: 60 }}>
                            <CartesianGrid strokeDasharray="3 3" stroke="#f3f4f6" />

                            {/* X Axis: Revenue OR Margin */}
                            <XAxis 
                                type="number" 
                                dataKey="xValue" 
                                name={xAxisMetric === 'REVENUE' ? "Revenue" : "Margin"}
                                unit={xAxisMetric === 'REVENUE' ? "£" : "%"}
                                domain={xDomain ? xDomain : (xAxisMetric === 'REVENUE' ? [0, 'auto'] : ['auto', 'auto'])}
                                allowDataOverflow={true} 
                                tickFormatter={(val) => xAxisMetric === 'REVENUE' ? `£${formatNumber(val)}` : `${val.toFixed(0)}%`}
                                label={{ value: xAxisMetric === 'REVENUE' ? 'Revenue (Relative Market Share)' : 'Net Profit Margin %', position: 'bottom', offset: 0, fontSize: 11, fill: '#6b7280' }}
                                tick={{ fontSize: 10, fill: '#9ca3af' }}
                            />

                            {/* Y Axis: Growth % (Using clamped vizGrowth for display) */}
                            <YAxis 
                                type="number" 
                                dataKey="vizGrowth" 
                                name="Growth" 
                                unit="%" 
                                domain={yDomain ? yDomain : [-100, 220]} 
                                allowDataOverflow={true}
                                label={{ value: 'Volume Growth % (PoP)', angle: -90, position: 'left', offset: 0, fontSize: 11, fill: '#6b7280' }}
                                tick={{ fontSize: 10, fill: '#9ca3af' }}
                                ticks={[-100, -50, 0, 50, 100, 150, 200]}
                            />

                            {/* Z Axis: Profit Size */}
                            <ZAxis type="number" dataKey="current.netProfit" range={[60, 800]} name="Profit" />

                            {/* Tooltip with high Z-Index to stay above filters */}
                            <Tooltip content={<CustomTooltip />} cursor={{ strokeDasharray: '3 3' }} wrapperStyle={{ zIndex: 1000 }} />

                            {/* Reference Lines for Quadrants */}
                            <ReferenceLine x={xMedian} stroke="#9ca3af" strokeDasharray="3 3" label={{ value: `Median ${xLabel}`, position: 'insideTopRight', fill: '#9ca3af', fontSize: 10, angle: 90 }} />
                            <ReferenceLine y={0} stroke="#9ca3af" strokeWidth={2} label={{ value: "No Growth", position: 'insideRight', fill: '#9ca3af', fontSize: 10 }} />

                            {/* Quadrant Backgrounds (Subtle) */}
                            {/* Q1: Stars (High X, High Growth) */}
                            <ReferenceArea x1={xMedian} y1={0} y2={220} fill="#22c55e" fillOpacity={0.03} />
                            {/* Q2: Questions (Low X, High Growth) */}
                            <ReferenceArea x2={xMedian} y1={0} y2={220} fill="#6366f1" fillOpacity={0.03} />
                            {/* Q3: Dogs (Low X, Neg Growth) */}
                            <ReferenceArea x2={xMedian} y1={-100} y2={0} fill="#ef4444" fillOpacity={0.03} />
                            {/* Q4: Cows (High X, Neg Growth) */}
                            <ReferenceArea x1={xMedian} y1={-100} y2={0} fill="#eab308" fillOpacity={0.03} />

                            <Scatter name="Products" data={displayData} onClick={(p) => onDeepDive(p.sku)}>
                                {displayData.map((entry, index) => {
                                    const isHighX = entry.xValue >= xMedian;
                                    const isGrowing = entry.vizGrowth >= 0;

                                    let color = '#9ca3af';
                                    if (isHighX && isGrowing) color = '#22c55e'; // Star
                                    else if (isHighX && !isGrowing) color = '#eab308'; // Cow
                                    else if (!isHighX && isGrowing) color = '#6366f1'; // Question
                                    else color = '#ef4444'; // Dog

                                    return (
                                        <Cell 
                                            key={`cell-${index}`} 
                                            fill={color} 
                                            stroke={color} 
                                            fillOpacity={0.5} 
                                            className="cursor-pointer hover:opacity-100 transition-opacity duration-200" 
                                        />
                                    );
                                })}
                            </Scatter>
                        </ScatterChart>
                    </ResponsiveContainer>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { formatSmartMoney } from '../../../utils/format';
import { createPortal } from 'react-dom';
import { Product, PricingRules, SkuFamily, PriceLog, OptimalPriceResult } from '../../../types';
import { VAT_MULTIPLIER } from '../../../constants';
import { getCanonicalSku } from '../../../services/skuNormalization';
import * as XLSX from 'xlsx-js-style';
import { FilterBar } from '../../common/FilterBar';
import { GradeBadge } from '../../common/GradeBadge';
import { Search, TrendingUp, TrendingDown, ChevronLeft, ChevronRight, Download, ArrowRight, ChevronDown, Star, X, Layers, Tag, Info, GitMerge, User, Globe, CornerDownLeft, List, Ship, LineChart, Zap, Eye, CheckSquare, Square } from 'lucide-react';
import { SortState, sortRows } from '../../../utils/tableSort';
import { SortableHeader } from '../../common/SortableHeader';

interface ProductListProps {
    products: Product[];
    skuFamilies?: SkuFamily[]; // Added
    onEditAliases?: (product: Product) => void;
    onEditTags?: (product: Product) => void;
    onViewShipments?: (sku: string) => void;
    onViewElasticity?: (product: Product, result?: OptimalPriceResult) => void;
    onDeepDive?: (sku: string) => void;
    pricingRules?: PricingRules;
    themeColor: string;
    priceHistoryMap: Map<string, PriceLog[]>;
    optimalPriceResults?: Map<string, OptimalPriceResult>;
}

const RecommendationTooltip = ({ product, rect }: { product: Product, rect: DOMRect }) => {
    // Add Scroll Offset to ensure fixed position works correctly on scrolled pages
    const scrollY = window.scrollY;
    const scrollX = window.scrollX;

    const style: React.CSSProperties = {
        position: 'absolute',
        top: `${rect.top + scrollY}px`,
        left: `${rect.left + rect.width / 2 + scrollX}px`,
        transform: 'translate(-50%, -100%) translateY(-8px)',
        zIndex: 9999,
        pointerEvents: 'none'
    };

    return createPortal(
        <div style={style} className="animate-in fade-in zoom-in duration-200">
            <div className="bg-gray-900 text-white p-3 rounded-lg shadow-xl text-xs max-w-xs z-50 border border-gray-700 backdrop-blur-md bg-opacity-95">
                <div className="font-bold mb-2 border-b border-gray-700 pb-1 flex items-center gap-2">
                    <span className={`w-2 h-2 rounded-full ${product.status === 'Critical' ? 'bg-red-500' :
                        product.status === 'Overstock' ? 'bg-orange-500' :
                            product.status === 'Warning' ? 'bg-amber-500' : 'bg-green-500'
                        }`}></span>
                    Inventory Intelligence
                </div>
                <div className="space-y-1.5">
                    <div className="grid grid-cols-2 gap-x-4 gap-y-1">
                        <span className="text-gray-400">Status:</span>
                        <span className={`font-bold text-right ${product.status === 'Critical' ? 'text-red-400' :
                            product.status === 'Overstock' ? 'text-orange-400' :
                                product.status === 'Warning' ? 'text-amber-400' : 'text-green-400'
                            }`}>{product.status}</span>

                        <span className="text-gray-400">Action:</span>
                        <span className="text-right text-gray-200">{product.recommendation}</span>

                        <span className="text-gray-400">Runway:</span>
                        <span className="text-right text-gray-200">{product.daysRemaining > 730 ? '> 2 Years' : `${(product.daysRemaining / 7).toFixed(1)} Weeks`}</span>

                        <span className="text-gray-400">Lead Time:</span>
                        <span className="text-right text-gray-200">{product.leadTimeDays} Days</span>
                    </div>

                    {product.returnRate !== undefined && product.returnRate > 5 && (
                        <div className="mt-2 pt-2 border-t border-gray-700">
                            <div className="flex justify-between items-center text-red-400">
                                <span className="font-bold flex items-center gap-1"><CornerDownLeft className="w-3 h-3" /> High Returns</span>
                                <span>{product.returnRate.toFixed(1)}%</span>
                            </div>
                        </div>
                    )}
                </div>
            </div>
            <div className="absolute top-full left-1/2 -translate-x-1/2 -mt-1 border-4 border-transparent border-t-gray-900"></div>
        </div>,
        document.body
    );
};

interface ProductRowProps {
    product: Product;
    themeColor: string;
    onEditAliases?: (p: Product) => void;
    onEditTags?: (p: Product) => void;
    onViewShipments?: (sku: string) => void;
    onViewElasticity?: (p: Product, result?: OptimalPriceResult) => void;
    onDeepDive?: (sku: string) => void;
    hoveredProduct: { id: string; rect: DOMRect } | null;
    handleMouseEnter: (id: string, e: React.MouseEvent) => void;
    handleMouseLeave: () => void;
    priceHistoryMap: Map<string, PriceLog[]>;
    optimalPriceResults?: Map<string, OptimalPriceResult>;
}

const ProductRow = React.memo(({
    product,
    themeColor,
    onEditAliases,
    onEditTags,
    onViewShipments,
    onViewElasticity,
    onDeepDive,
    handleMouseEnter,
    handleMouseLeave,
    priceHistoryMap,
    optimalPriceResults,
}: ProductRowProps) => {

    const { totalAdSpend, acos } = useMemo(() => {
        if (!priceHistoryMap || !priceHistoryMap.get) return { totalAdSpend: 0, acos: null };
        const logs = priceHistoryMap.get(product.sku) || [];
        const adSpend = logs.reduce((sum, l) => sum + (l.adsSpend || 0), 0);
        const revenue = logs.reduce((sum, l) =>
            sum + (l.price * (l.velocity || 0) * VAT_MULTIPLIER), 0);
        const acosVal = revenue > 0 ? (adSpend / revenue) * 100 : null;
        return { totalAdSpend: adSpend, acos: acosVal };
    }, [product.sku, priceHistoryMap]);

    // Apply 20% VAT Uplift for Display using shared constant
    const currentPriceWithVat = (product.currentPrice || 0) * VAT_MULTIPLIER;
    const oldPriceWithVat = product.oldPrice ? product.oldPrice * VAT_MULTIPLIER : null;

    // Optimal Price Logic (Profit)
    const optimalPriceWithVat = product.optimalPrice ? product.optimalPrice * VAT_MULTIPLIER : null;

    // Max Velocity Price Logic (Volume Fallback)
    const volumePriceWithVat = product.maxVelocityPrice ? product.maxVelocityPrice * VAT_MULTIPLIER : null;

    const runwayWeeks = (product.daysRemaining || 0) / 7;
    const runwayBin = {
        label: runwayWeeks > 104 ? '> 2 Years' : `${runwayWeeks.toFixed(1)} Weeks`,
        color: product.status === 'Critical' ? 'badge-red' :
            product.status === 'Overstock' ? 'badge-orange' :
                product.status === 'Warning' ? 'badge-amber' : 'badge-green'
    };

    const isHighReturns = product.returnRate !== undefined && product.returnRate > 5;

    return (
        <tr key={product.id} className="group text-sm border-b border-gray-100/50 last:border-none">
            <td className="px-4 py-4 text-center w-[80px]">
                <div className="grid grid-cols-2 gap-1.5 w-fit mx-auto">
                    {onDeepDive && (
                        <button
                            onClick={() => onDeepDive(product.sku)}
                            className="text-gray-400 hover:text-theme transition-colors p-1.5 rounded hover:bg-theme-10 border border-transparent hover:border-indigo-100"
                            title="Deep Dive SKU Analysis"
                        >
                            <Search className="w-3.5 h-3.5" />
                        </button>
                    )}
                    {onViewElasticity && (
                        <button
                            onClick={() => onViewElasticity(product, optimalPriceResults?.get(getCanonicalSku(product.sku)))}
                            className="text-gray-400 hover:text-theme transition-colors p-1.5 rounded hover:bg-theme-10 border border-transparent hover:border-indigo-100"
                            title="View Price Curve"
                        >
                            <LineChart className="w-3.5 h-3.5" />
                        </button>
                    )}
                    {onEditTags && (
                        <button
                            onClick={() => onEditTags(product)}
                            className="text-gray-400 hover:text-sky-600 transition-colors p-1.5 rounded hover:bg-sky-50 border border-transparent hover:border-sky-100"
                            title="Edit Seasonal/Event Tags"
                        >
                            <Tag className="w-3.5 h-3.5" />
                        </button>
                    )}
                    {onEditAliases && (
                        <button
                            onClick={() => onEditAliases(product)}
                            className="text-gray-400 hover:text-amber-600 transition-colors p-1.5 rounded hover:bg-amber-50 border border-transparent hover:border-amber-100"
                            title="Edit Aliases / SKU Mapping"
                        >
                            <GitMerge className="w-3.5 h-3.5" />
                        </button>
                    )}
                </div>
            </td>
            <td className="px-4 py-4">
                <div>
                    <div className="flex items-center">
                        <div className="font-bold text-gray-900 font-mono">{product.sku}</div>
                        <GradeBadge gradeLevel={product.gradeLevel} />
                    </div>
                    <div className="text-gray-900 font-medium text-xs mt-1 truncate max-w-[240px] xl:max-w-[350px]" title={product.name}>{product.name}</div>
                    <div className="flex gap-2 mt-1.5">
                        {product.subcategory && (
                            <span className="text-[10px] bg-gray-100 text-gray-600 px-2 py-0.5 rounded border border-gray-200">{product.subcategory}</span>
                        )}
                    </div>
                    <div className="flex flex-wrap gap-1 mt-1.5">
                        {product.seasonTags?.slice(0, 2).map(tag => (
                            <span key={tag} className="text-[10px] bg-slate-100 text-slate-600 px-2 py-0.5 rounded-full border border-slate-200">{tag}</span>
                        ))}
                        {(product.seasonTags?.length || 0) > 2 && (
                            <span className="text-[10px] bg-slate-100 text-slate-600 px-2 py-0.5 rounded-full border border-slate-200">+{(product.seasonTags?.length || 0) - 2}</span>
                        )}
                        {product.festivalTags?.slice(0, 2).map(tag => (
                            <span key={tag} className="text-[10px] bg-slate-100 text-slate-600 px-2 py-0.5 rounded-full border border-slate-200">{tag}</span>
                        ))}
                        {(product.festivalTags?.length || 0) > 2 && (
                            <span className="text-[10px] bg-slate-100 text-slate-600 px-2 py-0.5 rounded-full border border-slate-200">+{(product.festivalTags?.length || 0) - 2}</span>
                        )}
                    </div>
                </div>
            </td>
            <td className="px-4 py-4 text-right">
                {(() => {
                    const result = optimalPriceResults?.get(getCanonicalSku(product.sku));
                    if (!result) {
                        // Fallback to old optimalPrice if no new result yet
                        return optimalPriceWithVat ? (
                            <div className="flex items-center justify-end gap-1 font-bold text-gray-400" title="Legacy optimal reference (recalculate benchmarks to update)">
                                <Star className="w-3 h-3" style={{ fill: 'rgba(156,163,175,0.2)' }} />
                                {formatSmartMoney(optimalPriceWithVat)}
                            </div>
                        ) : (
                            <span className="text-gray-300">-</span>
                        );
                    }
                    const isStale = Date.now() - new Date(result.calculatedAt).getTime() > 30 * 24 * 60 * 60 * 1000;
                    const delta = result.recommendedPrice - result.currentPrice;
                    const confidenceBadge = (() => {
                        if (result.source === 'COHORT' || result.confidence < 0.3)
                            return <span className="px-1 py-0.5 text-[8px] font-bold rounded border border-gray-200 text-gray-400">Bench</span>;
                        if (result.confidence >= 0.9)
                            return <span className="px-1 py-0.5 text-[8px] font-bold rounded bg-emerald-100 text-emerald-700">High</span>;
                        if (result.confidence >= 0.5)
                            return <span className="px-1 py-0.5 text-[8px] font-bold rounded bg-amber-100 text-amber-700">Med</span>;
                        return <span className="px-1 py-0.5 text-[8px] font-bold rounded bg-gray-100 text-gray-500">Low</span>;
                    })();
                    return (
                        <div className="group relative flex flex-col items-end gap-0.5">
                            <div className="flex items-center gap-1">
                                <span className="font-bold text-gray-900" style={{ fontSize: 13 }}>
                                    {formatSmartMoney(result.recommendedPrice)}
                                </span>
                                {isStale && <span title={`Last calculated ${new Date(result.calculatedAt).toLocaleDateString()}`} className="text-gray-400 text-[10px]">🕐</span>}
                            </div>
                            {Math.abs(delta) >= 0.01 && (
                                <span className={`text-[10px] font-bold ${delta > 0 ? 'text-emerald-600' : 'text-red-500'}`}>
                                    {delta > 0 ? '+' : ''}{formatSmartMoney(delta)}
                                </span>
                            )}
                            {confidenceBadge}
                            {/* Inline reasoning tooltip */}
                            <div className="absolute top-full right-0 mt-2 w-72 p-3 bg-gray-900 text-white text-[11px] rounded-xl shadow-2xl opacity-0 group-hover:opacity-100 invisible group-hover:visible transition-all pointer-events-none z-[60]">
                                <p className="leading-relaxed">{result.reasoning.split('. ').slice(0, 2).join('. ')}.</p>
                                <div className="mt-1.5 text-gray-400 text-[10px]">
                                    Last calculated: {new Date(result.calculatedAt).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}
                                </div>
                                <div className="absolute bottom-full right-4 -mb-1 border-4 border-transparent border-b-gray-900"></div>
                            </div>
                        </div>
                    );
                })()}
            </td>
            <td className="px-4 py-4 text-right">
                <div className="text-gray-400 font-medium">
                    {oldPriceWithVat ? formatSmartMoney(oldPriceWithVat) : '-'}
                </div>
            </td>
            <td className="px-4 py-4 text-right">
                <div className="font-bold text-gray-900">{formatSmartMoney(currentPriceWithVat)}</div>
            </td>
            <td className="px-4 py-4 text-right">
                {product.caPrice ? (
                    <div className="font-bold text-purple-600 font-mono" title="Channel Advisor Reference Price">
                        {formatSmartMoney(product.caPrice)}
                    </div>
                ) : (
                    <span className="text-gray-300">—</span>
                )}
            </td>

            <td className="px-4 py-4 text-right">
                <div className="flex flex-col items-end gap-0.5">
                    <span className="font-bold text-gray-900">{product.stockLevel}</span>
                    {product.incomingStock && product.incomingStock > 0 ? (
                        <button
                            onClick={(e) => {
                                e.stopPropagation();
                                if (onViewShipments) onViewShipments(product.sku);
                            }}
                            className="text-[10px] font-semibold text-theme bg-theme-10 px-1.5 py-0.5 rounded border border-indigo-100 flex items-center gap-1 hover:bg-theme-10 hover:border-theme-20 transition-colors cursor-pointer"
                            title="Click to view incoming shipments"
                        >
                            <Ship className="w-3 h-3" />
                            +{product.incomingStock}
                        </button>
                    ) : null}
                </div>
            </td>

            <td
                className="px-4 py-4 text-right cursor-help"
                onMouseEnter={(e) => handleMouseEnter(product.id, e)}
                onMouseLeave={handleMouseLeave}
            >
                <div className="flex flex-col items-end gap-1.5">
                    <span className={`sello-badge ${runwayBin.color}`}>
                        {runwayBin.label}
                    </span>
                    <div className="flex items-center gap-1">
                        {!!product._trendData?.velocityChange && product._trendData.velocityChange < -0.2 && <TrendingDown className="w-3 h-3 text-red-400" />}
                        {!!product._trendData?.velocityChange && product._trendData.velocityChange > 0.2 && <TrendingUp className="w-3 h-3 text-green-400" />}
                        <span className="text-xs font-semibold text-gray-700">
                            {(product.averageDailySales || 0).toFixed(1)} / day
                        </span>
                    </div>
                </div>
            </td>
            <td className="px-4 py-4 text-right">
                {product.returnRate !== undefined ? (
                    <div className={`flex items-center justify-end gap-1 font-medium ${isHighReturns ? 'text-red-600 font-bold' : 'text-gray-500'}`}>
                        {isHighReturns && <CornerDownLeft className="w-3 h-3" />}
                        {product.returnRate.toFixed(1)}%
                    </div>
                ) : <span className="text-gray-300">-</span>}
            </td>
            <td className="px-4 py-4 text-right">
                <div className="flex flex-col items-end">
                    <span className="text-orange-600 font-bold">
                        £{(totalAdSpend || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </span>
                    {totalAdSpend > 0 ? (
                        <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-bold mt-1 ${acos === null ? 'text-gray-400 italic' :
                            acos < 15 ? 'text-green-600 bg-green-50' :
                                acos <= 30 ? 'text-amber-600 bg-amber-50' : 'text-red-600 bg-red-50'
                            }`}>
                            {acos !== null ? `${acos.toFixed(1)}%` : 'No revenue'}
                        </span>
                    ) : (
                        <span className="text-[10px] text-gray-400 italic">No spend</span>
                    )}
