                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { RefundLog, Product, PricingRules, PriceLog, ReturnDateBasis } from '../../../types';
