import React, { useMemo } from 'react';
import { ChipSelectionState, Suggestion, SuggestionPriority } from './types';
import { getSuggestions } from '../../services/search/suggestionEngine';
import { TrendingUp, AlertTriangle, Package, Search, Zap, TrendingDown, DollarSign, Activity, BarChart2, ShoppingBag, Clock, ArrowRight, Filter, Globe, Tag } from 'lucide-react';
import { Product } from '../../types';
import { useTranslation } from 'react-i18next';

interface SearchAssistantPopoverProps {
  state: ChipSelectionState;
  onApply: (suggestion: Suggestion) => void;
  onClear: () => void;
  isVisible: boolean;
  products?: Product[];
}

const PriorityIcon = ({ priority }: { priority: SuggestionPriority }) => {
  switch (priority) {
    case 'RISK': return <AlertTriangle className="w-3.5 h-3.5 text-red-500" />;
    case 'DECLINE': return <TrendingDown className="w-3.5 h-3.5 text-amber-500" />;
    case 'INVENTORY': return <Package className="w-3.5 h-3.5 text-blue-500" />;
    case 'OPPORTUNITY': return <TrendingUp className="w-3.5 h-3.5 text-green-500" />;
    default: return <Activity className="w-3.5 h-3.5 text-gray-400" />;
  }
};

const KindIcon = ({ kind }: { kind: string }) => {
    if (kind === 'metric') return <BarChart2 className="w-3.5 h-3.5 opacity-50" />;
    if (kind === 'shortcut') return <Zap className="w-3.5 h-3.5 text-yellow-500" />;
    if (kind === 'sku') return <Tag className="w-3.5 h-3.5 text-theme" />;
    return null;
}

export const SearchAssistantPopover: React.FC<SearchAssistantPopoverProps> = ({ state, onApply, onClear, isVisible, products = [] }) => {
  const { t } = useTranslation();
  const suggestions = useMemo(() => getSuggestions(state, products), [state, products]);

  if (!isVisible) return null;

  // --- SKU SEARCH MODE RENDER ---
  if (suggestions.skuSuggestions.length > 0 || (state.searchText.toLowerCase().startsWith('sku:') || state.searchText.toLowerCase().startsWith('sku '))) {
      return (
        <div className="absolute top-full left-0 mt-2 w-full max-w-3xl bg-white/95 backdrop-blur-xl rounded-xl shadow-2xl border border-gray-200 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200 max-h-[80vh] overflow-y-auto">
            <div className="p-4 bg-theme-10/50 border-b border-indigo-100 flex items-center gap-2">
                <Tag className="w-4 h-4 text-theme" />
                <span className="text-xs font-bold text-theme uppercase">{t('search_assistant_sku_mode')}</span>
            </div>
            <div className="p-2">
                {suggestions.skuSuggestions.length > 0 ? (
                    <div className="space-y-1">
                        {suggestions.skuSuggestions.map(s => (
                            <button
                                key={s.id}
                                onClick={() => onApply(s)}
                                className="w-full flex items-center gap-3 p-3 text-left bg-white hover:bg-theme-10 border border-transparent hover:border-indigo-100 rounded-lg transition-all group"
                            >
                                <div className="font-mono font-bold text-sm text-gray-800">{s.label}</div>
                                <div className="text-xs text-gray-500 truncate flex-1">{s.description}</div>
                                <ArrowRight className="w-3 h-3 text-gray-300 group-hover:text-theme" />
                            </button>
                        ))}
                    </div>
                ) : (
                    <div className="p-8 text-center text-gray-400 text-sm">
                        {t('search_assistant_no_products', { query: state.searchText.replace(/^sku[:\s]+/, '') })}
                    </div>
                )}
            </div>
        </div>
      );
  }

  // Only show platform suggestions if the user has typed something to refine scope
  // This effectively removes the static "preset" list while keeping search functionality
  const showPlatforms = state.searchText.trim().length > 0;

  return (
    <div className="absolute top-full left-0 mt-2 w-full max-w-3xl bg-white/95 backdrop-blur-xl rounded-xl shadow-2xl border border-gray-200 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200 max-h-[80vh] overflow-y-auto">
      <div className="grid grid-cols-1 md:grid-cols-2 divide-y md:divide-y-0 md:divide-x divide-gray-100">

        {/* LEFT COLUMN: Metrics & Conditions */}
        <div className="p-4 space-y-6">

          {/* Section 1: Metrics */}
          {suggestions.metricSuggestions.length > 0 && (
            <div>
              <h4 className="text-[10px] font-bold text-gray-400 uppercase mb-3 flex items-center gap-2">
                <Search className="w-3 h-3" /> {t('search_assistant_analyze')}
              </h4>
              <div className="grid grid-cols-2 gap-2">
                {suggestions.metricSuggestions.map(s => (
                  <button
                    key={s.id}
                    onClick={() => onApply(s)}
                    className="flex items-center gap-2 px-3 py-2 text-left text-xs bg-gray-50 hover:bg-theme-10 hover:text-theme border border-transparent hover:border-theme-20 rounded-lg transition-all group"
                    title={s.description}
                  >
                    <KindIcon kind="metric" />
                    <span className="font-medium text-gray-700 group-hover:text-theme truncate">{s.label}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Section 2: Conditions */}
          {suggestions.conditionSuggestions.length > 0 && (
            <div>
              <h4 className="text-[10px] font-bold text-gray-400 uppercase mb-3 flex items-center gap-2">
                <Activity className="w-3 h-3" /> {t('search_assistant_condition')}
              </h4>
              <div className="flex flex-wrap gap-2">
                {suggestions.conditionSuggestions.map(s => (
                  <button
                    key={s.id}
                    onClick={() => onApply(s)}
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs bg-white border border-gray-200 hover:border-gray-300 hover:shadow-sm rounded-full transition-all"
                    title={s.description}
                  >
                    <PriorityIcon priority={s.priority} />
                    <span className="font-medium text-gray-700">{s.label}</span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* RIGHT COLUMN: Shortcuts & Scope */}
        <div className="bg-gray-50/50 p-4 space-y-6">

          {/* Section 3: Shortcuts */}
          {suggestions.shortcutSuggestions.length > 0 && (
            <div>
              <h4 className="text-[10px] font-bold text-gray-400 uppercase mb-3 flex items-center gap-2">
                <Zap className="w-3 h-3" /> {t('search_assistant_shortcuts')}
              </h4>
              <div className="space-y-2">
                {suggestions.shortcutSuggestions.map(s => (
                  <button
                    key={s.id}
                    onClick={() => onApply(s)}
                    className="w-full flex items-center justify-between p-3 text-left bg-white border border-gray-200 hover:border-theme-20 hover:shadow-md rounded-xl transition-all group"
                  >
                    <div className="flex items-center gap-3">
                      <div className={`p-1.5 rounded-lg ${s.priority === 'RISK' ? 'bg-red-50 text-red-600' : s.priority === 'OPPORTUNITY' ? 'bg-green-50 text-green-600' : 'bg-gray-100 text-gray-500'}`}>
                        <KindIcon kind="shortcut" />
                      </div>
                      <span className="text-xs font-semibold text-gray-700 group-hover:text-theme">{s.label}</span>
                    </div>
                    <ArrowRight className="w-3 h-3 text-gray-300 group-hover:text-theme opacity-0 group-hover:opacity-100 transition-opacity" />
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Section 4: Refine Scope (Time & Platform) */}
          {(suggestions.timeSuggestions.length > 0 || (showPlatforms && suggestions.platformSuggestions.length > 0)) && (
            <div>
                <h4 className="text-[10px] font-bold text-gray-400 uppercase mb-3 flex items-center gap-2">
                    <Filter className="w-3 h-3" /> {t('search_assistant_refine')}
                </h4>

                {/* Time */}
                {suggestions.timeSuggestions.length > 0 && (
                    <div className="mb-3">
                        <div className="flex flex-wrap gap-2">
                            {suggestions.timeSuggestions.map(s => (
                                <button
                                    key={s.id}
                                    onClick={() => onApply(s)}
                                    className="flex items-center gap-1.5 px-3 py-1 text-[10px] font-bold bg-blue-50 text-blue-700 border border-blue-100 hover:border-blue-300 hover:shadow-sm rounded-full transition-all"
                                >
                                    <Clock className="w-3 h-3" />
                                    {s.label}
                                </button>
                            ))}
                        </div>
                    </div>
                )}

                {/* Platforms - Only shown if searching */}
                {showPlatforms && suggestions.platformSuggestions.length > 0 && (
                    <div>
                        <div className="flex flex-wrap gap-2">
                            {suggestions.platformSuggestions.map(s => (
                                <button
                                    key={s.id}
                                    onClick={() => onApply(s)}
                                    className="flex items-center gap-1.5 px-3 py-1 text-[10px] font-bold bg-purple-50 text-purple-700 border border-purple-100 hover:border-purple-300 hover:shadow-sm rounded-full transition-all"
                                >
                                    <Globe className="w-3 h-3" />
                                    {s.label}
                                </button>
                            ))}
                        </div>
                    </div>
                )}
            </div>
          )}

          {/* Footer Actions */}
          <div className="pt-4 border-t border-gray-200/50 flex justify-between items-center">
             <span className="text-[10px] text-gray-400">
               {t('search_assistant_footer')}
             </span>
             <button onClick={onClear} className="text-[10px] font-bold text-gray-500 hover:text-red-600 transition-colors">
               {t('search_assistant_clear')}
             </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, PricingRules, SearchConfig, PriceChangeRecord, OptimalPriceResult, PromotionEvent, NavigationIntent } from '../../../types';
import { SearchIntent } from '../../../services/searchIntentService';
import { isAdsEnabled } from '../../../services/platformCapabilities';
import SkuDeepDivePage from '../../skuDeepDive/SkuDeepDivePage';
import { ThresholdConfig } from '../../../services/thresholdsConfig';
import { SearchHeader } from './parts/SearchHeader';
import { SearchResultPanels } from './parts/SearchResultPanels';
import { RotateCcw } from 'lucide-react';

interface SearchResultsPageContainerProps {
    data: { results: any[], query: string, params: SearchIntent, id?: string };
    products: Product[];
    pricingRules: PricingRules;
    themeColor: string;
    headerStyle: React.CSSProperties;
    timeLabel?: string;
    onRefine: (sessionId: string, newIntent: SearchIntent) => void;
    searchConfig: SearchConfig;
    priceChangeHistory?: PriceChangeRecord[];
    thresholds: ThresholdConfig;
    skuFamilies: any[];
    adGroups: any[];
    promotions: PromotionEvent[];
    priceHistoryMap: Map<string, any[]>;
    optimalPriceResults?: Map<string, OptimalPriceResult>;
    navigateToEntity?: (intent: Omit<NavigationIntent, 'createdAt'>) => void;
}

type GroupBy = 'platform' | 'sku';

export const SearchResultsPageContainer: React.FC<SearchResultsPageContainerProps> = ({
    data, products, pricingRules, themeColor, headerStyle, timeLabel, onRefine, searchConfig, priceChangeHistory, thresholds,
    skuFamilies, adGroups, promotions, priceHistoryMap, optimalPriceResults, navigateToEntity
}) => {
    const [groupBy, setGroupBy] = useState<GroupBy>('platform');
    const [expandedGroup, setExpandedGroup] = useState<string | null>(null);
    const [expandedSubGroup, setExpandedSubGroup] = useState<string | null>(null);
    const [deductRefunds, setDeductRefunds] = useState<boolean>(() => {
        return localStorage.getItem('sello_search_deduct_refunds') === 'true';
    });

    useEffect(() => {
        localStorage.setItem('sello_search_deduct_refunds', deductRefunds.toString());
    }, [deductRefunds]);

    const isDeepDive = data.params.primaryMetric === 'DEEP_DIVE' && data.results.length > 0;

    // --- LIVE DATA HYDRATION ---
    const liveProductMap = useMemo(() => {
        const map = new Map<string, Product>();
        products.forEach(p => map.set(p.sku, p));
        return map;
    }, [products]);

    useEffect(() => {
        setExpandedGroup(null);
        setExpandedSubGroup(null);
    }, [groupBy]);

    const checkContext = (keywords: string[], fields: string[]) => {
        const q = data.query.toLowerCase();
        const p = data.params;
        const matchesKeyword = keywords.some(k => q.includes(k));
        const hasFilter = p?.filters?.some((f: any) => fields.includes(f.field));
        const hasSort = p?.sort?.field ? fields.includes(p.sort.field) : false;
        return matchesKeyword || hasFilter || hasSort;
    };

    const isVolumeContext = useMemo(() => checkContext(
        ['qty', 'quantity', 'unit', 'sold', 'volume', 'velocity', 'count', 'traffic', 'winning', 'scale'],
        ['velocity', 'qty']
    ), [data]);

    const isAdContext = useMemo(() => checkContext(
        ['ad', 'tacos', 'ppc', 'marketing', 'spend', 'cost'],
        ['tacos', 'adsSpend']
    ), [data]);

    const isMarginContext = useMemo(() => checkContext(
        ['margin', 'profit', 'loss', 'negative', 'net', 'winning', 'scale'],
        ['margin', 'profit', 'netPmPercent', 'MARGIN_CHANGE_PCT']
    ), [data]);

    const isInventoryContext = useMemo(() => checkContext(
        ['stock', 'inventory', 'runway', 'cover', 'days remaining', 'days cover', 'overstock', 'out of stock', 'level'],
        ['stockLevel', 'daysRemaining']
    ), [data]);

    const isTrendContext = useMemo(() => checkContext(
        ['drop', 'decline', 'growth', 'change', 'trend', 'wow', 'spike'],
        ['velocityChange', 'MARGIN_CHANGE_PCT']
    ), [data]);

    const isReturnContext = useMemo(() => checkContext(
        ['return', 'refund', 'rate', 'rr'],
        ['returnRate', 'periodReturnRate']
    ), [data]);

    const isOrganicContext = useMemo(() => checkContext(
        ['organic', 'natural'],
        ['organicShare', 'ORGANIC_SHARE_PCT']
    ), [data]);

    const isAgedContext = useMemo(() => checkContext(
        ['aged', 'old', 'long term', 'stale'],
        ['agedStockPct', 'AGED_STOCK_PCT']
    ), [data]);

    const isPostcodeContext = useMemo(() => checkContext(
        ['postcode', 'area', 'region'],
        ['postcode']
    ), [data]);

    useEffect(() => {
        if (isInventoryContext || isAgedContext) {
            setGroupBy('sku');
        }
    }, [isInventoryContext, isAgedContext]);

    // Hierarchical Data Calculation moved here
    const hierarchicalData = useMemo(() => {
        if (!data.results || isDeepDive) return [];

        const groups: Record<string, any> = {};

        data.results.forEach(item => {
            const mainKey = groupBy === 'platform' ? (item.platform || 'Unknown') : item.sku;

            const liveProduct = liveProductMap.get(item.sku);
            if (liveProduct && item.type === 'INVENTORY') {
                item.averageDailySales = liveProduct.averageDailySales;
                item.daysRemaining = liveProduct.averageDailySales > 0 ? liveProduct.stockLevel / liveProduct.averageDailySales : 999;
                item.stockLevel = liveProduct.stockLevel;
                item.agedStockPct = liveProduct.stockLevel > 0 && liveProduct.agedStockQty ? (liveProduct.agedStockQty / liveProduct.stockLevel) * 100 : 0;
            }

            if (!groups[mainKey]) {
                groups[mainKey] = {
                    key: mainKey,
                    label: mainKey,
                    productName: groupBy === 'sku' ? item.productName : undefined,
                    count: 0,
                    weightedMargin: null,
                    totalRevenue: 0,
                    totalProfit: 0,
                    totalQty: 0,
                    totalAdSpend: 0,
                    totalRefundAmount: 0,
                    totalRefundQty: 0,
                    tacos: null,
                    organicShare: null,
                    contribution: 0,
                    agedStockPct: 0,
                    subGroups: {},
                    globalVelocity: 0,
                    globalCover: 0,
                    periodReturnRate: null,
                    allTimeReturnRate: 0,
                    adEnabledRevenue: 0,
                    totalPrevRevenue: 0,
                    totalPrevQty: 0,
                    totalPrevProfit: 0,
                    weightedMarginChange: 0,
                    districtStats: {}
                };
            }

            const topGroup = groups[mainKey];
            topGroup.count++;

            if (item.type !== 'REFUND') {
                topGroup.totalRevenue += (item.revenue || 0);
                topGroup.totalProfit += (item.profit || 0);
                topGroup.totalQty += (item.velocity || 0);
                topGroup.totalAdSpend += (item.adsSpend || 0);
                topGroup.contribution += (item.contribution || 0);

                if (isAdsEnabled(item.platform || '')) {
                    topGroup.adEnabledRevenue += (item.revenue || 0);
                }
            } else {
                topGroup.totalRefundAmount += Math.abs(item.refundAmount || 0);
                topGroup.totalRefundQty += Math.abs(item.velocity || 0);
                if (deductRefunds) {
                    topGroup.totalProfit += (item.profit || 0); // Refunds have negative profit
                }
            }

            if ((isInventoryContext || isAgedContext) && item.type === 'INVENTORY' && groupBy === 'sku') {
                const gVel = item.averageDailySales || 0;
                topGroup.globalVelocity = gVel;
                topGroup.totalQty = item.stockLevel;
                topGroup.globalCover = gVel > 0 ? (item.stockLevel / gVel) : 999;

                if (item.agedStockQty) {
                    topGroup.agedStockPct = item.agedStockPct || 0;
                }

                if (item.channels && Array.isArray(item.channels)) {
                    item.channels.forEach((ch: any) => {
                        const subKey = ch.platform;
                        if (!topGroup.subGroups[subKey]) {
                            topGroup.subGroups[subKey] = {
                                key: subKey,
                                label: subKey,
                                productName: undefined,
                                count: 1,
                                weightedMargin: null,
                                totalRevenue: 0,
                                totalProfit: 0,
                                totalQty: 0,
                                totalAdSpend: 0,
                                totalRefundAmount: 0,
                                totalRefundQty: 0,
                                tacos: null,
                                organicShare: null,
                                contribution: 0,
                                agedStockPct: 0,
                                items: [],
                                platformVelocity: ch.velocity,
                                platformCover: ch.velocity > 0 ? (item.stockLevel / ch.velocity) : 999,
                                periodReturnRate: null,
                                adEnabledRevenue: 0,
                                totalPrevRevenue: 0,
                                totalPrevQty: 0,
                                totalPrevProfit: 0,
                                weightedMarginChange: 0,
                                districtStats: {}
                            };
                        }
                        const estRevenue = ch.velocity * (ch.price || item.price);
                        topGroup.subGroups[subKey].items.push({
                            date: item.date,
                            price: ch.price || item.price,
                            velocity: ch.velocity,
                            revenue: estRevenue,
                            stockLevel: item.stockLevel,
                            type: 'INVENTORY_CHANNEL',
                            postcode: item.postcode
                        });
                    });
                }
            }
            else {
                const subKey = groupBy === 'platform' ? item.sku : (item.platform || 'Unknown');

                if (!topGroup.subGroups[subKey]) {
                    topGroup.subGroups[subKey] = {
                        key: subKey,
                        label: subKey,
                        productName: groupBy === 'platform' ? item.productName : undefined,
                        count: 0,
                        weightedMargin: null,
                        totalRevenue: 0,
                        totalProfit: 0,
                        totalQty: 0,
                        totalAdSpend: 0,
                        totalRefundAmount: 0,
                        totalRefundQty: 0,
                        tacos: null,
                        organicShare: null,
                        contribution: 0,
                        agedStockPct: 0,
                        items: [],
                        periodReturnRate: null,
                        allTimeReturnRate: item.allTimeReturnRate || 0,
                        adEnabledRevenue: 0,
                        totalPrevRevenue: 0,
                        totalPrevQty: 0,
                        totalPrevProfit: 0,
                        weightedMarginChange: 0,
                        districtStats: {}
                    };
                }

                const subGroup = topGroup.subGroups[subKey];
                subGroup.count++;
                if (item.type !== 'REFUND') {
                    subGroup.totalRevenue += (item.revenue || 0);
                    subGroup.totalProfit += (item.profit || 0);
                    subGroup.totalQty += (item.velocity || 0);
                    subGroup.totalAdSpend += (item.adsSpend || 0);
                    subGroup.contribution += (item.contribution || 0);

                    if (isAdsEnabled(item.platform || '')) {
                        subGroup.adEnabledRevenue += (item.revenue || 0);
                    }
                } else {
                    subGroup.totalRefundAmount += Math.abs(item.refundAmount || 0);
                    subGroup.totalRefundQty += Math.abs(item.velocity || 0);
                    if (deductRefunds) {
                        subGroup.totalProfit += (item.profit || 0);
                    }
                }
                subGroup.items.push(item);

                if (item.postcode) {
                    const district = item.postcode.split(' ')[0];
                    if (district) {
                        if (!topGroup.districtStats) topGroup.districtStats = {};
                        topGroup.districtStats[district] = (topGroup.districtStats[district] || 0) + (item.velocity || 0);
                        if (!subGroup.districtStats) subGroup.districtStats = {};
                        subGroup.districtStats[district] = (subGroup.districtStats[district] || 0) + (item.velocity || 0);
                    }
                }
            }
        });

        // Aggregation Step
        Object.keys(groups).forEach(key => {
            const g = groups[key];
            g.weightedMargin = g.totalRevenue > 0 ? (g.totalProfit / g.totalRevenue) * 100 : null;

            const skuSet = new Set<string>();

            Object.values(g.subGroups).forEach((sg: any) => {
                if (groupBy === 'sku') {
                    if (sg.items.length > 0 && !skuSet.has(g.key)) {
                        g.totalPrevRevenue = sg.items[0].prevRevenue || 0;
                        g.totalPrevQty = sg.items[0].prevQty || 0;
                        g.totalPrevProfit = sg.items[0].prevProfit || 0;
                        skuSet.add(g.key);
                    }
                } else {
                    if (sg.items.length > 0) {
                        const item = sg.items[0];
                        if (!skuSet.has(sg.key)) {
                            g.totalPrevRevenue += (item.prevRevenue || 0);
                            g.totalPrevQty += (item.prevQty || 0);
                            g.totalPrevProfit += (item.prevProfit || 0);

                            sg.totalPrevRevenue = item.prevRevenue || 0;
                            sg.totalPrevQty = item.prevQty || 0;
                            sg.totalPrevProfit = item.prevProfit || 0;

                            skuSet.add(sg.key);
                        }
                    }
                }

                if (!sg.platformVelocity) {
                    sg.weightedMargin = sg.totalRevenue > 0 ? (sg.totalProfit / sg.totalRevenue) * 100 : null;
                    const sgPrevMargin = sg.totalPrevRevenue > 0 ? (sg.totalPrevProfit / sg.totalPrevRevenue) * 100 : 0;
                    sg.weightedMarginChange = (sg.weightedMargin || 0) - sgPrevMargin;

                    if (sg.adEnabledRevenue > 0) {
                        sg.tacos = (sg.totalAdSpend / sg.adEnabledRevenue) * 100;
                        sg.organicShare = Math.max(0, 100 - sg.tacos);
                    } else {
                        sg.tacos = null;
                        sg.organicShare = null;
                    }

                    sg.periodReturnRate = sg.totalQty > 0 ? (sg.totalRefundQty / sg.totalQty) * 100 : null;
                }
            });

            const prevGroupMargin = g.totalPrevRevenue > 0 ? (g.totalPrevProfit / g.totalPrevRevenue) * 100 : 0;
            g.weightedMarginChange = (g.weightedMargin || 0) - prevGroupMargin;

            if (g.adEnabledRevenue > 0) {
                g.tacos = (g.totalAdSpend / g.adEnabledRevenue) * 100;
                g.organicShare = Math.max(0, 100 - g.tacos);
            } else {
                g.tacos = null;
                g.organicShare = null;
            }

            g.periodReturnRate = g.totalQty > 0 ? (g.totalRefundQty / g.totalQty) * 100 : null;

            if (groupBy === 'sku') {
                const firstSub: any = Object.values(g.subGroups)[0];
                g.allTimeReturnRate = firstSub?.allTimeReturnRate || 0;
            } else {
                const subs: any[] = Object.values(g.subGroups);
                const sumAllTime = subs.reduce((acc, sub) => acc + (sub.allTimeReturnRate || 0), 0);
                g.allTimeReturnRate = subs.length > 0 ? sumAllTime / subs.length : 0;
            }
        });

        // Sorting
        return Object.values(groups).sort((a: any, b: any) => {
            if (data.params && data.params.sort) {
                const { field, direction } = data.params.sort;
                const dirMult = direction === 'asc' ? 1 : -1;

                if (field === 'MARGIN_CHANGE_PCT') {
                    return (a.weightedMarginChange - b.weightedMarginChange) * dirMult;
                }

                if (field === 'margin' || field === 'net_margin_pct' || field === 'netPmPercent') {
                    if (isTrendContext) {
                        return (a.weightedMarginChange - b.weightedMarginChange) * dirMult;
                    }
                    return (a.totalProfit - b.totalProfit) * dirMult;
                }
                if (field === 'profit' || field === 'net_profit') return (a.totalProfit - b.totalProfit) * dirMult;
                if (field === 'revenue') return (a.totalRevenue - b.totalRevenue) * dirMult;
                if (field === 'velocity' || field === 'qty' || field === 'sales_qty') return (a.totalQty - b.totalQty) * dirMult;
                if (field === 'tacos' || field === 'tacos_pct' || field === 'adsSpend') return ((a.tacos || 0) - (b.tacos || 0)) * dirMult;
                if (field === 'stockLevel') return (a.totalQty - b.totalQty) * dirMult;
                if (field === 'daysRemaining' || field === 'stock_cover_days') return ((a.globalCover || 0) - (b.globalCover || 0)) * dirMult;
                if (field === 'periodReturnRate' || field === 'returnRate' || field === 'RETURN_RATE_PCT') return ((a.periodReturnRate || 0) - (b.periodReturnRate || 0)) * dirMult;
                if (field === 'organicShare' || field === 'ORGANIC_SHARE_PCT') return ((a.organicShare || 0) - (b.organicShare || 0)) * dirMult;
                if (field === 'agedStockPct' || field === 'AGED_STOCK_PCT') return ((a.agedStockPct || 0) - (b.agedStockPct || 0)) * dirMult;
                if (field === 'VELOCITY_CHANGE') {
                    const aTrend = a.totalPrevQty > 0 ? ((a.totalQty - a.totalPrevQty) / a.totalPrevQty) : 0;
                    const bTrend = b.totalPrevQty > 0 ? ((b.totalQty - b.totalPrevQty) / b.totalPrevQty) : 0;
                    return (aTrend - bTrend) * dirMult;
                }
            }

            if (isAgedContext) return (b.agedStockPct || 0) - (a.agedStockPct || 0);
            if (isOrganicContext) return (b.organicShare || 0) - (a.organicShare || 0);
            if (isReturnContext) return (b.periodReturnRate || 0) - (a.periodReturnRate || 0);
            if (isInventoryContext) return a.totalQty - b.totalQty;
            if (isVolumeContext) return b.totalQty - a.totalQty;
            if (isAdContext) return (b.tacos || 0) - (a.tacos || 0);
            if (isMarginContext) return b.totalProfit - a.totalProfit;
            return b.totalRevenue - a.totalRevenue;
        });

    }, [data.results, groupBy, deductRefunds, isVolumeContext, isAdContext, isMarginContext, isInventoryContext, isReturnContext, isOrganicContext, isAgedContext, isTrendContext, isPostcodeContext, data.params, isDeepDive, liveProductMap]);

    const volumeContextStats = useMemo(() => {
        const quantities = hierarchicalData.map((g: any) => g.totalQty).sort((a: number, b: number) => a - b);
        const count = quantities.length;
        if (count === 0) return null;

        const max = quantities[count - 1] || 0;

        if (max < searchConfig.minAbsoluteFloor) {
            return { isLowVolume: true };
        }

        const bottomCutoffIndex = Math.floor(count * (searchConfig.volumeBands.bottomPercentile / 100));
        const topCutoffIndex = Math.floor(count * (1 - searchConfig.volumeBands.topPercentile / 100));

        const bottomVal = quantities[bottomCutoffIndex];
        const topVal = quantities[topCutoffIndex];

        const getBand = (qty: number) => {
            if (qty >= topVal) return 'Top';
            if (qty <= bottomVal) return 'Bottom';
            return 'Middle';
        };

        return { isLowVolume: false, getBand };
    }, [hierarchicalData, searchConfig]);

    const handleGroupToggle = (groupKey: string, e?: React.MouseEvent) => {
        const selection = window.getSelection();
        if (selection && selection.toString().length > 0) return;
        setExpandedGroup(prev => prev === groupKey ? null : groupKey);
        setExpandedSubGroup(null);
    };

    const handleSubGroupToggle = (compositeKey: string, e: React.MouseEvent) => {
        const selection = window.getSelection();
        if (selection && selection.toString().length > 0) return;
        e.stopPropagation();
        setExpandedSubGroup(prev => prev === compositeKey ? null : compositeKey);
    };

    const handleSortUpdate = (field: string, direction: 'asc' | 'desc') => {
        const newIntent: SearchIntent = {
            ...data.params,
            sort: { field, direction }
        };
        if (data.id) onRefine(data.id, newIntent);
    };

    if (isDeepDive) {
        const resultSnapshot = data.results[0];
        const liveProduct = liveProductMap.get(resultSnapshot.product.sku);
        const hydratedData = liveProduct ? { ...resultSnapshot, product: liveProduct } : resultSnapshot;
        return <SkuDeepDivePage
            data={hydratedData}
            themeColor={themeColor}
            priceChangeHistory={priceChangeHistory}
            thresholds={thresholds}
            pricingRules={pricingRules}
            skuFamilies={skuFamilies}
            products={products}
            adGroups={adGroups}
            promotions={promotions}
            priceHistoryMap={priceHistoryMap}
            optimalPriceResults={optimalPriceResults}
            navigateToEntity={navigateToEntity}
        />;
    }

    return (
        <div className="space-y-4">
            <div className="flex justify-end pr-2">
                <label className="flex items-center gap-2 px-3 py-2 bg-white rounded-lg border border-gray-200 shadow-sm cursor-pointer hover:border-theme-20 transition-colors">
                    <input
                        type="checkbox"
                        checked={deductRefunds}
                        onChange={e => setDeductRefunds(e.target.checked)}
                        className="w-4 h-4 text-theme rounded focus:ring-theme border-gray-300"
                    />
                    <div className="flex items-center gap-1.5">
                        <RotateCcw className={`w-3.5 h-3.5 ${deductRefunds ? 'text-red-500' : 'text-gray-400'}`} />
                        <span className={`text-[10px] font-bold uppercase tracking-tight ${deductRefunds ? 'text-gray-900' : 'text-gray-500'}`}>Deduct Returns</span>
                    </div>
                </label>
            </div>

            <SearchHeader
                data={data}
                themeColor={themeColor}
                timeLabel={timeLabel}
                context={{
                    isVolume: isVolumeContext,
                    isAd: isAdContext,
                    isMargin: isMarginContext,
                    isInventory: isInventoryContext,
                    isTrend: isTrendContext,
                    isReturn: isReturnContext,
                    isOrganic: isOrganicContext,
                    isAged: isAgedContext,
                }}
                onRefine={onRefine}
                handleSortUpdate={handleSortUpdate}
                groupBy={groupBy}
                setGroupBy={setGroupBy}
            />

            <SearchResultPanels
                data={data}
                hierarchicalData={hierarchicalData}
                groupBy={groupBy}
                expandedGroup={expandedGroup}
                expandedSubGroup={expandedSubGroup}
                handleGroupToggle={handleGroupToggle}
                handleSubGroupToggle={handleSubGroupToggle}
                volumeContextStats={volumeContextStats}
                context={{
                    isVolume: isVolumeContext,
                    isAd: isAdContext,
                    isMargin: isMarginContext,
                    isInventory: isInventoryContext,
                    isTrend: isTrendContext,
                    isReturn: isReturnContext,
                    isOrganic: isOrganicContext,
                    isAged: isAgedContext,
                    isPostcode: isPostcodeContext
                }}
                thresholds={thresholds}
                liveProductMap={liveProductMap}
            />
        </div>
    );
};

import React, { useState } from 'react';
import { X, Check, MapPin } from 'lucide-react';

interface FilterChipProps {
    filter: any;
    onUpdate: (f: any) => void;
    onDelete: () => void;
    themeColor: string;
}

const FIELD_LABELS: Record<string, string> = {
    stockLevel: 'Stock',
    averageDailySales: 'Velocity',
    daysRemaining: 'Stock Cover',
    margin: 'Margin',
    profit: 'Profit',
    tacos: 'TACoS',
    adsSpend: 'Ad Spend',
    returnRate: 'Return %',
    revenue: 'Revenue',
    velocity: 'Qty',
    velocityChange: 'Trend % (PoP)',
    netPmPercent: 'Net Margin',
    qty: 'Qty',
    name: 'Name',
    platform: 'Platform',
    periodReturnRate: 'Period RR%',
    organicShare: 'Organic (Ad-enabled)',
    agedStockPct: 'Aged Stock %',
    MARGIN_CHANGE_PCT: 'Margin Change (PoP)',
    postcode: 'Postcode Area'
};

export const FilterChip: React.FC<FilterChipProps> = ({ filter, onUpdate, onDelete, themeColor }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [editValue, setEditValue] = useState(filter.value);
    const [editOperator, setEditOperator] = useState(filter.operator);

    const handleSave = () => {
        onUpdate({ ...filter, value: editValue, operator: editOperator, label: undefined });
        setIsEditing(false);
    };

    const displayField = FIELD_LABELS[filter.field] || filter.field;
    const displayValue = typeof filter.value === 'number' ? filter.value.toLocaleString() : filter.value;

    // Special handling for Postcode Area to reassure users about strict matching
    const logicString = filter.field === 'postcode'
        ? `Area: ${displayValue}`
        : `${displayField} ${filter.operator} ${displayValue}`;

    // Explicit override for Trend < 0 to make it clear
    const finalContent = filter.field === 'velocityChange' && filter.value === 0 && filter.operator === 'LT'
        ? <span className="font-mono text-xs font-medium">Negative Trend (Period-over-Period)</span>
        : filter.label 
            ? <><span className="font-medium">{filter.label}:</span> <span className="opacity-80 ml-1 font-mono text-[10px]">{logicString}</span></>
            : <span className="font-mono text-xs font-medium">{logicString}</span>;

    const icon = filter.field === 'postcode' ? <MapPin className="w-3 h-3 text-theme" /> : null;

    if (isEditing) {
        return (
            <div className="flex items-center gap-1 bg-white border border-theme-20 rounded-lg p-1 shadow-sm animate-in fade-in zoom-in duration-200">
                <span className="text-[10px] font-bold text-gray-500 uppercase px-1">{displayField}</span>
                <select 
                    value={editOperator} 
                    onChange={e => setEditOperator(e.target.value)}
                    className="text-xs border-gray-200 rounded py-0.5 px-1 bg-gray-50"
                >
                    <option value=">">&gt;</option>
                    <option value="<">&lt;</option>
                    <option value=">=">&ge;</option>
                    <option value="<=">&le;</option>
                    <option value="=">=</option>
                    <option value="CONTAINS">has</option>
                </select>
                <input 
                    type={typeof filter.value === 'number' ? 'number' : 'text'}
                    value={editValue}
                    onChange={e => setEditValue(typeof filter.value === 'number' ? parseFloat(e.target.value) : e.target.value)}
                    className="w-16 text-xs border-gray-200 rounded py-0.5 px-1"
                    autoFocus
                />
                <button onClick={handleSave} className="p-1 text-green-600 hover:bg-green-50 rounded">
                    <Check className="w-3 h-3" />
                </button>
                <button onClick={() => setIsEditing(false)} className="p-1 text-gray-400 hover:bg-gray-50 rounded">
                    <X className="w-3 h-3" />
                </button>
            </div>
        )
    }

    return (
        <div 
            className="group flex items-center gap-1 px-3 py-1.5 bg-white border border-indigo-100 rounded-full text-xs text-theme shadow-sm hover:border-theme-20 transition-all cursor-pointer hover:shadow-md"
            onClick={() => setIsEditing(true)}
            title={filter.field === 'postcode' ? "Strict Area Match (e.g. 'B' matches 'B1' but not 'BN1')" : "Click to edit filter criteria"}
        >
            {icon}
            {finalContent}
            <button 
                onClick={(e) => { e.stopPropagation(); onDelete(); }}
                className="opacity-0 group-hover:opacity-100 p-0.5 hover:bg-theme-10 rounded-full text-theme hover:text-red-500 transition-all"
            >
                <X className="w-3 h-3" />
            </button>
        </div>
    );
};

import React from 'react';
import { Layers, Package, MapPin, TrendingDown, TrendingUp, Info, ChevronDown, ChevronRight, ArrowRight } from 'lucide-react';
import { GradeBadge } from '../../../common/GradeBadge';
import { formatNumber, formatMoney, formatSmartMoney, formatPct } from '../../../../utils/format';
import { calcRevenue, calcProfit, calcUnits, calcAdSpend, calcMarginPct } from '../../../../services/metrics';
import { ThresholdConfig } from '../../../../services/thresholdsConfig';
import { Product } from '../../../../types';
import { SortableHeader } from '../../../common/SortableHeader';

interface SearchResultPanelsProps {
    data: { results: any[] };
    hierarchicalData: any[];
    groupBy: 'platform' | 'sku';
    expandedGroup: string | null;
    expandedSubGroup: string | null;
    handleGroupToggle: (key: string, e?: React.MouseEvent) => void;
    handleSubGroupToggle: (key: string, e: React.MouseEvent) => void;
    volumeContextStats: any;
    context: {
        isVolume: boolean;
        isAd: boolean;
        isMargin: boolean;
        isInventory: boolean;
        isTrend: boolean;
        isReturn: boolean;
        isOrganic: boolean;
        isAged: boolean;
        isPostcode: boolean;
    };
    thresholds: ThresholdConfig;
    liveProductMap: Map<string, Product>;
}

export const SearchResultPanels: React.FC<SearchResultPanelsProps> = ({ 
    data, hierarchicalData, groupBy, expandedGroup, expandedSubGroup, 
    handleGroupToggle, handleSubGroupToggle, volumeContextStats, context, thresholds, liveProductMap 
}) => {

    if (data.results.length === 0) {
      return (
        <div className="text-center py-20 bg-custom-glass rounded-xl border border-custom-glass">
          <h3 className="text-lg font-bold text-gray-800">No Results Found</h3>
          <p className="text-gray-500 mt-2">Your query did not return any results. Try adjusting the filters above.</p>
        </div>
      );
    }

    // Helper to format top districts for display
    const getTopDistricts = (stats: Record<string, number> | undefined) => {
        if (!stats) return null;
        const sorted = Object.entries(stats).sort((a, b) => b[1] - a[1]);
        if (sorted.length === 0) return null;

        const top3 = sorted.slice(0, 3).map(([code, count]) => `${code} (${count})`).join(', ');
        return top3;
    };

    return (
      <div className="space-y-4">
        <div className="flex items-center gap-2 px-3 py-2 bg-blue-50/50 border border-blue-100 rounded-lg text-[10px] text-blue-700 mb-2">
            <Info className="w-3 h-3 flex-shrink-0" />
            <span>
                <strong>Data Basis:</strong> Some metrics are proxies (from Product Master), others are exact (from Transactions). 
                Hover over values for calculation details. &quot;—&quot; indicates insufficient data.
            </span>
        </div>
        {hierarchicalData.map(group => {
            // Volume Context Visuals
            let volumeBadge = null;
            if (volumeContextStats) {
                if (volumeContextStats.isLowVolume) {
                    volumeBadge = <span className="text-[9px] bg-gray-50 text-gray-400 px-1 rounded border border-gray-100">Low Vol</span>;
                } else if (volumeContextStats.getBand) {
                    const band = volumeContextStats.getBand(group.totalQty);
                    if (band === 'Top') volumeBadge = <span className="text-[9px] bg-slate-200 text-slate-700 px-1 rounded border border-slate-300 font-medium">Top 20%</span>;
                    if (band === 'Middle') volumeBadge = <span className="text-[9px] bg-gray-100 text-gray-600 px-1 rounded border border-gray-200 font-medium">Mid 60%</span>;
                    if (band === 'Bottom') volumeBadge = <span className="text-[9px] bg-white text-gray-400 px-1 rounded border border-gray-200 font-medium">Bot 20%</span>;
                }
            }

            // Calculate Trends for Top Group
            const revDiff = group.totalRevenue - group.totalPrevRevenue;
            const revDiffPct = group.totalPrevRevenue > 0 ? (revDiff / group.totalPrevRevenue) * 100 : (group.totalRevenue > 0 ? 100 : 0);

            const volDiff = group.totalQty - group.totalPrevQty;
            const volDiffPct = group.totalPrevQty > 0 ? (volDiff / group.totalPrevQty) * 100 : (group.totalQty > 0 ? 100 : 0);

            // Postcode Context Summary
            const topDistricts = context.isPostcode ? getTopDistricts(group.districtStats) : null;

            const productForGroup = groupBy === 'sku' ? liveProductMap.get(group.key) : null;

            return (
              <div key={group.key} className="bg-custom-glass rounded-xl shadow-lg border border-custom-glass overflow-hidden">
                <div
                  className={`w-full p-4 flex items-center justify-between hover:bg-gray-50/50 transition-colors cursor-pointer select-text ${expandedGroup === group.key ? 'bg-gray-50/30' : ''}`}
                  onClick={(e) => handleGroupToggle(group.key, e)}
                >
                  <div className="flex items-center gap-4">
                     <div className={`p-2 rounded-lg text-gray-600 ${groupBy === 'platform' ? 'bg-purple-100 text-purple-700' : 'bg-blue-100 text-blue-700'}`}>
                        {groupBy === 'platform' ? <Layers className="w-5 h-5" /> : <Package className="w-5 h-5" />}
                     </div>
                     <div>
                        <h3 className="font-bold text-gray-900 flex items-center">
                            {group.label}
                            {productForGroup && <GradeBadge gradeLevel={productForGroup.gradeLevel} />}
                        </h3>
                        {group.productName && <p className="text-xs text-gray-500">{group.productName}</p>}
                        {topDistricts && (
                            <p className="text-[10px] text-theme mt-1 flex items-center gap-1 font-medium">
                                <MapPin className="w-3 h-3" /> Top Districts: {topDistricts}
                            </p>
                        )}
                     </div>
                  </div>

                  <div className="flex items-center gap-8">
                    {/* UNITS COLUMN */}
                    <div className={`text-right hidden sm:block ${context.isVolume ? 'scale-110 transform origin-right' : 'opacity-70'}`}>
                        <div className={`text-xs ${context.isVolume ? 'text-theme font-bold' : 'text-gray-500'}`}>
                            {context.isInventory || context.isAged ? 'Total Stock' : context.isTrend ? 'Vol. Change (PoP)' : 'Units Sold'}
                        </div>

                        {context.isTrend ? (
                            <div className="flex flex-col items-end">
                                <span className="font-bold text-gray-900 text-sm">{formatNumber(group.totalQty)}</span>
                                <div className={`flex items-center gap-1 text-xs font-bold ${volDiff < 0 ? 'text-red-600' : 'text-green-600'}`}>
                                    {volDiff < 0 ? <TrendingDown className="w-3 h-3" /> : <TrendingUp className="w-3 h-3" />}
                                    {volDiff > 0 ? '+' : ''}{formatNumber(volDiff)} ({volDiffPct.toFixed(1)}%)
                                </div>
                            </div>
                        ) : (
                            <div className="flex flex-col items-end">
                                <div className={`font-bold text-lg ${context.isVolume ? 'text-theme' : 'text-gray-800'}`}>
                                    {formatNumber(group.totalQty)}
                                </div>
                                {volumeBadge}
                            </div>
                        )}
                    </div>

                    {/* REVENUE COLUMN */}
                    <div className="text-right hidden sm:block">
                        <div className="text-xs text-gray-500">
                            {context.isInventory || context.isAged ? 'Global Velocity' : context.isTrend ? 'Rev. Change (PoP)' : 'Total Revenue'}
                        </div>

                        {context.isTrend ? (
                            <div className="flex flex-col items-end">
                                <span className="font-bold text-gray-900 text-sm">{formatSmartMoney(group.totalRevenue)}</span>
                                <div className={`flex items-center gap-1 text-xs font-bold ${revDiff < 0 ? 'text-red-600' : 'text-green-600'}`}>
                                    {revDiff < 0 ? <TrendingDown className="w-3 h-3" /> : <TrendingUp className="w-3 h-3" />}
                                    {revDiff > 0 ? '+' : '-'}{formatSmartMoney(Math.abs(revDiff))} ({revDiffPct.toFixed(1)}%)
                                </div>
                            </div>
                        ) : (
                            <div className="font-bold text-lg text-gray-800">
                                {context.isInventory || context.isAged
                                    ? `${(group.globalVelocity || 0).toFixed(1)}/day`
                                    : formatSmartMoney(group.totalRevenue)
                                }
                            </div>
                        )}
                    </div>

                    {/* ADDITIONAL COLUMNS ... */}
                    {context.isReturn && (
                        <div className="text-right hidden sm:block">
                            <div className="text-xs text-gray-500 font-bold uppercase tracking-wider mb-1">
                                Return Health
                            </div>
                            <div className="flex items-center gap-4 bg-gray-50 px-3 py-1 rounded border border-gray-200">
                                <div className="text-right">
                                    <span className="block text-[9px] text-gray-400 uppercase">Period (Qty)</span>
                                    <span className={`block font-bold ${(group.periodReturnRate || 0) > thresholds.returnRatePct ? 'text-red-600' : 'text-gray-800'}`}>
                                        {formatPct(group.periodReturnRate)}
                                    </span>
                                </div>
                                <div className="w-px h-6 bg-gray-300"></div>
                                <div className="text-right">
                                    <span className="block text-[9px] text-gray-400 uppercase">All Time</span>
                                    <span className="block font-medium text-gray-600">
                                        {(group.allTimeReturnRate || 0).toFixed(1)}%
                                    </span>
                                </div>
                            </div>
                        </div>
                    )}

                    {!context.isReturn && (
                        <div className="text-right hidden md:block group relative">
                            <div className="text-xs text-gray-500 flex items-center justify-end gap-1">
                                {context.isInventory ? 'Global Cover' 
                                : context.isAd ? 'TACoS' 
                                : context.isOrganic ? 'Organic Share (Ad-enabled)' 
                                : context.isAged ? 'Aged Stock %' 
                                : context.isMargin && context.isTrend ? 'Margin Change (PoP)'
                                : context.isMargin ? 'Net Contribution' 
                                : 'Sales Share'}

                                {context.isOrganic && (
                                    <div className="group/tooltip relative">
                                        <Info className="w-3 h-3 text-gray-400 cursor-help" />
                                        <div className="absolute bottom-full right-0 mb-2 w-48 p-2 bg-gray-900 text-white text-[10px] rounded shadow-lg opacity-0 group-hover/tooltip:opacity-100 pointer-events-none z-50">
                                            Calculated only on ad-enabled platforms (currently Amazon/eBay/Temu).
                                        </div>
                                    </div>
                                )}
                            </div>

                            {context.isMargin ? (
                                <div className="flex flex-col items-end">
                                    <div className={`font-bold text-lg ${group.totalProfit < 0 ? 'text-red-600' : 'text-green-700'}`}>
                                        {formatSmartMoney(group.totalProfit)}
                                    </div>
                                    <div className={`text-xs flex items-center gap-1 ${group.weightedMargin !== null && group.weightedMargin < thresholds.marginBelowTargetPct ? 'text-red-400' : 'text-gray-400'}`} title="Net Profit / Revenue. Shows '—' if no revenue recorded.">
                                        {formatPct(group.weightedMargin)} 
                                        {context.isTrend && (
                                            <span className={`font-bold ${group.weightedMarginChange > 0 ? 'text-green-500' : 'text-red-500'}`}>
                                                ({group.weightedMarginChange > 0 ? '+' : ''}{group.weightedMarginChange.toFixed(1)}%)
                                            </span>
                                        )}
                                    </div>
                                </div>
                            ) : (
                                <div className={`font-bold text-lg ${
                                    context.isInventory
                                        ? ((group.globalCover || 999) < 14 ? 'text-red-600' : (group.globalCover || 0) > thresholds.overstockDays ? 'text-orange-600' : 'text-green-600')
                                        : context.isAd 
                                            ? (group.tacos !== null && group.tacos > thresholds.highAdDependencyPct ? 'text-red-600' : 'text-gray-800')
                                            : context.isOrganic
                                                ? (group.organicShare !== null && group.organicShare > 80 ? 'text-green-600' : group.organicShare !== null && group.organicShare < 40 ? 'text-red-600' : 'text-gray-800')
                                            : context.isAged
                                                ? (group.agedStockPct > 20 ? 'text-red-600' : group.agedStockPct > 10 ? 'text-orange-600' : 'text-green-600')
                                            : 'text-theme'
                                }`} title={context.isAd ? "Ad Spend / Ad-Enabled Revenue. Shows '—' if no revenue on ad platforms." : undefined}>
                                    {context.isInventory 
                                        ? `${(group.globalCover || 0) > 730 ? '>2y' : (group.globalCover || 0).toFixed(0) + ' days'}`
                                        : context.isAd ? formatPct(group.tacos)
                                        : context.isOrganic 
                                            ? (group.organicShare !== null ? `${group.organicShare.toFixed(1)}%` : <span className="text-xs text-gray-400 font-medium bg-gray-100 px-2 py-0.5 rounded">N/A <span className="hidden group-hover:inline">- Ads not enabled</span></span>)
                                        : context.isAged ? `${group.agedStockPct.toFixed(1)}%`
                                        : `${group.contribution.toFixed(1)}%`}
                                </div>
                            )}
                        </div>
                    )}

                    <div className={`transition-transform duration-200 ${expandedGroup === group.key ? 'rotate-180' : ''}`}>
                        <ChevronDown className="w-5 h-5 text-gray-400" />
                    </div>
                  </div>
                </div>

                {/* --- EXPANDED SUBGROUPS --- */}
                {expandedGroup === group.key && (
                    <div className="border-t border-gray-200/50 bg-gray-50/10">
                        <div className="px-4 py-2 bg-gray-100/50 text-[10px] font-bold text-gray-500 uppercase tracking-wide flex items-center gap-2">
                            <ArrowRight className="w-3 h-3" />
                            {groupBy === 'platform' ? 'Products (SKUs) in this Platform' : 'Platforms for this Product'}
                        </div>

                        <div className="divide-y divide-gray-100">
                            {(Object.values(group.subGroups) as any[])
                                .sort((a: any, b: any) => {
                                    return b.contribution - a.contribution;
                                })
                                .map((sub: any) => {
                                    const compositeKey = `${group.key}|${sub.key}`;
                                    const isSubExpanded = expandedSubGroup === compositeKey;

                                    // Calculate SubGroup Trends
                                    const subRevDiff = sub.totalRevenue - sub.totalPrevRevenue;
                                    const subRevDiffPct = sub.totalPrevRevenue > 0 ? (subRevDiff / sub.totalPrevRevenue) * 100 : (sub.totalRevenue > 0 ? 100 : 0);

                                    const subVolDiff = sub.totalQty - sub.totalPrevQty;
                                    const subVolDiffPct = sub.totalPrevQty > 0 ? (subVolDiff / sub.totalPrevQty) * 100 : (sub.totalQty > 0 ? 100 : 0);

                                    const productForSubgroup = groupBy === 'platform' ? liveProductMap.get(sub.key) : null;

                                    return (
                                        <div key={sub.key} className="bg-white/40">
                                            {/* ... Subgroup Header Row ... */}
                                            <div 
                                                className="w-full flex items-center justify-between px-6 py-3 hover:bg-white/80 transition-colors text-left cursor-pointer select-text"
                                                onClick={(e) => handleSubGroupToggle(compositeKey, e)}
                                            >
                                                <div className="flex items-center gap-3">
                                                    {isSubExpanded ? <ChevronDown className="w-4 h-4 text-theme" /> : <ChevronRight className="w-4 h-4 text-gray-400" />}
                                                    <div className="p-1.5 bg-gray-200 rounded text-gray-500">
                                                        {groupBy === 'platform' ? <Package className="w-3 h-3" /> : <Layers className="w-3 h-3" />}
                                                    </div>
                                                    <div>
                                                        <div className="font-mono text-sm font-bold text-gray-700 flex items-center">
                                                            {sub.label}
                                                            {productForSubgroup && <GradeBadge gradeLevel={productForSubgroup.gradeLevel} />}
                                                        </div>
                                                        {sub.productName && <div className="text-xs text-gray-500">{sub.productName}</div>}
                                                    </div>
                                                </div>
                                                <div className="flex items-center gap-6">
                                                    {/* ... Subgroup Metrics ... */}
                                                    {context.isInventory || context.isAged ? (
                                                        <>
                                                            <div className="text-right">
                                                                <div className="text-xs text-gray-400">Plat. Velocity</div>
                                                                <div className="text-sm font-bold text-theme">{(sub.platformVelocity || 0).toFixed(2)}/d</div>
                                                            </div>
                                                            {!context.isAged && <div className="text-right w-24">
                                                                <div className="text-xs text-gray-400">Plat. Cover</div>
                                                                <div className={`text-sm font-bold ${(sub.platformCover || 999) < 28 ? 'text-red-600' : 'text-green-600'}`}>
                                                                    {(sub.platformCover || 0).toFixed(0)} days
                                                                </div>
                                                            </div>}
                                                            {context.isAged && <div className="text-right w-24">
                                                                <div className="text-xs text-gray-400">Aged %</div>
                                                                <div className={`text-sm font-bold ${(sub.agedStockPct || 0) > 20 ? 'text-red-600' : 'text-green-600'}`}>
                                                                    {(sub.agedStockPct || 0).toFixed(1)}%
                                                                </div>
                                                            </div>}
                                                        </>
                                                    ) : context.isReturn ? (
                                                        <>
                                                            <div className="text-right w-16">
                                                                <div className="text-xs text-gray-400">Units</div>
                                                                <div className="text-sm font-bold text-gray-700">{formatNumber(sub.totalQty)}</div>
                                                            </div>
                                                            <div className="text-right w-16">
                                                                <div className="text-xs text-gray-400">Refunded</div>
                                                                <div className="text-sm font-bold text-red-600">{sub.totalRefundQty}</div>
                                                            </div>
                                                            <div className="text-right w-20">
                                                                <div className="text-xs text-gray-400">Period RR</div>
                                                                <div className={`text-sm font-bold ${(sub.periodReturnRate || 0) > thresholds.returnRatePct ? 'text-red-600' : 'text-gray-800'}`}>
                                                                    {formatPct(sub.periodReturnRate)}
                                                                </div>
                                                            </div>
                                                            <div className="text-right w-20">
                                                                <div className="text-xs text-gray-400">All Time</div>
                                                                <div className="text-sm font-medium text-gray-600">
                                                                    {(sub.allTimeReturnRate || 0).toFixed(1)}%
                                                                </div>
                                                            </div>
                                                        </>
                                                    ) : context.isTrend ? (
                                                        <>
                                                            <div className="text-right">
                                                                <div className="text-xs text-gray-400">Vol. Trend</div>
                                                                <div className={`text-xs font-bold ${subVolDiff < 0 ? 'text-red-600' : 'text-green-600'}`}>
                                                                    {subVolDiff > 0 ? '+' : ''}{subVolDiff} ({subVolDiffPct.toFixed(0)}%)
                                                                </div>
                                                            </div>
                                                            <div className="text-right">
                                                                <div className="text-xs text-gray-400">Rev. Trend</div>
                                                                <div className={`text-xs font-bold ${subRevDiff < 0 ? 'text-red-600' : 'text-green-600'}`}>
                                                                    {subRevDiff > 0 ? '+' : ''}{formatSmartMoney(Math.abs(subRevDiff))} ({subRevDiffPct.toFixed(0)}%)
                                                                </div>
                                                            </div>
                                                        </>
                                                    ) : (
                                                        <>
                                                            <div className="text-right w-16">
                                                                <div className="text-xs text-gray-400">Qty</div>
                                                                <div className="text-sm font-bold text-gray-700">{formatNumber(sub.totalQty)}</div>
                                                            </div>
                                                            <div className="text-right">
                                                                <div className="text-xs text-gray-400">Revenue</div>
                                                                <div className="text-sm font-medium text-gray-700">{formatSmartMoney(sub.totalRevenue)}</div>
                                                            </div>
                                                            {(context.isMargin || context.isAd || context.isOrganic) && (
                                                                <div className="text-right">
                                                                    <div className="text-xs text-gray-400">Ad Spent</div>
                                                                    <div className="text-sm font-medium text-orange-700">{formatSmartMoney(sub.totalAdSpend)}</div>
                                                                </div>
                                                            )}
                                                            <div className="text-right w-24">
                                                                <div className="text-xs text-gray-400">
                                                                    {context.isAd ? 'TACoS' : context.isOrganic ? 'Organic (Ads)' : context.isMargin ? 'Net Profit' : 'Share %'}
                                                                </div>
                                                                <span className={`text-sm font-bold ${
                                                                    context.isAd ? (sub.tacos !== null && sub.tacos > thresholds.highAdDependencyPct ? 'text-red-600' : 'text-gray-700') :
                                                                    context.isOrganic ? (sub.organicShare !== null && sub.organicShare > 80 ? 'text-green-600' : sub.organicShare !== null && sub.organicShare < 40 ? 'text-red-600' : 'text-gray-700') :
                                                                    context.isMargin ? (sub.totalProfit < 0 ? 'text-red-600' : 'text-green-600') :
                                                                    'text-theme'
                                                                }`}>
                                                                    {context.isAd ? formatPct(sub.tacos) :
                                                                     context.isOrganic ? (sub.organicShare !== null ? `${sub.organicShare.toFixed(1)}%` : <span className="text-xs text-gray-400 font-medium">N/A</span>) :
                                                                     context.isMargin ? formatSmartMoney(sub.totalProfit) :
                                                                     `${sub.contribution.toFixed(1)}%`}
                                                                </span>
                                                            </div>
                                                        </>
                                                    )}
                                                </div>
                                            </div>

                                            {/* ... Subgroup Transactions Table ... */}
                                            {isSubExpanded && (
                                                <div className="px-6 pb-4 animate-in fade-in slide-in-from-top-1">
                                                    <div className="border border-gray-200 rounded-lg overflow-hidden bg-white shadow-sm">
                                                        <table className="tbl w-full text-xs text-left">
                                                            <thead>
                                                                {context.isReturn ? (
                                                                    <tr>
                                                                        <th className="p-2 pl-3">Date</th>
                                                                        <th className="p-2 text-right">Refund Amount</th>
                                                                        <th className="p-2 text-right">Qty</th>
                                                                        <th className="p-2">Reason / Note</th>
                                                                        <th className="p-2 text-right">Platform</th>
                                                                    </tr>
                                                                ) : (
                                                                    <tr>
                                                                        <th className="p-2 pl-3">Date</th>
                                                                        <th className="p-2 text-right">Unit Price</th>
                                                                        <th className="p-2 text-right">
                                                                            {context.isInventory || context.isAged ? 'Velocity' : 'Qty'}
                                                                        </th>
                                                                        <th className="p-2 text-right">
                                                                            {context.isInventory || context.isAged ? 'Est. Daily Rev' : 'Revenue'}
                                                                        </th>
                                                                        {(context.isAd || context.isMargin || context.isOrganic) && <th className="p-2 text-right">Ad Spend</th>}
                                                                        {context.isAd && <th className="p-2 text-right">TACoS</th>}
                                                                        {context.isOrganic && <th className="p-2 text-right">Organic % (Ads)</th>}
                                                                        {(context.isInventory || context.isAged) && <th className="p-2 text-right">Stock</th>}
                                                                        {context.isAged && <th className="p-2 text-right">Aged Qty</th>}
                                                                        {context.isAged && <th className="p-2 text-right">Aged %</th>}
                                                                        {!context.isAged && context.isInventory && <th className="p-2 text-right">Stock Cover</th>}
                                                                        {context.isTrend && <th className="p-2 text-right">Trend</th>}
                                                                        {context.isPostcode && <th className="p-2 text-right">Postcode</th>}
                                                                        <th className="p-2 text-right">Profit</th>
                                                                        <th className="p-2 text-right">Margin %</th>
                                                                        <th className="p-2 text-right">Share %</th>
                                                                    </tr>
                                                                )}
                                                            </thead>
                                                            <tbody>
                                                                {sub.items
                                                                    .filter((item: any) => context.isReturn ? item.type === 'REFUND' : true)
                                                                    .slice(0, 50) 
                                                                    .map((tx: any, idx: number) => {
                                                                        const revenue = calcRevenue(tx);
                                                                        const profit = calcProfit(tx);
                                                                        const margin = revenue !== 0 ? calcMarginPct(revenue, profit) : null;
                                                                        const isAdRow = tx.type === 'AD_COST';

                                                                        return (
                                                                        <tr key={idx} className="hover:bg-theme-10/30">
                                                                            <td className="p-2 pl-3 font-mono text-gray-600">
                                                                                {new Date(tx.date).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}
                                                                            </td>

                                                                            {context.isReturn ? (
                                                                                <>
                                                                                    <td className="p-2 text-right font-medium text-red-600">
                                                                                        -{formatSmartMoney(Math.abs(tx.refundAmount || tx.profit || 0))}
                                                                                    </td>
                                                                                    <td className="p-2 text-right font-bold text-gray-800">{tx.velocity}</td>
                                                                                    <td className="p-2 text-gray-600 truncate max-w-[200px]" title={tx.platformReason || tx.customerReason || tx.reason}>
                                                                                        {tx.platformReason || tx.customerReason || tx.reason || 'Unknown Reason'}
                                                                                    </td>
                                                                                    <td className="p-2 text-right text-xs text-gray-500">{tx.platform}</td>
                                                                                </>
                                                                            ) : (
                                                                                <>
                                                                                    <td className={`p-2 text-right font-medium ${tx.type === 'AD_COST' ? 'text-orange-600' : tx.type === 'REFUND' ? 'text-red-600' : 'text-gray-900'}`}>
                                                                                        {tx.type === 'AD_COST' ? (
                                                                                            <span className="text-[9px] bg-orange-50 text-orange-700 px-1 rounded border border-orange-100 uppercase font-bold">Ad Spend</span>
                                                                                        ) : (
                                                                                            formatSmartMoney(Math.abs(tx.price || 0))
                                                                                        )}
                                                                                    </td>
                                                                                    <td className="p-2 text-right text-gray-900 font-bold">
                                                                                        {context.isInventory || context.isAged ? tx.velocity.toFixed(3) : formatNumber(tx.velocity)}
                                                                                    </td>
                                                                                    <td className="p-2 text-right text-gray-700">{formatSmartMoney(tx.revenue)}</td>
                                                                                    {(context.isAd || context.isMargin || context.isOrganic) && (
                                                                                        <td className="p-2 text-right text-orange-700">
                                                                                            {tx.adsSpend > 0 ? formatSmartMoney(tx.adsSpend) : '-'}
                                                                                        </td>
                                                                                    )}
                                                                                    {context.isAd && (
                                                                                        <td className="p-2 text-right">
                                                                                            {tx.tacos > 0 ? (
                                                                                                <span className={`${tx.tacos > thresholds.highAdDependencyPct ? 'text-red-600 font-bold' : 'text-gray-600'}`}>
                                                                                                    {formatPct(tx.tacos)}
                                                                                                </span>
                                                                                            ) : '-'}
                                                                                        </td>
                                                                                    )}
                                                                                    {context.isOrganic && (
                                                                                        <td className="p-2 text-right">
                                                                                            {tx.organicShare !== null ? (
                                                                                                <span className={`${tx.organicShare < 40 ? 'text-red-600 font-bold' : 'text-green-600'}`}>
                                                                                                    {tx.organicShare.toFixed(1)}%
                                                                                                </span>
                                                                                            ) : <span className="text-gray-400 italic">N/A</span>}
                                                                                        </td>
                                                                                    )}

                                                                                    {(context.isInventory || context.isAged) && (
                                                                                        <>
                                                                                            <td className="p-2 text-right text-gray-800 font-medium">
                                                                                                {tx.stockLevel !== undefined ? tx.stockLevel : '-'}
                                                                                            </td>
                                                                                            {context.isAged && <td className="p-2 text-right text-amber-700 font-medium">{tx.agedStockQty || '-'}</td>}
                                                                                            {context.isAged && <td className="p-2 text-right font-bold">{(tx.agedStockPct || 0).toFixed(1)}%</td>}

                                                                                            {!context.isAged && <td className="p-2 text-right">
                                                                                                {tx.daysRemaining !== undefined ? (
                                                                                                    <span className={`${tx.daysRemaining < 14 ? 'text-red-600 font-bold' : 'text-green-600'}`}>
                                                                                                        {tx.daysRemaining.toFixed(0)}d
                                                                                                    </span>
                                                                                                ) : '-'}
                                                                                            </td>}
                                                                                        </>
                                                                                    )}
                                                                                    {context.isTrend && (
                                                                                        <td className="p-2 text-right">
                                                                                            {tx.velocityChange !== undefined ? (
                                                                                                <span className={`${tx.velocityChange < -thresholds.velocityDropPct ? 'text-red-600' : tx.velocityChange > 20 ? 'text-green-600' : 'text-gray-500'}`}>
                                                                                                    {tx.velocityChange > 0 ? '+' : ''}{tx.velocityChange.toFixed(0)}%
                                                                                                </span>
                                                                                            ) : '-'}
                                                                                        </td>
                                                                                    )}
                                                                                    {context.isPostcode && (
                                                                                        <td className="p-2 text-right text-gray-600 font-mono text-[10px]">
                                                                                            {tx.postcode || '-'}
                                                                                        </td>
                                                                                    )}

                                                                                    <td className={`p-2 text-right font-medium ${tx.profit < 0 ? 'text-red-600' : 'text-green-600'}`}>
                                                                                        {formatSmartMoney(tx.profit)}
                                                                                    </td>
                                                                                    <td className="p-2 text-right font-bold">
                                                                                        {tx.type === 'REFUND' ? (
                                                                                            <span className="text-red-500 text-[10px] uppercase bg-red-50 px-1 rounded border border-red-100">Refund</span>
                                                                                        ) : tx.margin === -Infinity || (Math.abs(tx.revenue) < 0.01 && tx.adsSpend > 0) ? (
                                                                                            <span className="text-gray-900 font-normal cursor-help" title="Margin N/A (No Revenue)">
                                                                                                N/A
                                                                                            </span>
                                                                                        ) : (
                                                                                            <span className={`${(margin || 0) < thresholds.marginBelowTargetPct ? 'text-red-600' : 'text-green-600'}`}>
                                                                                                {margin !== null ? formatPct(margin) : isAdRow ? '—' : '-'}
                                                                                            </span>
                                                                                        )}
                                                                                    </td>
                                                                                    <td className="p-2 text-right text-xs text-gray-400 font-medium">
                                                                                        {tx.contribution ? `${tx.contribution.toFixed(1)}%` : '-'}
                                                                                    </td>
                                                                                </>
                                                                            )}
                                                                        </tr>
                                                                    )})}
                                                            </tbody>
                                                        </table>
                                                        {sub.items.length > 50 && <div className="p-2 text-center text-xs text-gray-400 bg-gray-50 border-t border-gray-100">...and {sub.items.length - 50} more records</div>}
                                                    </div>
                                                </div>
                                            )}
                                        </div>
                                    );
                                })
                            }
                        </div>
                    </div>
                )}
              </div>
            );
        })}
      </div>
    );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Search, Loader2, X, Tag } from 'lucide-react';
import { SearchChip, Product } from '../../types';
import { SearchAssistantPopover } from '../search/SearchAssistantPopover';
import { ChipSelectionState, Suggestion, MetricId, ConditionId, PlatformId, TimePresetId } from '../search/types';
import { METRICS, CONDITIONS } from '../../services/search/suggestionConfig';
import { useTranslation } from 'react-i18next';

interface GlobalSearchProps {
  onSearch: (query: string | SearchChip[]) => void;
  isLoading: boolean;
  platforms?: string[];
  products?: Product[];
}

const GlobalSearch: React.FC<GlobalSearchProps> = ({ onSearch, isLoading, platforms = [], products = [] }) => {
    const { t } = useTranslation();
    const [chips, setChips] = useState<SearchChip[]>([]);
    const [inputValue, setInputValue] = useState('');
    const [searchMode, setSearchMode] = useState<'GLOBAL' | 'SKU'>('GLOBAL');
    const [isFocused, setIsFocused] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);

    // --- MAPPING LOGIC: UI Chips <-> Engine State ---
    const selectionState = useMemo<ChipSelectionState>(() => {
        // Inject prefix if in SKU mode so the engine detects it
        const effectiveText = searchMode === 'SKU' ? `sku: ${inputValue}` : inputValue;

        return {
            metrics: chips.filter(c => c.type === 'METRIC').map(c => c.value as MetricId),
            conditions: chips.filter(c => c.type === 'CONDITION').map(c => c.value as ConditionId),
            platforms: chips.filter(c => c.type === 'PLATFORM').map(c => c.value as PlatformId),
            timePreset: chips.find(c => c.type === 'TIME')?.value as TimePresetId || null,
            searchText: effectiveText
        };
    }, [chips, inputValue, searchMode]);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsFocused(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const addChip = (chip: SearchChip) => {
        // Prevent dupes
        if (chips.some(c => c.type === chip.type && c.value === chip.value)) return;
        setChips([...chips, chip]);
        setInputValue('');
        setSearchMode('GLOBAL'); // Reset mode after selection
        inputRef.current?.focus();
    };

    const removeChip = (index: number) => {
        setChips(chips.filter((_, i) => i !== index));
    };

    const handleSuggestionApply = (suggestion: Suggestion) => {
        // Handle SKU suggestion explicitly — immediately trigger search, no Enter needed
        if (suggestion.kind === 'sku') {
            const val = `SKU: ${suggestion.id}`;
            const newChips = [...chips, { type: 'TEXT' as const, value: val, label: val }];
            setChips(newChips);
            setInputValue('');
            setSearchMode('GLOBAL');
            setIsFocused(false);
            onSearch(newChips);
            return;
        }

        if (!suggestion.applies) return;

        const newChips: SearchChip[] = [];

        // Helper to find label from config ID
        const getMetricLabel = (id: string) => METRICS.find(m => m.id === id)?.label || id;
        const getConditionLabel = (id: string) => CONDITIONS.find(c => c.id === id)?.label || id;

        if (suggestion.applies.metrics) {
            suggestion.applies.metrics.forEach(m => {
                newChips.push({ type: 'METRIC', value: m, label: getMetricLabel(m) });
            });
        }
        if (suggestion.applies.conditions) {
            suggestion.applies.conditions.forEach(c => {
                newChips.push({ type: 'CONDITION', value: c, label: getConditionLabel(c) });
            });
        }
        if (suggestion.applies.platforms) {
            suggestion.applies.platforms.forEach(p => {
                newChips.push({ type: 'PLATFORM', value: p, label: p.replace(/_/g, ' ') });
            });
        }
        if (suggestion.applies.timePreset) {
            newChips.push({ type: 'TIME', value: suggestion.applies.timePreset, label: suggestion.applies.timePreset.replace(/_/g, ' ') });
        }

        // Add all distinct new chips
        const uniqueNew = newChips.filter(nc => !chips.some(ec => ec.type === nc.type && ec.value === nc.value));

        if (uniqueNew.length > 0) {
            setChips(prev => [...prev, ...uniqueNew]);
        }

        // Keep focus for more selecting
        inputRef.current?.focus();
    };

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;

        // Detect "sku:" trigger to switch modes visually
        // Matches "sku:" or "sku " at start of string
        const skuTriggerRegex = /^sku[:\s]/i;
        if (searchMode === 'GLOBAL' && skuTriggerRegex.test(val)) {
            setSearchMode('SKU');
            // Remove the trigger text from input so user just types the ID
            setInputValue(val.replace(skuTriggerRegex, '').trimStart());
            return;
        }

        setInputValue(val);
    };

    const handleSearch = () => {
        const currentInput = inputValue.trim();
        const currentChips = [...chips];

        if (searchMode === 'SKU' && currentInput) {
             const formatted = `SKU: ${currentInput}`;
             currentChips.push({ type: 'TEXT', value: formatted, label: formatted });
        } else if (currentInput) {
            // Fallback: Detect manual SKU entry if mode wasn't triggered
            if (currentInput.toLowerCase().startsWith('sku:') || currentInput.toLowerCase().startsWith('sku ')) {
                const skuVal = currentInput.substring(3).replace(/^[:\s]+/, '').trim();
                if (skuVal) {
                    const formatted = `SKU: ${skuVal}`;
                    currentChips.push({ type: 'TEXT', value: formatted, label: formatted });
                }
            } else {
                currentChips.push({ type: 'TEXT', value: currentInput, label: currentInput });
            }
        }

        // Clear state before notifying parent to prevent flicker
        setInputValue('');
        setSearchMode('GLOBAL');
        setChips([]);
        setIsFocused(false);

        if (currentChips.length > 0) {
            onSearch(currentChips);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
        if (e.key === 'Enter') {
            handleSearch();
        } else if (e.key === 'Backspace' && inputValue === '') {
            // If in SKU mode, backspace exits mode first
            if (searchMode === 'SKU') {
                setSearchMode('GLOBAL');
                e.preventDefault();
            } else if (chips.length > 0) {
                removeChip(chips.length - 1);
            }
        }
    };

    const placeholderText = searchMode === 'SKU' 
        ? t('search_placeholder_sku')
        : chips.length === 0 
            ? t('search_placeholder_main')
            : "";

    return (
        <div className="relative w-full" ref={containerRef}>
            <div 
                className={`relative flex flex-wrap items-center gap-x-2 gap-y-1 p-1 border rounded-md bg-white/80 transition-all shadow-sm min-h-[20px] cursor-text ${searchMode === 'SKU' ? 'ring-2 ring-teal-500 border-teal-500' : 'border-gray-200 focus-within:ring-2 focus-within:ring-theme'}`}
                onClick={() => inputRef.current?.focus()}
            >
                <Search 
                    className="w-4 h-4 text-gray-400 pointer-events-none ml-2" 
                    style={{ display: (chips.length > 0 || inputValue || searchMode === 'SKU') ? 'none' : 'block' }} 
                />

                {chips.map((chip, index) => {
                    const isSku = chip.label.startsWith('SKU:');
                    return (
                        <div 
                            key={index} 
                            className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border animate-in fade-in zoom-in-90 ${
                                chip.type === 'METRIC' ? 'bg-theme-10 text-theme border-theme-20' :
                                chip.type === 'TIME' ? 'bg-blue-100 text-blue-700 border-blue-200' :
                                chip.type === 'PLATFORM' ? 'bg-purple-100 text-purple-700 border-purple-200' :
                                chip.type === 'CONDITION' ? 'bg-amber-100 text-amber-700 border-amber-200' :
                                isSku ? 'bg-teal-100 text-teal-800 border-teal-200' :
                                'bg-gray-100 text-gray-700 border-gray-200'
                            }`}
                        >
                            {isSku && <Tag className="w-3 h-3 text-teal-600" />}
                            <span>{chip.label}</span>
                            <button onClick={(e) => { e.stopPropagation(); removeChip(index); }} className="hover:bg-black/10 rounded-full p-0.5">
                                <X className="w-3 h-3" />
                            </button>
                        </div>
                    );
                })}

                {/* SKU Mode Visual Indicator */}
                {searchMode === 'SKU' && (
                    <div className="flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border bg-teal-100 text-teal-800 border-teal-200 animate-in fade-in zoom-in-90 select-none">
                        <Tag className="w-3 h-3" />
                        <span>{t('search_sku_mode_label')}</span>
                    </div>
                )}

                <input
                    ref={inputRef}
                    type="text"
                    value={inputValue}
                    onChange={handleInputChange}
                    onFocus={() => setIsFocused(true)}
                    onKeyDown={handleKeyDown}
                    placeholder={placeholderText}
                    className="flex-1 min-w-[120px] bg-transparent border-none focus:ring-0 p-1 text-sm placeholder:text-gray-400"
                />

                {isLoading && (
                    <Loader2 className="absolute right-4 top-1/2 -translate-y-1/2 w-5 h-5 text-theme animate-spin" />
                )}
            </div>

            {/* Smart Suggestion Engine */}
            <SearchAssistantPopover 
                state={selectionState}
                onApply={handleSuggestionApply}
                onClear={() => setChips([])}
                isVisible={isFocused}
                products={products}
            />
        </div>
    );
};

