                                                        }
                                                    </td>
                                                    <td className="r"><span className="v-num font-bold text-teal-700">{fmt(r.totalCharge)}</span></td>
                                                    {parsed[0]?.weight ? <td className="r"><span className="v-dim">{r.weight ? `${r.weight}kg` : '—'}</span></td> : null}
                                                    <td><span className="sello-badge badge-green text-[9px]">ERP</span></td>
                                                </tr>
                                            ))}
                                            {stats.formula > 0 && (
                                                <tr className="bg-amber-50/50">
                                                    <td colSpan={5} className="text-[10px] text-amber-700 font-medium px-4 py-2">
                                                        + {stats.formula} SKUs will use formula fallback (not in ERP file but have dimensions)
                                                    </td>
                                                </tr>
                                            )}
                                        </tbody>
                                    </table>
                                </div>
                            </div>

                            {/* Try again */}
                            <button onClick={() => { setParsed(null); setError(null); }}
                                className="text-xs text-gray-400 hover:text-gray-600 flex items-center gap-1">
                                Upload a different file
                            </button>
                        </div>
                    )}
                </div>

                {/* Footer */}
                <div className="flex items-center justify-between px-6 py-4 border-t border-gray-100 bg-gray-50 rounded-b-2xl">
                    <div className="text-xs text-gray-400">
                        Applying updates <strong>product.postage</strong> — used in all margin, profit and strategy calculations
                    </div>
                    <div className="flex gap-3">
                        <button onClick={onClose} className="sello-btn">Cancel</button>
                        {parsed && stats && (
                            <button onClick={handleConfirm}
                                className="sello-btn cta flex items-center gap-1.5 text-white border-transparent"
                                style={{ background: '#134E4A' }}>
                                <CheckCircle2 className="w-4 h-4" />
                                Apply {stats.erp + stats.formula} Rates
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default FreightUploadModal;

import React, { useState, useRef } from 'react';
import { formatSmartMoney } from '../../../utils/format';
import { Upload, X, Check, AlertCircle, Loader2, RotateCcw, Info, Link as LinkIcon, FileQuestion, Filter, Trash2, FileText, MessageSquare } from 'lucide-react';
import * as XLSX from 'xlsx';
import { RefundLog } from '../../../types';
import { VAT_MULTIPLIER } from '../../../constants';
import { asDateKeyNaive } from '../../../services/dateUtils';
import { getCanonicalSku } from '../../../services/skuNormalization';

interface ReturnsUploadModalProps {
    onClose: () => void;
    onConfirm: (refunds: RefundLog[]) => void;
    onReset?: () => void;
    existingOrders?: Map<string, string>; // OrderID -> Platform
}

const ReturnsUploadModal: React.FC<ReturnsUploadModalProps> = ({ onClose, onConfirm, onReset, existingOrders }) => {
    const [dragActive, setDragActive] = useState(false);
    const [isProcessing, setIsProcessing] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // File states
    const [detailsFile, setDetailsFile] = useState<File | null>(null);
    const [commentsFile, setCommentsFile] = useState<File | null>(null);

    const [parsedRefunds, setParsedRefunds] = useState<RefundLog[] | null>(null);
    const [stats, setStats] = useState({ count: 0, totalValue: 0, matchedOrders: 0, orphans: 0 });
    const [debugInfo, setDebugInfo] = useState<{ unmatchedSamples: string[], dbSamples: string[], mappedColumn: string }>({ unmatchedSamples: [], dbSamples: [], mappedColumn: '' });

    const [importStrategy, setImportStrategy] = useState<'ALL' | 'MATCHED_ONLY'>('ALL');
    const [isResetConfirmOpen, setIsResetConfirmOpen] = useState(false);

    const detailsInputRef = useRef<HTMLInputElement>(null);
    const commentsInputRef = useRef<HTMLInputElement>(null);

    const handleDrag = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setDragActive(true);
        } else if (e.type === "dragleave") {
            setDragActive(false);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setDragActive(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            // For drop, we default to details if empty
            if (!detailsFile) setDetailsFile(e.dataTransfer.files[0]);
            else if (!commentsFile) setCommentsFile(e.dataTransfer.files[0]);
        }
    };

    const readExcel = (file: File): Promise<any[]> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = (e) => {
                try {
                    const data = e.target?.result;
                    if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
                        const workbook = XLSX.read(data, { type: 'array', cellDates: true });
                        const sheet = workbook.Sheets[workbook.SheetNames[0]];
                        resolve(XLSX.utils.sheet_to_json(sheet, { header: 1 }) as any[]);
                    } else {
                        const text = data as string;
                        resolve(text.split('\n').map(l => l.split(',')));
                    }
                } catch (err) {
                    reject(err);
                }
            };
            if (file.name.endsWith('.xlsx')) reader.readAsArrayBuffer(file);
            else reader.readAsText(file);
        });
    };

    const processFiles = async () => {
        setIsProcessing(true);
        setError(null);

        try {
            if (!detailsFile || !commentsFile) throw new Error("Both files required for import");
            const detailsRows = await readExcel(detailsFile);
            const commentsRows = await readExcel(commentsFile);
            analyzeV2Rows(detailsRows, commentsRows);
        } catch (err: any) {
            setError(err.message || "Failed to process files");
            setIsProcessing(false);
        }
    };

    // Helper to generate a deterministic ID based on row content
    const generateRefundId = (sku: string, date: string, amount: number, qty: number, reason: string | undefined, orderId: string) => {
        const safeReason = (reason || 'unknown').trim().toLowerCase().substring(0, 20);
        const signature = `${sku.trim().toUpperCase()}|${orderId}|${date}|${amount.toFixed(2)}|${qty}|${safeReason}`;

        let hash = 0;
        for (let i = 0; i < signature.length; i++) {
            const char = signature.charCodeAt(i);
            hash = (hash << 5) - hash + char;
            hash |= 0;
        }
        return `ref-${Math.abs(hash).toString(36)}`;
    };

    const findColPriority = (headers: string[], terms: string[]) => {
        for (const term of terms) {
            const idx = headers.findIndex(h => h === term || h.includes(term));
            if (idx !== -1) return idx;
        }
        return -1;
    };

    const analyzeV2Rows = (detailsRows: any[][], commentsRows: any[][]) => {
        // 1. Map Comments by Order ID
        const commentMap = new Map<string, { cn: string, en: string }>();
        if (commentsRows.length > 1) {
            const cHeaders = commentsRows[0].map(h => String(h).trim().toLowerCase().replace(/[\s_\-/]/g, ''));
            const cOrderIdx = findColPriority(cHeaders, ['outerorderid', 'orderid']);
            const cnIdx = findColPriority(cHeaders, ['commentcn', 'chinesememo']);
            const enIdx = findColPriority(cHeaders, ['commenten', 'englishmemo']);

            if (cOrderIdx !== -1) {
                for (let i = 1; i < commentsRows.length; i++) {
                    const row = commentsRows[i];
                    const oid = String(row[cOrderIdx] || '').trim();
                    if (oid) {
                        commentMap.set(oid, {
                            cn: cnIdx !== -1 ? String(row[cnIdx] || '') : '',
                            en: enIdx !== -1 ? String(row[enIdx] || '') : ''
                        });
                    }
                }
            }
        }

        // 2. Parse Details
        if (detailsRows.length < 2) throw new Error("Details file empty");
        const dHeaders = detailsRows[0].map(h => String(h).trim().toLowerCase().replace(/[\s_\-/]/g, ''));

        const skuIdx = findColPriority(dHeaders, ['skucode', 'sku']);
        const orderIdx = findColPriority(dHeaders, ['outerorderid', 'orderid']);
        const amtIdx = findColPriority(dHeaders, ['returnamt', 'amount']);
        const qtyIdx = findColPriority(dHeaders, ['returnqty', 'qty']);
        const typeIdx = findColPriority(dHeaders, ['ordertype', 'type']);

        // Look for reason detail first, then fallback to general reason
        let reasonIdx = findColPriority(dHeaders, ['returnreasondetail', 'return_reason_detail']);
        if (reasonIdx === -1) reasonIdx = findColPriority(dHeaders, ['returnreason', 'reason']);

        // Update date columns to include order date and payment date candidates
        const dateIdx = findColPriority(dHeaders, ['ordertime', 'time', 'orderdate', 'date', 'refundtime', 'refund_time']);
        const platformIdx  = findColPriority(dHeaders, ['platformnamelevel1', 'platformname', 'platform']);
        const platform2Idx = findColPriority(dHeaders, ['platformnamelevel2']);

        const missingCols: string[] = [];
        if (skuIdx === -1) missingCols.push("SKU (sku_code)");
        if (orderIdx === -1) missingCols.push("Order ID (outer_order_id)");
        if (amtIdx === -1) missingCols.push("Refund Amount (return_amt)");

        if (missingCols.length > 0) {
            throw new Error(`Missing required columns in Details file: ${missingCols.join(', ')}`);
        }

        // Group by Order ID to handle Freight aggregation
        const orderGroups = new Map<string, { freight: number, items: any[] }>();

        for (let i = 1; i < detailsRows.length; i++) {
            const row = detailsRows[i];
            const oid = String(row[orderIdx] || '').trim();
            if (!oid) continue;

            if (!orderGroups.has(oid)) orderGroups.set(oid, { freight: 0, items: [] });
            const group = orderGroups.get(oid)!;

            const rawSku = String(row[skuIdx] || '').trim();
            const amt = parseFloat(String(row[amtIdx])) || 0; // V2 is Ex-VAT already

            if (rawSku.toLowerCase() === 'freight') {
                group.freight += amt;
            } else {
                const sku = getCanonicalSku(rawSku);
                group.items.push({ row, sku, amt, rawSku });
            }
        }

        const refunds: RefundLog[] = [];
        let totalValue = 0;
        let matchedOrders = 0;
        let orphans = 0;
        const unmatchedSamples: string[] = [];

        orderGroups.forEach((group, oid) => {
            // ERP now exports correct qty/amt per SKU line (fixed Mar 2026)
            // No resend correction needed — each line already has its own qty and cost
            const totalItemVal = group.items.reduce((sum, it) => sum + it.amt, 0);

            group.items.forEach(it => {
                const { row, sku, rawSku } = it;
                let amt = it.amt;

                let qty = 0;
                if (qtyIdx !== -1) {
                    const rawQty = row[qtyIdx];
                    if (rawQty === undefined || rawQty === null || String(rawQty).trim() === '') {
                        qty = 1;
                    } else {
                        qty = parseFloat(String(rawQty)) || 0;
                    }
                } else {
                    qty = 1;
                }

                // Allocate freight proportionally by item value
                const allocatedFreight = totalItemVal > 0
                    ? (amt / totalItemVal) * group.freight
                    : (group.freight / group.items.length);

                const oType = typeIdx !== -1 ? String(row[typeIdx]).toLowerCase() : 'refund';
                const reason = reasonIdx !== -1 ? String(row[reasonIdx]) : undefined;

                // Date
                let dateStr = new Date().toISOString();
                const rawDate = (dateIdx !== -1) ? row[dateIdx] : undefined;
                if (rawDate) {
                    const dKey = asDateKeyNaive(rawDate);
                    if (dKey) dateStr = new Date(dKey).toISOString();
                }

                // Platform Match — use level2 if available (e.g. "Amazon(UK) FBA" not "Amazon(UK)")
                // Same logic as salesImportWorker: prefer level2, fall back to level1
                let finalPlatform: string | undefined = undefined;
                if (platformIdx !== -1 || platform2Idx !== -1) {
                    const p1 = platformIdx  !== -1 ? String(row[platformIdx]  || '').trim() : '';
                    const p2 = platform2Idx !== -1 ? String(row[platform2Idx] || '').trim() : '';
                    if (p2 && p2 !== '-' && p2.toLowerCase() !== 'unknown') {
                        if (p1 && !p2.toLowerCase().includes(p1.toLowerCase()) && p2.length < 5) {
                            finalPlatform = `${p1} ${p2}`;
                        } else {
                            finalPlatform = p2;
                        }
                    } else if (p1) {
                        finalPlatform = p1;
                    }
                }
                if (existingOrders && existingOrders.size > 0) {
                    if (existingOrders.has(oid)) {
                        matchedOrders++;
                        finalPlatform = existingOrders.get(oid);
                    } else {
                        orphans++;
                        if (unmatchedSamples.length < 10) unmatchedSamples.push(`${oid} (SKU: ${sku})`);
                    }
                }

                const comments = commentMap.get(oid);
                const uniqueId = generateRefundId(rawSku, dateStr, amt, qty, reason, oid);

                let resendBase = undefined;
                if (oType.includes('resend') || oid.toLowerCase().includes('-resend')) {
                    // Strip ALL -resend suffixes (handles double-resend like W123-1M-V-resend-resend)
                    let base = oid;
                    while (/-resend$/i.test(base)) base = base.replace(/-resend$/i, '');
                    resendBase = base;
                }

                refunds.push({
                    id: uniqueId,
                    sku,
                    rawSku,
                    date: dateStr,
                    amount: amt, // Ex-VAT
                    freightAmount: allocatedFreight, // Ex-VAT
                    quantity: qty,
                    platform: finalPlatform,
                    reason: reason,
                    orderId: oid,
                    orderType: oType as any,
                    resendBaseOrderId: resendBase,
                    commentCn: comments?.cn,
                    commentEn: comments?.en
                });

                totalValue += ((amt + allocatedFreight) * VAT_MULTIPLIER); // Display Total Inc-VAT
            });
        });

        setParsedRefunds(refunds);
        setStats({ count: refunds.length, totalValue, matchedOrders, orphans });
        setDebugInfo({ unmatchedSamples, dbSamples: [], mappedColumn: 'outer_order_id' });
        setIsProcessing(false);
    };

    const handleConfirm = () => {
        if (!parsedRefunds) return;
        let finalData = parsedRefunds;
        if (importStrategy === 'MATCHED_ONLY' && existingOrders) {
            finalData = parsedRefunds.filter(r => r.orderId && existingOrders.has(r.orderId));
        }
        onConfirm(finalData);
    };

    const recordsToImport = importStrategy === 'ALL' ? stats.count : stats.matchedOrders;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-xl flex flex-col relative overflow-hidden max-h-[90vh]">

                {/* RESET CONFIRMATION OVERLAY */}
                {isResetConfirmOpen && (
                    <div className="absolute inset-0 z-10 bg-white/95 backdrop-blur-sm flex flex-col items-center justify-center p-8 animate-in fade-in duration-200">
                        <div className="bg-red-50 p-4 rounded-full mb-6">
                            <AlertCircle className="w-12 h-12 text-red-600" />
                        </div>
                        <h3 className="text-2xl font-bold text-gray-900 mb-2">Clear Refund History?</h3>
                        <p className="text-gray-500 text-center max-w-md mb-8">
                            This will <strong>permanently delete</strong> all existing refund records. This is recommended if your current data contains errors.
                        </p>
                        <div className="flex gap-4">
                            <button onClick={() => setIsResetConfirmOpen(false)} className="px-6 py-3 text-gray-700 font-medium hover:bg-gray-100 rounded-xl transition-colors">Cancel</button>
                            <button onClick={() => { if (onReset) onReset(); setIsResetConfirmOpen(false); }} className="px-6 py-3 bg-red-600 text-white font-medium rounded-xl hover:bg-red-700 shadow-lg hover:shadow-red-500/30 transition-all flex items-center gap-2"><Trash2 className="w-4 h-4" />Yes, Wipe Everything</button>
                        </div>
                    </div>
                )}

                <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-2xl">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-red-100 rounded-lg text-red-600"><RotateCcw className="w-5 h-5" /></div>
                        <div><h2 className="text-xl font-bold text-gray-900">Import Refunds &amp; Returns</h2><p className="text-xs text-gray-500">Upload the &quot;Return Details&quot; and &quot;Comments&quot; files from ERP.</p></div>
                    </div>
                    <button onClick={onClose}><X className="w-5 h-5 text-gray-500 hover:text-gray-700" /></button>
                </div>

                <div className="p-6 overflow-y-auto">
                    {!parsedRefunds ? (
                        <div className="space-y-6">
                            <div
                                className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center text-center transition-all ${dragActive ? 'border-theme bg-theme-10' : 'border-gray-300 hover:border-gray-400 bg-gray-50/50'}`}
                                onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
                            >
                                <div className="space-y-4 w-full max-w-sm">
                                    <div className="flex items-center justify-between p-3 bg-white rounded-lg border border-gray-200 shadow-sm cursor-pointer hover:border-theme-20" onClick={() => detailsInputRef.current?.click()}>
                                        <div className="flex items-center gap-3">
                                            <div className="p-2 bg-blue-50 text-blue-600 rounded"><FileText className="w-4 h-4" /></div>
                                            <div className="text-left"><span className="text-xs font-medium text-gray-700 block">Return Details.xlsx</span><span className="text-[10px] text-gray-400">{detailsFile ? detailsFile.name : 'Required'}</span></div>
                                        </div>
                                        {detailsFile ? <Check className="w-4 h-4 text-green-500" /> : <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded">Select</span>}
                                    </div>
                                    <input ref={detailsInputRef} type="file" className="hidden" onChange={(e) => e.target.files && setDetailsFile(e.target.files[0])} accept=".xlsx,.xls" />

                                    <div className="flex items-center justify-between p-3 bg-white rounded-lg border border-gray-200 shadow-sm cursor-pointer hover:border-theme-20" onClick={() => commentsInputRef.current?.click()}>
                                        <div className="flex items-center gap-3">
                                            <div className="p-2 bg-amber-50 text-amber-600 rounded"><MessageSquare className="w-4 h-4" /></div>
                                            <div className="text-left"><span className="text-xs font-medium text-gray-700 block">Return Order Comment.xlsx</span><span className="text-[10px] text-gray-400">{commentsFile ? commentsFile.name : 'Required'}</span></div>
                                        </div>
                                        {commentsFile ? <Check className="w-4 h-4 text-green-500" /> : <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded">Select</span>}
                                    </div>
                                    <input ref={commentsInputRef} type="file" className="hidden" onChange={(e) => e.target.files && setCommentsFile(e.target.files[0])} accept=".xlsx,.xls" />
                                </div>

                                <p className="text-xs text-gray-400 mt-4">Drag & drop files here or click boxes to browse.</p>
                            </div>

                            {error && <div className="p-3 bg-red-50 text-red-700 border border-red-100 rounded-lg text-xs flex items-center gap-2"><AlertCircle className="w-4 h-4" />{error}</div>}

                            <button
                                onClick={processFiles}
                                disabled={isProcessing || !detailsFile || !commentsFile}
                                className="w-full py-3 bg-theme text-white font-medium rounded-xl shadow-md hover:bg-theme disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                            >
                                {isProcessing ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Process Files'}
                            </button>
                        </div>
                    ) : (
                        <div className="space-y-6 text-center">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="p-4 bg-red-50 rounded-xl border border-red-100">
                                    <div className="text-2xl font-bold text-red-700">{stats.count}</div>
                                    <div className="text-xs text-red-600 font-medium uppercase">Refunds Found</div>
                                </div>
                                <div className="p-4 bg-gray-50 rounded-xl border border-gray-100">
                                    <div className="text-2xl font-bold text-gray-700">{formatSmartMoney(stats.totalValue)}</div>
                                    <div className="text-xs text-gray-600 font-medium uppercase">Total Value (Inc VAT)</div>
                                </div>
                            </div>

                            {existingOrders && existingOrders.size > 0 ? (
                                <div className={`p-4 rounded-xl border flex flex-col gap-3 text-left ${stats.orphans > 0 ? 'bg-amber-50 border-amber-200' : 'bg-green-50 border-green-200'}`}>
                                    <div className="flex items-center gap-3">
                                        {stats.orphans > 0 ? <AlertCircle className="w-6 h-6 text-amber-600 flex-shrink-0" /> : <LinkIcon className="w-6 h-6 text-green-600 flex-shrink-0" />}
                                        <div>
                                            <h4 className={`text-sm font-bold ${stats.orphans > 0 ? 'text-amber-800' : 'text-green-800'}`}>{stats.orphans > 0 ? 'Order Linking Issues' : 'Linked Successfully'}</h4>
                                            <p className="text-xs text-gray-600 mt-1">Matched {stats.matchedOrders} orders. {stats.orphans > 0 && <span className="font-bold">{stats.orphans} unmatched.</span>}</p>
                                        </div>
                                    </div>

                                    {stats.orphans > 0 && (
                                        <div className="mt-2 pt-2 border-t border-amber-200 space-y-3">
                                            <div className="bg-white/60 p-2 rounded border border-amber-200/60">
                                                <div className="flex items-start gap-2">
                                                    <div className="mt-0.5"><FileQuestion className="w-3.5 h-3.5 text-amber-600" /></div>
                                                    <div className="flex-1">
                                                        <p className="text-xs font-bold text-amber-800 mb-1">Mismatch Analysis (Top 10):</p>
                                                        <ul className="text-[10px] text-amber-900 font-mono space-y-1 mb-2">
                                                            {debugInfo.unmatchedSamples.map((s, i) => (
                                                                <li key={i} className="flex items-center gap-1.5">
                                                                    <span className="w-1 h-1 rounded-full bg-amber-400 flex-shrink-0"></span>
                                                                    <span className="opacity-90">{s}</span>
                                                                </li>
                                                            ))}
                                                        </ul>
                                                        <p className="text-[10px] text-amber-700 italic leading-relaxed">
                                                            <strong>Likely Cause:</strong> Order IDs not found in Sales History. <br />
                                                            Ensure sales data covers the dates for these returns.
                                                        </p>
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="flex flex-col gap-2">
                                                <p className="text-xs font-bold text-amber-900">Unmatched Strategy:</p>
                                                <div className="flex gap-3">
                                                    <button onClick={() => setImportStrategy('ALL')} className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded-lg border text-xs font-bold transition-all ${importStrategy === 'ALL' ? 'bg-amber-600 text-white border-amber-700' : 'bg-white text-amber-800 border-amber-200'}`}>Keep All</button>
                                                    <button onClick={() => setImportStrategy('MATCHED_ONLY')} className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 rounded-lg border text-xs font-bold transition-all ${importStrategy === 'MATCHED_ONLY' ? 'bg-green-600 text-white border-green-700' : 'bg-white text-green-800 border-green-200'}`}><Filter className="w-3 h-3" /> Exclude Unmatched</button>
                                                </div>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            ) : (
                                <div className="p-4 rounded-xl border bg-gray-50 border-gray-200 text-left text-xs text-gray-500">
                                    <p><strong>Note:</strong> No sales history loaded. Validation skipped.</p>
                                </div>
                            )}

                            <div className="bg-blue-50/50 p-3 rounded-lg border border-blue-100 text-xs text-blue-800 text-left">
                                <Info className="w-4 h-4 inline mr-1 mb-0.5" />
                                <strong>VAT Handling:</strong> Values are stored Ex-VAT to align with ERP data. Displayed values are VAT-Inclusive. Freight costs have been allocated to items.
                            </div>
                        </div>
                    )}
                </div>

                <div className="p-6 border-t bg-gray-50 flex justify-between items-center rounded-b-2xl">
                    <div>
                        {onReset && (
                            <button onClick={() => setIsResetConfirmOpen(true)} className="px-3 py-1.5 bg-white border border-red-100 text-red-500 text-xs font-bold rounded-lg hover:bg-red-50 transition-colors flex items-center gap-1.5 shadow-sm">
                                <Trash2 className="w-4 h-4" /> Reset Data
                            </button>
                        )}
                    </div>
                    <div className="flex gap-3">
                        <button onClick={onClose} className="px-4 py-2 text-gray-700 hover:bg-gray-200 rounded-lg text-sm font-bold transition-colors">Cancel</button>
                        {parsedRefunds && parsedRefunds.length > 0 && (
                            <button onClick={handleConfirm} className="px-4 py-2 bg-theme text-white text-sm font-bold rounded-lg shadow-md hover:bg-theme transition-colors flex items-center gap-2">
                                <Check className="w-4 h-4" /> Import {recordsToImport} Refunds
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ReturnsUploadModal;

import React, { useState, useRef, useMemo } from 'react';
import { formatSmartMoney } from '../../../utils/format';
import { Product, PricingRules, HistoryPayload } from '../../../types';
import { Upload, X, FileBarChart, AlertCircle, Check, Loader2, RefreshCw, Calendar, ArrowRight, HelpCircle, Settings2, DollarSign, Tag, Truck, RotateCcw, Search, Hash } from 'lucide-react';
import { asDateKeyNaive } from '../../../services/dateUtils';
import { getCanonicalSku } from '../../../services/skuNormalization';

export type { HistoryPayload };

interface SalesImportModalProps {
    products: Product[];
    pricingRules: PricingRules;
    learnedAliases?: Record<string, string>;
    onClose: () => void;
    onResetData?: () => void;
    onConfirm: (
        updatedProducts: Product[],
        dateLabels?: { current: string, last: string },
        historyPayload?: HistoryPayload[],
        shipmentLogs?: any[],
        discoveredPlatforms?: string[],
        newlyLearnedAliases?: Record<string, string>
    ) => void | Promise<void>;
}

interface ColumnMapping {
    sku: string;
    qty: string;
    revenue: string;
    date?: string;
    platform?: string;
    platformLevel2?: string; // New: Detect FBA/FBM distinction
    // Extended ERP Columns
    category?: string;
    cogs?: string;
    sellingFee?: string;
    adsFee?: string;
    postage?: string;
    logisticsService?: string; // New field for rate calibration
    extraFreight?: string;
    otherFee?: string;
    subscriptionFee?: string;
    wmsFee?: string;
    profitExclRn?: string; // New: Absolute Profit currency
    profitExclRnPercent?: string; // New: Net PM%
    outerOrderId?: string; // New: Unique Order ID
    orderType?: string;    // New: order_type (normal vs ad_only)
    receivePostcode?: string; // New: Receive Postcode
    logisticPartner?: string; // New: Logistic Partner (label_provider)
}

const SalesImportModal: React.FC<SalesImportModalProps> = ({ products, pricingRules, learnedAliases = {}, onClose, onResetData, onConfirm }) => {
    const [step, setStep] = useState<'upload' | 'mapping' | 'resolution' | 'preview'>('upload');
    const [isProcessing, setIsProcessing] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [isResetConfirmOpen, setIsResetConfirmOpen] = useState(false);

    const [rawHeaders, setRawHeaders] = useState<string[]>([]);
    const [rawRows, setRawRows] = useState<any[][]>([]);
    const [importProgress, setImportProgress] = useState(0);
    const [importProgressText, setImportProgressText] = useState('');
    const [isConfirmingImport, setIsConfirmingImport] = useState(false);

    const [mapping, setMapping] = useState<ColumnMapping>({ sku: '', qty: '', revenue: '' });
    const [periodDays, setPeriodDays] = useState<number>(30); // Default to 30 days calculation if no dates
    const [showAdvancedMapping, setShowAdvancedMapping] = useState(false);

    const [previewData, setPreviewData] = useState<any>(null);
    const [unknownSkus, setUnknownSkus] = useState<Record<string, { count: number, revenue: number, masterSku: string | null }>>({});
    const [resolvedAliases, setResolvedAliases] = useState<Record<string, string>>({});

    const fileInputRef = useRef<HTMLInputElement>(null);
    const revenueDisplay = useMemo(() => {
        const value = Number(previewData?.stats?.totalRevenue || 0);
        return `£${value.toLocaleString()}`;
    }, [previewData?.stats?.totalRevenue]);
    const revenueFontClass = useMemo(() => {
        const len = revenueDisplay.length;
        if (len >= 14) return 'text-sm';
        if (len >= 12) return 'text-base';
        if (len >= 10) return 'text-lg';
        return 'text-2xl';
    }, [revenueDisplay]);

    const handleConfirmImport = async () => {
        if (!previewData || isConfirmingImport) return;

        setIsConfirmingImport(true);
        setImportProgress(5);
        setImportProgressText('Applying import to app data...');

        let progressInterval: ReturnType<typeof setInterval> | null = null;
        try {
            await new Promise<void>(resolve => requestAnimationFrame(() => resolve()));
            progressInterval = setInterval(() => {
                setImportProgress(prev => (prev >= 90 ? prev : prev + 5));
            }, 180);

            await Promise.resolve(onConfirm(
                previewData.updates,
                { current: previewData.stats.dateLabel, last: "Previous" },
                previewData.history,
                previewData.shipmentLogs,
                previewData.stats.discoveredPlatforms,
                resolvedAliases
            ));

            setImportProgress(100);
            setImportProgressText('Import complete');
        } catch (err) {
            console.error(err);
            setError('Failed to apply import. Please try again.');
        } finally {
            if (progressInterval) clearInterval(progressInterval);
            setIsConfirmingImport(false);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files?.[0]) processFile(e.target.files[0]);
    };

    const processFile = (file: File) => {
        setIsProcessing(true);
        setImportProgress(0);
        setImportProgressText('Reading file...');
        setError(null);

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const worker = new Worker(
                    new URL('../../../workers/salesImportWorker.ts', import.meta.url),
                    { type: 'module' }
                );
                worker.onmessage = (message) => {
                    const payload = message.data;
                    if (payload?.type === 'progress') {
                        setImportProgress(payload.progress || 0);
                        setImportProgressText(payload.message || 'Processing...');
                        return;
                    }

                    if (payload?.type === 'parsed') {
                        worker.terminate();
                        setRawHeaders(payload.headers || []);
                        setRawRows(payload.rows || []);
                        setMapping(payload.detectedMapping || { sku: '', qty: '', revenue: '' });
                        setStep('mapping');
                        setIsProcessing(false);
                        setImportProgress(100);
                        setImportProgressText('Mapping required');
                        return;
                    }

                    worker.terminate();
                    if (payload?.success) {
                        setRawHeaders(payload.headers || []);
                        setRawRows(payload.rows || []);
                        if (payload.detectedMapping) setMapping(payload.detectedMapping);
                        setPreviewData(payload);
                        if (Object.keys(payload.unknownSkus || {}).length > 0) {
                            setUnknownSkus(payload.unknownSkus);
                            setStep('resolution');
                        } else {
                            setStep('preview');
                        }
                        setImportProgress(100);
                        setImportProgressText('Import analysis complete');
                    } else {
                        setError(payload?.error || 'Processing failed');
                    }
                    setIsProcessing(false);
                };

                worker.onerror = (err) => {
                    worker.terminate();
                    setError('Processing error: ' + err.message);
                    setIsProcessing(false);
                };

                worker.postMessage({
                    fileName: file.name,
                    fileBuffer: data instanceof ArrayBuffer ? data : undefined,
                    fileText: typeof data === 'string' ? data : undefined,
                    products,
                    pricingRules,
                    learnedAliases,
                    extraAliases: {}
                });
                return;
            } catch (err) {
                console.error(err);
                setError("Failed to parse file.");
            }
            setIsProcessing(false);
        };

        if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) reader.readAsArrayBuffer(file);
        else reader.readAsText(file);
    };



    const handleManualAnalyze = () => {
        if (!mapping.sku || !mapping.qty || !mapping.revenue) {
            setError("Please map at least SKU, Quantity, and Revenue.");
            return;
        }

        const worker = new Worker(
            new URL('../../../workers/salesImportWorker.ts', import.meta.url),
            { type: 'module' }
        );

        setIsProcessing(true);
        setImportProgress(0);
        setImportProgressText('Analyzing mapped data...');

        worker.onmessage = (e) => {
            const payload = e.data;
            if (payload?.type === 'progress') {
                setImportProgress(payload.progress || 0);
                setImportProgressText(payload.message || 'Processing...');
                return;
            }

            worker.terminate();
            if (payload.success) {
                setPreviewData(payload);
                if (Object.keys(payload.unknownSkus || {}).length > 0) {
                    setUnknownSkus(payload.unknownSkus);
                    setStep('resolution');
                } else {
                    setStep('preview');
                }
                setImportProgress(100);
                setImportProgressText('Analysis complete');
            } else {
                setError(payload.error || 'Processing failed');
            }
            setIsProcessing(false);
        };

        worker.onerror = (err) => {
            worker.terminate();
            setError('Processing error: ' + err.message);
            setIsProcessing(false);
        };

        worker.postMessage({
            headers: rawHeaders,
            rows: rawRows,
            mapping,
            products,
            pricingRules,
            learnedAliases,
            extraAliases: {}
        });
    };

    const mapField = (field: keyof ColumnMapping, value: string) => {
        setMapping(prev => ({ ...prev, [field]: value }));
    };

    const analyzeWithResolutions = () => {
        const newAliases: Record<string, string> = {};
        (Object.entries(unknownSkus) as [string, { count: number, revenue: number, masterSku: string | null }][]).forEach(([fileSku, data]) => {
            if (data.masterSku && products.some(p => p.sku === data.masterSku)) {
                newAliases[fileSku] = data.masterSku;
            }
        });

        const worker = new Worker(
            new URL('../../../workers/salesImportWorker.ts', import.meta.url),
            { type: 'module' }
        );

        setIsProcessing(true);
        setImportProgress(0);
        setImportProgressText('Reprocessing with SKU resolutions...');

        worker.onmessage = (e) => {
            const payload = e.data;
            if (payload?.type === 'progress') {
                setImportProgress(payload.progress || 0);
                setImportProgressText(payload.message || 'Processing...');
                return;
            }

            worker.terminate();
            if (payload.success) {
                setPreviewData(payload);
                setResolvedAliases(payload.resolvedAliases);
                setStep('preview');
                setImportProgress(100);
                setImportProgressText('Resolution complete');
            } else {
                setError(payload.error || 'Processing failed');
            }
            setIsProcessing(false);
        };

        worker.onerror = (err) => {
            worker.terminate();
            setError('Processing error: ' + err.message);
            setIsProcessing(false);
        };

        worker.postMessage({
            headers: rawHeaders,
            rows: rawRows,
            mapping,
            products,
            pricingRules,
            learnedAliases,
            extraAliases: newAliases
        });
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl flex flex-col max-h-[90vh] animate-in zoom-in-95 duration-200">
                <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-xl">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-theme-10 text-theme rounded-lg">
                            <FileBarChart className="w-5 h-5" />
                        </div>
                        <h2 className="text-xl font-bold text-gray-900">Import Sales Transaction Report</h2>
                    </div>
                    <button onClick={onClose}><X className="w-5 h-5 text-gray-500" /></button>
                </div>

                <div className="p-6 flex-1 overflow-y-auto relative">
                    {isProcessing && step !== 'preview' && step !== 'upload' && (
                        <div className="absolute inset-0 z-20 bg-white/80 backdrop-blur-sm flex flex-col items-center justify-center p-8 animate-in fade-in duration-200">
                            <Loader2 className="w-12 h-12 text-theme animate-spin mb-4" />
                            <h3 className="text-xl font-bold text-gray-900">Processing Data</h3>
                            <p className="text-gray-500 text-center mt-2">
                                Processing {rawRows.length} rows... this may take a moment
                            </p>
                        </div>
                    )}

                    {isResetConfirmOpen && (
                        <div className="absolute inset-0 z-10 bg-white/95 backdrop-blur-sm flex flex-col items-center justify-center p-8 animate-in fade-in duration-200">
                            <div className="bg-red-50 p-4 rounded-full mb-6">
                                <AlertCircle className="w-12 h-12 text-red-600" />
                            </div>
                            <h3 className="text-2xl font-bold text-gray-900 mb-2">Are you sure?</h3>
                            <p className="text-gray-500 text-center max-w-md mb-8">
                                This will <strong>permanently delete</strong> all imported sales history, custom product limits, and derived metrics. This action cannot be undone.
                            </p>
                            <div className="flex gap-4">
                                <button
                                    onClick={() => setIsResetConfirmOpen(false)}
                                    className="px-6 py-3 text-gray-700 font-medium hover:bg-gray-100 rounded-xl transition-colors"
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={() => {
                                        onResetData?.();
                                        setIsResetConfirmOpen(false);
                                    }}
                                    className="px-6 py-3 bg-red-600 text-white font-medium rounded-xl hover:bg-red-700 shadow-lg hover:shadow-red-500/30 transition-all flex items-center gap-2"
                                >
                                    <RotateCcw className="w-4 h-4" />
                                    Yes, Wipe Everything
                                </button>
                            </div>
                        </div>
                    )}

                    {(isProcessing || isConfirmingImport) && (
                        <div className="mb-4 rounded-lg border border-theme-20 bg-theme-5 p-3">
                            <div className="flex items-center justify-between text-xs text-theme mb-2">
                                <span>{importProgressText || 'Processing import...'}</span>
                                <span>{Math.round(importProgress)}%</span>
                            </div>
                            <div className="h-2 w-full rounded-full bg-gray-200 overflow-hidden">
                                <div
                                    className="h-full bg-theme transition-all duration-200"
                                    style={{ width: `${Math.max(0, Math.min(100, importProgress))}%` }}
                                />
                            </div>
                        </div>
                    )}

                    {step === 'upload' && (
                        <div className="space-y-6">
                            <div
                                className="border-2 border-dashed border-gray-300 rounded-xl p-10 flex flex-col items-center justify-center hover:bg-gray-50 transition-colors cursor-pointer"
                                onClick={() => fileInputRef.current?.click()}
                            >
                                <input ref={fileInputRef} type="file" className="hidden" accept=".csv, .xlsx" onChange={handleFileChange} />
                                {isProcessing ? (
                                    <div className="flex flex-col items-center animate-in fade-in zoom-in">
                                        <Loader2 className="w-10 h-10 text-theme animate-spin mb-3" />
                                        <p className="font-medium text-theme">{importProgressText || 'Auto-detecting Columns...'}</p>
                                    </div>
                                ) : (
                                    <>
                                        <Upload className="w-10 h-10 text-gray-400 mb-4" />
                                        <p className="font-medium text-gray-700">Click to upload Transaction Report</p>
                                        <p className="text-sm text-gray-500 mt-1">Supports CSV or Excel from ERP</p>
                                    </>
                                )}
                                {error && <p className="text-red-500 mt-4 text-sm flex items-center gap-1"><AlertCircle className="w-4 h-4" /> {error}</p>}
                            </div>
                        </div>
                    )}

                    {step === 'mapping' && (
                        <div className="space-y-6">
                            <div className="flex items-center justify-between">
                                <p className="text-sm text-gray-600">We couldn&apos;t auto-match everything. Please confirm columns.</p>
                                <button
                                    onClick={() => setShowAdvancedMapping(!showAdvancedMapping)}
                                    className="text-xs text-theme font-medium flex items-center gap-1 hover:underline"
                                >
                                    <Settings2 className="w-3 h-3" />
                                    {showAdvancedMapping ? 'Hide Advanced Fees' : 'Show Advanced Fees'}
                                </button>
                            </div>

                            <div className="grid grid-cols-2 gap-x-6 gap-y-4">
                                <MappingSelect label="SKU (sku_code)" value={mapping.sku} onChange={(v: string) => mapField('sku', v)} options={rawHeaders} required />
                                <MappingSelect label="Quantity (sku_quantity)" value={mapping.qty} onChange={(v: string) => mapField('qty', v)} options={rawHeaders} required />
                                <MappingSelect label="Revenue (sales_amt)" value={mapping.revenue} onChange={(v: string) => mapField('revenue', v)} options={rawHeaders} required />
                                <MappingSelect label="Date (order_time)" value={mapping.date} onChange={(v: string) => mapField('date', v)} options={rawHeaders} />
                                <MappingSelect label="Order ID (Optional)" value={mapping.outerOrderId} onChange={(v: string) => mapField('outerOrderId', v)} options={rawHeaders} />
                                <MappingSelect label="Postcode (receive_postcode)" value={mapping.receivePostcode} onChange={(v: string) => mapField('receivePostcode', v)} options={rawHeaders} />
                                <MappingSelect label="Platform Level 1" value={mapping.platform} onChange={(v: string) => mapField('platform', v)} options={rawHeaders} />
                                <MappingSelect label="Platform Level 2 (Subsource)" value={mapping.platformLevel2} onChange={(v: string) => mapField('platformLevel2', v)} options={rawHeaders} />
                            </div>

                            {showAdvancedMapping && (
                                <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 space-y-4 animate-in fade-in slide-in-from-top-2">
                                    <h4 className="text-xs font-bold text-gray-500 uppercase tracking-wide">Fees & Logistics (Optional)</h4>
                                    <div className="grid grid-cols-2 gap-x-6 gap-y-4">
                                        <MappingSelect label="Selling Fee" value={mapping.sellingFee} onChange={(v: string) => mapField('sellingFee', v)} options={rawHeaders} />
                                        <MappingSelect label="Ad Spend / PPC" value={mapping.adsFee} onChange={(v: string) => mapField('adsFee', v)} options={rawHeaders} />
                                        <MappingSelect label="Postage Cost" value={mapping.postage} onChange={(v: string) => mapField('postage', v)} options={rawHeaders} />
                                        <MappingSelect label="Logistics Name (Service)" value={mapping.logisticsService} onChange={(v: string) => mapField('logisticsService', v)} options={rawHeaders} />
                                        <MappingSelect label="WMS Fee" value={mapping.wmsFee} onChange={(v: string) => mapField('wmsFee', v)} options={rawHeaders} />
                                        <MappingSelect label="Extra Freight (Income)" value={mapping.extraFreight} onChange={(v: string) => mapField('extraFreight', v)} options={rawHeaders} />
                                        <MappingSelect label="Category" value={mapping.category} onChange={(v: string) => mapField('category', v)} options={rawHeaders} />
                                        <MappingSelect label="Net PM% (profit_excl_rn%)" value={mapping.profitExclRnPercent} onChange={(v: string) => mapField('profitExclRnPercent', v)} options={rawHeaders} />
                                        <MappingSelect label="Logistic Partner (label_provider)" value={mapping.logisticPartner} onChange={(v: string) => mapField('logisticPartner', v)} options={rawHeaders} />
                                    </div>
                                </div>
                            )}

                            {!mapping.date && (
                                <div className="bg-yellow-50 p-3 rounded border border-yellow-100 flex items-center gap-3">
                                    <Calendar className="w-4 h-4 text-yellow-600" />
                                    <div className="flex-1">
                                        <label className="block text-xs font-bold text-yellow-800 uppercase mb-1">Manual Period (Days)</label>
                                        <input
                                            type="number"
                                            value={periodDays}
                                            onChange={e => setPeriodDays(parseInt(e.target.value) || 1)}
                                            className="border rounded p-1 w-20 text-sm"
                                        />
                                    </div>
                                </div>
                            )}
                            {error && <p className="text-red-500 text-sm">{error}</p>}
                        </div>
                    )}

                    {step === 'resolution' && (
                        <div className="space-y-6">
                            <div className="flex items-center gap-3 p-4 bg-theme-10 text-theme rounded-xl border border-indigo-100">
                                <HelpCircle className="w-5 h-5 flex-shrink-0" />
                                <div className="text-sm">
                                    <p className="font-bold">Unknown SKUs Detected</p>
                                    <p className="opacity-80">These codes aren&apos;t in your inventory yet. Map them to a Master SKU to include them.</p>
                                </div>
                            </div>

                            <div className="max-h-[50vh] overflow-y-auto border border-gray-200 rounded-xl">
                                <table className="tbl tbl-compact w-full text-sm text-left">
                                    <thead className="sticky top-0">
                                        <tr>
                                            <th className="p-3">Unknown Code (In File)</th>
                                            <th className="p-3 text-center">Qty / Orders</th>
                                            <th className="p-3">Map to Master SKU</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {(Object.entries(unknownSkus) as [string, { count: number, revenue: number, masterSku: string | null }][]).map(([fileSku, data]) => (
                                            <tr key={fileSku}>
                                                <td className="p-3 font-mono text-xs text-gray-700">{fileSku}</td>
                                                <td className="p-3 text-center text-gray-500">{data.count}</td>
                                                <td className="p-3">
                                                    <div className="relative">
                                                        <input
                                                            type="text"
                                                            list="masterSkuList"
                                                            value={data.masterSku || ''}
                                                            onChange={(e) => {
                                                                const val = e.target.value;
                                                                setUnknownSkus(prev => ({
                                                                    ...prev,
                                                                    [fileSku]: { ...prev[fileSku], masterSku: val }
                                                                }));
                                                            }}
                                                            placeholder="Search inventory..."
                                                            className="w-full pl-8 pr-3 py-2 border border-gray-300 rounded-lg text-xs font-mono focus:ring-2 focus:ring-theme"
                                                        />
                                                        <Search className="w-4 h-4 text-gray-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
                                                    </div>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>

                            <datalist id="masterSkuList">
                                {products.map(p => <option key={p.id} value={p.sku}>{p.name}</option>)}
                            </datalist>

                            <div className="flex justify-between items-center bg-gray-50 p-4 rounded-xl border border-gray-100">
                                <div className="text-xs text-gray-500">
                                    Mapped SKUs will be remembered globally for future imports.
                                </div>
                                <button
                                    onClick={analyzeWithResolutions}
                                    className="px-6 py-2 bg-theme text-white font-medium rounded-lg hover:bg-theme shadow-md transition-all flex items-center gap-2"
                                >
                                    <Check className="w-4 h-4" />
                                    Continue Analysis
                                </button>
                            </div>
                        </div>
                    )}

                    {step === 'preview' && previewData && (
                        <div className="space-y-6">
                            <div className="grid grid-cols-4 gap-4 text-center">
                                <div className="p-4 bg-green-50 rounded-xl border border-green-100">
                                    <div className="h-full flex flex-col items-center justify-between">
                                        <div className="min-h-[2.25rem] w-full flex items-center justify-center">
                                            <div className="text-2xl font-bold text-green-700">{previewData.stats.matchedSkus}</div>
                                        </div>
                                        <div className="text-xs text-green-600 uppercase font-medium">Products Matched</div>
                                    </div>
                                </div>
                                <div className="min-w-0 max-w-full overflow-hidden p-4 bg-theme-10 rounded-xl border border-indigo-100">
                                    <div className="h-full flex flex-col items-center justify-between">
                                        <div className="min-h-[2.25rem] w-full flex items-center justify-center">
                                            <div className={`block w-full text-center leading-tight font-bold text-theme whitespace-nowrap tabular-nums ${revenueFontClass}`}>
                                                {revenueDisplay}
                                            </div>
                                        </div>
                                        <div className="text-xs text-theme uppercase font-medium">Total Revenue</div>
                                    </div>
                                </div>
                                <div className="p-4 bg-blue-50 rounded-xl border border-blue-100">
                                    <div className="h-full flex flex-col items-center justify-between">
                                        <div className="min-h-[2.25rem] w-full flex items-center justify-center">
                                            <div className="text-2xl font-bold text-blue-700">{previewData.stats.period} Days</div>
                                        </div>
                                        <div className="text-xs text-blue-600 uppercase font-medium">{previewData.stats.dateLabel}</div>
                                    </div>
                                </div>
                                <div className={`p-4 rounded-xl border ${previewData.stats.orderIdsCount > 0 ? 'bg-teal-50 border-teal-100' : 'bg-gray-50 border-gray-100'}`}>
                                    <div className="h-full flex flex-col items-center justify-between">
                                        <div className="min-h-[2.25rem] w-full flex items-center justify-center">
                                            <div className={`text-2xl font-bold ${previewData.stats.orderIdsCount > 0 ? 'text-teal-700' : 'text-gray-400'}`}>{previewData.stats.orderIdsCount}</div>
                                        </div>
                                        <div className={`text-xs uppercase font-medium ${previewData.stats.orderIdsCount > 0 ? 'text-teal-600' : 'text-gray-400'}`}>Transactions with IDs</div>
                                    </div>
                                </div>
                            </div>

                            <div className="flex flex-wrap gap-2 justify-center">
                                {previewData.features?.ads && (
                                    <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full bg-purple-100 text-purple-700 text-xs font-medium border border-purple-200">
                                        <Check className="w-3 h-3" /> Ad Data Detected
                                    </span>
                                )}
                                {previewData.features?.logistics && (
                                    <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full bg-orange-100 text-orange-700 text-xs font-medium border border-orange-200">
                                        <Check className="w-3 h-3" /> Logistics Costs Detected
                                    </span>
                                )}
                                {previewData.stats.shipmentCount > 0 && (
                                    <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full bg-teal-100 text-teal-700 text-xs font-medium border border-teal-200">
                                        <Truck className="w-3 h-3" /> {previewData.stats.shipmentCount} Shipments Logged
                                    </span>
                                )}
                            </div>

                            <div className="border rounded-lg overflow-hidden max-h-60 overflow-y-auto">
                                <table className="tbl tbl-compact w-full text-sm text-left">
                                    <thead className="sticky top-0">
                                        <tr>
                                            <th className="p-3">SKU</th>
                                            <th className="p-3 text-right">Old Vel.</th>
                                            <th className="p-3 text-right">New Vel.</th>
                                            <th className="p-3 text-right">Unit Price</th>
                                            <th className="p-3 text-right">Unit Fees</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {previewData.updates.slice(0, 50).map((u: any, i: number) => {
                                            const totalFees = (u.sellingFee || 0) + (u.adsFee || 0) + (u.postage || 0) + (u.wmsFee || 0);
                                            return (
                                                <tr key={i}>
                                                    <td className="p-3 font-mono text-xs">{u.sku}</td>
                                                    <td className="p-3 text-right text-gray-400">{u.previousDailySales?.toFixed(1) || '-'}</td>
                                                    <td className="p-3 text-right font-bold text-theme">{u.averageDailySales.toFixed(1)}</td>
                                                    <td className="p-3 text-right">{formatSmartMoney((u.currentPrice || 0))}</td>
                                                    <td className="p-3 text-right text-xs text-gray-500">
                                                        {totalFees > 0 ? formatSmartMoney(totalFees) : '-'}
                                                    </td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    )}
                </div>

                <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-between items-center rounded-b-xl">
                    <div>
                        {onResetData && (
                            <button
                                onClick={() => setIsResetConfirmOpen(true)}
                                title="Delete all sales logs and start fresh"
                                className="text-xs font-medium text-red-500 hover:text-red-600 flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-red-100 hover:bg-red-50 transition-all shadow-sm bg-white"
                            >
                                <RotateCcw className="w-3 h-3" />
                                Reset Data
                            </button>
                        )}
                    </div>
                    <div className="flex gap-3">
                        <button onClick={onClose} disabled={isConfirmingImport} className="px-4 py-2 text-gray-700 font-medium hover:bg-gray-200 rounded-lg disabled:opacity-50">Cancel</button>
                        {step === 'mapping' && (
                            <button
                                onClick={handleManualAnalyze}
                                disabled={isProcessing}
                                className="px-4 py-2 bg-theme text-white text-sm font-bold rounded-lg hover:bg-theme disabled:opacity-50 flex items-center gap-2"
                            >
                                {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <ArrowRight className="w-4 h-4" />}
                                Analyze Data
                            </button>
                        )}
                        {step === 'preview' && previewData && (
                            <button
                                onClick={handleConfirmImport}
                                disabled={isConfirmingImport}
                                className="px-4 py-2 bg-green-600 text-white text-sm font-bold rounded-lg hover:bg-green-700 disabled:opacity-50 flex items-center gap-2 shadow-lg hover:shadow-xl transition-all"
                            >
                                {isConfirmingImport ? <Loader2 className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />}
                                {isConfirmingImport ? 'Applying Import...' : 'Confirm Import'}
                            </button>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

const MappingSelect = ({ label, value, onChange, options, required }: any) => (
    <div>
        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">
            {label} {required && <span className="text-red-500">*</span>}
        </label>
        <div className="relative">
            <select
                value={value || ''}
                onChange={e => onChange(e.target.value)}
                className={`w-full border rounded-lg py-2 px-3 text-sm appearance-none bg-white focus:ring-2 focus:ring-theme ${required && !value ? 'border-red-300' : 'border-gray-300'}`}
            >
                <option value="">-- Ignore --</option>
                {options.map((h: string) => <option key={h} value={h}>{h}</option>)}
            </select>
            <div className="absolute right-3 top-2.5 pointer-events-none text-gray-400">
                <ArrowRight className="w-4 h-4 rotate-90" />
            </div>
        </div>
    </div>
);

export default SalesImportModal;

import React, { useState, useRef, useMemo } from 'react';
import { Upload, X, Check, AlertCircle, Loader2, Ship, Calendar, ArrowRight, TrendingUp, TrendingDown } from 'lucide-react';
import * as XLSX from 'xlsx';
import { Product, ShipmentDetail } from '../../../types';

interface ShipmentUpdate {
    sku: string;
    shipments: ShipmentDetail[];
    clearShipments?: boolean;
    reorderPlacedDate?: string;
    productionScheduledQty?: number;
    toBeShippedQty?: number;
    shippedOutQty?: number;
    shipmentStatus?: string;
}

type ChangeType = 'DELAYED' | 'EARLIER' | 'STATUS_CHANGE' | 'NEW' | 'UNCHANGED';

interface ContainerSummary {
    id: string;
    status: string;
    eta?: string;
    skuCount: number;
    totalQty: number;
    // Diff Data
    changeType: ChangeType;
    oldEta?: string;
    oldStatus?: string;
    daysDiff?: number;
}

interface ShipmentUploadModalProps {
    products: Product[];
    onClose: () => void;
    onConfirm: (updates: ShipmentUpdate[]) => void;
}

const ShipmentUploadModal: React.FC<ShipmentUploadModalProps> = ({ products, onClose, onConfirm }) => {
    const [dragActive, setDragActive] = useState(false);
    const [isProcessing, setIsProcessing] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [parsedUpdates, setParsedUpdates] = useState<ShipmentUpdate[] | null>(null);
    const [containerSummaries, setContainerSummaries] = useState<ContainerSummary[]>([]);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // 1. Build a Snapshot of Existing Containers
    const existingContainerMap = useMemo(() => {
        const map = new Map<string, { status: string, eta?: string }>();
        products.forEach(p => {
            if (p.shipments) {
                p.shipments.forEach(s => {
                    // If multiple SKUs have same container, we assume consistent ETA/Status. 
                    // We take the first one found or overwrite (doesn't matter if consistent).
                    if (s.containerId) {
                        map.set(s.containerId.trim(), { status: s.status, eta: s.eta });
                    }
                });
            }
        });
        return map;
    }, [products]);

    const handleDrag = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        if (e.type === "dragenter" || e.type === "dragover") {
            setDragActive(true);
        } else if (e.type === "dragleave") {
            setDragActive(false);
        }
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        e.stopPropagation();
        setDragActive(false);
        if (e.dataTransfer.files && e.dataTransfer.files[0]) {
            processFile(e.dataTransfer.files[0]);
        }
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            processFile(e.target.files[0]);
        }
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const processFile = (file: File) => {
        setIsProcessing(true);
        setError(null);

        setTimeout(() => {
            const reader = new FileReader();
            const handleContent = (content: any) => {
                let rows: any[][] = [];
                if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
                    const workbook = XLSX.read(content, { type: 'array', cellDates: true });
                    const sheet = workbook.Sheets[workbook.SheetNames[0]];
                    rows = XLSX.utils.sheet_to_json(sheet, { header: 1 }) as any[][];
                } else {
                    const text = content as string;
                    rows = text.split('\n').map(l => l.split(','));
                }
                analyzeRows(rows);
            };

            if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
                reader.onload = (e) => {
                    try { handleContent(e.target?.result); }
                    catch (err) { setError("Failed to parse Excel file."); setIsProcessing(false); }
                };
                reader.readAsArrayBuffer(file);
            } else {
                reader.onload = (e) => {
                    try { handleContent(e.target?.result); }
                    catch (err) { setError("Failed to parse CSV file."); setIsProcessing(false); }
                };
                reader.readAsText(file);
            }
        }, 100);
    };

    const analyzeRows = (rows: any[][]) => {
        try {
            if (rows.length < 2) throw new Error("File empty.");

            // Headers cleaning
            const headers = rows[0].map(h => String(h).trim().toLowerCase().replace(/[\s_\-/]/g, ''));

            // --- Column Mapping ---
            const findCol = (terms: string[]) => headers.findIndex(h => terms.some(t => h.includes(t)));

            const skuIdx = findCol(['sku', 'productsku']);

            // Container 1
            const c1Idx = findCol(['containerno.1', '1号柜']);
            const c1QtyIdx = findCol(['containerno.1stockqty', '1号柜装柜数量']);
            const c1StatusIdx = findCol(['containerno.1status', '1号柜状态']);
            const c1EtaIdx = findCol([
                'containerno.1expectedeta',
                'container1eta(wh)',
                'container1eta',
                '1号柜预计eta',
                '1号柜预计到仓日期'
            ]);
            const c1EtaCustomsIdx = findCol([
                'container1eta(wh,customsagent)',
                'container1etawhcustomsagent',
                '1号柜预计到仓日期（清关）'
            ]);

            // Container 2
            const c2Idx = findCol(['containerno.2', '2号柜']);
            const c2QtyIdx = findCol(['containerno.2stockqty', '2号柜装柜数量']);
            const c2StatusIdx = findCol(['containerno.2status', '2号柜状态']);
            const c2EtaIdx = findCol([
                'containerno.2expectedeta',
                'container2eta(wh)',
                'container2eta',
                '2号柜预计eta',
                '2号柜预计到仓日期'
            ]);
            const c2EtaCustomsIdx = findCol([
                'container2eta(wh,customsagent)',
                'container2etawhcustomsagent',
                '2号柜预计到仓日期（清关）'
            ]);

            if (skuIdx === -1) throw new Error("Could not detect 'Product SKU' column.");

            const reorderDateIdx = findCol(['reorderplaceddate']);
            const productionScheduledQtyIdx = findCol(['productionscheduledquantity']);
            const toBeShippedQtyIdx = findCol(['tobeshippedquantity']);
            const shippedOutQtyIdx = findCol(['shippedoutquantity']);
            const shipmentStatusIdx = findCol(['shipmentstatus']);

            const updatesMap: Record<string, ShipmentUpdate> = {};
            const summaryMap: Record<string, ContainerSummary> = {};

            const cleanStatus = (val: any): string => {
                const str = String(val).trim();
                if (!str || str === 'undefined' || str === 'null') return 'Pending';
                if (str.includes('/')) return str.split('/')[0].trim();
                return str.replace(/[\u4E00-\u9FFF]/g, '').trim();
            };
            const cleanEnglishText = (val: any): string => {
                const str = String(val ?? '').trim();
                if (!str || str === 'undefined' || str === 'null') return '';
                const first = str.includes('/') ? str.split('/')[0].trim() : str;
                return first.replace(/[\u4E00-\u9FFF]/g, '').trim();
            };
            const parseQty = (val: any): number => {
                const n = Number(val);
                return Number.isFinite(n) ? n : 0;
            };

            const updateSummary = (id: string, status: string, eta: string | undefined, qty: number) => {
                if (!summaryMap[id]) {
                    // Initialize new summary
                    // Check against Existing Map for DIFFs
                    const existing = existingContainerMap.get(id);
                    let changeType: ChangeType = existing ? 'UNCHANGED' : 'NEW';
                    let daysDiff = 0;
                    const oldEta = existing?.eta;
                    const oldStatus = existing?.status;

                    if (existing) {
                        // 1. Check ETA Difference
                        if (eta && existing.eta && eta !== existing.eta) {
                            const dOld = new Date(existing.eta);
                            const dNew = new Date(eta);
                            if (!isNaN(dOld.getTime()) && !isNaN(dNew.getTime())) {
                                const diffTime = dNew.getTime() - dOld.getTime();
                                daysDiff = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

                                if (daysDiff > 0) changeType = 'DELAYED';
                                else if (daysDiff < 0) changeType = 'EARLIER';
                            }
                        }

                        // 2. Check Status Change (if not already marked as delay/early, or force status update logic)
                        if (status !== existing.status) {
                            if (changeType === 'UNCHANGED') changeType = 'STATUS_CHANGE';
                            // Note: If it's delayed AND status changed, 'DELAYED' takes precedence for the badge, 
                            // but we will show the status text change regardless.
                        }
                    }

                    summaryMap[id] = {
                        id,
                        status,
                        eta,
                        skuCount: 0,
                        totalQty: 0,
                        changeType,
                        daysDiff,
                        oldEta,
                        oldStatus
                    };
                }

                // Assuming row-level data is consistent for the same container, we just aggregate stats
                summaryMap[id].skuCount++;
                summaryMap[id].totalQty += qty;
            };

            for (let i = 1; i < rows.length; i++) {
                const row = rows[i];
                if (!row || row.length <= skuIdx) continue;

                const rawSku = String(row[skuIdx]).trim();
                if (!rawSku) continue;

                const parseDate = (val: any) => {
                    if (!val) return undefined;
                    if (val instanceof Date) return val.toISOString().split('T')[0];
                    const d = new Date(val);
                    return !isNaN(d.getTime()) ? d.toISOString().split('T')[0] : undefined;
                };

                const shipmentByContainer = new Map<string, ShipmentDetail>();
                const upsertShipment = (containerIdRaw: any, qtyRaw: any, statusRaw: any, etaRaw: any) => {
                    const id = String(containerIdRaw || '').trim();
                    if (!id) return;
                    const qty = parseQty(qtyRaw);
                    if (qty <= 0) return;
                    const status = cleanStatus(statusRaw);
                    const eta = parseDate(etaRaw);
                    const existing = shipmentByContainer.get(id);
                    if (existing) {
                        existing.quantity = (Number(existing.quantity) || 0) + qty;
                        if (status) existing.status = status;
                        if (eta) existing.eta = eta;
                        shipmentByContainer.set(id, existing);
                    } else {
                        shipmentByContainer.set(id, { containerId: id, quantity: qty, status, eta });
                    }
                };

                // Process C1
                upsertShipment(
                    c1Idx !== -1 ? row[c1Idx] : undefined,
                    c1QtyIdx !== -1 ? row[c1QtyIdx] : undefined,
                    c1StatusIdx !== -1 ? row[c1StatusIdx] : undefined,
                    (c1EtaIdx !== -1 ? row[c1EtaIdx] : undefined) || (c1EtaCustomsIdx !== -1 ? row[c1EtaCustomsIdx] : undefined)
                );

                // Process C2
                upsertShipment(
                    c2Idx !== -1 ? row[c2Idx] : undefined,
                    c2QtyIdx !== -1 ? row[c2QtyIdx] : undefined,
                    c2StatusIdx !== -1 ? row[c2StatusIdx] : undefined,
                    (c2EtaIdx !== -1 ? row[c2EtaIdx] : undefined) || (c2EtaCustomsIdx !== -1 ? row[c2EtaCustomsIdx] : undefined)
                );

                const shipments: ShipmentDetail[] = Array.from(shipmentByContainer.values());
                shipments.forEach((s) => updateSummary(s.containerId, s.status, s.eta, s.quantity));

                const reorderPlacedDate = parseDate(reorderDateIdx !== -1 ? row[reorderDateIdx] : undefined);
                const productionScheduledQty = parseQty(productionScheduledQtyIdx !== -1 ? row[productionScheduledQtyIdx] : undefined);
                const toBeShippedQty = parseQty(toBeShippedQtyIdx !== -1 ? row[toBeShippedQtyIdx] : undefined);
                const shippedOutQty = parseQty(shippedOutQtyIdx !== -1 ? row[shippedOutQtyIdx] : undefined);
                const shipmentStatus = cleanEnglishText(shipmentStatusIdx !== -1 ? row[shipmentStatusIdx] : undefined);
                const isNoShipmentSignal = (
                    shipmentStatus.toLowerCase() === 'na' &&
                    shipments.length === 0 &&
                    !reorderPlacedDate &&
                    productionScheduledQty <= 0 &&
                    toBeShippedQty <= 0 &&
                    shippedOutQty <= 0
                );

                if (shipments.length > 0 || reorderPlacedDate || productionScheduledQty > 0 || toBeShippedQty > 0 || shippedOutQty > 0 || shipmentStatus) {
                    updatesMap[rawSku] = {
                        sku: rawSku,
                        shipments,
                        clearShipments: isNoShipmentSignal,
                        reorderPlacedDate,
                        productionScheduledQty,
                        toBeShippedQty,
                        shippedOutQty,
                        shipmentStatus
                    };
                }
            }

            const result: ShipmentUpdate[] = Object.values(updatesMap);

            // Sort summaries: Problems (Delays) first, then Opportunities (Earlier), then Updates, then New, then Unchanged
            const getPriority = (c: ContainerSummary) => {
                if (c.changeType === 'DELAYED') return 0;
                if (c.changeType === 'EARLIER') return 1;
                if (c.changeType === 'STATUS_CHANGE') return 2;
                if (c.changeType === 'NEW') return 3;
                return 4;
            };

            const summaries = Object.values(summaryMap).sort((a, b) => getPriority(a) - getPriority(b));

            setParsedUpdates(result);
            setContainerSummaries(summaries);

        } catch (err: any) {
            setError(err.message || "Failed to analyze file.");
        } finally {
            setIsProcessing(false);
        }
    };

    const getStatusColor = (status: string) => {
        const s = status.toLowerCase();
        if (s.includes('shipped')) return 'bg-blue-100 text-blue-800 border-blue-200';
        if (s.includes('arrived')) return 'bg-green-100 text-green-800 border-green-200';
        if (s.includes('delivered')) return 'bg-gray-100 text-gray-800 border-gray-200';
        return 'bg-amber-100 text-amber-800 border-amber-200';
    };

    const renderChangeBadge = (c: ContainerSummary) => {
        const badgeBase = "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-bold border whitespace-nowrap shadow-sm";

        if (c.changeType === 'DELAYED') {
            return (
                <span className={`${badgeBase} text-red-700 bg-red-50 border-red-200`}>
                    <TrendingDown className="w-3.5 h-3.5 flex-shrink-0" />
                    Delayed (+{c.daysDiff}d)
                </span>
            );
        }
        if (c.changeType === 'EARLIER') {
            return (
                <span className={`${badgeBase} text-green-700 bg-green-50 border-green-200`}>
                    <TrendingUp className="w-3.5 h-3.5 flex-shrink-0" />
                    Early ({Math.abs(c.daysDiff || 0)}d)
                </span>
            );
        }
        if (c.changeType === 'NEW') {
            return (
                <span className={`${badgeBase} text-blue-700 bg-blue-50 border-blue-200`}>
                    New Container
                </span>
            );
        }
        if (c.changeType === 'STATUS_CHANGE') {
            return (
                <span className={`${badgeBase} text-theme bg-theme-10 border-theme-20`}>
                    Status Update
                </span>
            );
        }
        return <span className="text-[10px] text-gray-400 font-medium whitespace-nowrap px-2">No Change</span>;
    };

    const stats = useMemo(() => {
        return {
            delayed: containerSummaries.filter(c => c.changeType === 'DELAYED').length,
            early: containerSummaries.filter(c => c.changeType === 'EARLIER').length,
            new: containerSummaries.filter(c => c.changeType === 'NEW').length,
        };
    }, [containerSummaries]);

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
            <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl flex flex-col max-h-[90vh]">
                <div className="p-6 border-b border-gray-100 flex justify-between items-center bg-gray-50 rounded-t-2xl">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-theme-10 rounded-lg text-theme">
                            <Ship className="w-5 h-5" />
                        </div>
                        <div>
                            <h2 className="text-xl font-bold text-gray-900">Import Shipment Schedule</h2>
                            <p className="text-xs text-gray-500">Update incoming stock and ETAs</p>
                        </div>
                    </div>
                    <button onClick={onClose}><X className="w-5 h-5 text-gray-500 hover:text-gray-700" /></button>
                </div>

                <div className="p-6 flex-1 overflow-y-auto">
                    {!parsedUpdates ? (
                        <div
                            className={`border-2 border-dashed rounded-xl p-10 flex flex-col items-center justify-center text-center transition-all ${dragActive ? 'border-theme bg-theme-10 scale-[1.02]' : 'border-gray-300 hover:border-gray-400 hover:bg-gray-50'
                                }`}
                            onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
                        >
                            <input ref={fileInputRef} type="file" className="hidden" onChange={handleFileChange} accept=".csv, .xlsx, .xls" />
                            {isProcessing ? (
                                <div className="flex flex-col items-center py-4">
                                    <Loader2 className="w-8 h-8 animate-spin text-theme mb-2" />
                                    <p className="text-theme font-medium">Parsing Logistics File...</p>
                                </div>
                            ) : (
                                <>
                                    <div className="w-14 h-14 bg-theme-10 text-theme rounded-full flex items-center justify-center mb-4">
                                        <Calendar className="w-7 h-7" />
                                    </div>
                                    <p className="text-gray-900 font-medium text-lg">Upload Container Schedule</p>
                                    <p className="text-sm text-gray-500 mt-1">Supports the Standard Shipment Export (XLSX)</p>

                                    <button
                                        onClick={() => fileInputRef.current?.click()}
                                        className="mt-6 px-6 py-2 bg-white border border-gray-200 shadow-sm text-gray-700 font-medium rounded-lg hover:bg-gray-50"
                                    >
                                        Select File
                                    </button>
                                </>
                            )}

                            {error && (
                                <div className="mt-6 flex items-center gap-2 text-red-600 bg-red-50 px-4 py-2 rounded-lg border border-red-100">
                                    <AlertCircle className="w-4 h-4" />
                                    <span className="text-sm">{error}</span>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div className="space-y-6">
                            {/* High Level Stats */}
                            <div className="grid grid-cols-4 gap-4">
                                <div className="p-3 bg-gray-50 rounded-xl border border-gray-200">
                                    <span className="text-xs text-gray-500 font-medium uppercase">Total Containers</span>
                                    <div className="text-xl font-bold text-gray-900 mt-1">{containerSummaries.length}</div>
                                </div>
                                <div className={`p-3 rounded-xl border ${stats.delayed > 0 ? 'bg-red-50 border-red-200' : 'bg-gray-50 border-gray-200'}`}>
                                    <span className={`text-xs font-medium uppercase ${stats.delayed > 0 ? 'text-red-600' : 'text-gray-500'}`}>Delayed</span>
                                    <div className={`text-xl font-bold mt-1 ${stats.delayed > 0 ? 'text-red-700' : 'text-gray-900'}`}>{stats.delayed}</div>
                                </div>
                                <div className={`p-3 rounded-xl border ${stats.early > 0 ? 'bg-green-50 border-green-200' : 'bg-gray-50 border-gray-200'}`}>
                                    <span className={`text-xs font-medium uppercase ${stats.early > 0 ? 'text-green-600' : 'text-gray-500'}`}>Early</span>
                                    <div className={`text-xl font-bold mt-1 ${stats.early > 0 ? 'text-green-700' : 'text-gray-900'}`}>{stats.early}</div>
                                </div>
                                <div className={`p-3 rounded-xl border ${stats.new > 0 ? 'bg-blue-50 border-blue-200' : 'bg-gray-50 border-gray-200'}`}>
                                    <span className={`text-xs font-medium uppercase ${stats.new > 0 ? 'text-blue-600' : 'text-gray-500'}`}>New</span>
                                    <div className={`text-xl font-bold mt-1 ${stats.new > 0 ? 'text-blue-700' : 'text-gray-900'}`}>{stats.new}</div>
                                </div>
                            </div>

                            <div className="border border-gray-200 rounded-xl overflow-hidden shadow-sm max-h-[400px] overflow-y-auto">
                                <table className="tbl tbl-compact w-full text-left text-sm">
                                    <thead className="sticky top-0">
                                        <tr>
                                            <th className="px-4 py-3 w-1/4">Container ID</th>
                                            <th className="px-4 py-3 w-1/6">Update Type</th>
                                            <th className="px-4 py-3 w-1/4">Status Change</th>
                                            <th className="px-4 py-3 w-1/4">ETA</th>
                                            <th className="px-4 py-3 text-right">Qty</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {containerSummaries.map((c) => {
                                            const isStatusChanged = c.oldStatus && c.oldStatus !== c.status;
                                            const isEtaChanged = c.oldEta && c.eta !== c.oldEta;

                                            return (
                                                <tr key={c.id} className={`${c.changeType === 'DELAYED' ? 'bg-red-50/10' : ''}`}>
                                                    <td className="px-4 py-3">
                                                        <div className="font-mono font-bold text-gray-900">{c.id}</div>
                                                        <div className="text-xs text-gray-500">{c.skuCount} SKUs</div>
                                                    </td>
                                                    <td className="px-4 py-3">
                                                        {renderChangeBadge(c)}
                                                    </td>
                                                    <td className="px-4 py-3">
                                                        <div className="flex flex-col gap-1">
                                                            <span className={`inline-block w-fit px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${getStatusColor(c.status)}`}>
                                                                {c.status}
                                                            </span>
                                                            {isStatusChanged && (
                                                                <div className="flex items-center gap-1 text-[10px] text-gray-400">
                                                                    <span className="line-through">{c.oldStatus}</span>
                                                                    <ArrowRight className="w-3 h-3" />
                                                                </div>
                                                            )}
                                                        </div>
                                                    </td>
                                                    <td className="px-4 py-3 text-sm">
                                                        <div className="font-medium text-gray-900">{c.eta || 'Pending'}</div>
                                                        {isEtaChanged && c.oldEta && (
                                                            <div className="text-xs text-gray-400 line-through">{c.oldEta}</div>
                                                        )}
                                                    </td>
                                                    <td className="px-4 py-3 text-right font-bold text-gray-800 font-mono">
                                                        {c.totalQty}
                                                    </td>
                                                </tr>
                                            );
                                        })}
                                    </tbody>
                                </table>
                            </div>

                            <div className="flex items-center gap-2 p-3 bg-blue-50 text-blue-700 rounded-lg text-xs">
                                <AlertCircle className="w-4 h-4 flex-shrink-0" />
                                <p>This update will overwrite shipment details for these <strong>{containerSummaries.length}</strong> containers. Unlisted containers remain unchanged.</p>
                            </div>
                        </div>
                    )}
                </div>

                <div className="p-6 border-t bg-gray-50 flex justify-end gap-3 rounded-b-2xl">
                    <button onClick={onClose} className="px-4 py-2 text-gray-700 hover:bg-gray-200 rounded-lg text-sm font-bold transition-colors">Cancel</button>
                    {parsedUpdates && parsedUpdates.length > 0 && (
                        <button
                            onClick={() => onConfirm(parsedUpdates)}
                            className="px-4 py-2 bg-theme text-white text-sm font-bold rounded-lg shadow-md hover:bg-theme transition-colors flex items-center gap-2"
                        >
                            <Check className="w-4 h-4" />
                            Confirm Update
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

export default ShipmentUploadModal;

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { ArrowLeft, Info, AlertTriangle, Package, RotateCcw, Megaphone, DollarSign, TrendingDown, TrendingUp, ExternalLink } from 'lucide-react';
import { Product, PriceLog, PriceChangeRecord, RefundLog, ReturnDateBasis, PricingRules, OptimalPriceResult, PromotionEvent, NavigationIntent } from '../../types';
import { ThresholdConfig } from '../../services/thresholdsConfig';
import { calcProfit, calcRevenue, calcAdSpend, marginPct, calcTACoSPct, calcUnits } from '../../services/metrics';
import { buildWindow } from '../../services/dateWindow';
import { asDateKey, isDateKeyBetween, getTodayKeyMelbourne, getReturnDateKey, addDaysToDateKey } from '../../services/dateUtils';
import { VAT_MULTIPLIER } from '../../constants';
import { buildRefundOverview } from '../../services/refundAgg';
import { parseReturnsReason } from '../../services/returnsReasonCodes';
import { sortRows, SortState } from '../../utils/tableSort';
import { aggregateRefundKeywords } from '../../services/refundTextAgg';
import { calculateQuantiles } from './charts/BoxPlot';
import { getCanonicalSku } from '../../services/skuNormalization';
import { formatNumber } from '../../utils/format';

// Section Components
import { SkuOverviewSection } from './sections/SkuOverviewSection';
import { DiagnosticSignalsSection } from './sections/DiagnosticSignalsSection';
import { DistributionAnalysisSection } from './sections/DistributionAnalysisSection';
import { PricingHistorySection } from './sections/PricingHistorySection';
import { TransactionLedgerSection } from './sections/TransactionLedgerSection';
import { ReturnsAnalysisSection } from './sections/ReturnsAnalysisSection';
import { StatusBadge } from '../promotionManager/parts/StatusBadge';

interface SkuDeepDivePageProps {
    data: {
        product: Product;
        allTimeSales: number;
        allTimeQty: number;
        transactions?: PriceLog[];
        refunds?: RefundLog[];
    };
    themeColor: string;
    onBack?: () => void;
    priceChangeHistory?: PriceChangeRecord[];
    initialTimeWindow?: 'yesterday' | '7d' | '30d' | 'custom';
    focus?: string;
    thresholds: ThresholdConfig;
    pricingRules?: PricingRules;
    promotions?: PromotionEvent[];
    skuFamilies: any[];
    products: Product[];
    adGroups: any[];
    priceHistoryMap: Map<string, any[]>;
    optimalPriceResults?: Map<string, OptimalPriceResult>;
    navigateToEntity?: (intent: Omit<NavigationIntent, 'createdAt'>) => void;
}

// Helper to read URL params
const getActiveSectionFromUrl = () => {
    if (typeof window === 'undefined') return null;
    const params = new URLSearchParams(window.location.search);
    return params.get('section');
};

const SkuDeepDivePage: React.FC<SkuDeepDivePageProps> = ({
    data, themeColor, onBack, priceChangeHistory = [], initialTimeWindow, focus, thresholds, pricingRules,
    promotions = [], skuFamilies, products, adGroups, priceHistoryMap, optimalPriceResults, navigateToEntity
}) => {
    const { product, allTimeSales, allTimeQty, transactions = [], refunds = [] } = data;

    // Analytics State
    const [txFilterPlatform, setTxFilterPlatform] = useState('All');
    const [txFilterType, setTxFilterType] = useState('All');
    const [txLimit, setTxLimit] = useState(50);
    const [txDays, setTxDays] = useState(() => {
        if (initialTimeWindow === 'yesterday') return 1;
        if (initialTimeWindow === '7d') return 7;
        if (initialTimeWindow === '30d') return 30;
        return 7; // Default
    });
    const [hoveredBubble, setHoveredBubble] = useState<any>(null);
    const [chartPeriod, setChartPeriod] = useState<string>('30 Days');
    const [chartLayout, setChartLayout] = useState<'horizontal' | 'vertical'>('horizontal');
    const [tooltip, setTooltip] = useState<{ visible: boolean, content: any, x: number, y: number, source?: string } | null>(null);
    const [isAuditPanelVisible, setIsAuditPanelVisible] = useState(false);

    // AI Toggle
    const [showAiInsights, setShowAiInsights] = useState(false);

    // Keyword Cloud State (Task C)
    const [kwMode, setKwMode] = useState<'All' | 'Reason'>('All');
    const [kwReason, setKwReason] = useState<string | null>(null);

    // Refund Table Sorting & Pagination
    const [refundSort, setRefundSort] = useState<SortState<string>>({ key: 'date', dir: 'desc' });
    const [refundPage, setRefundPage] = useState(1);
    const refundItemsPerPage = 10;

    // Return Date Basis Toggle
    const [returnDateBasis, setReturnDateBasis] = useState<ReturnDateBasis>('refundDate');

    const activeSignalRef = useRef<HTMLDivElement>(null);
    const refundsRef = useRef<HTMLDivElement>(null);

    // Refs for quick access scrolling
    const overviewRef = useRef<HTMLDivElement>(null);
    const signalsRef = useRef<HTMLDivElement>(null);
    const analysisRef = useRef<HTMLDivElement>(null);
    const pricingRef = useRef<HTMLDivElement>(null);
    const promotionRef = useRef<HTMLDivElement>(null);
    const ledgerRef = useRef<HTMLDivElement>(null);

    const scrollToSection = (section: 'analysis' | 'pricing' | 'promotion' | 'ledger' | 'refunds') => {
        const refMap = {
            analysis: analysisRef,
            pricing: pricingRef,
            promotion: promotionRef,
            ledger: ledgerRef,
            refunds: refundsRef
        };
        const targetRef = refMap[section];
        if (targetRef && targetRef.current) {
            targetRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    };

    // Calculate Date Window Keys
    const { startKey, endKey, expectedDays } = useMemo(() => buildWindow({
        mode: 'days',
        days: txDays,
        excludeToday: true
    }), [txDays]);

    // For Price History, we extend to Today to show recent actions
    const todayKey = getTodayKeyMelbourne();
    const historyEndKey = todayKey > endKey ? todayKey : endKey;

    useEffect(() => {
        if (focus && activeSignalRef.current) {
            setTimeout(() => {
                activeSignalRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }, 100);
        }

        // Deep linking for refunds
        const section = getActiveSectionFromUrl();
        if (section === 'refunds' && refundsRef.current) {
            setTimeout(() => {
                refundsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }, 300);
        }
    }, [focus]);

    // Derive Order Date Map for Order Date Basis logic
    const orderDateMap = useMemo(() => {
        const map = new Map<string, string>();
        (transactions || []).forEach(t => {
            if (t.orderId) {
                const dKey = asDateKey(t.date);
                if (dKey) map.set(t.orderId, dKey);
            }
        });
        return map;
    }, [transactions]);

    // Family Logic
    const myFamily = useMemo(() => skuFamilies.find((f: any) => f.memberSkus.includes(product.sku)), [skuFamilies, product.sku]);
    const isInFamily = !!myFamily;
    const siblings = useMemo(() =>
        myFamily
            ? products.filter(p => myFamily.memberSkus.includes(p.sku) && p.sku !== product.sku)
            : []
        , [myFamily, products, product.sku]);

    const sortedTransactions = useMemo(() => {
        const safeTx = Array.isArray(transactions) ? transactions : [];
        const safeRefunds = Array.isArray(refunds) ? refunds : [];

        const sales = safeTx.map(t => ({ ...t, _type: 'SALE' }));
        const refundLogs = safeRefunds.map(r => ({
            id: r.id,
            sku: r.sku,
            date: r.date,
            velocity: r.quantity > 0 ? -r.quantity : 0,
            price: r.amount > 0 ? (r.quantity > 0 ? r.amount / r.quantity : r.amount) : 0,
            platform: r.platform,
            margin: 0,
            // Consistency Fix: profit must be scaled by VAT since transactions.profit from searchExecution is scaled.
            profit: -((Number(r.amount || 0) + Number(r.freightAmount || 0))),
            _type: 'REFUND_LOG',
            reason: r.reason
        } as unknown as PriceLog));

        return [...sales, ...refundLogs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [transactions, refunds]);

    const filteredTransactions = useMemo(() => {
        let list = sortedTransactions;

        // Date Filter
        list = list.filter(t => {
            const dKey = asDateKey(t.date);
            return dKey && isDateKeyBetween(dKey, startKey, endKey);
        });

        if (txFilterPlatform !== 'All') {
            list = list.filter(t => t.platform === txFilterPlatform);
        }
        if (txFilterType !== 'All') {
            list = list.filter(t => {
                if (txFilterType === 'Sale') return t.velocity > 0;
                if (txFilterType === 'Ad Cost') return t.price === 0 && (t.adsSpend || 0) > 0;
                if (txFilterType === 'Refund') return t.velocity < 0;
                return true;
            });
        }
        return list;
    }, [sortedTransactions, txFilterPlatform, txFilterType, startKey, endKey]);

    const activeAdGroupInFamily = useMemo(() => adGroups.find((g: any) =>
        g.isActive && g.memberSkus.includes(product.sku)
    ), [adGroups, product.sku]);


    const adRedistributionSummary = useMemo(() => {
        if (!activeAdGroupInFamily || !isInFamily) return null;

        const redistributedLogs = filteredTransactions.filter(l =>
            l.rawAdsSpend !== undefined && l.rawAdsSpend !== null
        );

        const rawSpend = redistributedLogs.reduce((sum, l) => sum + (l.rawAdsSpend || 0), 0);
        const adjustedSpend = redistributedLogs.reduce((sum, l) => sum + (l.adsSpend || 0), 0);

        const active = redistributedLogs.length > 0 && Math.abs(rawSpend - adjustedSpend) > 0.01;

        if (!active) return null;

        return {
            active: true,
            groupName: activeAdGroupInFamily.name,
            rawSpend: rawSpend * VAT_MULTIPLIER,
            adjustedSpend: adjustedSpend * VAT_MULTIPLIER
        };
    }, [activeAdGroupInFamily, isInFamily, filteredTransactions]);

    // Available Reason Codes for Filtering (Task C)
    const availableReasonCodes = useMemo(() => {
        const codes = new Set<string>();
        refunds.forEach(r => {
            const { short } = parseReturnsReason(r.platformReason || r.reason);
            if (short && short !== 'UNK') codes.add(short);
        });
        return Array.from(codes).sort();
    }, [refunds]);

    const periodSalesQty = useMemo(() => {
        return filteredTransactions
            .filter(t => t.velocity > 0)
            .reduce((acc, t) => acc + t.velocity, 0);
    }, [filteredTransactions]);

    const allTimeMarginStats = useMemo(() => {
        if (!transactions || transactions.length === 0) return { pct: 0, rawProfit: 0, refundVal: 0, netSales: 0, netProfit: 0, grossSales: 0 };

        let rawProfit = 0;
        transactions.forEach(t => {
            // calcProfit uses t.profit if present. 
            // Since we reverted scaling in searchExecution for DEEP_DIVE, t.profit is Ex-VAT raw.
            rawProfit += calcProfit(t);
        });

        // Scale rawProfit to Inc-VAT once for comparison
        const rawProfitIncVat = rawProfit * VAT_MULTIPLIER;

        // refunds[i].amount and freightAmount are raw Ex-VAT (reverted in searchExecution). 
        // Scale exactly once here.
        const refundVal = refunds ? refunds.reduce((sum, r) => sum + ((Number(r.amount || 0) + Number(r.freightAmount || 0)) * VAT_MULTIPLIER), 0) : 0;
        const netProfit = rawProfitIncVat - refundVal;

        const netSales = allTimeSales; // already scaled in searchExecution summary

        const pct = marginPct(netProfit, netSales) || 0;

        return { pct, rawProfit: rawProfitIncVat, refundVal, netSales, netProfit, grossSales: allTimeSales };
    }, [transactions, refunds, allTimeSales]);

    // NEW: Calculate All-Time Return & Refund Rate
    const allTimeReturnStats = useMemo(() => {
        if (allTimeQty === 0) return { returnRate: 0, refundRate: 0, totalRefundQty: 0, totalRefundVal: 0 };

        // --- FORMULA REFINEMENT ---
        // 1. Return Rate (Qty): Includes Refunds AND Resends (Total Returns)
        const totalRefundQty = refunds.reduce((sum, r) => sum + r.quantity, 0);

        // 2. Refund Rate (Val): Includes Refunds AND Resends
        // Scaling exactly once.
        const totalRefundVal = refunds.reduce((sum, r) => {
            return sum + ((Number(r.amount || 0) + Number(r.freightAmount || 0)) * VAT_MULTIPLIER);
        }, 0);

        return {
            returnRate: (totalRefundQty / allTimeQty) * 100,
            refundRate: allTimeSales > 0 ? (totalRefundVal / allTimeSales) * 100 : 0,
            totalRefundQty,
            totalRefundVal
        };
    }, [refunds, allTimeQty, allTimeSales]);

    // Refund Detail Table Data - MODIFIED: Removed date filtering to align with timeline chart
    const filteredRefundsForTable = useMemo(() => {
        const getValue = (row: RefundLog, key: string) => {
            if (key === 'date') {
                const d = getReturnDateKey(row, returnDateBasis, orderDateMap);
                return d ? new Date(d).getTime() : 0;
            }
            if (key === 'reason') return parseReturnsReason(row.platformReason || row.reason).short;
            return (row as any)[key];
        };

        return sortRows(refunds || [], refundSort, getValue);
    }, [refunds, refundSort, returnDateBasis, orderDateMap]);

    const paginatedRefunds = useMemo(() => {
        return filteredRefundsForTable.slice((refundPage - 1) * refundItemsPerPage, refundPage * refundItemsPerPage);
    }, [filteredRefundsForTable, refundPage]);

    const totalRefundPages = Math.ceil(filteredRefundsForTable.length / refundItemsPerPage);

    // Refunds Analysis (Task A + Task C + Garbage Filtering)
    const refundAnalysis = useMemo(() => {
        if (!refunds || refunds.length === 0) return null;

        // Use central aggregation service for consistent logic (which now includes freight scaling)
        const overview = buildRefundOverview(refunds);

        // Separate totals for display
        const totalFreight = refunds.reduce((sum, r) => sum + (Number(r.freightAmount || 0)), 0);
        const resendCount = refunds.filter(r => r.orderType === 'resend').length;
        const refundCount = refunds.filter(r => r.orderType === 'refund' || !r.orderType).length;

        // Filter refunds based on selection (Task C)
        const filteredRefundsForKeywords = kwMode === 'Reason' && kwReason
            ? refunds.filter(r => parseReturnsReason(r.platformReason || r.reason).short === kwReason)
            : refunds;

        const topKeywords = aggregateRefundKeywords(filteredRefundsForKeywords, 60);

        // Local Sentiment Tracking (Simplified for now, relying on aggregateRefundKeywords or custom logic if needed)
        // Re-implementing sentiment stats locally as it was inside the hook previously
        const sentimentStats = { negative: 0, neutral: 0, positive: 0 };
        const negatives = ['broken', 'damage', 'defect', 'poor', 'bad', 'terrible', 'worst', 'awful', 'useless', 'dirty', 'rubbish', 'faulty', 'fake', 'counterfeit'];
        const positives = ['great', 'good', 'love', 'excellent', 'perfect', 'nice'];

        filteredRefundsForKeywords.forEach(r => {
            const rawText = `${r.reason || ''} ${r.customerReason || ''} ${r.remarks || ''} ${r.comments || ''}`.toLowerCase();
            let score = 0;
            negatives.forEach(w => { if (rawText.includes(w)) score--; });
            positives.forEach(w => { if (rawText.includes(w)) score++; });

            if (score < 0) sentimentStats.negative++;
            else if (score > 0) sentimentStats.positive++;
            else sentimentStats.neutral++;
        });

        return {
            overview,
            topWords: topKeywords.map(w => ({ text: w.text, value: w.count })),
            sentimentStats,
            totalFreight,
            resendCount,
            refundCount
        };
    }, [refunds, kwMode, kwReason]);

    const diagnostics = useMemo(() => {
        // ... (Diagnostics logic unchanged, reusing existing code)
        // Copying existing logic for signals
        const signals = [];
        if (product.stockLevel > 0) {
            if (product.daysRemaining != null && product.daysRemaining < (product.leadTimeDays * thresholds.stockoutRunwayMultiplier)) {
                signals.push({ id: 'STOCKOUT_RISK', label: 'Stockout Risk', severity: 'High', color: 'text-red-700 bg-red-50 border-red-200', icon: AlertTriangle, desc: `Stock covers ${product.daysRemaining.toFixed(0)} days, which is less than the lead time buffer (${(product.leadTimeDays * thresholds.stockoutRunwayMultiplier).toFixed(0)} days).` });
            } else if (product.daysRemaining != null && product.daysRemaining > thresholds.overstockDays) {
                signals.push({ id: 'OVERSTOCK_RISK', label: 'Overstock', severity: 'Medium', color: 'text-orange-700 bg-orange-50 border-orange-200', icon: Package, desc: `Stock covers ${product.daysRemaining.toFixed(0)} days, exceeding the ${thresholds.overstockDays}-day efficiency target.` });
            }
        }
        if (product.returnRate != null && product.returnRate > thresholds.returnRatePct) {
            signals.push({ id: 'HIGH_RETURN_RATE', label: 'Elevated Returns', severity: 'High', color: 'text-red-700 bg-red-50 border-red-200', icon: RotateCcw, desc: `Return rate is ${product.returnRate.toFixed(1)}%, which is above the ${thresholds.returnRatePct}% alert threshold.` });
        }
        const adPct = product.costDetail?.adsFeePct ?? (product.currentPrice > 0 ? ((product.adsFee || 0) / product.currentPrice * 100) : 0);
        if (adPct > thresholds.highAdDependencyPct) {
            signals.push({ id: 'HIGH_AD_DEPENDENCY', label: 'High Ad Dependency', severity: 'Medium', color: 'text-amber-700 bg-amber-50 border-amber-200', icon: Megaphone, desc: `Advertising costs consume ${adPct.toFixed(1)}% of the selling price (Target: < ${thresholds.highAdDependencyPct}%).` });
        }
        const margin = product.costDetail?.profitInclRnPct;
        if (margin != null && margin < thresholds.marginBelowTargetPct) {
            signals.push({ id: 'BELOW_TARGET', label: 'Margin Compression', severity: 'High', color: 'text-red-700 bg-red-50 border-red-200', icon: DollarSign, desc: `Net margin is ${margin.toFixed(1)}%, below the ${thresholds.marginBelowTargetPct}% target.` });
        }
        const trend = product._trendData?.velocityChange;
        if (trend !== undefined) {
            if (trend < -thresholds.velocityDropPct) {
                signals.push({ id: 'VELOCITY_DROP_WOW', label: 'Velocity Drop', severity: 'High', color: 'text-red-700 bg-red-50 border-red-200', icon: TrendingDown, desc: `Sales velocity has declined by ${Math.abs(trend).toFixed(0)}% compared to the prior period.` });
            } else if (trend > 20) {
                signals.push({ id: 'POSITIVE_MOMENTUM', label: 'Momentum Spike', severity: 'Low', color: 'text-green-700 bg-green-50 border-green-200', icon: TrendingUp, desc: `Sales velocity has increased by ${trend.toFixed(0)}% compared to the prior period.` });
            }
        }
        const stockValue = product.stockLevel * (product.costPrice || 0);
        const globalVelocity = product.dailyAverageSales || product.averageDailySales || 0;
        if (stockValue > thresholds.deadStockMinValueGBP && globalVelocity === 0) {
            signals.push({ id: 'DORMANT_NO_SALES', label: 'Dead Stock', severity: 'High', color: 'text-gray-700 bg-gray-50 border-gray-200', icon: Package, desc: `High value dormant stock (\u00A3${stockValue.toFixed(0)}) with 0 velocity detected.` });
        }
        return signals;
    }, [product, periodSalesQty, thresholds]);

    const platforms = useMemo(() => Array.from(new Set(sortedTransactions.map(t => t.platform || 'Unknown'))).sort(), [sortedTransactions]);

    const getStats = (days: number, valueFn: (t: PriceLog) => number | null) => {
        const { startKey, endKey } = buildWindow({ mode: 'days', days, excludeToday: true });
        const filtered = sortedTransactions
            .filter(t => {
                const dKey = asDateKey(t.date);
                if (!dKey || !isDateKeyBetween(dKey, startKey, endKey)) return false;
                return t.velocity > 0;
            })
            .map(valueFn)
            .filter((v): v is number => v !== null);
        return calculateQuantiles(filtered);
    };

    const analytics = useMemo(() => {
        const getDailyQtyStats = (days: number) => {
            const { startKey, endKey } = buildWindow({ mode: 'days', days, excludeToday: true });
            const dailyMap: Record<string, number> = {};
            sortedTransactions.forEach(t => {
                const dKey = asDateKey(t.date);
                if (dKey && isDateKeyBetween(dKey, startKey, endKey) && t.velocity > 0) {
                    dailyMap[dKey] = (dailyMap[dKey] || 0) + t.velocity;
                }
            });
            return calculateQuantiles(Object.values(dailyMap));
        };

        return {
            revenue: {
                d7: getStats(7, t => { const r = calcRevenue(t); return r > 0.01 ? r : null; }),
                d30: getStats(30, t => { const r = calcRevenue(t); return r > 0.01 ? r : null; }),
                d90: getStats(90, t => { const r = calcRevenue(t); if (r > 0.01) return r; return null; })
            },
            margin: {
                d7: getStats(7, t => { const rev = calcRevenue(t); if (rev > 0.01) { const profit = calcProfit(t); return marginPct(profit, rev); } return null; }),
                d30: getStats(30, t => { const rev = calcRevenue(t); if (rev > 0.01) { const profit = calcProfit(t); return marginPct(profit, rev); } return null; }),
                d90: getStats(90, t => { const rev = calcRevenue(t); if (rev > 0.01) { const profit = calcProfit(t); return marginPct(profit, rev); } return null; })
            },
            qty: {
                d7: getDailyQtyStats(7),
                d30: getDailyQtyStats(30),
                d90: getDailyQtyStats(90)
            },
            tacos: {
                d7: getStats(7, t => { const revenue = calcRevenue(t); if (revenue > 0) { const adSpend = calcAdSpend(t); const tacos = calcTACoSPct(adSpend, revenue); return Math.min(tacos, 300); } return null; }),
                d30: getStats(30, t => { const revenue = calcRevenue(t); if (revenue > 0) { const adSpend = calcAdSpend(t); const tacos = calcTACoSPct(adSpend, revenue); return Math.min(tacos, 300); } return null; }),
                d90: getStats(90, t => { const revenue = calcRevenue(t); if (revenue > 0) { const adSpend = calcAdSpend(t); const tacos = calcTACoSPct(adSpend, revenue); return Math.min(tacos, 300); } return null; })
            },
        };
    }, [sortedTransactions]);

    const tacosStats = useMemo(() => {
        const calculateForDays = (days: number) => {
            const { startKey, endKey } = buildWindow({ mode: 'days', days, excludeToday: true });
            const periodTx = sortedTransactions.filter(t => {
                const dKey = asDateKey(t.date);
                return dKey && isDateKeyBetween(dKey, startKey, endKey);
            });
            let totalAdSpend = 0; let totalRevenue = 0; let adOnlySpend = 0;
            periodTx.forEach(t => {
                const currentAdSpend = calcAdSpend(t);
                totalAdSpend += currentAdSpend;
                const isSale = (t as any)._type !== 'REFUND_LOG' && t.price > 0 && t.velocity > 0;
                if (isSale) {
                    totalRevenue += calcRevenue(t);
                } else if (currentAdSpend > 0 && t.price === 0) {
                    adOnlySpend += currentAdSpend;
                }
            });
            const tacosPct = calcTACoSPct(totalAdSpend, totalRevenue);
            return { totalAdSpend: totalAdSpend * VAT_MULTIPLIER, totalRevenue: totalRevenue * VAT_MULTIPLIER, tacosPct, adOnlySpend: adOnlySpend * VAT_MULTIPLIER };
        };
        return {
            d7: calculateForDays(7),
            d30: calculateForDays(30),
            d90: calculateForDays(90)
        };
    }, [sortedTransactions]);

    const priceVolumeAnalysis = useMemo(() => {
        const validTx = sortedTransactions.filter(t => t.velocity > 0 && t.price > 0);
        const refPrice = product.caPrice || (product.currentPrice * VAT_MULTIPLIER) || 1;
        const thresholdAmber = -(refPrice * 0.05);
        const thresholdRed = -(refPrice * 0.15);

        // --- 1. Global Price Point Aggregation (All Time) ---
        const aggregatedPoints: Record<number, { qty: number, costBasedCount: number }> = {};

        validTx.forEach(t => {
            const scaledPrice = t.price * VAT_MULTIPLIER;
            const p = Number(scaledPrice.toFixed(2));

            const rule = pricingRules ? pricingRules[t.platform || ''] : undefined;
            const isCostBased = rule?.pricingControl === 'PLATFORM_COST_BASED';

            if (!aggregatedPoints[p]) aggregatedPoints[p] = { qty: 0, costBasedCount: 0 };
            aggregatedPoints[p].qty += t.velocity;

            if (isCostBased) {
                aggregatedPoints[p].costBasedCount += t.velocity;
            }
        });

        // --- 2. Chart Buckets ---
        const buckets = [
            { label: '7 Days', days: 7 },
            { label: '14 Days', days: 14 },
            { label: '30 Days', days: 30 },
            { label: '90 Days', days: 90 },
            { label: 'All', days: 36500 }
        ];

        const chartData: any[] = [];
        const periodStats: any[] = [];
        const safeChanges = Array.isArray(priceChangeHistory) ? priceChangeHistory : [];

        const getEffectiveCA = (dateStr: string) => {
            const txDate = new Date(dateStr).getTime();
            const changes = safeChanges
                .filter(c => c.sku === product.sku)
                .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
            const match = changes.find(c => new Date(c.date).getTime() <= txDate);
            if (match) return match.newPrice;
            if (changes.length > 0) return changes[changes.length - 1].oldPrice;
            return refPrice;
        };

        buckets.forEach(bucket => {
            const { startKey, endKey } = buildWindow({ mode: 'days', days: bucket.days, excludeToday: true });
            const bucketTx = validTx.filter(t => {
                const dKey = asDateKey(t.date);
                return dKey && isDateKeyBetween(dKey, startKey, endKey);
            });
            const BAND_SIZE = 0.5;
            const groups: Record<string, { totalQty: number, totalRev: number, sumDelta: number, sumPrice: number }> = {};
            let totalPeriodQty = 0;
            let totalPeriodDelta = 0;

            bucketTx.forEach(t => {
                const effectiveRef = getEffectiveCA(t.date);
                const scaledPrice = t.price * VAT_MULTIPLIER;
                const rawDelta = scaledPrice - effectiveRef;
                const band = (Math.round(rawDelta / BAND_SIZE) * BAND_SIZE).toFixed(2);

                const rule = pricingRules ? pricingRules[t.platform || ''] : undefined;
                const isCostBased = rule?.pricingControl === 'PLATFORM_COST_BASED';

                // Exclude cost-based platforms from Chart Data: ERP sales recorded at agreed cost price; not comparable for sell-price deviation.
                if (!isCostBased) {
                    if (!groups[band]) groups[band] = { totalQty: 0, totalRev: 0, sumDelta: 0, sumPrice: 0 };
                    groups[band].totalQty += t.velocity;
                    groups[band].totalRev += (scaledPrice * t.velocity);
                    groups[band].sumDelta += (rawDelta * t.velocity);
                    groups[band].sumPrice += (scaledPrice * t.velocity);
                    totalPeriodQty += t.velocity;
                    totalPeriodDelta += (rawDelta * t.velocity);
                }
            });

            Object.entries(groups).forEach(([b, stats]) => {
                chartData.push({
                    period: bucket.label,
                    delta: parseFloat(b),
                    totalQty: stats.totalQty,
                    actualAvgDelta: stats.sumDelta / stats.totalQty,
                    tooltipPrice: stats.totalQty > 0 ? (stats.sumPrice / stats.totalQty).toFixed(2) : 0
                });
            });

            if (totalPeriodQty > 0) {
                periodStats.push({
                    period: bucket.label,
                    avgDelta: totalPeriodDelta / totalPeriodQty,
                    totalQty: 1
                });
            }
        });

        const pointsTable = Object.entries(aggregatedPoints)
            .map(([price, data]) => ({
                price: parseFloat(price),
                qty: data.qty,
                isCostBased: data.costBasedCount > 0
            }))
            .sort((a, b) => b.qty - a.qty);

        return { chartData, pointsTable, periodStats, thresholds: { amber: thresholdAmber, red: thresholdRed } };
    }, [sortedTransactions, priceChangeHistory, product, pricingRules]);

    const minPricePoint = useMemo(() => {
        if (priceVolumeAnalysis.pointsTable.length === 0) return null;
        return Math.min(...priceVolumeAnalysis.pointsTable.map(p => p.price));
    }, [priceVolumeAnalysis.pointsTable]);

    const maxPricePoint = useMemo(() => {
        if (priceVolumeAnalysis.pointsTable.length === 0) return null;
        return Math.max(...priceVolumeAnalysis.pointsTable.map(p => p.price));
    }, [priceVolumeAnalysis.pointsTable]);

    const filteredChartData = useMemo(() => {
        if (chartPeriod === 'All') return priceVolumeAnalysis.chartData;
        return priceVolumeAnalysis.chartData.filter(d => d.period === chartPeriod);
    }, [priceVolumeAnalysis, chartPeriod]);

    const filteredAvgStats = useMemo(() => {
        if (chartPeriod === 'All') return priceVolumeAnalysis.periodStats;
        return priceVolumeAnalysis.periodStats.filter(d => d.period === chartPeriod);
    }, [priceVolumeAnalysis, chartPeriod]);

    const platformSubtotals = useMemo(() => {
        const subtotals: Record<string, {
            platform: string;
            soldQty: number;
            adSpend: number;
            revenue: number;
            profit: number;
        }> = {};
        let totalRevenueAllPlatforms = 0;
        filteredTransactions.forEach(tx => {
            const platform = tx.platform || 'Unknown';
            if (!subtotals[platform]) {
                subtotals[platform] = {
                    platform,
                    soldQty: 0,
                    adSpend: 0,
                    revenue: 0,
                    profit: 0
                };
            }
            const group = subtotals[platform];
            const isRefund = (tx as any)._type === 'REFUND_LOG' || tx.velocity < 0;
            const isAdRow = tx.price === 0 && calcAdSpend(tx) > 0 && !isRefund;
            if (!isRefund && !isAdRow) {
                const txRevenue = calcRevenue(tx) * VAT_MULTIPLIER;
                group.soldQty += calcUnits(tx);
                group.revenue += txRevenue;
                totalRevenueAllPlatforms += txRevenue;
            }
            group.adSpend += calcAdSpend(tx) * VAT_MULTIPLIER;
            group.profit += calcProfit(tx) * VAT_MULTIPLIER;
        });
        return Object.values(subtotals).map(group => ({
            ...group,
            margin: marginPct(group.profit, group.revenue),
            revenueSharePct: totalRevenueAllPlatforms > 0 ? (group.revenue / totalRevenueAllPlatforms) * 100 : 0,
        })).sort((a, b) => b.revenue - a.revenue);
    }, [filteredTransactions]);

    const paginatedTransactions = useMemo(() => {
        return filteredTransactions.slice(0, txLimit);
    }, [filteredTransactions, txLimit]);

    const ledgerStats = useMemo(() => {
        let salesRows = 0;
        let totalUnits = 0;
        let adOnlySpend = 0;
        let refundCount = 0;
        let refundValue = 0;
        filteredTransactions.forEach(t => {
            if (t.velocity > 0) {
                salesRows++;
                totalUnits += t.velocity;
            } else if (t.price === 0 && (t.adsSpend || 0) > 0) {
                adOnlySpend += ((t.adsSpend || 0) * VAT_MULTIPLIER);
            } else if (t.velocity < 0 || t.price < 0) {
                refundCount++;
                refundValue += Math.abs(calcProfit(t) * VAT_MULTIPLIER);
            }
        });
        return { salesRows, totalUnits, adOnlySpend, refundCount, refundValue };
    }, [filteredTransactions]);

    const promotionHistoryRows = useMemo(() => {
        const targetCanonicalSku = getCanonicalSku(product.sku);
        const txLogs = Array.isArray(transactions) ? transactions : [];

        const parseFiniteNumber = (value: unknown): number | null => {
            const parsed = Number(value);
            return Number.isFinite(parsed) ? parsed : null;
        };

        const matchedRows: Array<{
            key: string;
            campaignName: string;
            promotionId: string;
            platform: string;
            status: PromotionEvent['status'];
            startDate: string;
            endDate: string;
            baselinePrice: number | null;
            promoPrice: number | null;
            discountRate: number | null;
            upliftQty: number | null;
            upliftProfit: number | null;
            sortDate: string;
        }> = [];

        const deriveStatus = (start: string | null, end: string | null): PromotionEvent['status'] => {
            if (!start || !end) return 'UPCOMING';
            if (start > todayKey) return 'UPCOMING';
            if (end < todayKey) return 'ENDED';
            return 'ACTIVE';
        };

        (promotions || []).forEach((promo) => {
            const promoItems = Array.isArray(promo.items) ? promo.items : [];
            const promoStart = asDateKey(promo.startDate);
            const promoEnd = asDateKey(promo.endDate);
            const platform = promo.platform || 'All';
            const derivedStatus = deriveStatus(promoStart, promoEnd);

            const skuScopedItems = promoItems.filter((item) => getCanonicalSku(item.sku || '') === targetCanonicalSku);
            const matchedPromoItems: Array<{ sku?: string; upliftUnits?: number; marginPctDuring?: number }> =
                skuScopedItems.length > 0
                    ? skuScopedItems
                    : (promo.promotionScope === 'SHOP' ? [{ sku: product.sku }] : []);

                matchedPromoItems.forEach((item, idx) => {
                const storedBaselinePrice = parseFiniteNumber((item as any).basePrice);
                const storedPromoPrice = parseFiniteNumber((item as any).promoPrice);
                const discountRate = (storedBaselinePrice !== null && storedPromoPrice !== null && storedBaselinePrice > 0)
                    ? ((storedBaselinePrice - storedPromoPrice) / storedBaselinePrice) * 100
                    : null;
                const storedUpliftQty = parseFiniteNumber(item.upliftUnits);
                const storedUpliftProfit = parseFiniteNumber((item as any).upliftProfit);

                let fallbackUpliftQty: number | null = null;
                let fallbackUpliftProfit: number | null = null;

                if ((storedUpliftQty === null || storedUpliftProfit === null) && promoStart && promoEnd && derivedStatus !== 'UPCOMING') {
                    const startDateObj = new Date(promoStart);
                    const effectiveEndKey = derivedStatus === 'ACTIVE'
                        ? (todayKey < promoEnd ? todayKey : promoEnd)
                        : promoEnd;
                    const effectiveEndDateObj = new Date(effectiveEndKey);
                    const eventDays = Math.max(1, Math.ceil((effectiveEndDateObj.getTime() - startDateObj.getTime()) / (1000 * 60 * 60 * 24)) + 1);
                    const baselineEnd = addDaysToDateKey(promoStart, -1);
                    const baselineStart = addDaysToDateKey(baselineEnd, -(eventDays - 1));

                    const samePlatform = (tx: PriceLog) => platform === 'All' || tx.platform === platform;
                    const sameSku = (tx: PriceLog) => getCanonicalSku(tx.sku || '') === targetCanonicalSku;
                    const salesOnly = (tx: PriceLog) => calcUnits(tx) > 0;

                    const eventLogs = txLogs.filter((tx) => {
                        const key = asDateKey(tx.date);
                        return !!key && sameSku(tx) && samePlatform(tx) && salesOnly(tx) && isDateKeyBetween(key, promoStart, effectiveEndKey);
                    });

                    const baselineLogs = txLogs.filter((tx) => {
                        const key = asDateKey(tx.date);
                        return !!key && sameSku(tx) && samePlatform(tx) && salesOnly(tx) && isDateKeyBetween(key, baselineStart, baselineEnd);
                    });

                    const eventUnits = eventLogs.reduce((sum, tx) => sum + calcUnits(tx), 0);
                    const baselineUnits = baselineLogs.reduce((sum, tx) => sum + calcUnits(tx), 0);
                    const baselineDailyUnits = baselineUnits / eventDays;
                    fallbackUpliftQty = eventUnits - (baselineDailyUnits * eventDays);

                    const eventProfit = eventLogs.reduce((sum, tx) => sum + calcProfit(tx), 0);
                    const baselineProfit = baselineLogs.reduce((sum, tx) => sum + calcProfit(tx), 0);
                    fallbackUpliftProfit = eventProfit - baselineProfit;
                }

                matchedRows.push({
                    key: `${promo.id}-${item.sku || product.sku}-${idx}`,
                    campaignName: promo.name || 'Untitled Campaign',
                    promotionId: promo.id,
                    platform,
                    status: derivedStatus,
                    startDate: promoStart || '-',
                    endDate: promoEnd || '-',
                    baselinePrice: storedBaselinePrice,
                    promoPrice: storedPromoPrice,
                    discountRate,
                    upliftQty: storedUpliftQty ?? fallbackUpliftQty,
                    upliftProfit: storedUpliftProfit ?? fallbackUpliftProfit,
                    sortDate: promoEnd || promoStart || '0000-00-00'
                });
            });
        });

        return matchedRows.sort((a, b) => b.sortDate.localeCompare(a.sortDate));
    }, [promotions, product.sku, transactions, todayKey]);

    const hasPromotionHistory = promotionHistoryRows.length > 0;

    // Each section band breaks out of the parent p-4 md:p-8 padding with -mx-4 md:-mx-8
    // and re-applies inner padding so content lines up with the rest of the app.
    // This gives true full-width colour bands that expand naturally with content.
    const band = "relative -mx-4 md:-mx-8 px-4 md:px-8 py-6";

    return (
        <div className="pb-20">

            {/* â”€â”€ Page header â”€â”€ */}
            <div className="flex items-center justify-between px-0 py-4">
                <div className="flex items-center gap-2">
                    {onBack && (
                        <button onClick={onBack} className="text-gray-500 hover:text-gray-700 transition-colors p-2 rounded-full hover:bg-gray-100">
                            <ArrowLeft className="w-5 h-5" />
                        </button>
                    )}
                    <div>
                        <h2 className="text-xl font-bold text-gray-900">SKU Deep Dive</h2>
                        {initialTimeWindow && (
                            <div className="text-[10px] text-theme font-medium flex items-center gap-1 mt-0.5 bg-theme-10 px-2 py-0.5 rounded w-fit border border-indigo-100">
                                <Info className="w-3 h-3" />
                                Dashboard window: Last {txDays} days
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* â”€â”€ 1. Overview â€” white â”€â”€ */}
            <div ref={overviewRef} className={`${band}`}>
                <SkuOverviewSection
                    product={product}
                    allTimeSales={allTimeSales}
                    allTimeQty={allTimeQty}
                    allTimeMarginStats={allTimeMarginStats}
                    allTimeReturnStats={allTimeReturnStats}
                    thresholds={thresholds}
                    hasTransactions={sortedTransactions.length > 0}
                    onScrollToSection={scrollToSection}
                />
            </div>

            {/* â”€â”€ 2. Diagnostic Signals â€” amber tint â”€â”€ */}
            {diagnostics.length > 0 && (
                <div ref={signalsRef} className={`${band}`}>
                    <DiagnosticSignalsSection
                        diagnostics={diagnostics}
                        focus={focus}
                        activeSignalRef={activeSignalRef}
                    />
                </div>
            )}

            {/* â”€â”€ 3. Distribution Analysis â€” light slate â”€â”€ */}
            {sortedTransactions.length > 0 && (
                <div ref={analysisRef} className={`${band} bg-slate-50 border-y border-slate-100`}>
                    <DistributionAnalysisSection
                        analytics={analytics}
                        tacosStats={tacosStats}
                        chartLayout={chartLayout}
                        setChartLayout={setChartLayout}
                        tooltip={tooltip}
                        setTooltip={setTooltip}
                        thresholds={thresholds}
                        themeColor={themeColor}
                    />
                </div>
            )}

            {/* â”€â”€ 4. Pricing History â€” white â”€â”€ */}
            {sortedTransactions.length > 0 && (
                <div ref={pricingRef} className={`${band} bg-lime-50 border-y border-gray-100`}>
                    <PricingHistorySection
                        priceVolumeAnalysis={priceVolumeAnalysis}
                        minPricePoint={minPricePoint}
                        maxPricePoint={maxPricePoint}
                        filteredChartData={filteredChartData}
                        filteredAvgStats={filteredAvgStats}
                        chartPeriod={chartPeriod}
                        setChartPeriod={setChartPeriod}
                        hoveredBubble={hoveredBubble}
                        setHoveredBubble={setHoveredBubble}
                        priceChangeHistory={priceChangeHistory}
                        productSku={product.sku}
                        startKey={startKey}
                        endKey={endKey}
                        themeColor={themeColor}
                        optimalPrice={(product.optimalPrice || product.maxVelocityPrice || 0) * VAT_MULTIPLIER}
                        optimalPriceResult={optimalPriceResults?.get(getCanonicalSku(product.sku))}
                        currentPrice={product.caPrice || (product.currentPrice * VAT_MULTIPLIER)}
                        siblings={siblings}
                        isInFamily={isInFamily}
                        priceHistoryMap={priceHistoryMap}
                    />
                </div>
            )}

            {/* 5. Promotion History */}
            <div
                ref={promotionRef}
                className={`${band} border-y border-emerald-100/70`}
                style={{ backgroundColor: '#ecfdf5' }}
            >
                <div className="bg-custom-glass rounded-xl shadow-sm border border-custom-glass overflow-hidden backdrop-blur-custom p-6">
                    <div className="flex items-center justify-between mb-4 border-b border-emerald-100 pb-3">
                        <div className="flex items-center gap-2">
                            <div className="p-2 bg-emerald-100 text-emerald-700 rounded-lg">
                                <Megaphone className="w-4 h-4" />
                            </div>
                            <h3 className="text-lg font-bold text-gray-900">Promotion History</h3>
                        </div>
                        <span className="text-xs text-gray-500 font-medium">
                            {hasPromotionHistory ? `${promotionHistoryRows.length} campaign item(s)` : 'No campaign records'}
                        </span>
                    </div>

                    {hasPromotionHistory ? (
                        <div className="overflow-x-auto">
                            <table className="sello-table">
                                <thead className="sticky top-0">
                                    <tr>
                                        <th>Campaign Name</th>
                                        <th>Platform</th>
                                        <th>Status</th>
                                        <th className="r">Baseline Price</th>
                                        <th className="r col-red">Promo Price</th>
                                        <th className="r col-red">Discount Rate</th>
                                        <th className="r">Uplift Qty</th>
                                        <th className="r">Uplift Profit</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {promotionHistoryRows.map((row) => (
                                        <tr key={row.key}>
                                            <td>
                                                <div className="flex items-center gap-2">
                                                    <div className="font-medium text-gray-900">{row.campaignName}</div>
                                                    <button
                                                        type="button"
                                                        className="inline-flex items-center justify-center w-5 h-5 rounded text-gray-400 hover:text-theme hover:bg-theme-10 transition-colors"
                                                        title="Open campaign"
                                                        onClick={() => navigateToEntity?.({
                                                            targetView: 'promotions',
                                                            entityType: 'promotion_campaign',
                                                            entityId: row.promotionId,
                                                            sourceView: 'search'
                                                        })}
                                                    >
                                                        <ExternalLink className="w-3.5 h-3.5" />
                                                    </button>
                                                </div>
                                                <div className="text-[11px] text-gray-500">{row.startDate} to {row.endDate}</div>
                                            </td>
                                            <td className="text-gray-700">{row.platform}</td>
                                            <td><StatusBadge status={row.status} /></td>
                                            <td className="r font-medium text-gray-800">
                                                {row.baselinePrice === null ? '-' : `\u00A3${formatNumber(row.baselinePrice, 2)}`}
                                            </td>
                                            <td className="r col-red font-medium text-gray-800">
                                                {row.promoPrice === null ? '-' : `\u00A3${formatNumber(row.promoPrice, 2)}`}
                                            </td>
                                            <td className="r col-red font-medium text-gray-800">
                                                {row.discountRate === null ? '-' : `${row.discountRate > 0 ? '-' : ''}${formatNumber(Math.abs(row.discountRate), 1)}%`}
                                            </td>
                                            <td className="r font-semibold text-gray-900">
                                                {row.upliftQty === null ? '-' : `${row.upliftQty > 0 ? '+' : ''}${formatNumber(row.upliftQty, 0)}`}
                                            </td>
                                            <td className={`r font-semibold ${row.upliftProfit !== null && row.upliftProfit < 0 ? 'text-red-600' : 'text-emerald-700'}`}>
                                                {row.upliftProfit === null
                                                    ? '-'
                                                    : `${row.upliftProfit > 0 ? '+' : row.upliftProfit < 0 ? '-' : ''}\u00A3${formatNumber(Math.abs(row.upliftProfit), 2)}`}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    ) : (
                        <div className="text-sm text-gray-500 py-6">No promotion history found for this SKU yet.</div>
                    )}
                </div>
            </div>

            {/* 6. Transaction Ledger */}
            {sortedTransactions.length > 0 && (
                <div ref={ledgerRef} className={`${band} bg-theme-10/40 border-y border-indigo-100/60`}>
                    <TransactionLedgerSection
                        ledgerStats={ledgerStats}
                        platformSubtotals={platformSubtotals}
                        paginatedTransactions={paginatedTransactions}
                        filteredTransactionsLength={filteredTransactions.length}
                        txLimit={txLimit}
                        setTxLimit={setTxLimit}
                        isAuditPanelVisible={isAuditPanelVisible}
                        setIsAuditPanelVisible={setIsAuditPanelVisible}
                        txDays={txDays}
                        setTxDays={setTxDays}
                        txFilterPlatform={txFilterPlatform}
                        setTxFilterPlatform={setTxFilterPlatform}
                        txFilterType={txFilterType}
                        setTxFilterType={setTxFilterType}
                        platforms={platforms}
                        startKey={startKey}
                        endKey={endKey}
                        filteredTransactions={filteredTransactions}
                        thresholds={thresholds}
                        calcRevenue={calcRevenue}
                        calcUnits={calcUnits}
                        calcProfit={calcProfit}
                        calcAdSpend={calcAdSpend}
                        marginPct={marginPct}
                        product={product}
                        adRedistributionSummary={adRedistributionSummary}
                    />
                </div>
            )}

            {/* 7. Returns Analysis */}
