export const BoxPlot = ({ title, stats7, stats30, stats90, format, color = '#6366f1', adOnly7, layout = 'horizontal', showAdOnlyFooter = false, setTooltip, tooltip }: any) => {
    const CustomRechartsTooltip = ({ active, payload, label, formatFn }: any) => {
        if (active && payload && payload.length) {
            const data = payload[0].payload;
            const content = {
                label,
                n: data.n,
                max: data.max,
                q3: data.q3,
                median: data.median,
                q1: data.q1,
                min: data.min,
            };
            return (
                <div className="bg-gray-900 text-white p-3 rounded-lg shadow-xl text-xs max-w-xs z-50 border border-gray-700 backdrop-blur-md bg-opacity-95">
                    <div className="font-bold mb-2 border-b border-gray-700 pb-1">{content.label} (n={content.n})</div>
                    <div className="grid grid-cols-2 gap-x-4 gap-y-1 text-[10px]">
                        <span>Max:</span><span className="text-right font-mono">{formatFn(content.max)}</span>
                        <span>Q3:</span><span className="text-right font-mono">{formatFn(content.q3)}</span>
                        <span className="font-bold">Median:</span><span className="text-right font-mono font-bold">{formatFn(content.median)}</span>
                        <span>Q1:</span><span className="text-right font-mono">{formatFn(content.q1)}</span>
                        <span>Min:</span><span className="text-right font-mono">{formatFn(content.min)}</span>
                    </div>
                </div>
            );
        }
        return null;
    };

    const BoxAndWhisker = (props: any) => {
        const { x, y, width, height, payload, color } = props;
        const { min, q1, median, q3, max } = payload;

        const iqrHeight = Math.abs(height);
        const iqrRange = q3 - q1;

        if (iqrRange <= 0 && height === 0) return null;

        const scale = (value: number) => {
            if (iqrRange <= 0) return y + iqrHeight / 2;
            return y + ((getValInRange(q3, 0.0001) - value) / (getValInRange(iqrRange, 0.0001))) * iqrHeight;
        };

        const getValInRange = (val: number, min: number) => val === 0 ? min : val;

        const medianY = scale(median);
        const minY = scale(min);
        const maxY = scale(max);

        const whiskerX = x + width / 2;
        const tickWidth = width / 2;

        return (
            <g>
                <rect x={x} y={y} width={width} height={height} fill={`${color}20`} stroke={color} />
                <line x1={x} y1={medianY} x2={x + width} y2={medianY} stroke={color} strokeWidth={2} />
                <line x1={whiskerX} y1={y} x2={whiskerX} y2={maxY} stroke="gray" />
                <line x1={whiskerX} y1={y + height} x2={whiskerX} y2={minY} stroke="gray" />
                <line x1={whiskerX - tickWidth} y1={maxY} x2={whiskerX + tickWidth} y2={maxY} stroke="gray" />
                <line x1={whiskerX - tickWidth} y1={minY} x2={whiskerX + tickWidth} y2={minY} stroke="gray" />
            </g>
        );
    };

    const CustomizedAxisTick = (props: any) => {
        const { x, y, payload, data } = props;
        const dataPoint = data.find((d: any) => d.name === payload.value);

        return (
          <g transform={`translate(${x},${y})`}>
            <text x={0} y={0} dy={16} textAnchor="middle" fill="#666" fontSize={10} fontWeight="500" style={{ userSelect: 'none' }}>
              {payload.value}
            </text>
            {dataPoint && (
                <text x={0} y={28} dy={0} textAnchor="middle" fill="#666" fontSize={10} style={{ userSelect: 'none' }}>
                    (n={dataPoint.n})
                </text>
            )}
            {dataPoint && dataPoint.n < 10 && (
                <text x={0} y={42} dy={0} textAnchor="middle" fill="#92400e" fontSize={9} fontWeight="bold" style={{ userSelect: 'none' }}>
                    (Low Data)
                </text>
            )}
          </g>
        );
    };

    if (layout === 'vertical') {
        const chartData = [
            { name: '7 Days', ...(stats7 || {}) },
            { name: '30 Days', ...(stats30 || {}) },
            { name: '90 Days', ...(stats90 || {}) },
        ].filter(d => d.min !== undefined && d.min !== null);

        if (chartData.length === 0) {
            return (
                <div className="bg-white py-4 px-4 rounded-xl border border-gray-200 shadow-sm h-full flex flex-col items-center justify-center">
                    <h4 className="text-xs font-bold text-gray-500 uppercase mb-3 flex items-center gap-2">
                        <Activity className="w-3 h-3" /> {title}
                    </h4>
                    <div className="text-xs text-gray-400">No data available for this period.</div>
                </div>
            );
        }

        const allValues = chartData.flatMap(d => [d.min, d.max]);
        const globalMin = Math.min(...allValues);
        const globalMax = Math.max(...allValues);
        const range = globalMax - globalMin;
        const padding = range > 0 ? range * 0.15 : Math.max(Math.abs(globalMin) * 0.2, 1);
        const yDomain: [number, number] = [globalMin - padding, globalMax + padding];

        return (
            <div className="bg-white py-4 px-2 rounded-xl border border-gray-200 shadow-sm h-full flex flex-col select-none">
                <h4 className="text-xs font-bold text-gray-500 uppercase mb-3 flex items-center gap-2 px-2">
                    <Activity className="w-3 h-3" /> {title}
                </h4>
                <div className="flex-1 min-h-0">
                    <ResponsiveContainer width="100%" height="100%">
                        <ComposedChart data={chartData} margin={{ top: 5, right: 10, left: 0, bottom: 5 }}>
                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                            <XAxis dataKey="name" tick={<CustomizedAxisTick data={chartData} />} height={55} tickLine={false} axisLine={false} />
                            <YAxis 
                                domain={yDomain} 
                                tickFormatter={format} 
                                tick={{fontSize: 10, style: { userSelect: 'none' }}}
                                width={45}
                                tickLine={false}
                                axisLine={false}
                            />
                            <RechartsTooltip 
                              content={<CustomRechartsTooltip formatFn={format} />} 
                              cursor={{ fill: `${color}10` }} 
                            />
                            <Bar 
                                dataKey={(d) => [d.q1, d.q3]} 
                                shape={<BoxAndWhisker color={color} />} 
                                barSize={40}
                            />
                        </ComposedChart>
                    </ResponsiveContainer>
                </div>
            </div>
        );
    }

    // Default Horizontal Layout
    const renderBar = (stats: any, label: string, baselineMedian?: number) => {
        if (!stats) return <div className="h-8 flex items-center text-xs text-gray-400 pl-2">No data</div>;

        const range = stats.max - stats.min;
        const width = (val: number) => range === 0 ? 0 : ((val - stats.min) / range) * 100;

        let deltaInfo = null;
        if (baselineMedian !== undefined && stats.median !== undefined && baselineMedian !== 0) {
            const diff = ((stats.median - baselineMedian) / baselineMedian) * 100;
            const isPositive = diff > 0;
            const isZero = Math.abs(diff) < 0.1;

            if (!isZero) {
                deltaInfo = (
                    <span className={`ml-2 text-[9px] font-medium px-1.5 py-0.5 rounded flex items-center gap-0.5 ${isPositive ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                        {isPositive ? <TrendingUp className="w-2.5 h-2.5" /> : <TrendingDown className="w-2.5 h-2.5" />}
                        {Math.abs(diff).toFixed(1)}% vs 90d
                    </span>
                );
            }
        }

        return (
            <div 
                className="mb-3"
                onMouseEnter={(e) => {
                    const rect = e.currentTarget.getBoundingClientRect();
                    setTooltip({
                        visible: true,
                        source: title,
                        content: { label, ...stats },
                        x: rect.left + rect.width / 2,
                        y: rect.top,
                    });
                }}
                onMouseLeave={() => {
                    setTooltip(null);
                }}
            >
                <div className="flex justify-between items-center mb-1">
                    <div className="flex items-center">
                        <span className="text-[10px] font-medium text-gray-500">{label} (n={stats.n})</span>
                        {deltaInfo}
                    </div>
                    {stats.n < 10 && <span className="text-[9px] text-amber-600 flex items-center gap-1 bg-amber-50 px-1 rounded"><AlertTriangle className="w-2.5 h-2.5"/> Low Data</span>}
                </div>
                <div className="relative h-6 rounded border border-gray-100">
                    <div className="absolute top-1/2 left-0 right-0 h-px bg-gray-300"></div>
                    <div 
                        className="absolute top-1 bottom-1 border"
                        style={{ 
                            left: `${width(stats.q1)}%`, 
                            width: `${width(stats.q3) - width(stats.q1)}%`,
                            backgroundColor: `${color}20`,
                            borderColor: color
                        }} 
                    />
                    <div 
                        className="absolute top-0 bottom-0 w-0.5"
                        style={{ left: `${width(stats.median)}%`, backgroundColor: color }} 
                    />
                    <div className="absolute top-1 bottom-1 w-px bg-gray-400" style={{ left: '0%' }} />
                    <div className="absolute top-1 bottom-1 w-px bg-gray-400" style={{ right: '0%' }} />
                </div>
                <div className="flex justify-between text-[9px] text-gray-400 mt-0.5 font-mono">
                    <span>{format(stats.min)}</span>
                    <span className="text-gray-700 font-medium bg-white px-1 rounded shadow-sm border border-gray-100">{format(stats.median)}</span>
                    <span>{format(stats.max)}</span>
                </div>
            </div>
        );
    };

    return (
        <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex flex-col justify-between h-full select-none">
            <div>
                <h4 className="text-xs font-bold text-gray-500 uppercase mb-3 flex items-center gap-2">
                    <Activity className="w-3 h-3" /> {title}
                </h4>
                {renderBar(stats7, '7 Days', stats90?.median)}
                {renderBar(stats30, '30 Days', stats90?.median)}
                {renderBar(stats90, '90 Days')}
            </div>
            {showAdOnlyFooter && adOnly7 !== undefined && (
                <div className="mt-auto pt-2 border-t border-gray-100 bg-orange-50/50 -m-4 mt-2 px-4 py-2 rounded-b-xl">
                    <div className="flex justify-between items-center text-sm">
                        <span className="text-gray-600 font-medium">Ad-Only Spend (7d):</span>
                        <span className="font-bold text-orange-700">{formatSmartMoney(adOnly7)}</span>
                    </div>
                </div>
            )}
            {tooltip?.visible && tooltip.source === title && <BoxPlotTooltip content={tooltip.content} x={tooltip.x} y={tooltip.y} format={format} />}
        </div>
    );
};

import React, { useMemo, useState } from 'react';
import { DollarSign, Tag, TrendingUp, TrendingDown, ArrowRight, Info, Users, Clock, LayoutGrid } from 'lucide-react';
import { ResponsiveContainer, ScatterChart, Scatter, XAxis, YAxis, ZAxis, CartesianGrid, ReferenceArea, ReferenceLine, Tooltip as RechartsTooltip, Legend, BarChart, Bar, ComposedChart, Line } from 'recharts';
import { PriceChangeHistoryPanel } from '../../strategy/PriceChangeHistoryPanel';
import { OptimalPriceCard } from '../parts/OptimalPriceCard';
import { Product, PriceLog, OptimalPriceResult, PricePoint } from '../../../types';
import { formatMoney, formatSmartMoney } from '../../../utils/format';
import { VAT_MULTIPLIER } from '../../../constants';
import { asDateKey, addDaysToDateKey } from '../../../services/dateUtils';

interface PricingHistorySectionProps {
    priceVolumeAnalysis: any;
    minPricePoint: number | null;
    maxPricePoint: number | null;
    filteredChartData: any[];
    filteredAvgStats: any[];
    chartPeriod: string;
    setChartPeriod: (p: string) => void;
    hoveredBubble: any;
    setHoveredBubble: (b: any) => void;
    priceChangeHistory: any[];
    productSku: string;
    startKey: string;
    endKey: string;
    themeColor: string;
    formatYAxis?: (val: any) => string;
    optimalPrice: number;
    optimalPriceResult?: OptimalPriceResult;   // new: full result
    currentPrice: number;
    siblings: Product[];
    isInFamily: boolean;
    priceHistoryMap: Map<string, PriceLog[]>;
}

export const PricingHistorySection: React.FC<PricingHistorySectionProps> = ({
    priceVolumeAnalysis,
    minPricePoint,
    maxPricePoint,
    filteredChartData,
    filteredAvgStats,
    chartPeriod,
    setChartPeriod,
    hoveredBubble,
    setHoveredBubble,
    priceChangeHistory,
    productSku,
    startKey,
    endKey,
    themeColor,
    optimalPrice,
    optimalPriceResult,
    currentPrice,
    siblings,
    isInFamily,
    priceHistoryMap
}) => {
    const [viewMode, setViewMode] = useState<'deviation' | 'velocity'>('deviation');

    // Calculate total volume for share % calculation
    const totalVolume = useMemo(() => {
        return priceVolumeAnalysis.pointsTable.reduce((sum: number, pt: any) => sum + pt.qty, 0);
    }, [priceVolumeAnalysis.pointsTable]);

    const siblingColors = ['#64748b', '#f59e0b', '#14b8a6', '#f43f5e', '#8b5cf6', '#ec4899'];

    const aggregatedFamilyVelocityData = useMemo(() => {
        if (!isInFamily || !startKey || !endKey) return [];

        const allFamilySkus = [productSku, ...siblings.map(s => s.sku)];
        const data: any[] = [];

        // 1. Determine Bucket Strategy
        let bucketSize: 'daily' | 'weekly' | 'monthly' = 'daily';
        if (chartPeriod === '30 Days' || chartPeriod === '90 Days') bucketSize = 'weekly';
        if (chartPeriod === 'All') bucketSize = 'monthly';

        // 2. Generate Buckets
        const startDate = new Date(startKey);
        const endDate = new Date(endKey);

        if (bucketSize === 'daily') {
            let curr = startKey;
            while (curr <= endKey) {
                const d = new Date(curr);
                const label = d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
                data.push({ period: label, dateKey: curr });
                curr = addDaysToDateKey(curr, 1);
            }
        } else if (bucketSize === 'weekly') {
            let curr = startKey;
            let weekCount = 1;
            while (curr <= endKey) {
                const weekEnd = addDaysToDateKey(curr, 6);
                const actualEnd = weekEnd > endKey ? endKey : weekEnd;

                const dStart = new Date(curr);
                const dEnd = new Date(actualEnd);
                const label = `${dStart.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })} - ${dEnd.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}`;

                data.push({
                    period: label,
                    start: curr,
                    end: actualEnd,
                    weekLabel: `Week ${weekCount++}`
                });
                curr = addDaysToDateKey(actualEnd, 1);
            }
        } else { // monthly
            let curr = new Date(startDate.getFullYear(), startDate.getMonth(), 1);
            while (curr <= endDate) {
                const monthEnd = new Date(curr.getFullYear(), curr.getMonth() + 1, 0);
                const mStartKey = asDateKey(curr)!;
                const mEndKey = asDateKey(monthEnd)!;

                const label = curr.toLocaleDateString('en-GB', { month: 'short', year: 'numeric' });
                data.push({
                    period: label,
                    start: mStartKey,
                    end: mEndKey
                });
                curr = new Date(curr.getFullYear(), curr.getMonth() + 1, 1);
            }
        }

        // 3. Fill Buckets with Data
        allFamilySkus.forEach(sku => {
            const logs = priceHistoryMap.get(sku) || [];
            data.forEach(bucket => {
                let units = 0;
                if (bucketSize === 'daily') {
                    units = logs
                        .filter(l => asDateKey(l.date) === bucket.dateKey)
                        .reduce((sum, l) => sum + (l.velocity || 0), 0);
                } else {
                    units = logs
                        .filter(l => {
                            const d = asDateKey(l.date);
                            return d && d >= bucket.start && d <= bucket.end;
                        })
                        .reduce((sum, l) => sum + (l.velocity || 0), 0);
                }
                bucket[sku] = units;
            });
        });

        return data;
    }, [isInFamily, siblings, productSku, priceHistoryMap, chartPeriod, startKey, endKey]);

    const familySkus = [productSku, ...siblings.map(s => s.sku)];

    // ── Inline Profit Curve Chart (same spec as modal in Session 4)
    const ProfitCurveChart: React.FC<{ result?: OptimalPriceResult; currentPrice: number }> = ({ result: r, currentPrice: cp }) => {
        if (!r) {
            return (
                <div className="w-full h-full flex items-center justify-center text-gray-400 text-sm">
                    No optimal price data available for this SKU yet.
                </div>
            );
        }
        const pricePoints: PricePoint[] = r.skuPricePoints;
        const recommendedPrice = r.recommendedPrice;
        const cohortElasticity = r.cohort.elasticity;
        const cohortVelocity = r.cohort.medianVelocity;
        const costs = 0; // costs not available in this context — guardrail zone omitted

        const allPrices = pricePoints.map(p => p.price);
        const lo = allPrices.length > 0 ? Math.min(...allPrices) * 0.9 : cp * 0.7;
        const hi = Math.max(cp, recommendedPrice) * 1.15;
        const xMin = Math.min(lo, cp * 0.85);
        const xMax = hi;

        const organicData = pricePoints.filter(p => p.source === 'organic').map(p => ({
            x: p.price, y: p.dailyProfit, price: p.price, source: 'organic',
            velocity: p.velocity, margin: p.margin, dailyProfit: p.dailyProfit, eraId: p.eraId,
        }));
        const promoData = pricePoints.filter(p => p.source === 'promo').map(p => ({
            x: p.price, y: p.dailyProfit, price: p.price, source: 'promo',
            velocity: p.velocity, margin: p.margin, dailyProfit: p.dailyProfit, eraId: p.eraId,
        }));
        // Organic points only, 2+ distinct prices required — avoids vertical spikes
        // when promo and organic share the same price on the x axis
        const organicSorted = [...pricePoints]
            .filter(p => p.source === 'organic')
            .sort((a, b) => a.price - b.price);
        const distinctOrganicPrices = new Set(organicSorted.map(p => p.price)).size;
        const curveData = distinctOrganicPrices >= 2
            ? organicSorted.map(p => ({ x: p.price, y: p.dailyProfit, price: p.price, dailyProfit: p.dailyProfit }))
            : [];
        const STEPS = 40;
        const bucketMid = (xMin + xMax) / 2;
        const cohortCurveData = Array.from({ length: STEPS + 1 }, (_, i) => {
            const price = xMin + (i / STEPS) * (xMax - xMin);
            const margin = price - costs;
            if (margin <= 0) return null;
            const vf = 1 + cohortElasticity * ((price - bucketMid) / (bucketMid || 1));
            const estV = cohortVelocity * Math.max(0, vf);
            return { x: price, y: margin * estV, price, dailyProfit: margin * estV };
        }).filter((d): d is NonNullable<typeof d> => d !== null);

        const hasNoData = pricePoints.length === 0;

        return (
            <div className="relative w-full h-full">
                {hasNoData && (
                    <div className="absolute top-2 left-0 right-0 flex justify-center z-10 pointer-events-none">
                        <span className="bg-gray-800/80 text-white text-[10px] px-3 py-1 rounded-full">
                            No sales history — curve based on benchmark
                        </span>
                    </div>
                )}
                <ResponsiveContainer width="100%" height="100%">
                    <ComposedChart margin={{ top: 24, right: 20, left: 10, bottom: 20 }}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
                        <XAxis type="number" dataKey="x" domain={[xMin, xMax]} tickFormatter={(v) => `£${Number(v).toFixed(0)}`} tick={{ fontSize: 10 }} label={{ value: 'Price (£)', position: 'insideBottom', offset: -8, fontSize: 10, fill: '#9ca3af' }} />
                        <YAxis tick={{ fontSize: 10 }} tickFormatter={(v) => `£${Number(v).toFixed(2)}`} label={{ value: 'Daily Profit', angle: -90, position: 'insideLeft', offset: 10, fontSize: 10, fill: '#9ca3af' }} />
                        <RechartsTooltip
                            content={({ active, payload }: any) => {
                                if (!active || !payload?.length) return null;
                                const d = payload[0]?.payload;
                                if (!d) return null;
                                const isOpt = Math.abs(d.price - recommendedPrice) < 0.5;
                                return (
                                    <div className="bg-gray-900 text-white p-3 rounded-xl text-[11px] min-w-[160px] border border-gray-700">
                                        <div className="font-bold text-indigo-300 mb-1">{formatSmartMoney(d.price)}{isOpt ? ' ★' : ''}</div>
                                        {d.velocity != null && <div className="text-gray-400">Velocity: {d.velocity.toFixed(2)}/day</div>}
                                        <div className={isOpt ? 'font-bold text-emerald-300' : ''}>Profit: {formatSmartMoney(d.dailyProfit ?? d.y)}</div>
                                    </div>
                                );
                            }}
                        />
                        {cohortCurveData.length > 0 && (
                            <Line data={cohortCurveData} type="monotone" dataKey="y" stroke="#9ca3af" strokeWidth={1.5} strokeDasharray="4 4" dot={false} isAnimationActive={false} />
                        )}
                        {curveData.length >= 3 && (
                            <Line data={curveData} type="monotone" dataKey="y" stroke='var(--theme)' strokeWidth={2} dot={false} isAnimationActive={false} />
                        )}
                        {organicData.length > 0 && <Scatter data={organicData} fill='var(--theme)' name="Organic" />}
                        {promoData.length > 0 && <Scatter data={promoData} fill="none" stroke="#f59e0b" strokeWidth={2} name="Promo" />}
                        {(() => {
                            const priceDiff = Math.abs(recommendedPrice - cp);
                            const xRange = xMax - xMin;
                            const tooClose = xRange > 0 && (priceDiff / xRange) < 0.08;
                            return (
                                <ReferenceLine
                                    x={cp}
                                    stroke="#6b7280"
                                    strokeWidth={1.5}
                                    strokeDasharray="4 3"
                                    label={{ value: `Current ${formatSmartMoney(cp)}`, position: tooClose ? 'insideTopLeft' : 'top', fontSize: 9, fill: '#6b7280', ...(tooClose ? { dy: 28 } : {}) }}
                                />
                            );
                        })()}
                        <ReferenceLine x={recommendedPrice} stroke="#10b981" strokeWidth={2} label={{ value: `Optimal ${formatSmartMoney(recommendedPrice)} ★`, position: 'top', fontSize: 9, fill: '#10b981' }} />
                    </ComposedChart>
                </ResponsiveContainer>
            </div>
        );
    };

    // ── Profit Curve Price Points Table
    const ProfitCurveTable: React.FC<{ result: OptimalPriceResult }> = ({ result: r }) => (
        <div className="mt-4">
            {r.aliasesUsed.length > 0 && (
                <p className="text-xs text-gray-500 mb-2">
