                                </div>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {activeTab === 'COST_HISTORY' && (
                <div className="space-y-6">
                    <div className="bg-custom-glass p-4 rounded-xl border border-custom-glass shadow-sm flex items-start gap-4">
