                                                    onChange={e => {
                                                        const v = parseFloat(e.target.value) || 0;
                                                        update(row.id, {
                                                            proposedPrice: v,
                                                            lastEdited: 'price',
                                                            // keep margin in sync so switching back is smooth
                                                            proposedMarginPct: 0,
                                                        });
                                                    }}
                                                    className="flex-1 text-xs font-mono text-right font-bold text-gray-800 bg-transparent outline-none min-w-0"
