    const [newTemplateName, setNewTemplateName] = useState('');
    const [newTemplateFormat, setNewTemplateFormat] = useState<'csv' | 'xlsx'>('xlsx'); // New: File format state
    const [isMappingTemplate, setIsMappingTemplate] = useState(false);
    
