// ─────────────────────────────────────────────────────────────

export interface BudgetRecommendation {
    action: 'INCREASE' | 'DECREASE' | 'MAINTAIN';
    reason: string;
    suggestedBudget?: number;
}

export function getBudgetRecommendation(
    group: AdGroupSnapshot,
    prevGroup: AdGroupSnapshot | null,
    targetSpendToSalesRatio = 0.05
): BudgetRecommendation {
    if (group.roasOptIn > 3 && group.utilisation > 0.9) {
        return {
            action: 'INCREASE',
            reason: `Strong ROAS (${group.roasOptIn.toFixed(1)}) and fully utilised (${Math.round(group.utilisation * 100)}%). Increase to capture more sales.`,
            suggestedBudget: Math.ceil(group.dailyBudget * 1.25),
        };
    }

    if (group.spendToSalesRatio > targetSpendToSalesRatio && group.sales > 0) {
        return {
            action: 'DECREASE',
            reason: `Spend/sales ${(group.spendToSalesRatio * 100).toFixed(1)}% exceeds ${(targetSpendToSalesRatio * 100).toFixed(0)}% target.`,
            suggestedBudget: Math.floor(group.dailyBudget * 0.8),
        };
    }

    if (prevGroup && group.utilisation < 0.65 && prevGroup.utilisation > 0.85) {
        return {
            action: 'DECREASE',
            reason: `Utilisation dropped from ${Math.round(prevGroup.utilisation * 100)}% to ${Math.round(group.utilisation * 100)}% — remaining SKUs not absorbing budget.`,
            suggestedBudget: Math.floor(group.dailyBudget * (group.utilisation / 0.85)),
        };
    }

    if (prevGroup && prevGroup.sales > 0 && group.sales < prevGroup.sales * 0.8) {
        return {
            action: 'DECREASE',
            reason: `Sales dropped ${Math.round((1 - group.sales / prevGroup.sales) * 100)}% WoW.`,
        };
    }

    if (group.sales === 0 && group.spend > 0) {
        return {
            action: 'DECREASE',
            reason: `Zero sales on £${group.spend.toFixed(2)} spend. Pause or overhaul.`,
            suggestedBudget: Math.max(5, Math.floor(group.dailyBudget * 0.5)),
        };
    }

    return { action: 'MAINTAIN', reason: 'Performance within targets.' };
}

// ─────────────────────────────────────────────────────────────
//  CANDIDATE SUGGESTIONS
// ─────────────────────────────────────────────────────────────

export function findAdCandidates(
    products: Product[],
    salesHistory: PriceLog[],
    existingAdSkus: Set<string>,
    platform: string
): AdCandidate[] {
    // Aggregate last 30 days for this platform
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - 30);
    const cutoffStr = cutoff.toISOString().split('T')[0];

    const skuTotals = new Map<string, { sales: number; units: number }>();
    for (const log of salesHistory) {
        if (log.platform !== platform) continue;
        if (log.date < cutoffStr) continue;
        const existing = skuTotals.get(log.sku) ?? { sales: 0, units: 0 };
        existing.sales += (log.price ?? 0) * (log.velocity ?? 0);
        existing.units += log.velocity ?? 0;
        skuTotals.set(log.sku, existing);
    }

    const totalSales = Array.from(skuTotals.values()).reduce((s, v) => s + v.sales, 0);

    const sorted = Array.from(skuTotals.entries())
        .sort((a, b) => b[1].sales - a[1].sales)
        .slice(0, 100);

    const candidates: AdCandidate[] = [];

    for (let i = 0; i < sorted.length; i++) {
        const [sku, data] = sorted[i];
        const product = products.find(p => p.sku === sku);
        if (!product) continue;

        const grade = product.gradeLevel ?? 0;
        const stock = product.stockLevel ?? 0;
        const runway = product.daysRemaining / 7;

        if (grade < 4 || grade > 7) continue;
        if (stock < 10) continue;

        const salesShare = totalSales > 0 ? data.sales / totalSales : 0;
        const reasons: string[] = [];
        reasons.push(`Top ${i + 1} seller on ${platform} (last 30 days)`);
        reasons.push(`Grade ${grade}`);
        reasons.push(`Stock: ${stock} units (${runway.toFixed(1)}w runway)`);

        const score =
            salesShare * 0.40 +
            Math.min(1, stock / 100) * 0.25 +
            ((grade - 3) / 4) * 0.20 +
            (existingAdSkus.has(sku) ? 0 : 0.15);

        const isAlready = existingAdSkus.has(sku);

        candidates.push({
            sku,
            productName: product.name,
            brand: product.brand ?? '',
            category: product.category ?? '',
            gradeLevel: grade,
            stockQty: stock,
            runway,
            platformSales30d: data.sales,
            platformUnits30d: data.units,
            platformSalesShare: salesShare,
            score,
            reasons,
            isAlreadyInAdGroup: isAlready,
        });
    }

    return candidates.sort((a, b) => b.score - a.score);
}

// ─────────────────────────────────────────────────────────────
//  SNAPSHOT BUILDER
// ─────────────────────────────────────────────────────────────

export function buildSnapshot(
    platform: string,
    campaigns: AdCampaign[],
    dailySkuData: DailySkuRow[],
    weekStartDate: string,
    weekEndDate: string,
    prevSnapshot: AdSnapshot | null,
    products: Product[]
): AdSnapshot {
    // Generate summaries
    const enrichedCampaigns = campaigns.map(campaign => {
        const prevCampaign = prevSnapshot?.campaigns.find(c => c.name === campaign.name) ?? null;

        const adGroups = campaign.adGroups.map(group => {
            const prevGroup = prevCampaign?.adGroups.find(g => g.name === group.name) ?? null;
            const skuSummaries: AdSkuWeeklySummary[] = buildSkuSummaries(
                group.name,
                campaign.name,
                dailySkuData,
                prevSnapshot,
                products
            );

            // Derive memberSkus from detail CSV data
            const groupDetailRows = dailySkuData.filter(
                r => r.adGroup === group.name && r.campaign === campaign.name
            );
            const memberSkus = [...new Set(
                groupDetailRows
                    .map(r => r.mappedSku || r.offerSku)
                    .filter(Boolean)
            )];

            // Aggregate direct metrics from detail CSV (more accurate than summary-level zeros)
            const totalDirectSales = groupDetailRows.reduce((s, r) => s + r.directSales, 0);
            const totalDirectOrders = groupDetailRows.reduce((s, r) => s + r.directOrders, 0);
            const totalDirectConversions = groupDetailRows.reduce((s, r) => s + r.directConversions, 0);
            const directRoas = group.spend > 0 ? totalDirectSales / group.spend : 0;
            const haloEffect = group.sales > 0 ? (group.sales - totalDirectSales) / group.sales : 0;

            const weeklySummary = generateAdGroupSummary(group, prevGroup, skuSummaries);
            return {
                ...group,
                memberSkus,
                weeklySummary,
                directSales: totalDirectSales,
                directOrders: totalDirectOrders,
                directConversions: totalDirectConversions,
                directRoas,
                haloEffect,
            };
        });

        const campaignWithGroups = { ...campaign, adGroups };
        const weeklySummary = generateCampaignSummary(campaignWithGroups, prevCampaign);
        return { ...campaignWithGroups, weeklySummary };
    });

    return {
        id: `adcampaign-${platform}-${weekStartDate}-${Date.now()}`,
        platform,
        weekStartDate,
        weekEndDate,
        importedAt: new Date().toISOString(),
        campaigns: enrichedCampaigns,
        dailySkuData,
    };
}

function buildSkuSummaries(
    adGroupName: string,
    campaignName: string,
    dailySkuData: DailySkuRow[],
    prevSnapshot: AdSnapshot | null,
    products: Product[]
): AdSkuWeeklySummary[] {
    const groupRows = dailySkuData.filter(r => r.adGroup === adGroupName && r.campaign === campaignName);
    const skuMap = new Map<string, DailySkuRow[]>();
    for (const row of groupRows) {
        const key = row.mappedSku || row.offerSku;
        if (!skuMap.has(key)) skuMap.set(key, []);
        skuMap.get(key)!.push(row);
    }

    const totalGroupSpend = groupRows.reduce((s, r) => s + r.spend, 0);
    const groupAvgCtr = (() => {
        const totalImpr = groupRows.reduce((s, r) => s + r.impressions, 0);
        const totalClicks = groupRows.reduce((s, r) => s + r.clicks, 0);
        return totalImpr > 0 ? totalClicks / totalImpr : 0;
    })();
    const groupAvgConvRate = (() => {
        const totalClicks = groupRows.reduce((s, r) => s + r.clicks, 0);
        const totalConv = groupRows.reduce((s, r) => s + r.conversions, 0);
        return totalClicks > 0 ? totalConv / totalClicks : 0;
    })();

    const summaries: AdSkuWeeklySummary[] = [];

    for (const [sku, rows] of skuMap.entries()) {
        const impressions = rows.reduce((s, r) => s + r.impressions, 0);
        const clicks = rows.reduce((s, r) => s + r.clicks, 0);
        const spend = rows.reduce((s, r) => s + r.spend, 0);
        const sales = rows.reduce((s, r) => s + r.sales, 0);
        const orders = rows.reduce((s, r) => s + r.orders, 0);
        const conversions = rows.reduce((s, r) => s + r.conversions, 0);
        const directSales = rows.reduce((s, r) => s + r.directSales, 0);
        const directOrders = rows.reduce((s, r) => s + r.directOrders, 0);
        const directConversions = rows.reduce((s, r) => s + r.directConversions, 0);

        const product = products.find(p => p.sku === sku);
        const roas = spend > 0 ? sales / spend : 0;
        const directRoas = spend > 0 ? directSales / spend : 0;
        const poas = calculatePoas(sku, spend, sales, products);
        const ctr = impressions > 0 ? clicks / impressions : 0;
        const cpc = clicks > 0 ? spend / clicks : 0;
        const spendShare = totalGroupSpend > 0 ? spend / totalGroupSpend : 0;
        const ctrVsGroupAvg = groupAvgCtr > 0 ? ctr / groupAvgCtr : 1;
        const runway = product ? product.daysRemaining / 7 : 0;

        const summary: AdSkuWeeklySummary = {
            sku,
            offerSku: rows[0]?.offerSku ?? sku,
            adGroup: adGroupName,
            campaign: campaignName,
            productName: rows[0]?.productName ?? product?.name ?? sku,
            brand: rows[0]?.brand ?? product?.brand ?? '',
            category: rows[0]?.productCategory ?? product?.category ?? '',
            impressions,
            clicks,
            spend,
            sales,
            orders,
            conversions,
            roas,
            ctr,
            cpc,
            spendShare,
            directSales,
            directOrders,
            directConversions,
            directRoas,
            haloSales: sales - directSales,
            poas,
            gradeLevel: product?.gradeLevel ?? 0,
            stockQty: product?.stockLevel ?? 0,
            runway,
            isLowStock: runway < 4 && (product?.stockLevel ?? 0) < 10,
            prevWeekSales: 0,
            prevWeekSpend: 0,
            prevWeekOrders: 0,
            salesTrend: 'no-data',
            salesDelta: '',
            ordersDelta: '',
            ctrVsGroupAvg,
            weeksInGroup: 1,
            flags: [],
        };

        summary.flags = flagSku(summary, totalGroupSpend, groupAvgCtr, product, []);
        summaries.push(summary);
    }

    return summaries;
}

/**
 * Extracts feature bullet points, specifications, and package contents
 * from structured product description text.
 *
 * Expected format:
 *   [Product Title]
 *   [Description paragraphs]
 *   FEATURES
 *   - FEATURE NAME – Description
 *   SPECIFICATION
 *   Key: Value
 *   PACKAGE CONTENT
 *   1 x Item
 *
 * No AI — pure regex + sentence scoring.
 */

export interface ProductBullets {
    features: string[];
    specs: Record<string, string>;
    packageContent: string[];
}


// Strip characters jsPDF standard fonts cannot encode (CJK, fullwidth brackets, etc.)
// and clean up common CJK bullet/header patterns like 【TITLE】
function sanitiseLine(line: string): string {
    return line
        .replace(/【[^】]*】/g, '')          // remove 【header】 patterns entirely
        .replace(/[^�- -ÿ–—’“”•·]/g, ' ')  // strip non-latin
        .replace(/\s{2,}/g, ' ')              // collapse multiple spaces
        .trim();
}

export function extractProductBullets(content: string): ProductBullets {
    const result: ProductBullets = { features: [], specs: {}, packageContent: [] };
    if (!content || content.length < 20) return result;

    // ── 1. Extract FEATURES section ──
    const featMatch = content.match(
        /FEATURES?\s*[-–]?\s*\n?([\s\S]*?)(?=\n\s*SPECIFICATIONS?|\n\s*PACKAGE|\n\s*WHAT'?S?\s*INCLUDED|$)/i
    );
    if (featMatch) {
        result.features = featMatch[1]
            .split(/\n/)
            .map(line => sanitiseLine(line.replace(/^[-•*]\s*/, '')))
            .filter(line => line.length > 10)
            .map(line => line.length > 120 ? line.slice(0, 117) + '...' : line)
            .slice(0, 5);
    }

    // ── 2. Fallback: sentence scoring if no FEATURES section ──
    if (result.features.length === 0) {
        const descText = content.match(
            /^([\s\S]*?)(?=\n\s*FEATURES?|\n\s*SPECIFICATIONS?|\n\s*PACKAGE|$)/i
        );
        if (descText) {
            result.features = scoreSentences(descText[1], 5);
        }
    }

    // ── 3. Extract SPECIFICATION section ──
    const specMatch = content.match(
        /SPECIFICATIONS?\s*\n?([\s\S]*?)(?=\n\s*PACKAGE|\n\s*WHAT'?S?\s*INCLUDED|$)/i
    );
    if (specMatch) {
        specMatch[1].split(/\n/).forEach(line => {
            const kv = line.match(/^([^:]+):\s*(.+)/);
            if (kv) {
                const key = kv[1].trim();
                const val = kv[2].trim();
                // Skip overly long "Function:" fields — they're descriptions, not specs
                if (key && val && key !== 'Function' && val.length < 200) {
                    result.specs[key] = val;
                }
            }
        });
    }

    // ── 4. Extract PACKAGE CONTENT section ──
    const pkgMatch = content.match(
        /(?:PACKAGE\s*CONTENT|WHAT'?S?\s*INCLUDED)\s*\n?([\s\S]*?)$/i
    );
    if (pkgMatch) {
        result.packageContent = pkgMatch[1]
            .split(/\n/)
            .map(line => line.replace(/<\/?[^>]+>/g, '').replace(/^[-•*]\s*/, '').trim())
            .filter(line => line.length > 3 && !line.startsWith('<'));
    }

    return result;
}

function scoreSentences(text: string, max: number): string[] {
    const sentences = text
        .replace(/\n+/g, ' ')
        .split(/(?<=[.!])\s+/)
        .map(s => s.trim())
        .filter(s => s.length > 30);

    const featureWords = [
        'feature', 'built', 'design', 'provide', 'offer', 'support',
        'adjust', 'sturdy', 'durable', 'comfort', 'storage', 'space',
        'protect', 'easy', 'secure', 'stable', 'portable', 'removable',
        'resistant', 'suitable', 'ideal', 'includes', 'equipped',
        'waterproof', 'breathable', 'foldable', 'lightweight', 'premium'
    ];
    const filler = ['combination of', 'creating a', 'well arranged', 'delivers a', 'making it'];

    const scored = sentences.map((s, idx) => {
        const sl = s.toLowerCase();
        let score = featureWords.filter(w => sl.includes(w)).length;
        if (40 < s.length && s.length < 120) score += 1;
        if (filler.some(f => sl.includes(f))) score -= 3;
        if (idx === 0) score -= 1;
        return { score, text: s };
    });

    return scored
        .sort((a, b) => b.score - a.score)
        .slice(0, max)
        .filter(s => s.score >= 1)
        .map(s => {
            let t = sanitiseLine(s.text.replace(/\.$/, ''));
            if (t.length > 120) {
                const cut = t.slice(0, 120).lastIndexOf(',');
                t = cut > 50 ? t.slice(0, cut) : t.slice(0, 117) + '...';
            }
            return t;
        });
}

import { PriceLog, Product, RefundLog, ReturnDateBasis } from '../types';
import { asDateKey, isDateKeyBetween, addDaysToDateKey, getYesterdayKeyMelbourne, getReturnDateKey as _getReturnDateKey } from './dateUtils';

/**
 * Safely converts a value to a number.
 * @param x - The value to convert.
 * @param defaultValue - The value to return if conversion fails. Defaults to 0.
 * @returns A number.
 */
export const toNumber = (x: any, defaultValue: number = 0): number => {
    if (x === null || x === undefined) return defaultValue;
    const num = Number(x);
    return isNaN(num) ? defaultValue : num;
};

/**
 * Clamps a number between a minimum and maximum value.
 * @param x - The number to clamp.
 * @param min - The minimum value.
 * @param max - The maximum value.
 * @returns The clamped number.
 */
export const clamp = (x: number, min: number, max: number): number => {
    return Math.max(min, Math.min(x, max));
};

/**
 * Safely divides two numbers, returning a fallback value on division by zero.
 * @param numerator - The numerator.
 * @param denominator - The denominator.
 * @param fallback - The value to return if denominator is 0. Defaults to 0.
 * @returns The result of the division or the fallback value.
 */
export const safeDiv = (numerator: number, denominator: number, fallback: number = 0): number => {
    if (denominator === 0) return fallback;
    const result = numerator / denominator;
    return isNaN(result) ? fallback : result;
};


/**
 * Calculates revenue from a transaction log.
 * @param log - The PriceLog object.
 * @returns The calculated revenue.
 */
export const calcRevenue = (log: PriceLog): number => {
    return toNumber(log.price) * toNumber(log.velocity) + toNumber(log.realExtraFreight);
};


/**
 * Extracts the number of units (velocity) from a transaction log.
 * @param log - The PriceLog object.
 * @returns The number of units.
 */
export const calcUnits = (log: PriceLog): number => {
    return toNumber(log.velocity);
};


/**
 * Calculates the ad spend from a transaction log.
 * Ad-only rows (price=0, ad spend > 0) are valid.
 * @param log - The PriceLog object.
 * @returns The ad spend amount.
 */
export const calcAdSpend = (log: PriceLog): number => {
    return toNumber(log.adsSpend);
};

/**
 * Calculates the profit from a transaction log.
 * DEFINITION: This returns Net Profit (After Ads) as per standard system formulas.
 * If the source data is Gross Profit, it should be adjusted before calling this.
 * @param log - The PriceLog object.
 * @returns The calculated net profit.
 */
export const calcProfit = (log: PriceLog): number => {
    if (log.profit !== undefined && log.profit !== null) {
        return toNumber(log.profit);
    }
    const revenue = calcRevenue(log);
    const margin = toNumber(log.margin, 0);
    return revenue * (margin / 100);
};

// --- SUM FUNCTIONS ---

export const sumRevenue = (rows: PriceLog[]): number => {
    return rows.reduce((sum, log) => sum + calcRevenue(log), 0);
};

export const sumQty = (rows: PriceLog[]): number => {
    return rows.reduce((sum, log) => sum + calcUnits(log), 0);
};

export const sumProfit = (rows: PriceLog[]): number => {
    return rows.reduce((sum, log) => sum + calcProfit(log), 0);
};

export const sumAdSpend = (rows: PriceLog[]): number => {
    return rows.reduce((sum, log) => sum + calcAdSpend(log), 0);
};

// --- RATIO FUNCTIONS ---

/**
 * Calculates the margin percentage from revenue and profit. Returns null on invalid division.
 * @param profit - Total profit.
 * @param revenue - Total revenue.
 * @returns The margin percentage or null.
 */
export const marginPct = (profit: number, revenue: number): number | null => {
    if (revenue <= 0) return null;
    const margin = (profit / revenue) * 100;
    return isNaN(margin) ? null : margin;
};

/**
 * Calculates the Total Advertising Cost of Sales (TACoS) percentage. Returns null on invalid division.
 * @param adSpend - Total ad spend.
 * @param revenue - Total revenue.
 * @returns The TACoS percentage or null.
 */
export const tacosPct = (adSpend: number, revenue: number): number | null => {
    if (revenue <= 0) return null;
    const tacos = (adSpend / revenue) * 100;
    return isNaN(tacos) ? null : tacos;
};

/**
 * Calculates the margin percentage from revenue and profit.
 * @param revenue - Total revenue.
 * @param profit - Total profit.
 * @returns The margin percentage.
 */
export const calcMarginPct = (revenue: number, profit: number): number => {
    return safeDiv(profit, revenue) * 100;
};

/**
 * Calculates the Total Advertising Cost of Sales (TACoS) percentage.
 * @param adSpend - Total ad spend.
 * @param revenue - Total revenue.
 * @returns The TACoS percentage. Returns 0 if revenue is 0.
 */
export const calcTACoSPct = (adSpend: number, revenue: number): number => {
    return safeDiv(adSpend, revenue) * 100;
};


// --- COVERAGE HELPERS ---
export const coverageCount = (rows: any[], fieldName: string): { present: number; missing: number; pct: number } => {
    if (rows.length === 0) {
        return { present: 0, missing: 0, pct: 0 };
    }

    let present = 0;
    for (const row of rows) {
        const val = row[fieldName];
        if (val !== undefined && val !== null && !Number.isNaN(val)) {
            present++;
        }
    }

    const total = rows.length;
    const missing = total - present;
    const pct = (present / total) * 100;

    return { present, missing, pct };
}

// --- VELOCITY CALCULATIONS ---

/**
 * Calculates a weighted average daily sales (velocity) based on multiple lookback periods.
 * Formula: (3-day × 10%) + (7-day × 10%) + (15-day × 15%) + (30-day × 25%) + (60-day × 20%) + (90-day × 20%)
 */
export const calculateWeightedVelocity = (skuLogs: PriceLog[]): number => {
    if (!skuLogs || skuLogs.length === 0) return 0;

    const yesterdayKey = getYesterdayKeyMelbourne();

    const calculatePeriodVelocity = (days: number): number => {
        const startKey = addDaysToDateKey(yesterdayKey, -(days - 1));
        const periodLogs = skuLogs.filter(l => {
            const dKey = asDateKey(l.date);
            return dKey && isDateKeyBetween(dKey, startKey, yesterdayKey);
        });
        const totalQty = periodLogs.reduce((sum, l) => sum + toNumber(l.velocity), 0);
        return totalQty / days;
    };

    const v3 = calculatePeriodVelocity(3);
    const v7 = calculatePeriodVelocity(7);
    const v15 = calculatePeriodVelocity(15);
    const v30 = calculatePeriodVelocity(30);
    const v60 = calculatePeriodVelocity(60);
    const v90 = calculatePeriodVelocity(90);

    return (v3 * 0.10) + (v7 * 0.10) + (v15 * 0.15) + (v30 * 0.25) + (v60 * 0.20) + (v90 * 0.20);
};

/**
 * Resolves the final "Average Daily Sales" for a product.
 * PRIORITIZATION RULE: Use ERP Daily Average Sales if it exists and is > 0.
 * Fallback to weighted history otherwise.
 */
export const resolveEffectiveVelocity = (product: Product, skuLogs?: PriceLog[]): number => {
    // 1. Mandatory Primary: ERP Daily Average Sales
    // Check both potential field mappings from the inventory report
    const erpVal = toNumber(product.dailyAverageSales || (product as any).Daily_Average_Sales);

    if (erpVal > 0) {
        return erpVal;
    }

    // 2. Fallback: Weighted Calculation from imported transaction history
    if (skuLogs && skuLogs.length > 0) {
        return calculateWeightedVelocity(skuLogs);
    }

    // 3. Last Resort: Existing value or 0
    return toNumber(product.averageDailySales);
};

export const getReturnDateKey = _getReturnDateKey;

import { normalizeRestoredState } from './restoreSanitizer';
import { getCanonicalSku, isMergeVariant } from './skuNormalization';

/**
 * Centralized migration pipeline for restored database objects.
 * Handles schema versioning and legacy field mapping for Promotions.
 */
export const migrateRestoredDatabase = (data: any): any => {
    if (!data) return data;

    // --- STEP 1: NORMALIZATION ---
    data = normalizeRestoredState(data);

    // --- STEP 2: SKU MERGING (Specific Rule for VM1014 variants) ---
    data = mergeSpecificSkusMigration(data);

    // --- STEP 3: MIGRATION: Promotions Schema ---
    if (data.promotions && Array.isArray(data.promotions)) {
        data.promotions = data.promotions.map((p: any) => {
            const items = p.items?.map((item: any) => {
                const legacyPrice = Number(item.promoPrice || item.discountPrice || 0);
                const isLegacy = !item.discountType ||
                    (item.discountType === 'FIXED' && (item.discountValue === 0 || item.discountValue === undefined));

                if (isLegacy && legacyPrice > 0) {
                    return {
                        ...item,
                        discountType: 'FIXED_PRICE',
                        discountValue: legacyPrice,
                        promoPrice: legacyPrice,
                        basePrice: item.basePrice || 0
                    };
                }

                if (legacyPrice > 0 && (item.promoPrice === 0 || item.promoPrice === undefined)) {
                    return { ...item, promoPrice: legacyPrice };
                }

                return item;
            }) || [];

            return {
                ...p,
                schemaVersion: p.schemaVersion || 2,
                promotionScope: p.promotionScope || 'SKU',
                baselineMode: p.baselineMode || 'CA_PRICE',
                items
            };
        });
    }

    data.skuFamilies = Array.isArray(data.skuFamilies) ? data.skuFamilies : [];

    // --- STEP 4: MIGRATION: AdGroups Schema ---
    if (data.adGroups && Array.isArray(data.adGroups)) {
        const yesterday = new Date();
        yesterday.setDate(yesterday.getDate() - 1);
        const yesterdayStr = yesterday.toISOString().split('T')[0];

        data.adGroups = data.adGroups.map((g: any) => {
            if (Object.prototype.hasOwnProperty.call(g, 'isActive')) {
                const migrated = {
                    ...g,
                    startDate: g.startDate || '2020-01-01',
                    endDate: g.isActive ? g.endDate : (g.endDate || yesterdayStr)
                };
                delete migrated.isActive;
                return migrated;
            }
            return g;
        });
    } else {
        data.adGroups = [];
    }

    return data;
};

/**
 * Internal helper to merge specific variant SKUs into their canonical form in a restored database.
 */
function mergeSpecificSkusMigration(data: any): any {
    const products = Array.isArray(data.products) ? [...data.products] : [];

    // 1. Identify and consolidate product entries
    const mergedProductsMap = new Map<string, any>();
    const variantsToRemove = new Set<string>();

    products.forEach(p => {
        const canonical = getCanonicalSku(p.sku);
        if (canonical !== p.sku) {
            variantsToRemove.add(p.sku);
        }

        if (!mergedProductsMap.has(canonical)) {
            mergedProductsMap.set(canonical, { ...p, sku: canonical });
        } else {
            // MERGE LOGIC
            const existing = mergedProductsMap.get(canonical);

            // Sum stock and incoming
            existing.stockLevel = (Number(existing.stockLevel) || 0) + (Number(p.stockLevel) || 0);
            existing.incomingStock = (Number(existing.incomingStock) || 0) + (Number(p.incomingStock) || 0);

            // Combine shipments
            if (p.shipments) {
                existing.shipments = [...(existing.shipments || []), ...p.shipments];
            }

            // Combine channels (aliases)
            if (p.channels) {
                const existingChannels = existing.channels || [];
                p.channels.forEach((newChan: any) => {
                    const match = existingChannels.find((ec: any) => ec.platform === newChan.platform);
                    if (match) {
                        const aliases = new Set([
                            ...(match.skuAlias || '').split(',').map((s: string) => s.trim()),
                            ...(newChan.skuAlias || '').split(',').map((s: string) => s.trim()),
                            p.sku // Add the variant SKU itself as an alias
                        ].filter(Boolean));
                        match.skuAlias = Array.from(aliases).join(', ');
                    } else {
                        existingChannels.push({ ...newChan });
                    }
                });
                existing.channels = existingChannels;
            }
        }
    });

    data.products = Array.from(mergedProductsMap.values());

    // 2. Normalize all history references
    const normalizeList = (list: any[]) => {
        if (!Array.isArray(list)) return list;
        return list.map(item => {
            if (item && item.sku) {
                return { ...item, sku: getCanonicalSku(item.sku) };
            }
            return item;
        });
    };

    data.priceHistory = normalizeList(data.priceHistory);
    data.refundHistory = normalizeList(data.refundHistory);
    data.priceChangeHistory = normalizeList(data.priceChangeHistory);
    data.costChangeHistory = normalizeList(data.costChangeHistory);
    data.inventoryChangeHistory = normalizeList(data.inventoryChangeHistory);

    if (data.promotions) {
        data.promotions = data.promotions.map((promo: any) => ({
            ...promo,
            items: Array.isArray(promo.items) ? promo.items.map((it: any) => ({
                ...it,
                sku: getCanonicalSku(it.sku)
            })) : []
        }));
    }

    return data;
}

export const auditRestoredDatabase = (data: any): { hasFatal: boolean; issues: any[] } => {
    const issues: Array<{ path: string; expected: string; actual: string; sample?: any }> = [];

    const checkArray = (path: string, val: any) => {
        if (!Array.isArray(val)) {
            issues.push({ path, expected: 'Array', actual: typeof val, sample: val });
        }
    };

    if (!data || typeof data !== 'object') {
        return { hasFatal: true, issues: [{ path: 'root', expected: 'Object', actual: typeof data }] };
    }

    checkArray('products', data.products);
    if (Array.isArray(data.products)) {
        data.products.slice(0, 30).forEach((p: any, i: number) => {
            if (!p) return;
            checkArray(`products[${i}].channels`, p.channels);
            if (p.shipments !== undefined && p.shipments !== null) {
                checkArray(`products[${i}].shipments`, p.shipments);
            }
        });
    }

    checkArray('promotions', data.promotions);
    if (Array.isArray(data.promotions)) {
        data.promotions.slice(0, 30).forEach((p: any, i: number) => {
            if (!p) return;
            checkArray(`promotions[${i}].items`, p.items);
            if (Array.isArray(p.items)) {
                p.items.forEach((item: any, j: number) => {
                    if (item && !item.sku) {
                        issues.push({ path: `promotions[${i}].items[${j}].sku`, expected: 'String', actual: typeof item?.sku });
                    }
                });
            }
        });
    }

    checkArray('priceHistory', data.priceHistory);
    checkArray('refundHistory', data.refundHistory);
    checkArray('shipmentHistory', data.shipmentHistory);
    checkArray('priceChangeHistory', data.priceChangeHistory);
    checkArray('costChangeHistory', data.costChangeHistory);
    checkArray('inventoryChangeHistory', data.inventoryChangeHistory);
    checkArray('skuFamilies', data.skuFamilies);
    checkArray('adGroups', data.adGroups);

    return { hasFatal: issues.length > 0, issues };
};

import { PriceLog, RefundLog, ReturnDateBasis } from '../types';
import { calcRevenue, calcProfit, calcUnits, calcAdSpend, getReturnDateKey } from './metrics';
import { asDateKey, isDateKeyBetween, addDaysToDateKey } from './dateUtils';
import { scaleMoneyInclTax } from './taxPolicy';
import { VAT_MULTIPLIER } from '../constants';

export interface PlatformTrendMetrics {
  revenue: number;
  netProfit: number; // Final bottom line
  unitsSold: number;
  orders: number;
  adSpend: number;
  refundValue: number;
  avgOrderValue: number;
  marginPct: number;
  tacosPct: number;
  refundRatePct: number;
}

export interface PlatformTrendData {
  platform: string;
  current: PlatformTrendMetrics;
  prior: PlatformTrendMetrics;
  deltas: {
    revenueDeltaPct: number | null;
    netProfitDeltaPct: number | null;
    ordersDeltaPct: number | null;
    unitsDeltaPct: number | null;
    marginDeltaPp: number;
    tacosDeltaPp: number;
    refundRateDeltaPp: number;
    avgOrderValueDeltaPct: number | null;
  };
}

interface RawBucket {
  revenue: number;
  netProfit: number; // calcProfit result (already Net After Ads)
  adSpend: number;
  refundValue: number;
  units: number;
  orderIds: Set<string>;
  nonOrderCount: number;
  adRowsCount: number;
}

const createRawBucket = (): RawBucket => ({
  revenue: 0,
  netProfit: 0,
  adSpend: 0,
  refundValue: 0,
  units: 0,
  orderIds: new Set(),
  nonOrderCount: 0,
  adRowsCount: 0
});

/**
 * Aggregates platform performance for a selected date window vs the immediate prior window of the same length.
 * All monetary outputs are Tax Inclusive.
 */
export const aggregatePlatformTrends = (
  priceLogs: PriceLog[],
  dateRange: { startKey: string; endKey: string },
  platforms: string[],
  refundHistory: RefundLog[] = [],
  deductRefunds: boolean = false,
  dateBasis: ReturnDateBasis = 'refundDate',
  orderDateMap?: Map<string, string>
): PlatformTrendData[] => {
  const { startKey, endKey } = dateRange;

  // Calculate duration
  const startDate = new Date(startKey);
  const endDate = new Date(endKey);
  const diffTime = endDate.getTime() - startDate.getTime();
  const durationDays = Math.round(diffTime / (1000 * 60 * 60 * 24)) + 1;

  // Calculate prior window
  const prevEndKey = addDaysToDateKey(startKey, -1);
  const prevStartKey = addDaysToDateKey(prevEndKey, -(durationDays - 1));

  // Initialize buckets
  const buckets: Record<string, { current: RawBucket; prior: RawBucket }> = {};
  platforms.forEach(p => {
    buckets[p] = { current: createRawBucket(), prior: createRawBucket() };
  });

  // Include an 'Unknown' bucket just in case
  buckets['Unknown'] = { current: createRawBucket(), prior: createRawBucket() };

  // 1. Aggregate Transaction Logs
  for (const log of priceLogs) {
    const logDateKey = asDateKey(log.date);
    if (!logDateKey) continue;

    const platform = (log.platform && buckets[log.platform]) ? log.platform : 'Unknown';
    const bucketPair = buckets[platform];

    const isCurrent = isDateKeyBetween(logDateKey, startKey, endKey);
    const isPrior = isDateKeyBetween(logDateKey, prevStartKey, prevEndKey);

    if (!isCurrent && !isPrior) continue;

    const targetBucket = isCurrent ? bucketPair.current : bucketPair.prior;

    // Accumulate Raw Metrics
    targetBucket.revenue += calcRevenue(log);
    targetBucket.netProfit += calcProfit(log); // calcProfit is Net After Ads
    targetBucket.adSpend += calcAdSpend(log);
    targetBucket.units += calcUnits(log);

    if (log.adsSpend !== undefined && log.adsSpend !== null) {
      targetBucket.adRowsCount++;
    }

    if (log.orderId) {
      targetBucket.orderIds.add(log.orderId);
    } else {
      targetBucket.nonOrderCount++;
    }
  }

  // 2. Process Refund Deductions
  for (const r of refundHistory) {
    const refundDateKey = getReturnDateKey(r, dateBasis, orderDateMap);
    if (!refundDateKey) continue;

    const isCurrent = isDateKeyBetween(refundDateKey, startKey, endKey);
    const isPrior = isDateKeyBetween(refundDateKey, prevStartKey, prevEndKey);

    if (!isCurrent && !isPrior) continue;

    const platform = (r.platform && buckets[r.platform]) ? r.platform : 'Unknown';
    const bucketPair = buckets[platform];
    const targetBucket = isCurrent ? bucketPair.current : bucketPair.prior;

    const refundVal = (Number(r.amount) + Number(r.freightAmount || 0));
    targetBucket.refundValue += refundVal;

    if (deductRefunds) {
      targetBucket.netProfit -= refundVal;
    }
  }

  // 3. Transform to Final Output
  return platforms.map(platform => {
    const raw = buckets[platform] || { current: createRawBucket(), prior: createRawBucket() };

    const processMetrics = (b: RawBucket): PlatformTrendMetrics => {
      // Scale Money to Tax Inclusive
      const revenue = scaleMoneyInclTax(b.revenue);
      const netProfit = scaleMoneyInclTax(b.netProfit);
      const adSpend = scaleMoneyInclTax(b.adSpend);
      const refundValue = scaleMoneyInclTax(b.refundValue);
      const orders = b.orderIds.size + b.nonOrderCount;

      return {
        revenue,
        netProfit,
        adSpend,
        refundValue,
        unitsSold: b.units,
        orders,
        avgOrderValue: orders > 0 ? (revenue / orders) : 0,
        marginPct: revenue > 0 ? (netProfit / revenue) * 100 : 0,
        tacosPct: revenue > 0 ? (adSpend / revenue) * 100 : 0,
        refundRatePct: revenue > 0 ? (refundValue / revenue) * 100 : 0
      };
    };

    const current = processMetrics(raw.current);
    const prior = processMetrics(raw.prior);

    // Deltas
    const calcDeltaPct = (curr: number, prev: number): number | null => {
      if (prev === 0) return curr === 0 ? 0 : null; // null indicates new or undefined growth
      return ((curr - prev) / Math.abs(prev)) * 100;
    };

    return {
      platform,
      current,
      prior,
      deltas: {
        revenueDeltaPct: calcDeltaPct(current.revenue, prior.revenue),
        netProfitDeltaPct: calcDeltaPct(current.netProfit, prior.netProfit),
        ordersDeltaPct: calcDeltaPct(current.orders, prior.orders),
        unitsDeltaPct: calcDeltaPct(current.unitsSold, prior.unitsSold),
        marginDeltaPp: current.marginPct - prior.marginPct,
        tacosDeltaPp: current.tacosPct - prior.tacosPct,
        refundRateDeltaPp: current.refundRatePct - prior.refundRatePct,
        avgOrderValueDeltaPct: calcDeltaPct(current.avgOrderValue, prior.avgOrderValue)
      }
    };
  });
};

import { PriceLog, RefundLog, Product, ReturnDateBasis } from '../types';
import { calcRevenue, calcProfit, calcUnits, calcAdSpend, getReturnDateKey } from './metrics';
import { asDateKey, isDateKeyBetween, addDaysToDateKey } from './dateUtils';
import { scaleMoneyInclTax } from './taxPolicy';
import { VAT_MULTIPLIER } from '../constants';

export interface ProductTrendMetrics {
  revenue: number;
  netProfit: number;
  unitsSold: number;
  adSpend: number;
  refundValue: number;
  marginPct: number;
  tacosPct: number | null;
  refundRatePct: number;
}

export interface ProductTrendData {
  sku: string;
  name: string;
  category: string;
  gradeLevel?: number;
  current: ProductTrendMetrics;
  prior: ProductTrendMetrics;
  deltas: {
    revenueDeltaPct: number | null;
    netProfitDeltaPct: number | null;
    unitsDeltaPct: number | null;
    marginDeltaPp: number;
    tacosDeltaPp: number | null;
    refundRateDeltaPp: number;
  };
}

interface RawBucket {
  revenue: number;
  netProfit: number;
  adSpend: number;
  refundValue: number;
  units: number;
  adRowsCount: number;
}

const createRawBucket = (): RawBucket => ({
  revenue: 0,
  netProfit: 0,
  adSpend: 0,
  refundValue: 0,
  units: 0,
  adRowsCount: 0
});

/**
 * Aggregates SKU-level performance for a selected date window vs the prior window.
 */
export const aggregateProductTrends = (
  products: Product[],
  priceLogs: PriceLog[],
  dateRange: { startKey: string; endKey: string },
  refundHistory: RefundLog[] = [],
  deductRefunds: boolean = false,
  dateBasis: ReturnDateBasis = 'refundDate',
  orderDateMap?: Map<string, string>
): ProductTrendData[] => {
  const { startKey, endKey } = dateRange;

  const startDate = new Date(startKey);
  const endDate = new Date(endKey);
  const diffTime = endDate.getTime() - startDate.getTime();
  const durationDays = Math.round(diffTime / (1000 * 60 * 60 * 24)) + 1;

  const prevEndKey = addDaysToDateKey(startKey, -1);
  const prevStartKey = addDaysToDateKey(prevEndKey, -(durationDays - 1));

  const buckets: Record<string, { current: RawBucket; prior: RawBucket }> = {};
  const skuInfoMap = new Map<string, Product>();

  products.forEach(p => {
    buckets[p.sku] = { current: createRawBucket(), prior: createRawBucket() };
    skuInfoMap.set(p.sku, p);
  });

  // 1. Transaction Aggregation
  for (const log of priceLogs) {
    const logDateKey = asDateKey(log.date);
    if (!logDateKey || !buckets[log.sku]) continue;

    const bucketPair = buckets[log.sku];
    const isCurrent = isDateKeyBetween(logDateKey, startKey, endKey);
    const isPrior = isDateKeyBetween(logDateKey, prevStartKey, prevEndKey);

    if (!isCurrent && !isPrior) continue;

    const target = isCurrent ? bucketPair.current : bucketPair.prior;
    const p = skuInfoMap.get(log.sku);

    target.revenue += calcRevenue(log);
    target.netProfit += calcProfit(log);
    target.units += calcUnits(log);

    const ads = log.adsSpend !== undefined ? log.adsSpend : (p?.adsFee || 0) * log.velocity;
    target.adSpend += ads;
    if (log.adsSpend !== undefined) target.adRowsCount++;
  }

  // 2. Refund Deductions
  for (const r of refundHistory) {
    const refundDateKey = getReturnDateKey(r, dateBasis, orderDateMap);
    if (!refundDateKey || !buckets[r.sku]) continue;

    const isCurrent = isDateKeyBetween(refundDateKey, startKey, endKey);
    const isPrior = isDateKeyBetween(refundDateKey, prevStartKey, prevEndKey);

    if (!isCurrent && !isPrior) continue;

    const target = isCurrent ? buckets[r.sku].current : buckets[r.sku].prior;
    const refundVal = (Number(r.amount) + Number(r.freightAmount || 0));
    target.refundValue += refundVal;

    if (deductRefunds) {
      target.netProfit -= refundVal;
    }
  }

  // 3. Transform
  return products.map(p => {
    const raw = buckets[p.sku];

    const process = (b: RawBucket): ProductTrendMetrics => {
      const revenue = scaleMoneyInclTax(b.revenue);
      const netProfit = scaleMoneyInclTax(b.netProfit);
      const adSpend = scaleMoneyInclTax(b.adSpend);
      const refundValue = scaleMoneyInclTax(b.refundValue);

      return {
        revenue,
        netProfit,
        adSpend,
        refundValue,
        unitsSold: b.units,
        marginPct: revenue > 0 ? (netProfit / revenue) * 100 : 0,
        tacosPct: (revenue > 0 && b.adRowsCount > 0) ? (adSpend / revenue) * 100 : null,
        refundRatePct: revenue > 0 ? (refundValue / revenue) * 100 : 0
      };
    };

    const current = process(raw.current);
    const prior = process(raw.prior);

    const calcDeltaPct = (curr: number, prev: number): number | null => {
      if (prev === 0) return curr === 0 ? 0 : null;
      return ((curr - prev) / Math.abs(prev)) * 100;
    };

    const tacosDelta = (current.tacosPct !== null && prior.tacosPct !== null) 
      ? current.tacosPct - prior.tacosPct 
      : null;

    return {
      sku: p.sku,
      name: p.name,
      category: p.category || 'Uncategorized',
      gradeLevel: p.gradeLevel,
      current,
      prior,
      deltas: {
        revenueDeltaPct: calcDeltaPct(current.revenue, prior.revenue),
        netProfitDeltaPct: calcDeltaPct(current.netProfit, prior.netProfit),
        unitsDeltaPct: calcDeltaPct(current.unitsSold, prior.unitsSold),
        marginDeltaPp: current.marginPct - prior.marginPct,
        tacosDeltaPp: tacosDelta,
        refundRateDeltaPp: current.refundRatePct - prior.refundRatePct
      }
    };
  });
};

import { RefundLog, ReturnDateBasis } from '../types';
import { asDateKey, getReturnDateKey } from './dateUtils';
import { VAT_MULTIPLIER } from '../constants';

export interface RefundAggregationOptions {
  salesMap?: Map<string, number>; // SKU -> Unit Sales Count
  revenueMap?: Map<string, number>; // SKU -> Revenue Amount
  productMap?: Map<string, { name: string }>; // SKU -> Product Info
  dateBasis?: ReturnDateBasis; // Mode for date attribution
  orderDateMap?: Map<string, string>; // Lookup for original order dates
}

export interface RefundSkuRow {
  sku: string;
  title: string;
  platform: string;
  refundCount: number;
  refundQty: number; // Sum of physical units
  refundValue: number; // Total Value (Item + Freight) Inc VAT
  itemValue: number; // Item Only Value Inc VAT
  freightValue: number; // Freight Only Value Inc VAT
  logisticsFeeValue: number;
  topReasons: { reason: string; count: number }[];
  refundRate: number | null; // %
  refundRateValue: number | null;
  flags: string[];
}

export interface RefundReasonRow {
  reason: string;
  count: number;
  value: number;
}

export interface RefundTimelineBucket {
  date: string;
  count: number;
  value: number;
}

export interface RefundOverview {
  kpis: {
    totalRefundCount: number;
    totalRefundQty: number;
    totalRefundValue: number;
    totalLogisticsFees: number;
    refundRateQty: number | null;
    refundRateValue: number | null;
  };
  skuRows: RefundSkuRow[];
  reasonRows: RefundReasonRow[];
  timeline: RefundTimelineBucket[];
  meta: {
    columnsUsed: string[];
  };
}

export const buildRefundOverview = (
  refundRows: RefundLog[],
  opts: RefundAggregationOptions = {}
): RefundOverview => {
  const kpis = {
    totalRefundCount: 0,
    totalRefundQty: 0,
    totalRefundValue: 0,
    totalLogisticsFees: 0,
    refundRateQty: null as number | null,
    refundRateValue: null as number | null,
  };

  const skuMap = new Map<string, {
    count: number;
    qty: number;
    value: number;
    itemVal: number;
    freight: number;
    logistics: number;
    reasons: Map<string, number>;
    platform: string;
    timestamps: number[];
  }>();

  const reasonMap = new Map<string, { count: number; value: number }>();
  const timelineMap = new Map<string, { count: number; value: number }>();

  // Track which optional fields we actually encountered
  const columnsSeen = new Set<string>(['sku', 'amount', 'date', 'quantity']);

  for (const row of refundRows) {
    // --- Global KPI Aggregation ---
    kpis.totalRefundCount += 1;

    // Amounts stored Ex-VAT. Scale to Inc-VAT for display.
    const amountExVat = Number(row.amount) || 0;
    const freightExVat = Number(row.freightAmount) || 0;

    const itemIncVat = amountExVat * VAT_MULTIPLIER;
    const freightIncVat = freightExVat * VAT_MULTIPLIER;
    const totalIncVat = itemIncVat + freightIncVat;

    const quantity = Number(row.quantity) || 1;

    kpis.totalRefundValue += totalIncVat;
    kpis.totalRefundQty += quantity;

    // Metadata tracking
    if (row.platform) columnsSeen.add('platform');
    if (row.orderId) columnsSeen.add('orderId');
    if (row.reason) columnsSeen.add('reason');
    if (row.orderType) columnsSeen.add('type');
    if (row.customerReason) columnsSeen.add('customerReason');

    // --- SKU Aggregation ---
    const sku = row.sku || 'Unknown';
    if (!skuMap.has(sku)) {
      skuMap.set(sku, {
        count: 0,
        qty: 0,
        value: 0,
        itemVal: 0,
        freight: 0,
        logistics: 0,
        reasons: new Map(),
        platform: row.platform || 'Unknown',
        timestamps: []
      });
    }
    const entry = skuMap.get(sku)!;
    entry.count += 1;
    entry.qty += quantity;
    entry.value += totalIncVat;
    entry.itemVal += itemIncVat;
    entry.freight += freightIncVat;

    // --- Timeline Aggregation ---
    const dateBasis = opts.dateBasis || 'refundDate';
    const dateKey = getReturnDateKey(row, dateBasis, opts.orderDateMap);
    if (dateKey) {
      const ts = new Date(dateKey).getTime();
      if (!isNaN(ts)) {
        entry.timestamps.push(ts);

        if (!timelineMap.has(dateKey)) {
          timelineMap.set(dateKey, { count: 0, value: 0 });
        }
        const tBucket = timelineMap.get(dateKey)!;
        tBucket.count += 1;
        tBucket.value += totalIncVat;
      }
    }

    // --- Reason Aggregation ---
    // Priority: reason -> customerReason -> platformReason -> 'Unknown'
    const reason = row.reason || row.customerReason || row.platformReason || 'Unknown';

    entry.reasons.set(reason, (entry.reasons.get(reason) || 0) + 1);

    if (!reasonMap.has(reason)) {
      reasonMap.set(reason, { count: 0, value: 0 });
    }
    const rBucket = reasonMap.get(reason)!;
    rBucket.count += 1;
    rBucket.value += totalIncVat;
  }

  // --- Finalize SKU Rows ---
  const skuRows: RefundSkuRow[] = [];

  skuMap.forEach((data, sku) => {
    // Top 3 Reasons
    const topReasons = Array.from(data.reasons.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3)
      .map(([r, c]) => ({ reason: r, count: c }));

    // Flags Computation
    const flags: string[] = [];

    // 1. High Cost
    if (data.value > 300) flags.push("High Cost");

    // 2. Rising Trend (Simple)
    if (data.timestamps.length >= 2) {
      data.timestamps.sort((a, b) => a - b);
      const minT = data.timestamps[0];
      const maxT = data.timestamps[data.timestamps.length - 1];
      const span = maxT - minT;
      if (span > 0) {
        const mid = minT + (span / 2);
        const firstHalf = data.timestamps.filter(t => t < mid).length;
        const secondHalf = data.timestamps.filter(t => t >= mid).length;
        if (secondHalf > (firstHalf * 1.5) && secondHalf > 2) {
          flags.push("Rising Trend");
        }
      }
    }

    // 3. Refund Rate
    let refundRate: number | null = null;
    let refundRateValue: number | null = null;
    if (opts.salesMap && opts.salesMap.has(sku)) {
      const sales = opts.salesMap.get(sku) || 0;
      if (sales > 0) {
        refundRate = (data.qty / sales) * 100;
        if (refundRate > 10) flags.push("High Rate");
      }
    }
    if (opts.revenueMap && opts.revenueMap.has(sku)) {
        const revenue = opts.revenueMap.get(sku) || 0;
        if (revenue > 0) {
            refundRateValue = (data.value / revenue) * 100;
        }
    }

    // Title resolution
    let title = sku;
    if (opts.productMap && opts.productMap.has(sku)) {
      title = opts.productMap.get(sku)!.name;
    }

    skuRows.push({
      sku,
      title,
      platform: data.platform,
      refundCount: data.count,
      refundQty: data.qty,
      refundValue: data.value,
      itemValue: data.itemVal,
      freightValue: data.freight,
      logisticsFeeValue: data.logistics,
      topReasons,
      refundRate,
      refundRateValue,
      flags
    });
  });

  // --- Finalize Global KPIs ---
  if (opts.salesMap) {
    let totalUnitsSold = 0;
    for (const val of opts.salesMap.values()) totalUnitsSold += val;
    if (totalUnitsSold > 0) {
      kpis.refundRateQty = (kpis.totalRefundQty / totalUnitsSold) * 100;
    }
  }

  if (opts.revenueMap) {
    let totalRevenueSold = 0;
    for (const val of opts.revenueMap.values()) totalRevenueSold += val;
    if (totalRevenueSold > 0) {
      kpis.refundRateValue = (kpis.totalRefundValue / totalRevenueSold) * 100;
    }
  }

  // --- Sort Outputs ---
  const sortedSkuRows = skuRows.sort((a, b) => b.refundValue - a.refundValue);
  const sortedReasonRows = Array.from(reasonMap.entries())
    .map(([r, d]) => ({ reason: r, ...d }))
    .sort((a, b) => b.count - a.count);
  const sortedTimeline = Array.from(timelineMap.entries())
    .map(([d, val]) => ({ date: d, ...val }))
    .sort((a, b) => a.date.localeCompare(b.date));

  return {
    kpis,
    skuRows: sortedSkuRows,
    reasonRows: sortedReasonRows,
    timeline: sortedTimeline,
    meta: {
      columnsUsed: Array.from(columnsSeen)
    }
  };
};

import { Product, PriceLog, PricingRules, RefundLog } from '../types';
import { SearchIntent } from './searchIntentService';
import { isAdsEnabled } from './platformCapabilities';
import { scaleMoneyInclTax } from './taxPolicy';
import { VAT_MULTIPLIER } from '../constants';
import { getCanonicalSku } from './skuNormalization';

export const safeCalculateMargin = (p: Product | undefined, price: number): number => {
    if (!p || !price || isNaN(price)) return 0;
    const totalCost = (Number(p.costPrice) || 0) +
        (Number(p.sellingFee) || 0) +
        (Number(p.adsFee) || 0) +
        (Number(p.postage) || 0) +
        (Number(p.otherFee) || 0) +
        (Number(p.subscriptionFee) || 0) +
        (Number(p.wmsFee) || 0);

    const totalIncome = price + (Number(p.extraFreight) || 0);
    const netProfit = totalIncome - totalCost;
    const margin = price > 0 ? (netProfit / price) * 100 : 0;
    return isNaN(margin) ? 0 : margin;
};

const isMissingFilterValue = (value: unknown): boolean => {
    return value === undefined || value === null || (typeof value === 'number' && Number.isNaN(value));
};

export const processDataForSearch = (intent: SearchIntent, products: Product[], priceHistory: PriceLog[], pricingRules: PricingRules, refundHistory: RefundLog[]) => {
    
    // Guard against undefined inputs
    const safeProducts = products || [];
    const safePriceHistory = priceHistory || [];
    const safeRefundHistory = refundHistory || [];
    const safePricingRules = pricingRules || {};

    // --- DEEP DIVE HANDLER ---
    if (intent.primaryMetric === 'DEEP_DIVE') {
        const skuQuery = String(intent.filters[0].value).trim().toLowerCase();
        // Case-insensitive exact match
        const product = safeProducts.find(p => p.sku.toLowerCase() === skuQuery);
        
        if (product) {
            let allTimeSales = 0;
            let allTimeQty = 0;
            const transactions: PriceLog[] = [];
            const targetMasterSku = product.sku.toUpperCase();
            
            safePriceHistory.forEach(l => {
                // Use Canonical Mapping to catch variant sales (e.g. -A-UK, -B-UK)
                if (getCanonicalSku(l.sku).toUpperCase() === targetMasterSku) {
                    allTimeSales += (l.price * l.velocity);
                    allTimeQty += l.velocity;
                    transactions.push(l);
                }
            });

            // Use Canonical Mapping to catch variant refunds
            const productRefunds = safeRefundHistory.filter(r => 
                getCanonicalSku(r.sku).toUpperCase() === targetMasterSku
            );

            return {
                results: [{
                    type: 'DEEP_DIVE',
                    product,
                    allTimeSales: scaleMoneyInclTax(allTimeSales), // Scale Global Total for summary
                    allTimeQty,
                    // Keep transactions and refunds Ex-VAT (raw)
                    // The SkuDeepDive component applies its own VAT multiplier for analysis
                    transactions, 
                    refunds: productRefunds
                }],
                timeLabel: 'All Time',
                resultMeta: { moneyIsTaxInclusive: true, vatMultiplierUsed: VAT_MULTIPLIER }
            };
        }
        // Fallback if not found, return empty or standard search
        return { results: [], timeLabel: 'All Time' };
    }

    const productMap = new Map(safeProducts.map(p => [p.sku, p]));
    
    if (intent.targetData === 'refunds') {
        const results: any[] = [];
        safeRefundHistory.forEach(r => {
            const p = productMap.get(getCanonicalSku(r.sku));
            results.push({ 
                sku: r.sku, 
                productName: p?.name || 'Unknown', 
                platform: r.platform || 'Unknown', 
                date: r.date, 
                price: -scaleMoneyInclTax(r.amount), // Scale Refund Amount (Negative Price for display)
                velocity: r.quantity, 
                margin: -100, 
                type: 'REFUND' 
            });
        });
        return { results, timeLabel: 'All Refunds', resultMeta: { moneyIsTaxInclusive: true, vatMultiplierUsed: VAT_MULTIPLIER } };
    }

    if (intent.targetData === 'inventory') {
        const results: any[] = [];
        safeProducts.forEach(p => {
            const agedStockPct = p.stockLevel > 0 && p.agedStockQty ? (p.agedStockQty / p.stockLevel) * 100 : 0;
            const derivedMetrics: any = { 
                daysRemaining: p.averageDailySales > 0 ? p.stockLevel / p.averageDailySales : 999, 
                velocityChange: p.previousDailySales && p.previousDailySales > 0 ? ((p.averageDailySales - p.previousDailySales) / p.previousDailySales) * 100 : 0,
                agedStockPct: agedStockPct
            };
            const pass = intent.filters.every(f => {
                let val = (p as any)[f.field];
                if (val === undefined) val = derivedMetrics[f.field];
                const criteria = Number(f.value) || f.value;
                if (f.field === 'name' && f.operator === 'CONTAINS') {
                    const strCriteria = String(f.value).toLowerCase();
                    const nameMatch = p.name.toLowerCase().includes(strCriteria);
                    const skuMatch = p.sku.toLowerCase().includes(strCriteria);
                    const aliasMatch = p.channels.some(c => c.skuAlias && c.skuAlias.toLowerCase().includes(strCriteria));
                    return nameMatch || skuMatch || aliasMatch;
                }
                if (isMissingFilterValue(val)) {
                    return true;
                }
                if (f.operator === 'CONTAINS') return String(val).toLowerCase().includes(String(criteria).toLowerCase());
                if (f.operator === '=') return String(val).toLowerCase() === String(criteria).toLowerCase();
                if (f.operator === '>') return val > criteria;
                if (f.operator === '<') return val < criteria;
                if (f.operator === '>=') return val >= criteria;
                if (f.operator === '<=') return val <= criteria;
                return val == criteria;
            });
            if (!pass) return;
            results.push({ 
                sku: p.sku, 
                productName: p.name, 
                platform: p.channels.length > 0 ? p.channels[0].platform : 'General', 
                channels: p.channels,
                date: new Date().toISOString(), 
                price: scaleMoneyInclTax(p.currentPrice), // Scale Price
                velocity: p.stockLevel, 
                revenue: scaleMoneyInclTax(p.stockLevel * p.currentPrice), // Scale Revenue Value
                margin: safeCalculateMargin(p, p.currentPrice), // Margin % stays same
                stockLevel: p.stockLevel, 
                agedStockQty: p.agedStockQty,
                agedStockPct: derivedMetrics.agedStockPct,
                averageDailySales: p.averageDailySales, 
                daysRemaining: derivedMetrics.daysRemaining, 
                velocityChange: derivedMetrics.velocityChange, 
                type: 'INVENTORY' 
            });
        });
        if (intent.sort) {
            results.sort((a, b) => {
                const field = intent.sort!.field;
                const valA = a[field] || 0;
                const valB = b[field] || 0;
                return intent.sort!.direction === 'asc' ? valA - valB : valB - valA;
            });
        }
        if (intent.limit && intent.limit > 0) { return { results: results.slice(0, intent.limit), timeLabel: 'Current Snapshot', resultMeta: { moneyIsTaxInclusive: true, vatMultiplierUsed: VAT_MULTIPLIER } }; }
        return { results, timeLabel: 'Current Snapshot', resultMeta: { moneyIsTaxInclusive: true, vatMultiplierUsed: VAT_MULTIPLIER } };
    }

    let startTime = 0; let endTime = Number.MAX_SAFE_INTEGER; let timeLabel = "All Time";
    if (intent.timeRange) {
        const now = new Date();
        if (intent.timeRange.type === 'relative' && intent.timeRange.value.endsWith('d')) { const days = parseInt(intent.timeRange.value); const start = new Date(); start.setDate(now.getDate() - days); startTime = start.getTime(); endTime = now.getTime(); timeLabel = `Last ${days} Days`; } 
        else if (intent.timeRange.type === 'absolute') { const val = intent.timeRange.value; const date = new Date(val); if (!isNaN(date.getTime())) { startTime = date.getTime(); timeLabel = `Since ${val}`; } }
    } else { const start = new Date(); start.setDate(start.getDate() - 30); startTime = start.getTime(); endTime = Date.now(); timeLabel = "Last 30 Days (Default)"; }

    // --- TREND ANALYSIS: PREVIOUS PERIOD CALCULATION ---
    let prevStartTime = 0;
    let prevEndTime = 0;
    if (startTime > 0 && endTime < Number.MAX_SAFE_INTEGER) {
        const duration = endTime - startTime;
        prevEndTime = startTime; // Ends where current starts
        prevStartTime = startTime - duration; // Shift back by duration
    }

    const skuPeriodStats = new Map<string, { 
        revenue: number, refunds: number, organicQty: number, adEnabledQty: number,
        // New Trend Fields
        qty: number, prevRevenue: number, prevQty: number, prevProfit: number
    }>();
    
    // Pass 1: Aggregate stats for Refund Rate, Organic Share, and Trend comparison
    safeRefundHistory.forEach(r => {
        const rTime = new Date(r.date).getTime();
        if (rTime >= startTime && rTime <= endTime) {
            const canonicalSku = getCanonicalSku(r.sku);
            if (!skuPeriodStats.has(canonicalSku)) skuPeriodStats.set(canonicalSku, { revenue: 0, refunds: 0, organicQty: 0, adEnabledQty: 0, qty: 0, prevRevenue: 0, prevQty: 0, prevProfit: 0 });
            skuPeriodStats.get(canonicalSku)!.refunds += r.amount;
        }
    });
    safePriceHistory.forEach(l => {
        const lTime = new Date(l.date).getTime();
        const canonicalSku = getCanonicalSku(l.sku);
        
        // Ensure map entry exists
        if (!skuPeriodStats.has(canonicalSku)) skuPeriodStats.set(canonicalSku, { revenue: 0, refunds: 0, organicQty: 0, adEnabledQty: 0, qty: 0, prevRevenue: 0, prevQty: 0, prevProfit: 0 });
        const stats = skuPeriodStats.get(canonicalSku)!;

        // Current Period Aggregation
        if (lTime >= startTime && lTime <= endTime) {
            stats.revenue += (l.price * l.velocity);
            stats.qty += l.velocity;
            
            // Organic Share Accumulation
            const p = productMap.get(canonicalSku);
            const adsSpend = l.adsSpend !== undefined ? l.adsSpend : (p?.adsFee || 0) * l.velocity;
            
            if (isAdsEnabled(l.platform || '')) {
                stats.adEnabledQty += l.velocity;
                if (adsSpend === 0) {
                    stats.organicQty += l.velocity;
                }
            }
        }

        // Previous Period Aggregation (For Trends)
        if (lTime >= prevStartTime && lTime < prevEndTime) {
            stats.prevRevenue += (l.price * l.velocity);
            stats.prevQty += l.velocity;
            
            // Calculate Previous Profit
            let logProfit = 0;
            if (l.profit !== undefined) {
                logProfit = l.profit;
            } else {
                const margin = l.margin || 0;
                logProfit = l.price * l.velocity * (margin / 100);
            }
            stats.prevProfit += logProfit;
        }
    });

    const candidates: any[] = [];
    const skuTotals: Record<string, number> = {};
    let grandTotalRevenue = 0;

    // Pass 2: Filter and Build Candidates
    safePriceHistory.forEach(log => {
        const canonicalSku = getCanonicalSku(log.sku);
        const product = productMap.get(canonicalSku);
        if (!product) return;
        const logTime = new Date(log.date).getTime();
        if (logTime < startTime || logTime > endTime) return;

        let margin = log.margin;
        let type = 'TRANSACTION';
        const revenue = log.price * log.velocity;
        const adsSpend = log.adsSpend !== undefined ? log.adsSpend : (product.adsFee || 0) * log.velocity;

        if (log.price === 0 && adsSpend > 0) {
            type = 'AD_COST';
            margin = -Infinity;
        } else if (margin === undefined || margin === null) {
            margin = safeCalculateMargin(product, log.price);
        }

        const tacos = revenue > 0 ? (adsSpend / revenue) * 100 : 0;
        
        // Stats for current SKU
        const pStats = skuPeriodStats.get(canonicalSku) || { revenue: 0, refunds: 0, organicQty: 0, adEnabledQty: 0, qty: 0, prevRevenue: 0, prevQty: 0, prevProfit: 0 };
        const periodReturnRate = pStats.revenue > 0 ? (pStats.refunds / pStats.revenue) * 100 : 0;
        const organicShare = pStats.adEnabledQty > 0 ? (pStats.organicQty / pStats.adEnabledQty) * 100 : null;

        // Calculate Dynamic Trends
        const revenueChange = pStats.revenue - pStats.prevRevenue;
        const revenueChangePct = pStats.prevRevenue > 0 ? (revenueChange / pStats.prevRevenue) * 100 : (pStats.revenue > 0 ? 100 : 0);
        
        const velocityChange = pStats.qty - pStats.prevQty; // Absolute change
        const velocityChangePct = pStats.prevQty > 0 ? (velocityChange / pStats.prevQty) * 100 : (pStats.qty > 0 ? 100 : 0);

        // Calculate Margin Trend - KEY FIX
        const prevMargin = pStats.prevRevenue > 0 ? (pStats.prevProfit / pStats.prevRevenue) * 100 : 0;
        const marginChange = (margin || 0) - prevMargin;
        
        const agedStockPct = product.stockLevel > 0 && product.agedStockQty ? (product.agedStockQty / product.stockLevel) * 100 : 0;

        const calculatedMetrics: any = {
            revenue, margin, adsSpend, tacos, 
            organicShare: organicShare !== null ? organicShare : 0,
            profit: log.profit || (revenue * ((margin || 0)/100)),
            returnRate: product.returnRate || 0,
            periodReturnRate: periodReturnRate,
            stockLevel: product.stockLevel,
            agedStockQty: product.agedStockQty,
            agedStockPct: agedStockPct,
            daysRemaining: product.averageDailySales > 0 ? product.stockLevel / product.averageDailySales : 999,
            
            velocityChange: velocityChangePct,
            velocityChangeAbs: velocityChange,
            revenueChangeAbs: revenueChange,
            revenueChangePct: revenueChangePct,
            marginChange: marginChange // Add for sorting limit
        };

        if (log.price === 0 && adsSpend > 0) {
            calculatedMetrics.profit = -adsSpend;
        }

        const pass = intent.filters.every(f => {
            let val: any = (log as any)[f.field];
            
            // Map Margin Change special filter
            if (f.field === 'MARGIN_CHANGE_PCT') {
                val = marginChange;
            } else if (calculatedMetrics[f.field] !== undefined) {
                val = calculatedMetrics[f.field];
            } else if (val === undefined) {
                val = (product as any)[f.field];
            }
            
            if (val === null && (f.field === 'organicShare' || f.field === 'ORGANIC_SHARE_PCT')) {
                 val = 0; 
            }

            const criteria = Number(f.value);
            const strCriteria = String(f.value).toLowerCase();
            const valStr = String(val).toLowerCase();

            // Explicit Postcode Matching Logic
            if (f.field === 'postcode') {
                const pcRegex = new RegExp(`^${strCriteria}(\\d|$)`, 'i');
                return pcRegex.test(valStr);
            }

            if (f.field === 'name' && f.operator === 'CONTAINS') {
                const nameMatch = product.name.toLowerCase().includes(strCriteria);
                const skuMatch = product.sku.toLowerCase().includes(strCriteria);
                const aliasMatch = product.channels.some(c => c.skuAlias && c.skuAlias.toLowerCase().includes(strCriteria));
                return nameMatch || skuMatch || aliasMatch;
            }
            if (isMissingFilterValue(val)) {
                return f.field === 'postcode' ? false : true;
            }
            if (f.operator === 'CONTAINS') return valStr.includes(strCriteria);
            if (f.operator === '=') return valStr === strCriteria || val == f.value;
            if (f.operator === '>') return val > criteria;
            if (f.operator === '<') return val < criteria;
            if (f.operator === '>=') return val >= criteria;
            if (f.operator === '<=') return val <= criteria;
            return true;
        });

        if (pass) {
            grandTotalRevenue += revenue;
            const sortField = intent.sort?.field || 'revenue';
            
            // Handle special mapping for MARGIN_CHANGE_PCT
            let sortVal = calculatedMetrics[sortField] || revenue;
            if (sortField === 'MARGIN_CHANGE_PCT') {
                sortVal = marginChange * log.velocity; 
            }

            if (!skuTotals[product.sku]) skuTotals[product.sku] = 0;
            skuTotals[product.sku] += sortVal;
            
            candidates.push({
                sku: product.sku,
                productName: product.name,
                platform: log.platform || 'Unknown',
                date: log.date,
                price: log.price,
                velocity: log.velocity,
                revenue: calculatedMetrics.revenue,
                profit: calculatedMetrics.profit,
                margin: calculatedMetrics.margin,
                adsSpend: calculatedMetrics.adsSpend,
                tacos: calculatedMetrics.tacos,
                organicShare: calculatedMetrics.organicShare,
                stockLevel: calculatedMetrics.stockLevel,
                agedStockQty: calculatedMetrics.agedStockQty,
                agedStockPct: calculatedMetrics.agedStockPct,
                daysRemaining: calculatedMetrics.daysRemaining,
                postcode: log.postcode, // Pass postcode through to UI
                
                // Trend Metrics (Percentages - Unitless)
                velocityChange: calculatedMetrics.velocityChange,
                revenueChangePct: calculatedMetrics.revenueChangePct,
                
                // Absolute Changes (Need scaling later)
                velocityChangeAbs: calculatedMetrics.velocityChangeAbs,
                revenueChangeAbs: calculatedMetrics.revenueChangeAbs, // EX-TAX currently
                
                returnRate: calculatedMetrics.returnRate,
                periodReturnRate: calculatedMetrics.periodReturnRate,
                allTimeReturnRate: product.returnRate || 0,
                type: type,
                
                // Pass previous values for aggregation in UI (EX-TAX)
                prevRevenue: pStats.prevRevenue || 0,
                prevQty: pStats.prevQty || 0,
                prevProfit: pStats.prevProfit || 0
            });
        }
    });

    safeRefundHistory.forEach(r => {
        const logTime = new Date(r.date).getTime();
        if (logTime < startTime || logTime > endTime) return;
        const canonicalSku = getCanonicalSku(r.sku);
        const product = productMap.get(canonicalSku);
        if (!product) return;
        const pStats = skuPeriodStats.get(canonicalSku) || { revenue: 0, refunds: 0, organicQty: 0, adEnabledQty: 0, qty: 0, prevRevenue: 0, prevQty: 0, prevProfit: 0 };
        const derivedMetrics: any = {
            revenue: 0, profit: -r.amount, margin: 0, returnRate: product.returnRate || 0,
            periodReturnRate: pStats.revenue > 0 ? (pStats.refunds / pStats.revenue) * 100 : 0,
            stockLevel: product.stockLevel, velocity: r.quantity, adsSpend: 0, tacos: 0, organicShare: 0, agedStockPct: 0
        };
        const pass = intent.filters.every(f => {
            let val: any = (r as any)[f.field];
            if (derivedMetrics[f.field] !== undefined) val = derivedMetrics[f.field];
            else if (val === undefined) val = (product as any)[f.field];
            const criteria = Number(f.value);
            const strCriteria = String(f.value).toLowerCase();
            const valStr = String(val).toLowerCase();
            
            if (f.field === 'postcode') return false;

            if (f.field === 'name' && f.operator === 'CONTAINS') {
                const nameMatch = product.name.toLowerCase().includes(strCriteria);
                const skuMatch = product.sku.toLowerCase().includes(strCriteria);
                const aliasMatch = product.channels.some(c => c.skuAlias && c.skuAlias.toLowerCase().includes(strCriteria));
                return nameMatch || skuMatch || aliasMatch;
            }
            if (isMissingFilterValue(val)) {
                return true;
            }
            if (f.operator === 'CONTAINS') return valStr.includes(strCriteria);
            if (f.operator === '=') return valStr === strCriteria || val == f.value;
            if (f.operator === '>') return val > criteria;
            if (f.operator === '<') return val < criteria;
            if (f.operator === '>=') return val >= criteria;
            if (f.operator === '<=') return val <= criteria;
            return true;
        });
        if (pass) {
            if (!skuTotals[product.sku]) skuTotals[product.sku] = 0;
            candidates.push({
                sku: product.sku, productName: product.name, platform: r.platform || 'Unknown',
                date: r.date, price: 0, velocity: r.quantity, revenue: 0, 
                profit: -r.amount, margin: 0, periodReturnRate: derivedMetrics.periodReturnRate,
                allTimeReturnRate: product.returnRate || 0, type: 'REFUND', reason: r.reason, refundAmount: r.amount, status: r.status
            });
        }
    });

    let validSkus = new Set<string>();
    if (intent.limit && intent.limit > 0) {
        const sortedSkus = Object.entries(skuTotals).sort(([, a], [, b]) => (intent.sort?.direction === 'asc' ? a - b : b - a)).slice(0, intent.limit).map(([sku]) => sku);
        validSkus = new Set(sortedSkus);
    } else { validSkus = new Set(Object.keys(skuTotals)); }

    const results: any[] = [];
    candidates.forEach(cand => {
        if (validSkus.has(cand.sku)) {
            // Contribution calculated on ex-tax values (ratio is same)
            const contribution = grandTotalRevenue > 0 ? (cand.revenue / grandTotalRevenue) * 100 : 0;
            
            results.push({ 
                ...cand, 
                contribution: contribution,
                // Scale monetary values for display
                price: scaleMoneyInclTax(cand.price),
                revenue: scaleMoneyInclTax(cand.revenue),
                profit: scaleMoneyInclTax(cand.profit),
                adsSpend: scaleMoneyInclTax(cand.adsSpend),
                refundAmount: cand.refundAmount ? scaleMoneyInclTax(cand.refundAmount) : undefined,
                
                // Scale Trend Absolutes
                revenueChangeAbs: scaleMoneyInclTax(cand.revenueChangeAbs),
                prevRevenue: scaleMoneyInclTax(cand.prevRevenue),
                prevProfit: scaleMoneyInclTax(cand.prevProfit)
            });
        }
    });

    if (intent.sort) {
        results.sort((a, b) => {
            const field = intent.sort!.field;
            const valA = a[field] || 0;
            const valB = b[field] || 0;
            return intent.sort!.direction === 'asc' ? valA - valB : valB - valA;
        });
    }

    return { results, timeLabel, resultMeta: { moneyIsTaxInclusive: true, vatMultiplierUsed: VAT_MULTIPLIER } };
};

import { Product, AnalysisResult, PlatformConfig } from "../types";
import { buildQueryPlanFromText } from "./search/aiParser";
import { QueryPlan } from "./search/queryPlan";
import { ThresholdConfig, DEFAULT_THRESHOLDS } from "../services/thresholdsConfig";
import { VAT_MULTIPLIER } from "../constants";

/**
 * Placeholder for price adjustment analysis.
 * The AI-driven analysis has been removed as requested.
 */
export const analyzePriceAdjustment = async (product: Product, _platformRule: PlatformConfig, _context?: string, _thresholds: ThresholdConfig = DEFAULT_THRESHOLDS): Promise<AnalysisResult> => {
  const currentPriceWithVat = (product.currentPrice || 0) * VAT_MULTIPLIER;
  const velocity = product.averageDailySales || 0.1;
  const stock = product.stockLevel;
  const daysRemaining = stock / velocity;

  // Simple deterministic logic as a placeholder
  return {
    productId: product.id,
    recommendedPrice: currentPriceWithVat,
    percentageChange: 0,
    daysRemaining: Math.floor(daysRemaining),
    status: daysRemaining < 14 ? 'Critical' : 'Healthy',
    reasoning: "Analysis functionality has been disabled. This is a placeholder result based on current stock cover."
  };
};

// --- SEARCH PARSER ---

export interface SearchIntent {
  targetData: 'inventory' | 'transactions' | 'refunds';
  filters: Array<{
    field: string;
    operator: '>' | '<' | '>=' | '<=' | '=' | 'CONTAINS';
    value: string | number;
    label?: string; // Friendly label for UI
  }>;
  sort?: {
    field: string;
    direction: 'asc' | 'desc';
  };
  limit?: number; 
  timeRange?: {
    type: 'relative' | 'absolute';
    value: string; // '30d' or ISO string
  };
  explanation?: string;
  primaryMetric?: string;
}

const mapPlanFieldToIntentField = (rawField: string): string => {
    const field = String(rawField || '').toUpperCase();
    if (field === 'NET_MARGIN_PCT') return 'margin';
    if (field === 'CMA_PCT') return 'margin';
    if (field === 'MARGIN') return 'margin';
    if (field === 'TACOS_PCT') return 'tacos';
    if (field === 'ADS_SPEND') return 'adsSpend';
    if (field === 'SALES_QTY' || field === 'UNITS') return 'velocity';
    if (field === 'DAILY_VELOCITY') return 'averageDailySales';
    if (field === 'REVENUE') return 'revenue';
    if (field === 'NET_PROFIT' || field === 'PROFIT') return 'profit';
    if (field === 'STOCK_COVER_DAYS') return 'daysRemaining';
    if (field === 'STOCK_LEVEL') return 'stockLevel';
    if (field === 'VELOCITY_CHANGE') return 'velocityChange';
    if (field === 'MARGIN_CHANGE_PCT') return 'MARGIN_CHANGE_PCT';
    if (field === 'RETURN_RATE_PCT' || field === 'RETURN_RATE') return 'periodReturnRate';
    if (field === 'ORGANIC_SHARE_PCT') return 'organicShare';
    if (field === 'AGED_STOCK_PCT') return 'agedStockPct';
    if (field === 'PLATFORM') return 'platform';
    if (field === 'POSTCODE') return 'postcode';
    if (field === 'SKU' || field === 'PRODUCT_NAME' || field === 'NAME') return 'name';
    return rawField;
};

const mapPlanSortToIntentSort = (rawField: string): string => {
    const field = String(rawField || '').toLowerCase();
    if (field === 'revenue') return 'revenue';
    if (field === 'net_margin_pct' || field === 'margin') return 'margin';
    if (field === 'cma_pct') return 'margin';
    if (field === 'tacos_pct') return 'tacos';
    if (field === 'stock_cover_days') return 'daysRemaining';
    if (field === 'daily_velocity') return 'averageDailySales';
    if (field === 'sales_qty' || field === 'units') return 'velocity';
    if (field === 'net_profit' || field === 'profit') return 'profit';
    if (field === 'velocity_change') return 'velocityChange';
    if (field === 'margin_change_pct') return 'MARGIN_CHANGE_PCT';
    if (field === 'return_rate_pct' || field === 'return_rate') return 'periodReturnRate';
    if (field === 'organic_share_pct') return 'organicShare';
    if (field === 'aged_stock_pct') return 'agedStockPct';
    if (field === 'platform') return 'platform';
    return field;
};

/**
 * Adapter: QueryPlan -> SearchIntent
 * Converts the new high-level Query Plan into the legacy SearchIntent format
 * expected by the SearchResultsPage engine.
 */
function adaptPlanToIntent(plan: QueryPlan): SearchIntent {
    let targetData: 'inventory' | 'transactions' | 'refunds' = 'transactions';

    // 1. Determine Target Data
    if (plan.primaryMetric === 'STOCK_LEVEL' || plan.primaryMetric === 'STOCK_COVER_DAYS' || plan.primaryMetric === 'AGED_STOCK_PCT') {
        targetData = 'inventory';
    } else if (plan.primaryMetric === 'RETURN_RATE_PCT') {
        // While returns are conceptually "refunds", often we want transaction data with return rate context
        targetData = 'transactions';
    }

    // 2. Map Filters
    const filters = plan.filters.map(f => {
        let op: any = '=';
        if (f.op === 'GT') op = '>';
        if (f.op === 'LT') op = '<';
        if (f.op === 'GTE') op = '>=';
        if (f.op === 'LTE') op = '<=';
        if (f.op === 'CONTAINS') op = 'CONTAINS';

        const field = mapPlanFieldToIntentField(f.field);

        return {
            field,
            operator: op,
            value: f.value
        };
    });

    // 3. Map Time
    // Updated to support extended range logic
    let timeValue = '30d'; // Default

    if (plan.customDays) {
        timeValue = `${plan.customDays}d`;
    } else if (plan.timePreset === 'LAST_7_DAYS') {
        timeValue = '7d';
    } else if (plan.timePreset === 'LAST_MONTH') {
        timeValue = '60d'; // Approx
    } else if (plan.timePreset === 'LAST_90_DAYS') {
        timeValue = '90d';
    } else if (plan.timePreset === 'LAST_180_DAYS') {
        timeValue = '180d';
    } else if (plan.timePreset === 'ALL_TIME') {
        timeValue = '3650d'; 
    } else if (plan.timePreset === 'THIS_YEAR') {
        const now = new Date();
        const startOfYear = new Date(now.getFullYear(), 0, 1);
        const diffTime = Math.abs(now.getTime() - startOfYear.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
        timeValue = `${diffDays}d`;
    }

    // 4. Map Sort
    const sortField = mapPlanSortToIntentSort(plan.sort.field);

    return {
        targetData,
        filters,
        sort: {
            field: sortField,
            direction: plan.sort.direction.toLowerCase() as 'asc' | 'desc'
        },
        limit: plan.limit,
        timeRange: { type: 'relative', value: timeValue },
        explanation: plan.explain,
        primaryMetric: plan.primaryMetric
    };
}

/**
 * Local Search Parser
 * Uses the deterministic `aiParser` logic to build a structured query plan,
 * then adapts it to the existing `SearchIntent` format.
 */
export const parseSearchQuery = async (query: string): Promise<SearchIntent> => {
  // Simulate minor network delay for UX consistency
  await new Promise(resolve => setTimeout(resolve, 150));

  // --- DEEP DIVE INTERCEPT ---
  if (query.trim().toUpperCase().startsWith('SKU:')) {
      const sku = query.trim().substring(4).trim();
      return {
          targetData: 'inventory',
          filters: [{ field: 'sku', operator: '=', value: sku }],
          primaryMetric: 'DEEP_DIVE',
          limit: 1,
          explanation: 'SKU Deep Dive Analysis'
      };
  }

  // Extract Context from Query String
  const context = {
      selectedPlatforms: [], 
      timePreset: undefined
  };

  try {
      const plan = buildQueryPlanFromText(query, context);
      return adaptPlanToIntent(plan);
  } catch (e) {
      console.warn("AI Parser failed, falling back to legacy heuristics", e);
      return legacyParseSearchQuery(query);
  }
};

/**
 * Legacy Parser (Backup)
 * Kept for stability if specific edge cases fail in the new parser.
 */
export const legacyParseSearchQuery = (query: string): SearchIntent => {
  const lower = query.toLowerCase().trim();
  const intent: SearchIntent = {
    targetData: 'inventory', // Default context
    filters: [],
    limit: 50,
    explanation: 'Legacy Rule-Based Search'
  };

  // ... (Preserve the exact legacy logic from previous version for fallback)
  // --- 1. DETERMINE DATA SOURCE ---
  if (lower.includes('return') || lower.includes('refund')) {
    intent.targetData = 'refunds';
    intent.explanation = "Searching Refunds database.";
  } else if (
    lower.includes('sold') || lower.includes('sales') || lower.includes('revenue') ||
    lower.includes('profit') || lower.includes('margin') || lower.includes('ads') ||
    lower.includes('spend') || lower.includes('tacos') || lower.includes('history') ||
    lower.includes('transaction')
  ) {
    intent.targetData = 'transactions';
    intent.explanation = "Searching Sales Transaction history.";
  }

  // --- 2. EXTRACT LIMIT ---
  const limitMatch = lower.match(/(?:top|limit)\s+(\d+)/);
  if (limitMatch) {
    intent.limit = parseInt(limitMatch[1]);
  }

  // --- 3. EXTRACT TIME RANGE ---
  const daysMatch = lower.match(/last\s+(\d+)\s+days?/);
  if (daysMatch) {
    intent.timeRange = { type: 'relative', value: `${daysMatch[1]}d` };
  } else if (lower.includes('yesterday')) {
    intent.timeRange = { type: 'relative', value: '1d' };
  } else if (lower.includes('month')) {
    intent.timeRange = { type: 'relative', value: '30d' };
  }

  // --- 4. APPLY BUSINESS LOGIC FILTERS ---
  // Explicit "Out of Stock" (stock <= 0)
  if (lower.includes('out of stock') || (lower.includes('stockout') && !lower.includes('risk'))) {
    intent.targetData = 'inventory';
    intent.filters.push({ field: 'stockLevel', operator: '<=', value: 0, label: 'Out of Stock' });
    intent.sort = { field: 'averageDailySales', direction: 'desc' }; 
    intent.explanation = "Filtering for Out of Stock items.";
  } 
  // "Risk" implies low stock but NOT dead stock
  else if (lower.includes('low stock') || lower.includes('risk') || lower.includes('stockout')) {
    intent.targetData = 'inventory';
    intent.filters.push({ field: 'daysRemaining', operator: '<', value: 14, label: 'Low Stock Risk' });
    intent.filters.push({ field: 'stockLevel', operator: '>', value: 0, label: 'In Stock' }); // Exclude 0
    intent.sort = { field: 'daysRemaining', direction: 'asc' };
    intent.explanation = "Filtering for Low Stock Risk (< 14 days, excluding OOS).";
  } else if (lower.includes('overstock')) {
    intent.targetData = 'inventory';
    intent.filters.push({ field: 'daysRemaining', operator: '>', value: 120, label: 'Overstock' });
    intent.sort = { field: 'daysRemaining', direction: 'desc' };
    intent.explanation = "Filtering for Overstock (> 120 days).";
  } else if (lower.includes('dormant') || lower.includes('dead')) {
    intent.targetData = 'inventory';
    intent.filters.push({ field: 'averageDailySales', operator: '=', value: 0, label: 'Zero Velocity' });
    intent.filters.push({ field: 'stockLevel', operator: '>', value: 0, label: 'Has Stock' });
    intent.explanation = "Filtering for Dead Stock (Stock > 0 but Velocity = 0).";
  }

  if (lower.includes('loss') || lower.includes('negative')) {
    intent.targetData = 'transactions';
    intent.filters.push({ field: 'margin', operator: '<', value: 0, label: 'Unprofitable' });
    intent.sort = { field: 'margin', direction: 'asc' };
    intent.explanation = "Filtering for Unprofitable items.";
  } else if (lower.includes('high ad') || lower.includes('high tacos') || lower.includes('dependency')) {
    intent.targetData = 'transactions';
    intent.filters.push({ field: 'tacos', operator: '>', value: 15, label: 'High Ad Dependency' });
    intent.sort = { field: 'tacos', direction: 'desc' };
    intent.explanation = "Filtering for High Ad Dependency (TACoS > 15%).";
  }

  // --- 5. SORTING HINTS ---
  if (!intent.sort) {
    if (lower.includes('best') || lower.includes('top') || lower.includes('highest')) {
      if (lower.includes('margin')) intent.sort = { field: 'margin', direction: 'desc' };
      else if (lower.includes('profit')) intent.sort = { field: 'profit', direction: 'desc' };
      else if (lower.includes('velocity') || lower.includes('sales')) intent.sort = { field: 'velocity', direction: 'desc' };
      else intent.sort = { field: 'revenue', direction: 'desc' };
    } else if (lower.includes('worst') || lower.includes('lowest')) {
      if (lower.includes('margin')) intent.sort = { field: 'margin', direction: 'asc' };
      else intent.sort = { field: 'margin', direction: 'asc' };
    }
  }

  // --- 6. PLATFORM FILTER ---
  const platforms = ['amazon', 'ebay', 'wayfair', 'range', 'manomano', 'onbuy', 'groupon', 'tiktok', 'wowcher', 'kaufland', 'tesco', 'debenhams'];
  platforms.forEach(p => {
    if (lower.includes(p)) {
      intent.filters.push({ field: 'platform', operator: 'CONTAINS', value: p, label: `Platform: ${p}` });
    }
  });

  // --- 7. TEXT MATCHING ---
  const hasLogicFilters = intent.filters.some(f => f.field !== 'platform');
  if (!hasLogicFilters) {
      const keywords = [
          ...platforms, 
          'return', 'refund', 'sales', 'revenue', 'profit', 'margin', 'ads', 'spend', 'tacos', 'history', 
          'top', 'limit', 'stock', 'inventory', 'runway', 'velocity', 'sku', 'product', 'days', 'last', 
          'low', 'high', 'overstock', 'loss', 'negative', 'best', 'worst', 'lowest', 'highest', 'dead', 'dormant', 'risk',
          'cover',
          // UPDATED KEYWORDS FOR ROBUSTNESS
          'velocity', 'daily', 'candidate', 'average', 'avg', 'ratio', 'percent', 'pct', 
          'per', 'unit', 'qty', 'level', 'aged', 'inbound', 'below', 'target', 'dependency', 
          'strong', 'organic', 'dormant', 'no', 'winning', 'scale', 'contribution', 'net', 'gross'
      ];
      let remainingText = lower;
      keywords.forEach(k => { 
          const regex = new RegExp(`\\b${k}\\b`, 'g');
          remainingText = remainingText.replace(regex, ''); 
      });
      remainingText = remainingText.replace(/\b\d+(d| days?)\b/g, '').replace(/\btop\s+\d+\b/g, '').replace(/[()]/g, '').trim();

      if (remainingText.length > 2) {
         const cleanQuery = remainingText.replace(/\s+/g, ' ').trim();
         intent.filters.push({ field: 'name', operator: 'CONTAINS', value: cleanQuery, label: `Text: "${cleanQuery}"` });
      }
  }

  return intent;
};

export const createTextFallbackIntent = (query: string): SearchIntent => {
  const cleanQuery = query.trim();
  return {
    targetData: 'inventory',
    filters: cleanQuery.length > 0 ? [{ field: 'name', operator: 'CONTAINS', value: cleanQuery }] : [],
    limit: 100,
    explanation: 'Fallback text search'
  };
};

import { QueryPlan, MetricId, TimePreset } from './queryPlan';
import { PLATFORM_MAPPING } from './suggestionConfig';

interface Context {
  selectedPlatforms: string[];
  timePreset?: string; 
}

/**
 * Deterministic rules-based parser to simulate AI intent understanding.
 * This ensures "High Ad Dependency" maps strictly to a TACoS filter.
 */
export function buildQueryPlanFromText(text: string, context: Context): QueryPlan {
  const lowerText = text.toLowerCase();

  // 1. Resolve Time: Use Context First, then Text, then Default
  let selectedTime: TimePreset = "LAST_30_DAYS";
  let customDays: number | undefined = undefined;

  const daysMatch = lowerText.match(/last\s+(\d+)\s+days?/);

  if (context.timePreset) {
      selectedTime = context.timePreset as TimePreset;
  } else if (daysMatch) {
      // Arbitrary day support
      customDays = parseInt(daysMatch[1]);
      selectedTime = "LAST_30_DAYS"; // Placeholder, will be overridden by customDays in adapter
  } else if (lowerText.includes('last 7')) {
      selectedTime = "LAST_7_DAYS";
  } else if (lowerText.includes('last 30')) {
      selectedTime = "LAST_30_DAYS";
  } else if (lowerText.includes('last 90')) {
      selectedTime = "LAST_90_DAYS";
  } else if (lowerText.includes('last 180') || lowerText.includes('6 months')) {
      selectedTime = "LAST_180_DAYS";
  } else if (lowerText.includes('this month')) {
      selectedTime = "THIS_MONTH";
  } else if (lowerText.includes('last month')) {
      selectedTime = "LAST_MONTH";
  } else if (lowerText.includes('this year') || lowerText.includes('ytd') || lowerText.includes('year to date')) {
      selectedTime = "THIS_YEAR";
  } else if (lowerText.includes('all time') || lowerText.includes('total history')) {
      selectedTime = "ALL_TIME";
  }

  // 2. Resolve Platforms: Map ID -> Data Name
  let resolvedPlatforms: string[] | undefined = undefined;
  if (context.selectedPlatforms && context.selectedPlatforms.length > 0) {
      resolvedPlatforms = context.selectedPlatforms.map(p => PLATFORM_MAPPING[p] || p);
  }

  // Default Plan Structure
  const plan: QueryPlan = {
    metrics: ["REVENUE", "UNITS", "NET_MARGIN_PCT", "PROFIT"],
    primaryMetric: "REVENUE",
    groupBy: "PLATFORM",
    timePreset: selectedTime,
    customDays: customDays,
    platforms: resolvedPlatforms,
    filters: [],
    sort: { field: "REVENUE", direction: "DESC" },
    limit: 100, // Increased default from 50 to 100
    viewHint: "SUMMARY_CARDS",
    explain: "Showing overview based on revenue."
  };

  // --- 3. Detect Grouping ---
  if (lowerText.includes('sku') || lowerText.includes('product') || lowerText.includes('item')) {
      plan.groupBy = "SKU";
      plan.viewHint = "TABLE"; // Tables are better for SKU lists
  }

  // --- 4. Detect Text Search Term (The Fix) ---
  // We identify keywords used for logic/commands. Any text NOT matching these is considered a search term.
  const commandKeywords = [
      'tacos', 'ad dependency', 'advertising', 'ad spend', 'ads',
      'profit', 'margin', 'loss', 'negative', 'low', 'high', 'gross', 'net', 'contribution',
      'stock', 'inventory', 'runway', 'cover', 'days', 'remaining', 'overstock', 'stockout', 'risk', 'excess',
      'scale', 'winning', 'best', 'top', 'limit', 'show', 'worst', 'bad', 'drop', 'decline', 'wow', 'trend',
      'return', 'returns', 'refund', 'refunds', 'rate', 'rates', 'rr', // Updated to include plurals
      'sku', 'product', 'item', 'list', 'table', 'products', 'items', 'skus',
      'show', 'me', 'with', 'on', 'the', 'of', 'in', 'for', 'and', 'at', 'from',
      'last', 'month', 'year', 'ytd', 'this', 'all time', 'history',
      'amazon', 'ebay', 'range', 'manomano', 'wayfair', 'onbuy', 'groupon', 'tiktok', 'volume', 'sales', 'revenue',
      'transaction', 'transactions', // Added to prevent these from being seen as product names
      // EXPANDED KEYWORDS LIST
      'velocity', 'daily', 'candidate', 'average', 'avg', 'ratio', 'percent', 'pct', 
      'per', 'unit', 'qty', 'level', 'aged', 'inbound', 'below', 'target', 'dependency', 
      'strong', 'organic', 'dormant', 'no', 'old', 'long term', 'stale',
      // UPDATED: Include new terms to prevent accidental text filtering
      'share', 'natural', 'change', 'pop', 'growth', 'spike', 'improvement', 'fall', 'down', 'up', 'rise',
      'postcode', 'area', 'region', 'district'
  ];

  // --- 3.5. Extract Postcode/Area Filters explicitly ---
  // Look for "postcode: X" or "area: X"
  const postcodeMatch = lowerText.match(/(?:postcode|area|region):\s*([a-z0-9]{1,4})/i);
  if (postcodeMatch) {
      const pcCode = postcodeMatch[1].toUpperCase();
      plan.filters.push({ field: "postcode", op: "CONTAINS", value: pcCode });
      plan.explain += ` Filtered by Postcode Area: ${pcCode}.`;
      // Remove from text processing
      // We don't remove it from potentialSearchTerm yet, handled by keywords below
  }

  let potentialSearchTerm = lowerText;

  // Remove the explicit match pattern from the text so it doesn't become a name filter
  if (postcodeMatch) {
      potentialSearchTerm = potentialSearchTerm.replace(postcodeMatch[0], '');
  }

  commandKeywords.forEach(k => {
      // Remove keywords safely
      try {
        potentialSearchTerm = potentialSearchTerm.replace(new RegExp(`\\b${k}\\b`, 'gi'), '');
      } catch(e) {
        potentialSearchTerm = potentialSearchTerm.replace(k, '');
      }
  });

  // Clean up numbers often associated with time/limit
  potentialSearchTerm = potentialSearchTerm.replace(/\b\d+\b/g, '').trim();
  // Remove special chars often used in logic but allow hyphens/underscores/spaces for SKUs/Names
  potentialSearchTerm = potentialSearchTerm.replace(/[><=%:]/g, '').replace(/\s+/g, ' ').trim();

  // If there is significant text left, apply it as a filter
  if (potentialSearchTerm.length > 2) {
      plan.filters.push({ field: "name", op: "CONTAINS", value: potentialSearchTerm });
      plan.groupBy = "SKU"; // Text search implies specific items, not platform summaries
      plan.viewHint = "TABLE";
      plan.explain = `Searching for "${potentialSearchTerm}".`;
  }

  // --- 5. Detect Intent / Metrics ---

  // A) TREND / CHANGE LOGIC (Drop, Decline, Growth, Change, PoP)
  const isNegativeTrend = lowerText.includes('drop') || lowerText.includes('decline') || lowerText.includes('down') || lowerText.includes('fall') || lowerText.includes('loss');
  const isPositiveTrend = lowerText.includes('growth') || lowerText.includes('spike') || lowerText.includes('up') || lowerText.includes('increase') || lowerText.includes('rise');
  const isGeneralTrend = lowerText.includes('trend') || lowerText.includes('change') || lowerText.includes('pop') || lowerText.includes('wow');

  if (isNegativeTrend || isPositiveTrend || isGeneralTrend) {

      // A1. Volume / Revenue / Sales / Velocity Trends
      if (lowerText.includes('volume') || lowerText.includes('revenue') || lowerText.includes('sales') || lowerText.includes('velocity')) {
          plan.primaryMetric = "VELOCITY_CHANGE";
          plan.metrics = ["VELOCITY_CHANGE", "REVENUE", "UNITS"];
          plan.viewHint = "RANKED_LIST";

          if (isNegativeTrend) {
              plan.sort = { field: "VELOCITY_CHANGE", direction: "ASC" };
              plan.filters.push({ field: "VELOCITY_CHANGE", op: "LT", value: 0 }); 
              if (!plan.explain.includes("Searching")) plan.explain = "Analyzing negative sales trends (Period-over-Period).";
          } else if (isPositiveTrend) {
              plan.sort = { field: "VELOCITY_CHANGE", direction: "DESC" };
              plan.filters.push({ field: "VELOCITY_CHANGE", op: "GT", value: 0 }); 
              if (!plan.explain.includes("Searching")) plan.explain = "Analyzing sales growth (Period-over-Period).";
          } else {
              // Neutral "Change" or "Trend" - Default to seeing big moves (Growth first usually)
              plan.sort = { field: "VELOCITY_CHANGE", direction: "DESC" };
              if (!plan.explain.includes("Searching")) plan.explain = "Analyzing sales velocity trends (Period-over-Period).";
          }
      }

      // A2. Margin Trends
      else if (lowerText.includes('margin') || lowerText.includes('profit') || lowerText.includes('contribution')) {
          // KEY FIX: Use MARGIN_CHANGE_PCT instead of NET_MARGIN_PCT for sorting limits
          const metric = lowerText.includes('contribution') ? "CMA_PCT" : "MARGIN_CHANGE_PCT";
          plan.primaryMetric = metric;
          plan.metrics = [metric, "PROFIT", "REVENUE", "NET_MARGIN_PCT"];
          plan.viewHint = "RANKED_LIST";

          if (isNegativeTrend) {
              plan.sort = { field: metric, direction: "ASC" };
              // For margin change, LT 0 means decline
              plan.filters.push({ field: metric, op: "LT", value: 0 }); 
              if (!plan.explain.includes("Searching")) plan.explain = "Highlighting products with declining margins.";
          } else if (isPositiveTrend) {
              plan.sort = { field: metric, direction: "DESC" };
              plan.filters.push({ field: metric, op: "GT", value: 0 });
              if (!plan.explain.includes("Searching")) plan.explain = "Highlighting products with improving margins.";
          } else {
              // General Margin Change/Trend
              plan.sort = { field: metric, direction: "DESC" };
              if (!plan.explain.includes("Searching")) plan.explain = "Analyzing margin trends (Period-over-Period).";
          }
      }
  }

  // B) TACoS / Ad Dependency / Ad Spend
  else if (lowerText.includes('tacos') || lowerText.includes('ad dependency') || lowerText.includes('advertising') || lowerText.includes('ad spend')) {
      plan.primaryMetric = "TACOS_PCT";
      plan.metrics = ["TACOS_PCT", "ADS_SPEND", "REVENUE", "MER"];
      plan.sort = { field: "TACOS_PCT", direction: "DESC" };
      plan.viewHint = "RANKED_LIST"; 
      if (!plan.explain.includes("Searching")) plan.explain = "Analyzing Total Advertising Cost of Sales (TACoS).";

      // Filter: Only show items with valid ad spend activity
      plan.filters.push({ field: "ADS_SPEND", op: "GT", value: 0 });

      // High Dependency Logic
      if (lowerText.includes('high') || lowerText.includes('dependency')) {
          const threshold = lowerText.includes('very high') ? 25 : 15; 
          plan.filters.push({ field: "TACOS_PCT", op: "GTE", value: threshold });
          if (!plan.explain.includes("Searching")) plan.explain = `Showing items with high ad dependency (TACoS >= ${threshold}%).`;
      }
  } 
  // C) Contribution Margin Specific (General)
  else if (lowerText.includes('contribution')) {
      plan.primaryMetric = "CMA_PCT";
      plan.metrics = ["CMA_PCT", "PROFIT", "REVENUE", "UNITS"];
      plan.sort = { field: "CMA_PCT", direction: "DESC" }; // Default to highest contribution

      if (lowerText.includes('low') || lowerText.includes('bad') || lowerText.includes('negative')) {
          plan.sort = { field: "CMA_PCT", direction: "ASC" };
          // Active Logic for "Low"
          plan.filters.push({ field: "CMA_PCT", op: "LT", value: 10 });
          if (!plan.explain.includes("Searching")) plan.explain = "Highlighting low contribution margin items.";
      } else {
          if (!plan.explain.includes("Searching")) plan.explain = "Analyzing Contribution Margin.";
      }
  }
  // D) Profit / Margin / Loss (General)
  else if (lowerText.includes('profit') || lowerText.includes('margin') || lowerText.includes('loss')) {
      plan.primaryMetric = "NET_MARGIN_PCT";
      plan.metrics = ["NET_MARGIN_PCT", "PROFIT", "REVENUE", "UNITS"];
      plan.sort = { field: "PROFIT", direction: "DESC" };

      if (lowerText.includes('low') || lowerText.includes('negative') || lowerText.includes('loss')) {
          plan.sort = { field: "NET_MARGIN_PCT", direction: "ASC" }; 
          if (lowerText.includes('loss')) {
             plan.filters.push({ field: "NET_MARGIN_PCT", op: "LT", value: 0 });
          } else {
             plan.filters.push({ field: "NET_MARGIN_PCT", op: "LT", value: 10 });
          }
          plan.viewHint = "RANKED_LIST";
          if (!plan.explain.includes("Searching")) plan.explain = "Highlighting profitability issues.";
      } else {
          if (!plan.explain.includes("Searching")) plan.explain = "Analyzing profitability.";
      }
  }
  // E) Aged Stock / Old Stock
  else if (lowerText.includes('aged') || lowerText.includes('old') || lowerText.includes('long term') || lowerText.includes('stale')) {
      plan.primaryMetric = "AGED_STOCK_PCT";
      plan.metrics = ["AGED_STOCK_PCT", "STOCK_LEVEL", "DAILY_VELOCITY", "REVENUE"];
      plan.groupBy = "SKU";
      plan.viewHint = "TABLE";
      plan.sort = { field: "AGED_STOCK_PCT", direction: "DESC" };

      if (lowerText.includes('high') || lowerText.includes('risk') || lowerText.includes('heavy') || lowerText.includes('bad')) {
          plan.filters.push({ field: "AGED_STOCK_PCT", op: "GTE", value: 20 });
          if (!plan.explain.includes("Searching")) plan.explain = "Highlighting high aged stock (> 20%).";
      } else {
          // General view, ensure we only show items WITH aged stock
          plan.filters.push({ field: "AGED_STOCK_PCT", op: "GT", value: 0 });
          if (!plan.explain.includes("Searching")) plan.explain = "Analyzing Aged Stock levels.";
      }
  }
  // F) Inventory / Stock / Cover / Runway
  else if (lowerText.includes('stock') || lowerText.includes('inventory') || lowerText.includes('runway') || lowerText.includes('cover')) {
      plan.primaryMetric = "STOCK_COVER_DAYS";
      plan.metrics = ["STOCK_COVER_DAYS", "STOCK_LEVEL", "DAILY_VELOCITY", "REVENUE"];
      plan.groupBy = "SKU";
      plan.viewHint = "TABLE";

      if (lowerText.includes('stockout') || lowerText.includes('out of stock') || lowerText.includes('low')) {
          // Explicit OOS Intent
          if (lowerText.includes('out of stock') || (lowerText.includes('stockout') && !lowerText.includes('risk'))) {
              plan.sort = { field: "DAILY_VELOCITY", direction: "DESC" }; 
              plan.filters.push({ field: "STOCK_LEVEL", op: "LTE", value: 0 });
              if (!plan.explain.includes("Searching")) plan.explain = "Showing items currently Out of Stock.";
          } else {
              // Risk / Low Stock Intent
              plan.sort = { field: "STOCK_COVER_DAYS", direction: "ASC" };
              plan.filters.push({ field: "STOCK_COVER_DAYS", op: "LT", value: 14 });
              plan.filters.push({ field: "STOCK_LEVEL", op: "GT", value: 0 });
              if (!plan.explain.includes("Searching")) plan.explain = "Highlighting items at risk of stocking out (< 14 days cover).";
          }
      } else if (lowerText.includes('overstock') || lowerText.includes('excess') || lowerText.includes('high')) {
          plan.sort = { field: "STOCK_COVER_DAYS", direction: "DESC" };
          plan.filters.push({ field: "STOCK_COVER_DAYS", op: "GT", value: 120 });
          if (!plan.explain.includes("Searching")) plan.explain = "Highlighting potential overstock (> 120 days cover).";
      } else {
          // Generic Inventory View
          plan.sort = { field: "STOCK_COVER_DAYS", direction: "ASC" };
          if (!plan.explain.includes("Searching")) plan.explain = "Inventory health overview.";
      }
  }
  // G) Opportunity / Scale / Winning
  else if (lowerText.includes('scale') || lowerText.includes('winning') || lowerText.includes('best') || lowerText.includes('top')) {
      plan.primaryMetric = "PROFIT"; // Focus on contribution
      plan.metrics = ["PROFIT", "REVENUE", "UNITS", "NET_MARGIN_PCT"];
      plan.sort = { field: "PROFIT", direction: "DESC" };
      plan.viewHint = "RANKED_LIST";
      if (!plan.explain.includes("Searching")) plan.explain = "Highlighting top performing products.";
  }
  // H) Returns
  else if (lowerText.includes('return') || lowerText.includes('refund') || lowerText.includes('rr')) {
      plan.primaryMetric = "RETURN_RATE_PCT";
      plan.viewHint = "TABLE";
      plan.sort = { field: "RETURN_RATE_PCT", direction: "DESC" };

      // Default Filter Logic: High vs Normal
      const isHigh = lowerText.includes('high');
      const threshold = isHigh ? 10 : 5;

      plan.filters.push({ field: "RETURN_RATE_PCT", op: "GT", value: threshold });

      if (!plan.explain.includes("Searching")) {
          plan.explain = isHigh 
            ? "Analyzing High Returns (> 10%)." 
            : "Returns analysis (> 5%).";
      }
  }
  // I) Organic / Natural Sales
  else if (lowerText.includes('organic') || lowerText.includes('natural')) {
      plan.primaryMetric = "ORGANIC_SHARE_PCT";
      plan.metrics = ["ORGANIC_SHARE_PCT", "REVENUE", "TACOS_PCT", "ADS_SPEND"];
      plan.sort = { field: "ORGANIC_SHARE_PCT", direction: "DESC" };
      plan.viewHint = "RANKED_LIST";

      if (lowerText.includes('strong') || lowerText.includes('high') || lowerText.includes('good')) {
          plan.filters.push({ field: "ORGANIC_SHARE_PCT", op: "GTE", value: 70 });
          if (!plan.explain.includes("Searching")) plan.explain = "Showing products with strong organic sales (> 70% share).";
      } else if (lowerText.includes('low') || lowerText.includes('weak') || lowerText.includes('bad')) {
          plan.sort = { field: "ORGANIC_SHARE_PCT", direction: "ASC" };
          plan.filters.push({ field: "ORGANIC_SHARE_PCT", op: "LT", value: 30 });
          if (!plan.explain.includes("Searching")) plan.explain = "Highlighting products with weak organic share.";
      } else {
          if (!plan.explain.includes("Searching")) plan.explain = "Analyzing Organic Share %.";
      }
  }

  // --- 6. Extract Explicit Limit ---
  const limitMatch = lowerText.match(/(?:top|limit|show)\s+(\d+)/);
  if (limitMatch) {
      plan.limit = parseInt(limitMatch[1]);
  } else if (
      lowerText.includes('all products') || 
      lowerText.includes('all skus') || 
      lowerText.includes('show all') || 
      lowerText.includes('list all') ||
      lowerText.includes('unlimited')
  ) {
      plan.limit = 0; 
      plan.explain = plan.explain.replace('overview', 'complete list');
  }

  // Override view hint if specific structure requested
  if (lowerText.includes('table') || lowerText.includes('list')) {
      plan.viewHint = "TABLE";
  }

  return plan;
}

