import { ChipSelectionState, Suggestion, SuggestionPriority, MetricId, ConditionId, PlatformId } from '../../components/search/types';
import { METRICS, CONDITIONS, SMART_PAIRINGS, PLATFORM_BOOSTS, SHORTCUTS_LIBRARY, PLATFORMS_LIST, TIME_PRESETS_LIST } from './suggestionConfig';
import { Product } from '../../types';

// Base scores for priorities (Decision-First Ranking)
const PRIORITY_SCORES: Record<SuggestionPriority, number> = {
  RISK: 100,
  DECLINE: 80,
  INVENTORY: 60,
  OPPORTUNITY: 40,
  HYGIENE: 20
};

// Boost constants - Updated for stronger context awareness
const BOOSTS = {
  TEXT_MATCH_EXACT: 3000,
  TEXT_MATCH_START: 2000,
  TEXT_MATCH_PARTIAL: 1000,
  CONTEXT_MATCH: 200, // Sufficient to override base priority differences (e.g. Opportunity vs Risk)
  PLATFORM_MATCH: 100, 
  TIME_MATCH: 50,     
  ALREADY_SELECTED_PENALTY: -9999 
};

/**
 * Main Engine Function
 */
export function getSuggestions(state: ChipSelectionState, products: Product[] = []): {
  metricSuggestions: Suggestion[];
  conditionSuggestions: Suggestion[];
  shortcutSuggestions: Suggestion[];
  platformSuggestions: Suggestion[];
  timeSuggestions: Suggestion[];
  skuSuggestions: Suggestion[];
} {
  const searchLower = state.searchText.toLowerCase().trim();

  // --- SKU MODE DETECTION ---
  if (searchLower.startsWith('sku:') || searchLower.startsWith('sku ')) {
      const term = searchLower.replace(/^sku[:\s]+/, '').trim();
      const skuSuggestions: Suggestion[] = [];

      if (term.length > 0) {
          const matches = products.filter(p => 
              p.sku.toLowerCase().includes(term) || 
              p.name.toLowerCase().includes(term) ||
              p.channels.some(c => c.skuAlias?.toLowerCase().includes(term))
          ).slice(0, 15);

          matches.forEach(p => {
              skuSuggestions.push({
                  id: p.sku,
                  label: p.sku,
                  kind: 'sku',
                  priority: 'INVENTORY',
                  groupLabel: 'Products',
                  description: p.name,
                  score: 1000,
                  applies: {} // Handled explicitly in UI
              });
          });
      }

      // Return ONLY SKU suggestions when in this mode to avoid clutter
      return {
          metricSuggestions: [],
          conditionSuggestions: [],
          shortcutSuggestions: [],
          platformSuggestions: [],
          timeSuggestions: [],
          skuSuggestions
      };
  }

  // Helper to score based on text match
  const getTextScore = (label: string, description?: string) => {
      if (!searchLower) return 0;
      const labelLower = label.toLowerCase();

      // 1. Exact Match
      if (labelLower === searchLower) return BOOSTS.TEXT_MATCH_EXACT;

      // 2. Starts With
      if (labelLower.startsWith(searchLower)) return BOOSTS.TEXT_MATCH_START;

      // 3. Contains
      if (labelLower.includes(searchLower)) return BOOSTS.TEXT_MATCH_PARTIAL;

      // 4. Description Match (Lower priority)
      if (description && description.toLowerCase().includes(searchLower)) return BOOSTS.TEXT_MATCH_PARTIAL / 2;

      return -9999; // Filter out if searching and no match
  };

  // 1. Calculate Metric Suggestions
  const metricSuggestions = METRICS.map((m): Suggestion | null => {
    let score = PRIORITY_SCORES[m.defaultPriority];

    // Text Search Logic
    if (searchLower) {
        const matchScore = getTextScore(m.label, m.description);
        if (matchScore === -9999) return null; // Explicit filter
        score += matchScore;
    }

    // Penalize if already selected
    if (state.metrics.includes(m.id)) score += BOOSTS.ALREADY_SELECTED_PENALTY;

    return {
      id: m.id,
      label: m.label,
      kind: "metric" as const,
      priority: m.defaultPriority,
      groupLabel: m.group,
      description: m.description,
      score,
      applies: { metrics: [m.id] }
    };
  })
  .filter((s): s is Suggestion => s !== null && s.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 8); 

  // 2. Calculate Condition Suggestions
  const conditionSuggestions = CONDITIONS.map((c): Suggestion | null => {
    let score = PRIORITY_SCORES[c.defaultPriority];

    // Text Search Logic
    if (searchLower) {
        const matchScore = getTextScore(c.label, c.description);
        if (matchScore === -9999) return null;
        score += matchScore;
    }

    // Boost based on selected Metrics (Smart Pairings)
    state.metrics.forEach(selectedMetric => {
      const pairedConditions = SMART_PAIRINGS[selectedMetric];
      if (pairedConditions && pairedConditions.includes(c.id)) {
        score += BOOSTS.CONTEXT_MATCH;
      }
    });

    // Boost based on selected Platforms
    state.platforms.forEach(selectedPlatform => {
      const platformConditions = PLATFORM_BOOSTS[selectedPlatform];
      if (platformConditions && platformConditions.includes(c.id)) {
        score += BOOSTS.PLATFORM_MATCH;
      }
    });

    // Boost based on Time Preset
    if (state.timePreset === 'LAST_7_DAYS') {
      if (c.defaultPriority === 'DECLINE' || c.id === 'STOCKOUT_RISK') score += BOOSTS.TIME_MATCH;
    }
    if (state.timePreset === 'LAST_30_DAYS' || state.timePreset === 'THIS_MONTH') {
      if (c.defaultPriority === 'INVENTORY' || c.defaultPriority === 'HYGIENE') score += BOOSTS.TIME_MATCH;
    }

    // Penalize if already selected
    if (state.conditions.includes(c.id)) score += BOOSTS.ALREADY_SELECTED_PENALTY;

    return {
      id: c.id,
      label: c.label,
      kind: "condition" as const,
      priority: c.defaultPriority,
      groupLabel: c.group,
      description: c.description,
      score,
      applies: { conditions: [c.id] }
    };
  })
  .filter((s): s is Suggestion => s !== null && s.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 10); 

  // 3. Calculate Shortcut Suggestions
  const shortcutSuggestions = SHORTCUTS_LIBRARY.map((s, index): Suggestion | null => {
    let score = PRIORITY_SCORES[s.priority];

    // Text Search Logic
    if (searchLower) {
        // Shortcuts don't have descriptions in config usually, just label
        if (s.label.toLowerCase().includes(searchLower)) score += BOOSTS.TEXT_MATCH_PARTIAL;
        else return null; 
    }

    // Context Boost: If the shortcut involves a metric that is currently selected
    if (state.metrics.length > 0 && s.applies?.metrics) {
        const hasMetricOverlap = s.applies.metrics.some(m => state.metrics.includes(m));
        if (hasMetricOverlap) score += BOOSTS.CONTEXT_MATCH;
    }

    // Context Boost: If the shortcut matches conditions relevant to selected metrics
    if (state.metrics.length > 0 && s.applies?.conditions) {
        state.metrics.forEach(m => {
            const pairs = SMART_PAIRINGS[m] || [];
            if (s.applies?.conditions?.some(c => pairs.includes(c))) {
                score += BOOSTS.CONTEXT_MATCH;
            }
        });
    }

    // Boost if platform matches logic
    const isAmazon = state.platforms.some(p => p.includes('AMAZON'));
    if (isAmazon && s.label.toLowerCase().includes('ad')) score += BOOSTS.PLATFORM_MATCH;

    score -= index; // Stable sort fallback

    return {
      id: `shortcut-${index}`,
      label: s.label,
      kind: "shortcut" as const,
      priority: s.priority,
      score,
      applies: s.applies
    };
  })
  .filter((s): s is Suggestion => s !== null)
  .sort((a, b) => b.score - a.score)
  .slice(0, 6);

  // 4. Calculate Platform Suggestions
  const platformSuggestions = PLATFORMS_LIST.map((p): Suggestion | null => {
    if (state.platforms.includes(p.id)) return null;

    let score = 30;
    if (searchLower) {
        if (p.label.toLowerCase().includes(searchLower)) score += BOOSTS.TEXT_MATCH_PARTIAL;
        else return null;
    }

    return {
        id: p.id,
        label: p.label,
        kind: 'platform' as const,
        priority: 'INVENTORY' as SuggestionPriority,
        score,
        applies: { platforms: [p.id] }
    };
  }).filter((s): s is Suggestion => s !== null).sort((a, b) => b.score - a.score);

  // 5. Calculate Time Suggestions
  const timeSuggestions = TIME_PRESETS_LIST.map((t): Suggestion | null => {
    if (state.timePreset) return null;

    let score = 35;
    if (searchLower) {
        if (t.label.toLowerCase().includes(searchLower)) score += BOOSTS.TEXT_MATCH_PARTIAL;
        else return null;
    }

    return {
        id: t.id,
        label: t.label,
        kind: 'time' as const,
        priority: 'OPPORTUNITY' as SuggestionPriority,
        score,
        applies: { timePreset: t.id }
    };
  }).filter((s): s is Suggestion => s !== null).sort((a, b) => b.score - a.score);

  return {
    metricSuggestions,
    conditionSuggestions,
    shortcutSuggestions,
    platformSuggestions,
    timeSuggestions,
    skuSuggestions: [] // Default if no SKU logic triggered
  };
}

/**
 * showcasePdfGenerator.ts
 * Layout: 2×2 grid (4 cards per page), grouped by category.
 * Card structure: image left | text right (SKU, brand, name, bullets, pills, price position, speed)
 */

import { Product, CohortSnapshot } from '../types';
import { extractProductBullets } from './bulletExtractor';

const TEAL        = '#134E4A';
const TEAL_LIGHT  = '#ccfbf1';
const TEAL_50     = '#f0fdfa';
const TEAL_MID    = '#0f766e';
const WHITE       = '#ffffff';
const GRAY_900    = '#111827';
const GRAY_600    = '#4b5563';
const GRAY_400    = '#9ca3af';
const GRAY_100    = '#f3f4f6';
const GRAY_200    = '#e5e7eb';
const GREEN_700   = '#047857';
const GREEN_50    = '#ecfdf5';
const GREEN_100   = '#d1fae5';
const BLUE_700    = '#0369a1';
const BLUE_50     = '#f0f9ff';
const BLUE_100    = '#dbeafe';
const AMBER_700   = '#b45309';
const AMBER_50    = '#fffbeb';
const AMBER_100   = '#fef3c7';
const RED_700     = '#be123c';
const RED_50      = '#fff1f2';
const RED_100     = '#fee2e2';
const PURPLE_700  = '#6d28d9';
const PURPLE_50   = '#f5f3ff';

// A4 landscape
const PW = 297;
const PH = 210;
const MARGIN = 6;

function gradeColour(grade?: number): { bg: string; text: string } {
    const n = Number(grade);
    if (!n || n <= 0) return { bg: GRAY_100,  text: GRAY_600  };
    if (n <= 2)       return { bg: GREEN_50,  text: GREEN_700  };
    if (n === 3)      return { bg: BLUE_50,   text: BLUE_700   };
    if (n <= 5)       return { bg: AMBER_50,  text: AMBER_700  };
    return                   { bg: RED_50,    text: RED_700    };
}

function marginColour(pct: number): { bg: string; text: string } {
    if (pct >= 15) return { bg: GREEN_50,  text: GREEN_700 };
    if (pct >= 5)  return { bg: AMBER_50,  text: AMBER_700 };
    return               { bg: RED_50,    text: RED_700   };
}

function calcTotalCost(p: Product): number {
    return (p.costPrice ?? 0)
         + ((p as any).postage ?? (p as any).costDetail?.postage ?? 0)
         + ((p as any).sellingFee ?? (p as any).costDetail?.sellingFee ?? 0)
         + ((p as any).adsFee ?? 0)
         + ((p as any).wmsFee ?? 0)
         + ((p as any).otherFee ?? 0);
}

function calcMarginPct(p: Product): number | null {
    const price = p.caPrice || p.currentPrice || 0;
    if (price <= 0) return null;
    return ((price - calcTotalCost(p)) / price) * 100;
}

interface BucketInfo {
    label: string;
    priceMin: number;
    priceMax: number;
    medianVelocity?: number;
    medianMarginPct?: number;
    skuCount?: number;
    bucketIndex?: number;
    totalBuckets?: number;
}

function getBucketInfo(sku: string, category: string, snap: CohortSnapshot | null): BucketInfo | null {
    if (!snap) return null;
    const bucketKey = snap.skuAssignments?.get(sku) || snap.skuAssignments?.get(sku.toUpperCase());
    if (!bucketKey) return null;
    const stats  = snap.cohortStats?.get(bucketKey);
    const bucket = stats?.bucket;
    const catBuckets = snap.categoryBuckets?.get(category) || snap.categoryBuckets?.get(category.toLowerCase());
    if (!bucket) {
        if (!catBuckets) return null;
        const found = catBuckets.find((b: any) =>
            `${b.category}|${b.bucketIndex}` === bucketKey || bucketKey.includes(`|${b.bucketIndex}`)
        );
        return found ? { label: found.label, priceMin: found.priceMin, priceMax: found.priceMax,
                         bucketIndex: found.bucketIndex, totalBuckets: catBuckets.length } : null;
    }
    return {
        label: bucket.label, priceMin: bucket.priceMin, priceMax: bucket.priceMax,
        medianVelocity: stats.medianVelocity, medianMarginPct: stats.medianMarginPct,
        skuCount: stats.skuCount, bucketIndex: bucket.bucketIndex, totalBuckets: catBuckets?.length,
    };
}

async function loadImg(url: string): Promise<string | null> {
    try {
        const resp = await fetch(url, { mode: 'cors' });
        if (!resp.ok) return null;
        const blob = await resp.blob();
        return new Promise(res => {
            const r = new FileReader();
            r.onload  = () => res(r.result as string);
            r.onerror = () => res(null);
            r.readAsDataURL(blob);
        });
    } catch { return null; }
}

function detectImageFormats(dataUrl: string): string[] {
    const head = dataUrl.slice(0, 40).toLowerCase();
    if (head.startsWith('data:image/png')) return ['PNG', 'JPEG'];
    if (head.startsWith('data:image/webp')) return ['WEBP', 'PNG', 'JPEG'];
    if (head.startsWith('data:image/jpg') || head.startsWith('data:image/jpeg')) return ['JPEG', 'PNG'];
    return ['JPEG', 'PNG'];
}

function splitText(doc: any, text: string, maxW: number): string[] {
    return doc.splitTextToSize(text, maxW);
}

function rrect(doc: any, x: number, y: number, w: number, h: number, r: number, fill?: string, stroke?: string) {
    if (fill)   { doc.setFillColor(fill);   doc.roundedRect(x, y, w, h, r, r, 'F'); }
    if (stroke) { doc.setDrawColor(stroke); doc.setLineWidth(0.25); doc.roundedRect(x, y, w, h, r, r, 'S'); }
}

// Draw pill, returns next x position
function pill(doc: any, x: number, y: number, label: string, bg: string, fg: string, fs = 6): number {
    doc.setFontSize(fs);
    const tw = doc.getTextWidth(label);
    const pw = tw + 4, ph = 4.5;
    rrect(doc, x, y - 3.2, pw, ph, 1.2, bg);
    doc.setTextColor(fg);
    doc.text(label, x + 2, y);
    return x + pw + 1.5;
}

// ── Cover ──────────────────────────────────────────────────────
function drawCover(doc: any, products: Product[], themeColor: string) {
    doc.setFillColor(themeColor);
    doc.rect(0, 0, PW, PH, 'F');
    doc.setFillColor(TEAL_MID);
    doc.circle(PW - 22, 22, 42, 'F');
    doc.circle(22, PH - 22, 30, 'F');

    const cX = MARGIN + 10, cY = 20, cW = PW - (MARGIN + 10) * 2, cH = PH - 40;
    rrect(doc, cX, cY, cW, cH, 7, WHITE);

    doc.setFontSize(28); doc.setFont('helvetica', 'bold'); doc.setTextColor(themeColor);
    doc.text('NEW PRODUCT', PW / 2, 58, { align: 'center' });
    doc.text('SHOWCASE',    PW / 2, 75, { align: 'center' });

    doc.setFillColor(themeColor);
    doc.rect(PW / 2 - 20, 80, 40, 0.8, 'F');

    const weekStr = `Week of ${new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}`;
    doc.setFontSize(9); doc.setFont('helvetica', 'normal'); doc.setTextColor(GRAY_600);
    doc.text(weekStr, PW / 2, 89, { align: 'center' });

    const speeds = products.filter(p => p.landedAt && p.listingReadyAt && p.landedAt !== p.listingReadyAt)
        .map(p => Math.round((new Date(p.listingReadyAt!).getTime() - new Date(p.landedAt!).getTime()) / 86400000));
    const avgSpeed = speeds.length > 0 ? Math.round(speeds.reduce((a, b) => a + b, 0) / speeds.length) : null;
    const cats = new Set(products.map(p => p.category || 'Uncategorised')).size;

    const stats = [
        { v: String(products.length),                                    l: 'Products'          },
        { v: String(cats),                                               l: 'Categories'        },
        { v: String(products.filter(p => p.imageUrl).length),            l: 'With Images'       },
        { v: String(products.filter(p => p.description).length),         l: 'With Descriptions' },
        { v: avgSpeed != null ? `${avgSpeed}d` : '—',                    l: 'Avg Listing Speed' },
    ];
    const sW = cW / stats.length;
    stats.forEach(({ v, l }, i) => {
        const sx = cX + i * sW + sW / 2;
        doc.setFontSize(22); doc.setFont('helvetica', 'bold'); doc.setTextColor(themeColor);
        doc.text(v, sx, 115, { align: 'center' });
        doc.setFontSize(7); doc.setFont('helvetica', 'normal'); doc.setTextColor(GRAY_400);
        doc.text(l.toUpperCase(), sx, 123, { align: 'center' });
    });

    doc.setFontSize(6.5); doc.setTextColor(GRAY_400);
    doc.text('Generated by Sello UK Hub', PW / 2, PH - 10, { align: 'center' });
}

// ── Single card (drawn into a bounding box) ───────────────────
async function drawCard(
    doc: any,
    p: Product,
    x: number, y: number, w: number, h: number,
    snap: CohortSnapshot | null,
    imgCache: Map<string, string | null>,
    themeColor: string,
    bulletCache: Map<string, string[]>
) {
    // Card shell
    rrect(doc, x, y, w, h, 3, WHITE, GRAY_200);
    // Top teal accent
    doc.setFillColor(themeColor);
    doc.rect(x, y, w, 1.2, 'F');

    const PAD = 3.5;
    const IMG_SIZE = 28;   // image column width = 28mm

    // ── Left column: image ──
    const imgX = x + PAD;
    const imgY = y + PAD + 1.5;
    let drawn = false;

    if (p.imageUrl) {
        let d = imgCache.get(p.imageUrl);
        if (d === undefined) { d = await loadImg(p.imageUrl); imgCache.set(p.imageUrl, d); }
        if (d) {
            const formats = detectImageFormats(d);
            for (const fmt of formats) {
                try {
                    rrect(doc, imgX, imgY, IMG_SIZE, IMG_SIZE, 2, TEAL_50);
                    doc.addImage(d, fmt, imgX, imgY, IMG_SIZE, IMG_SIZE, undefined, 'FAST');
                    drawn = true;
                    break;
                } catch {
                    // Try next compatible format
                }
            }
        }
    }
    if (!drawn) {
        rrect(doc, imgX, imgY, IMG_SIZE, IMG_SIZE, 2, TEAL_50, TEAL_LIGHT);
        doc.setFontSize(11); doc.setFont('helvetica', 'bold'); doc.setTextColor(themeColor);
        doc.text((p.brand || p.name || 'P')[0].toUpperCase(), imgX + IMG_SIZE / 2, imgY + IMG_SIZE / 2 + 2, { align: 'center' });
    }

    // ── Right column: text ──
    const txtX = imgX + IMG_SIZE + 3.5;
    const txtW = x + w - txtX - PAD;
    let cy = y + PAD + 3;

    // Row 1: SKU + grade badge
    doc.setFontSize(7.5); doc.setFont('helvetica', 'bold'); doc.setTextColor(themeColor);
    doc.text(p.sku, txtX, cy);
    if (p.gradeLevel) {
        const gc = gradeColour(p.gradeLevel);
        const skuW = doc.getTextWidth(p.sku);
        pill(doc, txtX + skuW + 2, cy, `G${p.gradeLevel}`, gc.bg, gc.text, 6);
    }
    cy += 4.5;

    // Row 2: brand
    if (p.brand) {
        doc.setFontSize(6); doc.setFont('helvetica', 'normal'); doc.setTextColor(GRAY_400);
        doc.text(p.brand.toUpperCase(), txtX, cy);
        cy += 3.5;
    }

    // Row 3: product name (2 lines max)
    doc.setFontSize(7); doc.setFont('helvetica', 'bold'); doc.setTextColor(GRAY_900);
    const nameLines = splitText(doc, p.name || '', txtW).slice(0, 2);
    doc.text(nameLines, txtX, cy);
    cy += nameLines.length * 3.8 + 2.5;

    // Horizontal rule + padding
    doc.setDrawColor(GRAY_200); doc.setLineWidth(0.25);
    doc.line(txtX, cy, txtX + txtW, cy);
    cy += 3.5; // ← padding below rule

    // Rows 4-8: bullets (leave room for pills + price panel + speed)
    const bullets = bulletCache.get(p.sku) || [];

    // Reserve space: pills row (6) + price panel (if any, 18) + speed (6) + bottom pad (2)
    const bi = getBucketInfo(p.sku, p.category || '', snap);
    const reservedH = 6 + (bi ? 17 : 0) + 5 + 2;
    const bulletBottom = y + h - reservedH;

    doc.setFontSize(6); doc.setFont('helvetica', 'normal'); doc.setTextColor(GRAY_600);
    for (const b of bullets) {
        if (cy > bulletBottom) break;
        const wrapped = splitText(doc, `• ${b}`, txtW).slice(0, 2);
        doc.text(wrapped, txtX, cy);
        cy += wrapped.length * 3 + 0.8;
    }

    // Snap cy: ensure bullets don't push into the reserved area
    cy = Math.min(cy + 2, bulletBottom);

    // ── Row 9: Metric pills ──
    let px = txtX;
    const price = p.caPrice || p.currentPrice || 0;
    if (price > 0) px = pill(doc, px, cy, `£${price.toFixed(2)}`, TEAL_50, TEAL_MID);
    if (p.stockLevel !== undefined) px = pill(doc, px, cy, `Stock: ${p.stockLevel}`, GRAY_100, GRAY_600);
    const mPct = calcMarginPct(p);
    if (mPct !== null) {
        const mc = marginColour(mPct);
        px = pill(doc, px, cy, `${mPct.toFixed(0)}% margin`, mc.bg, mc.text);
    }
    if (bi) {
        pill(doc, px, cy, `${p.category || 'Uncategorised'} · ${bi.label}`, PURPLE_50, PURPLE_700);
    } else {
        pill(doc, px, cy, p.category || 'Uncategorised', TEAL_LIGHT, themeColor);
    }
    cy += 6;

    // ── Price position panel (inline, below pills) ──
    if (bi) {
        const panelH = 16;
        rrect(doc, txtX, cy, txtW, panelH, 2, TEAL_50);
        let py = cy + 3;

        doc.setFontSize(5.5); doc.setFont('helvetica', 'bold'); doc.setTextColor(themeColor);
        doc.text('PRICE POSITION', txtX + txtW / 2, py, { align: 'center' });

        doc.setFontSize(7); doc.setFont('helvetica', 'bold'); doc.setTextColor(GRAY_900);
        doc.text(bi.label, txtX + txtW / 2, py + 3.5, { align: 'center' });

        // Progress bar
        if (bi.totalBuckets && bi.bucketIndex !== undefined) {
            const barX = txtX + 4, barW = txtW - 8, barH = 2;
            const barY = py + 5.5;
            rrect(doc, barX, barY, barW, barH, 1, GRAY_200);
            const fill = Math.max(3, barW * (bi.bucketIndex + 1) / bi.totalBuckets);
            rrect(doc, barX, barY, fill, barH, 1, themeColor);

            doc.setFontSize(5); doc.setFont('helvetica', 'normal'); doc.setTextColor(GRAY_400);
            doc.text('lower', barX, barY + barH + 2);
            doc.text('higher', barX + barW, barY + barH + 2, { align: 'right' });
        }

        // Median stats (compact, single line)
        if (bi.medianVelocity !== undefined) {
            const statsY = py + 13;
            doc.setFontSize(5.5); doc.setFont('helvetica', 'normal'); doc.setTextColor(GRAY_600);
            doc.text(`Bucket median: `, txtX + 2, statsY);
            doc.setFont('helvetica', 'bold'); doc.setTextColor(GRAY_900);
            const labelW = doc.getTextWidth('Bucket median: ');
            doc.text(
                `${bi.medianVelocity.toFixed(1)}/day  ·  ${(bi.medianMarginPct || 0).toFixed(0)}% margin  ·  ${bi.skuCount ?? '—'} SKUs`,
                txtX + 2 + labelW, statsY
            );
        }
        cy += panelH + 0.5;
    }

    // ── Row 10: Listing speed ──
    // landedAt = arrived in warehouse  |  listingReadyAt = content & images ready (listed)
    const speedY = y + h - 4;
    doc.setFontSize(5.5); doc.setFont('helvetica', 'normal'); doc.setTextColor(GRAY_400);

    const parts: string[] = [];
    if (p.landedAt) parts.push(`Landed: ${p.landedAt}`);
    if (p.listingReadyAt && p.listingReadyAt !== p.landedAt) {
        parts.push(`Listed: ${p.listingReadyAt}`);
        if (p.landedAt) {
            const days = Math.round(
                (new Date(p.listingReadyAt).getTime() - new Date(p.landedAt).getTime()) / 86400000
            );
            if (days > 0) parts.push(`⏱ ${days}d to list`);
        }
    } else if (p.listingReadyAt) {
        // Same date — only show once, label as "Listed"
        parts.push(`Listed: ${p.listingReadyAt}`);
    }

    if (parts.length) doc.text(parts.join('  ·  '), x + PAD, speedY);
}

// ── Category product pages (2×2 grid) ────────────────────────
async function drawProductPages(
    doc: any,
    byCategory: Map<string, Product[]>,
    snap: CohortSnapshot | null,
    imgCache: Map<string, string | null>,
    themeColor: string,
    bulletCache: Map<string, string[]>
) {
    const HEADER_H = 12;
    const FOOTER_H = 5;
    const COLS = 2, ROWS = 2;
    const CARDS_PER_PAGE = COLS * ROWS;
    const GAP = 2;

    const availW = PW - MARGIN * 2;
    const availH = PH - HEADER_H - FOOTER_H - MARGIN;
    const cardW = (availW - GAP) / COLS;
    const cardH = (availH - GAP) / ROWS;

    for (const [category, products] of byCategory) {
        let remaining = [...products];
        while (remaining.length > 0) {
            doc.addPage();
            const chunk = remaining.splice(0, CARDS_PER_PAGE);

            // Category header
            doc.setFillColor(themeColor);
            doc.rect(0, 0, PW, HEADER_H, 'F');
            doc.setFontSize(8.5); doc.setFont('helvetica', 'bold'); doc.setTextColor(WHITE);
            doc.text(category.toUpperCase(), MARGIN, 8);

            // Footer
            doc.setFontSize(5.5); doc.setFont('helvetica', 'normal'); doc.setTextColor(GRAY_400);
            doc.text('Sello UK Hub — New Product Showcase', PW / 2, PH - 2.5, { align: 'center' });

            for (let i = 0; i < chunk.length; i++) {
                const col = i % COLS;
                const row = Math.floor(i / COLS);
                const cx = MARGIN + col * (cardW + GAP);
                const cy = HEADER_H + 2 + row * (cardH + GAP);
                await drawCard(doc, chunk[i], cx, cy, cardW, cardH, snap, imgCache, themeColor, bulletCache);
            }
        }
    }
}

// ── Summary page ──────────────────────────────────────────────
function drawSummary(doc: any, products: Product[], snap: CohortSnapshot | null) {
    doc.addPage();
    doc.setFillColor(TEAL);
    doc.rect(0, 0, PW, 14, 'F');
    doc.setFontSize(10); doc.setFont('helvetica', 'bold'); doc.setTextColor(WHITE);
    doc.text('Summary', MARGIN, 10);

    const byCategory = new Map<string, Product[]>();
    products.forEach(p => {
        const cat = p.category || 'Uncategorised';
        if (!byCategory.has(cat)) byCategory.set(cat, []);
        byCategory.get(cat)!.push(p);
    });

    let ty = 24;
    const cols = { cat: MARGIN, count: 75, price: 100, bucket: 134, margin: 210, img: 248, desc: 270 };

    doc.setFontSize(6.5); doc.setFont('helvetica', 'bold'); doc.setTextColor(GRAY_400);
    ['CATEGORY','COUNT','AVG CA PRICE','PRICE BUCKET (COHORT)','AVG MARGIN','IMG','DESC'].forEach((h, i) => {
        doc.text(h, [cols.cat, cols.count, cols.price, cols.bucket, cols.margin, cols.img, cols.desc][i], ty);
    });
    doc.setDrawColor(GRAY_200); doc.setLineWidth(0.3);
    doc.line(MARGIN, ty + 2, PW - MARGIN, ty + 2);
    ty += 7;

    let totalRevPot = 0;
    let rowIdx = 0;

    byCategory.forEach((ps, catName) => {
        if (rowIdx % 2 === 0) { doc.setFillColor(GRAY_100); doc.rect(MARGIN, ty - 3.5, PW - MARGIN * 2, 7, 'F'); }
        const priced = ps.filter(p => p.caPrice && p.caPrice > 0);
        const avgP = priced.length ? priced.reduce((s, p) => s + p.caPrice!, 0) / priced.length : 0;
        const mVals = ps.map(p => calcMarginPct(p)).filter((v): v is number => v !== null);
        const avgM = mVals.length ? mVals.reduce((a, b) => a + b, 0) / mVals.length : null;
        totalRevPot += ps.reduce((s, p) => s + (p.caPrice || 0) * (p.stockLevel || 0), 0);

        const bucketSet = new Set<string>();
        ps.forEach(p => { const bi = getBucketInfo(p.sku, p.category || '', snap); if (bi) bucketSet.add(bi.label); });

        doc.setFontSize(7); doc.setFont('helvetica', 'normal'); doc.setTextColor(GRAY_900);
        doc.text(catName, cols.cat, ty);
        doc.setTextColor(GRAY_600);
        doc.text(String(ps.length), cols.count, ty);
        doc.text(avgP > 0 ? `£${avgP.toFixed(2)}` : '—', cols.price, ty);
        doc.text(splitText(doc, bucketSet.size ? [...bucketSet].join(', ') : '—', 68).slice(0,1), cols.bucket, ty);
        if (avgM !== null) {
            const mc = marginColour(avgM);
            doc.setTextColor(mc.text);
            doc.text(`${avgM.toFixed(1)}%`, cols.margin, ty);
            doc.setTextColor(GRAY_600);
        } else {
            doc.text('—', cols.margin, ty);
        }
        doc.text(`${ps.filter(p => p.imageUrl).length}/${ps.length}`, cols.img, ty);
        doc.text(`${ps.filter(p => p.description).length}/${ps.length}`, cols.desc, ty);
        ty += 7; rowIdx++;
        if (ty > PH - 20) { doc.addPage(); ty = MARGIN + 10; }
    });

    doc.setDrawColor(TEAL); doc.setLineWidth(0.5);
    doc.line(MARGIN, ty, PW - MARGIN, ty);
    ty += 5;
    doc.setFontSize(7.5); doc.setFont('helvetica', 'bold'); doc.setTextColor(TEAL);
    doc.text(`Total: ${products.length} products across ${byCategory.size} categories`, MARGIN, ty);
    if (totalRevPot > 0) {
        ty += 5;
        doc.setFontSize(7); doc.setFont('helvetica', 'normal'); doc.setTextColor(GRAY_600);
        doc.text(`Stock value potential: £${Math.round(totalRevPot).toLocaleString('en-GB')}`, MARGIN, ty);
    }
}

// ── Main export ───────────────────────────────────────────────
export async function generateShowcasePdf(
    selectedSkus: string[],
    allProducts: Product[],
    cohortSnapshot: CohortSnapshot | null,
    themeColor: string = TEAL
): Promise<void> {
    let jsPDF: any;
    try {
        jsPDF = (window as any).jspdf?.jsPDF || (window as any).jsPDF;
        if (!jsPDF) {
            const mod = await import('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js' as any);
            jsPDF = mod.jsPDF || mod.default?.jsPDF;
        }
    } catch {
        alert('PDF generation requires jsPDF. Please check your network connection and try again.');
        return;
    }
    if (!jsPDF) { alert('Could not load PDF library.'); return; }

    const selected = selectedSkus
        .map(sku => allProducts.find(p => p.sku === sku))
        .filter((p): p is Product => !!p);
    if (!selected.length) return;

    const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });

    // Pre-load all images in parallel
    const imgCache = new Map<string, string | null>();
    await Promise.all(
        selected.filter(p => p.imageUrl)
                .map(p => loadImg(p.imageUrl!).then(d => imgCache.set(p.imageUrl!, d)))
    );

    // Cover
    drawCover(doc, selected, themeColor);

    // Group by category
    const byCategory = new Map<string, Product[]>();
    selected.forEach(p => {
        const cat = p.category || 'Uncategorised';
        if (!byCategory.has(cat)) byCategory.set(cat, []);
        byCategory.get(cat)!.push(p);
    });

    // Pre-compute bullets for all products (avoids regex parsing per card in draw loop)
    const bulletCache = new Map<string, string[]>();
    selected.forEach(p => {
        if (p.description) {
            bulletCache.set(p.sku, extractProductBullets(p.description).features.slice(0, 5));
        }
    });

    // Product pages
    await drawProductPages(doc, byCategory, cohortSnapshot, imgCache, themeColor, bulletCache);

    // Summary
    drawSummary(doc, selected, cohortSnapshot);

    doc.save(`sello-new-product-showcase-${new Date().toISOString().split('T')[0]}.pdf`);
}

import { VAT_MULTIPLIER } from '../constants';

export const TAX_NOTE_SHORT = "All monetary values include tax unless stated otherwise.";

export type TaxBasis = 'inc' | 'ex';

/**
 * Generates a consistent label for monetary values indicating tax basis.
 * @param taxBasis - Whether the value is tax-inclusive ('inc') or tax-exclusive ('ex'). Defaults to 'inc'.
 * @returns A formatted string label, e.g., "£ (inc tax)".
 */
export function moneyLabel(taxBasis: TaxBasis = 'inc'): string {
  if (taxBasis === 'ex') {
    return "£ (ex tax)";
  }
  return "£ (inc tax)";
}

/**
 * Development utility to guard against double-application of VAT scaling.
 * Use this before applying scaleMoneyInclTax if the source is ambiguous.
 * @param context - Debug context string
 * @param value - The value being scaled
 */
export function assertNotAlreadyScaled(context: string, value: number): void {
  // In development, this serves as a placeholder hook for debugging double-taxation bugs.
  // We do not throw in production to avoid crashing the app, but this documents intent.
  if (process.env.NODE_ENV === 'development') {
    // Future expansion: Add heuristic checks here if needed
  }
}

/**
 * Apply VAT scaling to a raw monetary value.
 * Apply VAT at aggregation/output only. Do not scale raw logs.
 */
export function scaleMoneyInclTax(amount: number | null | undefined): number {
  if (amount === null || amount === undefined || isNaN(amount)) return 0;
  return amount * VAT_MULTIPLIER;
}

/**
 * Conditionally apply VAT scaling.
 */
export function scaleMoneyInclTaxIf(amount: number | null | undefined, apply: boolean): number {
  if (amount === null || amount === undefined || isNaN(amount)) return 0;
  return apply ? amount * VAT_MULTIPLIER : amount;
}

/**
 * Sums an array of potentially null/undefined numbers safely.
 */
export function safeSumMoney(values: (number | null | undefined)[]): number {
  return values.reduce((sum, val) => {
    const num = Number(val);
    return (sum || 0) + (isNaN(num) ? 0 : num);
  }, 0) || 0;
}

import * as XLSX from 'xlsx';
import { Product, PricingRules, HistoryPayload } from '../types';
import { asDateKeyNaive } from '../services/dateUtils';
import { getCanonicalSku } from '../services/skuNormalization';

function dateKeyToLocal(key: string): Date {
    const [y, m, d] = key.split('-').map(Number);
    return new Date(y, m - 1, d);
}

interface ColumnMapping {
    sku: string;
    qty: string;
    revenue: string;
    date?: string;
    platform?: string;
    platformLevel2?: string;
    category?: string;
    cogs?: string;
    sellingFee?: string;
    adsFee?: string;
    postage?: string;
    logisticsService?: string;
    extraFreight?: string;
    otherFee?: string;
    subscriptionFee?: string;
    wmsFee?: string;
    profitExclRn?: string;
    profitExclRnPercent?: string;
    outerOrderId?: string;
    orderType?: string;
    receivePostcode?: string;
    logisticPartner?: string;
}

type ProgressPhase = 'reading' | 'parsing' | 'mapping' | 'aggregating' | 'finalizing';

const postProgress = (phase: ProgressPhase, progress: number, message: string) => {
    self.postMessage({
        type: 'progress',
        phase,
        progress: Math.max(0, Math.min(100, Math.round(progress))),
        message
    });
};

const normalizeHeader = (h: string) => h.toLowerCase().replace(/[^a-z0-9]/g, '');

const findMappedHeader = (headers: string[], candidates: string[], fuzzy = false): string => {
    const normalizedHeaders = headers.map(h => ({ original: h, normalized: normalizeHeader(h) }));

    for (const rawCand of candidates) {
        const cand = normalizeHeader(rawCand);
        const isPercentCand = rawCand.includes('%') || rawCand.toLowerCase().includes('percent');
        const strictMatch = normalizedHeaders.find(h => {
            const hasPercentSymbol = h.original.includes('%') || h.original.toLowerCase().includes('percent');
            if (isPercentCand && !hasPercentSymbol) return false;
            if (!isPercentCand && hasPercentSymbol) return false;
            return h.normalized === cand;
        });
        if (strictMatch) return strictMatch.original;
    }

    for (const rawCand of candidates) {
        const cand = normalizeHeader(rawCand);
        const isPercentCand = rawCand.includes('%') || rawCand.toLowerCase().includes('percent');
        if (fuzzy) {
            const fuzzyMatch = normalizedHeaders.find(h => {
                const hasPercentSymbol = h.original.includes('%') || h.original.toLowerCase().includes('percent');
                if (isPercentCand && !hasPercentSymbol) return false;
                if (!isPercentCand && hasPercentSymbol) return false;
                return h.normalized.includes(cand);
            });
            if (fuzzyMatch) return fuzzyMatch.original;
        }
    }

    for (const rawCand of candidates) {
        const cand = normalizeHeader(rawCand);
        const match = headers.find(h => normalizeHeader(h) === cand);
        if (match) return match;
    }

    return '';
};

const autoDetectMapping = (headers: string[]): ColumnMapping => {
    return {
        sku: findMappedHeader(headers, ['skucode', 'sku', 'sellersku', 'itemnumber']),
        qty: findMappedHeader(headers, ['sold_qty', 'sku_quantity', 'skuquantity', 'qty', 'quantity', 'units', 'sold']),
        revenue: findMappedHeader(headers, ['salesamt', 'revenue', 'totalprice', 'price', 'grosssales']),
        date: findMappedHeader(headers, ['ordertime', 'date', 'orderdate', 'created']),
        platform: findMappedHeader(headers, ['platformnamelevel1', 'platform', 'source', 'channel', 'marketplace']),
        platformLevel2: findMappedHeader(headers, ['platformnamelevel2', 'fulfillment', 'subsource']),
        category: findMappedHeader(headers, ['category', 'maincategory']),
        cogs: findMappedHeader(headers, ['cogs', 'cost', 'unitcost']),
        sellingFee: findMappedHeader(headers, ['sellingfee', 'commission', 'referralfee']),
        adsFee: findMappedHeader(headers, ['adsfee', 'adspend', 'ppc', 'sponsored']),
        postage: findMappedHeader(headers, ['postage', 'shipping', 'freight', 'delivery']),
        logisticsService: findMappedHeader(headers, ['logisticsname', 'logistics_name', 'service', 'courier', 'shippingmethod']),
        extraFreight: findMappedHeader(headers, ['extrafreight', 'shippingincome', 'shippingcharge']),
        otherFee: findMappedHeader(headers, ['otherfee']),
        subscriptionFee: findMappedHeader(headers, ['subscriptionfee']),
        wmsFee: findMappedHeader(headers, ['wmsfee', 'fulfillment', 'pickpack']),
        profitExclRn: findMappedHeader(headers, ['profit_excl_rn', 'netprofit', 'profitamount'], false),
        profitExclRnPercent: findMappedHeader(headers, ['profit_excl_rn%', 'netpm', 'profit%', 'margin%'], true),
        outerOrderId: findMappedHeader(headers, ['outer_order_id', 'order_id', 'orderid', 'order_no', 'ordernumber', 'transaction_id'], false),
        orderType: findMappedHeader(headers, ['ordertype', 'order_type', 'type'], false),
        receivePostcode: findMappedHeader(headers, ['receive_postcode', 'postcode', 'zip', 'postalcode', 'ship_to_zip'], false),
        logisticPartner: findMappedHeader(headers, ['label_provider', 'shipping_partner', 'logistic_partner', 'carrier_partner'], false)
    };
};

const parseSpreadsheetPayload = (
    fileName: string,
    fileBuffer?: ArrayBuffer,
    fileText?: string
): { headers: string[]; rows: any[][] } => {
    const lowerName = (fileName || '').toLowerCase();

    if ((lowerName.endsWith('.xlsx') || lowerName.endsWith('.xls')) && fileBuffer) {
        const workbook = XLSX.read(fileBuffer, { type: 'array', cellDates: true });
        const sheet = workbook.Sheets[workbook.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(sheet, { header: 1 }) as any[][];
        if (!rows.length) return { headers: [], rows: [] };
        const headers = rows[0].map(h => String(h ?? '').trim());
        return { headers, rows: rows.slice(1) };
    }

    const text = fileText || '';
    const parsed = text.split('\n').map(l => l.split(','));
    if (!parsed.length) return { headers: [], rows: [] };
    const headers = parsed[0].map(h => String(h ?? '').trim());
    return { headers, rows: parsed.slice(1) };
};

const processRows = (
    headers: string[],
    rows: any[][],
    mapping: ColumnMapping,
    products: Product[],
    pricingRules: PricingRules,
    learnedAliases: Record<string, string>,
    extraAliases: Record<string, string>
) => {
    const getIdx = (col?: string) => col ? headers.indexOf(col) : -1;

    const skuIdx = getIdx(mapping.sku);
    const qtyIdx = getIdx(mapping.qty);
    const revIdx = getIdx(mapping.revenue);
    const dateIdx = getIdx(mapping.date);
    const platIdx = getIdx(mapping.platform);
    const plat2Idx = getIdx(mapping.platformLevel2);

    const cogsIdx = getIdx(mapping.cogs);
    const catIdx = getIdx(mapping.category);
    const sellingIdx = getIdx(mapping.sellingFee);
    const adsIdx = getIdx(mapping.adsFee);
    const postIdx = getIdx(mapping.postage);
    const logNameIdx = getIdx(mapping.logisticsService);
    const extraIdx = getIdx(mapping.extraFreight);
    const otherIdx = getIdx(mapping.otherFee);
    const subIdx = getIdx(mapping.subscriptionFee);
    const wmsIdx = getIdx(mapping.wmsFee);
    const profitIdx = getIdx(mapping.profitExclRn);
    const netPmIdx = getIdx(mapping.profitExclRnPercent);
    const orderIdIdx = getIdx(mapping.outerOrderId);
    const orderTypeIdx = getIdx(mapping.orderType);
    const postcodeIdx = getIdx(mapping.receivePostcode);
    const partnerIdx = getIdx(mapping.logisticPartner);

    const aggregated: Record<string, {
        qty: number;
        revenue: number;
        count: number;
        dates: Set<string>;
        fees: { selling: number; ads: number; postage: number; extra: number; other: number; sub: number; wms: number; cogs: number };
        netPmSum: number;
        profitSum: number;
        category: string;
        platformStats: Record<string, { qty: number; revenue: number }>;
    }> = {};

    const dailyAggregated: Record<string, {
        sku: string;
        date: string;
        totalQty: number;
        totalRevenue: number;
        netPmSum: number;
        totalProfit: number;
        totalAds: number;
        platform: string;
        orderId?: string;
        postcode?: string;
        logisticPartner?: string;
        logisticService?: string;
        totalPostage: number;
        totalExtraFreight: number;
    }> = {};

    const discoveredPlatforms = new Set<string>();
    let orderIdsDetectedCount = 0;
    let minDate = new Date(9999, 11, 31);
    let maxDate = new Date(0);
    let hasDates = false;
    const shipmentLogs: any[] = [];

    const productBySku = new Map<string, Product>();
    const productByUpperSku = new Map<string, Product>();
    products.forEach((p: Product) => {
        productBySku.set(p.sku, p);
        productByUpperSku.set(p.sku.toUpperCase(), p);
    });

    const aliasMap: Record<string, string> = {};
    products.forEach((p: Product) => {
        aliasMap[p.sku.toUpperCase()] = p.sku;
        p.channels.forEach(c => {
            if (c.skuAlias) {
                c.skuAlias.split(',').forEach(a => {
                    aliasMap[a.trim().toUpperCase()] = p.sku;
                });
            }
        });
    });

    Object.entries(learnedAliases).forEach(([alias, master]) => {
        const aliasUpper = alias.toUpperCase();
        if (!aliasMap[aliasUpper]) aliasMap[aliasUpper] = master;
    });
    Object.entries(extraAliases).forEach(([alias, master]) => {
        const aliasUpper = alias.toUpperCase();
        if (!aliasMap[aliasUpper]) aliasMap[aliasUpper] = master;
    });

    const currentUnknownSkus: Record<string, { count: number; revenue: number; masterSku: string | null }> = {};
    let matchCount = 0;
    let skipCount = 0;
    const totalRows = rows.length || 1;
    let nextProgressRow = 0;

    rows.forEach((row: any[], index: number) => {
        if (index >= nextProgressRow) {
            const pct = 30 + (index / totalRows) * 55;
            postProgress('aggregating', pct, `Processing rows ${index}/${rows.length}`);
            nextProgressRow = index + 5000;
        }

        if (!row[skuIdx]) return;

        const parseVal = (idx: number) => {
            if (idx === -1 || row[idx] === undefined || row[idx] === null || row[idx] === '') return 0;
            const val = row[idx];
            if (typeof val === 'number') return val;
            const str = String(val).replace(/[^\d.-]/g, '').trim();
            const v = parseFloat(str);
            return isNaN(v) ? 0 : v;
        };

        const rev = parseVal(revIdx);
        const adsCost = parseVal(adsIdx);
        const qty = parseVal(qtyIdx);
        if (rev <= 0.001 && adsCost <= 0.001 && qty <= 0) return;

        const rawSku = String(row[skuIdx]).trim();
        const canonicalRawSku = getCanonicalSku(rawSku);
        const rawSkuUpper = canonicalRawSku.toUpperCase();

        let masterSku = aliasMap[rawSkuUpper];
        if (!masterSku) {
            const directMatch = productByUpperSku.get(rawSkuUpper);
            if (directMatch) masterSku = directMatch.sku;
        }

        if (!masterSku) {
            if (!currentUnknownSkus[rawSku]) {
                currentUnknownSkus[rawSku] = { count: 0, revenue: 0, masterSku: null };
            }
            currentUnknownSkus[rawSku].count++;
            currentUnknownSkus[rawSku].revenue += rev;
            skipCount++;
            return;
        }

        matchCount++;

        const parsePercent = (idx: number) => {
            if (idx === -1 || row[idx] === undefined || row[idx] === null || row[idx] === '') return 0;
            const val = row[idx];
            if (typeof val === 'number') {
                if (Math.abs(val) > 0 && Math.abs(val) <= 1.0) return val * 100;
                return val;
            }
            const str = String(val).replace('%', '').replace(/[^\d.-]/g, '').trim();
            const v = parseFloat(str);
            return isNaN(v) ? 0 : v;
        };

        const profit = parseVal(profitIdx);
        const netPm = parsePercent(netPmIdx);

        let platformName = 'Unknown';
        const p1 = (platIdx !== -1 && row[platIdx]) ? String(row[platIdx]).trim() : '';
        const p2 = (plat2Idx !== -1 && row[plat2Idx]) ? String(row[plat2Idx]).trim() : '';
        if (p2 && p2 !== '-' && p2.toLowerCase() !== 'unknown') {
            if (p1 && !p2.toLowerCase().includes(p1.toLowerCase()) && p2.length < 5) platformName = `${p1} ${p2}`;
            else platformName = p2;
        } else if (p1) {
            platformName = p1;
        }

        const orderId = (orderIdIdx !== -1 && row[orderIdIdx]) ? String(row[orderIdIdx]).trim() : '';
        const orderType = (orderTypeIdx !== -1 && row[orderTypeIdx]) ? String(row[orderTypeIdx]).trim().toLowerCase() : '';
        const isAdOnly = orderType === 'ad_only';
        const postcode = (postcodeIdx !== -1 && row[postcodeIdx]) ? String(row[postcodeIdx]).trim() : undefined;
        const partner = (partnerIdx !== -1 && row[partnerIdx]) ? String(row[partnerIdx]).trim() : undefined;
        const serviceName = (logNameIdx !== -1 && row[logNameIdx]) ? String(row[logNameIdx]).trim() : undefined;

        if (orderId) orderIdsDetectedCount++;
        discoveredPlatforms.add(platformName);

        if (!aggregated[masterSku]) {
            aggregated[masterSku] = {
                qty: 0, revenue: 0, count: 0, dates: new Set(),
                fees: { selling: 0, ads: 0, postage: 0, extra: 0, other: 0, sub: 0, wms: 0, cogs: 0 },
                netPmSum: 0, profitSum: 0, category: '', platformStats: {}
            };
        }

        const platformConfig = pricingRules[platformName];
        const isCostBased = platformConfig?.pricingControl === 'PLATFORM_COST_BASED' || platformConfig?.isExcluded === true;
        const item = aggregated[masterSku];

        if (!isCostBased && !isAdOnly) {
            item.qty += qty;
            item.revenue += rev;
        }
        if (!isAdOnly) item.count++;

        const weight = Math.abs(qty) || 1;
        if (!isCostBased && !isAdOnly) {
            item.netPmSum += (netPm * weight);
            item.profitSum += profit;
        }

        const postageCost = parseVal(postIdx);
        const extraFreightInc = parseVal(extraIdx);

        item.fees.selling += parseVal(sellingIdx);
        item.fees.ads += adsCost;
        item.fees.postage += postageCost;
        item.fees.extra += extraFreightInc;
        item.fees.other += parseVal(otherIdx);
        item.fees.sub += parseVal(subIdx);
        item.fees.wms += parseVal(wmsIdx);
        item.fees.cogs += parseVal(cogsIdx);

        if (catIdx !== -1 && row[catIdx]) item.category = String(row[catIdx]).trim();

        const dLog = (() => {
            if (dateIdx !== -1 && row[dateIdx]) {
                const dk = asDateKeyNaive(row[dateIdx]);
                if (dk) return dateKeyToLocal(dk);
            }
            return new Date();
        })();
        if (qty === 1 && serviceName && postageCost > 0) {
            shipmentLogs.push({
                id: Math.random().toString(36).substr(2, 9),
                sku: masterSku,
                service: serviceName,
                cost: postageCost,
                date: dLog.toISOString()
            });
        }

        if (!item.platformStats[platformName]) item.platformStats[platformName] = { qty: 0, revenue: 0 };
        item.platformStats[platformName].qty += qty;
        item.platformStats[platformName].revenue += rev;

        const rawDateVal = (dateIdx !== -1) ? row[dateIdx] : undefined;
        const dateKey = asDateKeyNaive(rawDateVal);
        if (dateKey) {
            hasDates = true;
            const d = dateKeyToLocal(dateKey);
            if (d < minDate) minDate = d;
            if (d > maxDate) maxDate = d;

            const dailyKey = orderId
                ? `${masterSku}|${dateKey}|${platformName}|${orderId}`
                : `${masterSku}|${dateKey}|${platformName}`;

            if (!dailyAggregated[dailyKey]) {
                dailyAggregated[dailyKey] = {
                    sku: masterSku,
                    date: dateKey,
                    totalQty: 0,
                    totalRevenue: 0,
                    netPmSum: 0,
                    totalProfit: 0,
                    totalAds: 0,
                    platform: platformName,
                    orderId: orderId || undefined,
                    postcode: postcode || undefined,
                    logisticPartner: partner || undefined,
                    logisticService: serviceName || undefined,
                    totalPostage: 0,
                    totalExtraFreight: 0
                };
            }
            if (!isAdOnly) {
                dailyAggregated[dailyKey].totalQty += qty;
                dailyAggregated[dailyKey].totalRevenue += rev;
                dailyAggregated[dailyKey].totalPostage += postageCost;
                dailyAggregated[dailyKey].totalExtraFreight += extraFreightInc;

                const dailyWeight = Math.abs(qty) || 0;
                dailyAggregated[dailyKey].netPmSum += (netPm * dailyWeight);

                if (profit === 0 && netPm !== 0 && rev !== 0) dailyAggregated[dailyKey].totalProfit += rev * (netPm / 100);
                else dailyAggregated[dailyKey].totalProfit += profit;
            }
            dailyAggregated[dailyKey].totalAds += adsCost;
            if (!isAdOnly) item.dates.add(dateKey);
        }
    });

    postProgress('finalizing', 88, 'Building transaction payload');

    let calculatedPeriod = 30;
    let dateLabel = 'Manual Period';
    if (hasDates && maxDate > minDate) {
        const diffTime = Math.abs(maxDate.getTime() - minDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
        calculatedPeriod = diffDays;
        const formatDate = (d: Date) => d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
        dateLabel = `${formatDate(minDate)} – ${formatDate(maxDate)}`;
    }

    const updates: Product[] = [];
    const history: HistoryPayload[] = [];
    const todayStr = new Date().toISOString().split('T')[0];

    Object.values(dailyAggregated).forEach(bucket => {
        const weight = bucket.totalQty;
        const avgPrice = weight > 0 ? bucket.totalRevenue / weight : 0;

        let finalMargin = 0;
        if (profitIdx !== -1 && bucket.totalRevenue > 0) finalMargin = (bucket.totalProfit / bucket.totalRevenue) * 100;
        else finalMargin = weight > 0 ? bucket.netPmSum / weight : 0;

        if (bucket.totalQty !== 0 || bucket.totalAds > 0) {
            const payload: HistoryPayload = {
                sku: bucket.sku,
                date: bucket.date,
                price: isNaN(avgPrice) ? 0 : avgPrice,
                velocity: isNaN(bucket.totalQty) ? 0 : bucket.totalQty,
                platform: bucket.platform,
                orderId: bucket.orderId,
                postcode: bucket.postcode,
                logisticPartner: bucket.logisticPartner,
                logisticService: bucket.logisticService,
                adsSpend: Number(bucket.totalAds.toFixed(4)),
                realPostage: Number(bucket.totalPostage.toFixed(4)),
                realExtraFreight: Number(bucket.totalExtraFreight.toFixed(4))
            };
            if (!isNaN(finalMargin)) payload.margin = Number(finalMargin.toFixed(4));
            if (profitIdx !== -1) payload.profit = Number(bucket.totalProfit.toFixed(4));
            history.push(payload);
        }
    });

    postProgress('finalizing', 93, 'Updating SKU metrics');

    Object.entries(aggregated).forEach(([sku, data]) => {
        const product = productBySku.get(sku);
        if (!product) return;

        const validQty = data.qty > 0 ? data.qty : 1;
        const newVelocity = data.qty / calculatedPeriod;
        const currentPrice = product.currentPrice || 0;
        const rawAvg = data.qty > 0 ? data.revenue / data.qty : currentPrice;
        const avgPrice = Number((rawAvg || 0).toFixed(2));

        const unitFees = {
            selling: (Number(data.fees.selling) || 0) / validQty,
            ads: (Number(data.fees.ads) || 0) / validQty,
            postage: (Number(data.fees.postage) || 0) / validQty,
            extra: (Number(data.fees.extra) || 0) / validQty,
            other: (Number(data.fees.other) || 0) / validQty,
            sub: (Number(data.fees.sub) || 0) / validQty,
            wms: (Number(data.fees.wms) || 0) / validQty,
        };

        const updatedChannels = [...product.channels];
        Object.entries(data.platformStats).forEach(([platform, stats]) => {
            const channelIdx = updatedChannels.findIndex(c => c.platform === platform);
            const channelVelocity = stats.qty / calculatedPeriod;
            const channelPrice = stats.qty > 0 ? stats.revenue / stats.qty : 0;
            if (channelIdx >= 0) {
                updatedChannels[channelIdx] = { ...updatedChannels[channelIdx], velocity: channelVelocity, price: channelPrice };
            } else {
                const defaultManager = pricingRules[platform]?.manager || 'Unassigned';
                updatedChannels.push({
                    platform,
                    manager: defaultManager,
                    velocity: channelVelocity,
                    price: channelPrice,
                    skuAlias: ''
                });
            }
        });

        updates.push({
            ...product,
            averageDailySales: newVelocity,
            previousDailySales: product.averageDailySales,
            currentPrice: avgPrice,
            oldPrice: currentPrice,
            lastUpdated: todayStr,
            sellingFee: unitFees.selling || product.sellingFee,
            adsFee: unitFees.ads || product.adsFee,
            postage: unitFees.postage || product.postage,
            extraFreight: unitFees.extra || product.extraFreight,
            otherFee: unitFees.other || product.otherFee,
            subscriptionFee: unitFees.sub || product.subscriptionFee,
            wmsFee: unitFees.wms || product.wmsFee,
            category: data.category || product.category,
            channels: updatedChannels
        });

        if (!hasDates && newVelocity > 0) {
            const primaryPlatform = Object.keys(data.platformStats)[0] || 'General';
            history.push({
                sku,
                date: todayStr,
                price: avgPrice,
                velocity: newVelocity,
                margin: 0,
                platform: primaryPlatform,
                adsSpend: data.fees.ads
            });
        }
    });

    postProgress('finalizing', 98, 'Finalizing import summary');

    const features = {
        ads: mapping.adsFee && updates.some(u => u.adsFee && u.adsFee > 0),
        fees: mapping.sellingFee && updates.some(u => u.sellingFee && u.sellingFee > 0),
        logistics: (mapping.postage || mapping.wmsFee) && updates.some(u => (u.postage || 0) + (u.wmsFee || 0) > 0),
        category: mapping.category && updates.some(u => u.category !== productBySku.get(u.sku)?.category)
    };

    return {
        success: true,
        updates,
        history,
        shipmentLogs,
        features,
        stats: {
            matchedSkus: updates.length,
            totalRevenue: Object.values(aggregated).reduce((a, b) => a + b.revenue, 0),
            period: calculatedPeriod,
            dateLabel,
            shipmentCount: shipmentLogs.length,
            discoveredPlatforms: Array.from(discoveredPlatforms),
            orderIdsCount: orderIdsDetectedCount
        },
        unknownSkus: currentUnknownSkus,
        resolvedAliases: extraAliases
    };
};

self.onmessage = (e: MessageEvent) => {
    const {
        fileName,
        fileBuffer,
        fileText,
        headers,
        rows,
        mapping,
        products,
        pricingRules,
        learnedAliases = {},
        extraAliases = {}
    } = e.data || {};

    try {
        let workingHeaders: string[] = headers || [];
        let workingRows: any[][] = rows || [];
        let workingMapping: ColumnMapping = mapping;

        if ((!workingHeaders.length || !workingRows.length) && (fileBuffer || fileText)) {
            postProgress('reading', 5, 'Reading file');
            postProgress('parsing', 12, 'Parsing spreadsheet');
            const parsed = parseSpreadsheetPayload(fileName || 'upload.csv', fileBuffer, fileText);
            workingHeaders = parsed.headers;
            workingRows = parsed.rows;
            postProgress('parsing', 22, `Parsed ${workingRows.length} rows`);
        }

        if (!workingHeaders.length || workingRows.length === 0) {
            self.postMessage({ success: false, error: 'File empty or missing headers' });
            return;
        }

        if (!workingMapping || !workingMapping.sku || !workingMapping.qty || !workingMapping.revenue) {
            postProgress('mapping', 26, 'Detecting column mapping');
            workingMapping = autoDetectMapping(workingHeaders);
        }

        const canAutoProcess = !!(workingMapping.sku && workingMapping.qty && workingMapping.revenue);
        if (!canAutoProcess) {
            self.postMessage({
                type: 'parsed',
                success: true,
                headers: workingHeaders,
                rows: workingRows,
                detectedMapping: workingMapping
            });
            return;
        }

        postProgress('aggregating', 30, 'Preparing aggregation');
        const result = processRows(
            workingHeaders,
            workingRows,
            workingMapping,
            products || [],
            pricingRules || {},
            learnedAliases || {},
            extraAliases || {}
        );

        postProgress('finalizing', 100, 'Import ready');
        const hasUnknownSkus = !!(result.unknownSkus && Object.keys(result.unknownSkus).length > 0);
        self.postMessage({
            ...result,
            headers: hasUnknownSkus ? workingHeaders : undefined,
            rows: hasUnknownSkus ? workingRows : undefined,
            detectedMapping: workingMapping
        });
    } catch (err: any) {
        self.postMessage({ success: false, error: err.message });
    }
};
